	[6323] = {
		id = 6323,
		skillName = 'ท่าไม้ตาย',
		skillTypeShow = 'ทักษะสังหาร',
		describe = 'Gyarados กระโดดขึ้นแล้วพ่นปืนน้ำใส่แนวหน้าศัตรู สร้างความเสียหายทางกายภาพ #C0xE69900#300% ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54#กายภาพ#C0x5B545B# ลบ Buff ทั้งหมดของเป้าหมาย เพิ่มคริติคอลดาเมจ 80% หากโจมตีติดคริติคอล หลังจบการโจมตีอาจติดสถานะสับสน 1–2 เทิร์น (ยิ่งคริติคอลเรตสูง ยิ่งใช้ท่าไม้ตายบ่อย โอกาสติด Confuse ยิ่งสูง); หากไม่ติดคริติคอล ท่าไม้ตายถัดไปจะเพิ่มคริติคอลดาเมจเป็น 2 เท่า',
		simDesc = 'Gyarados กระโดดขึ้นฟ้าแล้วยิง Hydro Pump โจมตีศัตรูแถวหน้า เพิ่ม Critical Damage อย่างมาก ลบ Buff เป้าหมาย และมีโอกาสทำให้ตนเองติด Confuse หลังโจมตี',
		starEffect = __data_t__starEffect[6323],
		-- {11}
		starEffectDesc = 'สร้างความเสียหายกระจาย 20% ไปยังศัตรูรอบข้าง',
		zawakeEffect = __data_t__zawakeEffect[6323],
		-- {79003}
		zawakeEffectDesc = 'Gyaradosกระโจนขึ้นฟ้าแล้วพ่นปืนฉีดน้ำใส่แนวแถวของศัตรู สร้างความเสียหาย#C0xE69900#300%พลังโจมตีกายภาพ#C0x5B545B#+$(skillLevel*4*24)$เป็น#C0xF13B54#ความเสียหายกายภาพ#C0x5B545B# ล้างบัฟทั้งหมดของเป้าหมาย การโจมตีนี้เพิ่มคริติคอลแดเมจขึ้น 80% หากเกิดคริติคอล หลังจบการโจมตีมีโอกาสเข้าสถานะสับสน (Confused) เป็นเวลา 1-2 เทิร์น (ยิ่งอัตราคริติคอลปัจจุบันสูง และจำนวนครั้งที่ใช้ท่าไม้ตายมาก โอกาสสับสนจะยิ่งสูง); หากไม่เกิดคริติคอล ท่าไม้ตายถัดไปจะมีคริติคอลแดเมจเพิ่มขึ้นเป็น 2 เท่า และเพิ่มอัตราคริติคอล 50%',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'หากไม่เกิดคริติคอล ท่าไม้ตายถัดไปจะเพิ่มความเสียหายคริติคอลเป็นสองเท่า\n#F20# \n#F40##C0x5c9970#→หากไม่เกิดคริติคอล ท่าไม้ตายถัดไปจะเพิ่มความเสียหายคริติคอลเป็นสองเท่า และเพิ่มคริติคอลเรท 50%',
