	[7692] = {
		id = 7692,
		skillName = 'สกิลพิเศษ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#F40##L10#ใช้ได้ในฟอร์มร่างหลัก คูลดาวน์ 3 เทิร์น#L0#\nโจมตีเป้าหมายในแนวแถวของศัตรู สร้างความเสียหายพิเศษ #C0x3D8A99#160%พลังโจมตีพิเศษ#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# ความเสียหายพิเศษ#C0x5B545B#\nดูดเกจโกรธศัตรู 60 แต้ม\nArchiveดีบัฟระดับ 1/2 แบบสุ่ม 1 อันเข้าสู่【โลกในจิต】นาน 2 เทิร์น (หากไม่มีผลให้ArchiveจะArchive【ลดพลังป้องกันพิเศษ II】)\n#C0xF13B54#【โลกในจิต】#C0x5B545B#\nสนามพิเศษในจิตใจ สามารถArchiveเอฟเฟกต์แปลกประหลาดและความเสียหาย ทุกเทิร์นสามารถArchiveความเสียหายพิเศษได้สูงสุด 120% (รวมสูงสุด 240%) และทุก 2 เทิร์นสามารถArchiveดีบัฟควบคุมระดับ 1/2 ได้ 1 ครั้ง หากเงื่อนไขตรงจะConcreteกลายเป็นสนามระดับสูงของพลังจิต ทำให้พลังจิตฝ่ายเรารับความเสียหายลดลง 10% และศัตรูรับความเสียหายพลังจิตเพิ่ม 10%\n#C0xF13B54#【ลดพลังป้องกันพิเศษ II】#C0x5B545B#\nดีบัฟระดับ 1 ลดพลังป้องกันพิเศษของเป้าหมาย 20%',
		zawakeEffect = __data_t__zawakeEffect[7692],
		-- {79002}
		zawakeEffectDesc = '#F40##L10#ใช้ได้ในร่างต้นฉบับ คูลดาวน์ 3 เทิร์น#L0#\nโจมตีศัตรูในแนวแถว สร้างความเสียหาย#C0x3D8A99#160%พลังโจมตีพิเศษ#C0x5B545B#+$(skillLevel*4*24)$เป็น#C0xF13B54#ความเสียหายพิเศษ#C0x5B545B#\nดูดซับค่าโกรธของเป้าหมาย 60 แต้ม\nผนึกดีบัฟ 1 อย่างระดับ 1/2 แบบสุ่มไว้ใน【Reverse World】เป็นเวลา 2 เทิร์น (หากไม่มีดีบัฟให้ผนึก จะผนึก【Sp. DEF Down II】แทน)\n#C0xF13B54#【Reverse World】#C0x5B545B#\nสนามพิเศษในจิตใต้สำนึกต้นฉบับ ใช้ผนึกผลดีบัฟและความเสียหายได้ ทุกเทิร์นสามารถผนึกความเสียหายจาก Sp. ATK ได้สูงสุด 120% (รวมสูงสุด 240%) ทุก 2 เทิร์นสามารถผนึกผลควบคุมระดับ 1/2 ได้ 1 อย่าง เมื่อเข้าเงื่อนไขพิเศษจะ เป็นสนามทั้งฉาก ธาตุ Psychic พิเศษ ลดความเสียหายที่ฝ่ายเราสาย Psychic ได้รับลง 10% ศัตรูทั้งหมดจะได้รับความเปราะต่อท่า Psychic เพิ่มขึ้น 10%\n#C0xF13B54#【Sp. DEF Down II】#C0x5B545B#\nดีบัฟระดับ 1 ลดพลังป้องกันพิเศษของเป้าหมายลง 20%',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '#C0x5c9970#ค่าสัดส่วนดาเมจพื้นฐานเพิ่มเป็น 180%, การดูดเกจโกรธเพิ่มเป็น 80 และสามารถผนึกผลลบได้ 2 ชนิด',
		upLvDesc = 'เพิ่มความเสียหายคงที่+192',
