		targetChooseType = 'all',
		damageFormula = 'self:specialDamage()*(self:flagZ2() and 0.6 or 0.5)+(self:flag(99) and skillLevel or skillLevel*4)*24',
		skillProcess = __data_t__skillProcess[7693],
