	[7694] = {
		id = 7694,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = 'โจมตีศัตรูทุกตัว สร้างความเสียหายพิเศษ #C0x3D8A99#180%พลังโจมตีพิเศษ#C0x5B545B#+$(skillLevel*4*36)$#C0xF13B54# ความเสียหายพิเศษ#C0x5B545B#\nแปลงร่างเป็น【ร่างจิต】\nปล่อยดีบัฟที่ผนึกไว้ใน【โลกในจิต】ให้กับศัตรูทุกตัวนาน 2 เทิร์น\nในรอบใหญ่นี้ ฝ่ายศัตรูตัวแรกที่ได้เทิร์นจะถูก【เปิดโลกในจิต】ก่อนการกระทำ\n#C0xF13B54#【โลกในจิต】#C0x5B545B#\nสนามพิเศษในจิตใจ สามารถผนึกเอฟเฟกต์แปลกประหลาดและความเสียหาย ทุกเทิร์นสามารถผนึกความเสียหายพิเศษได้สูงสุด 120% (รวมสูงสุด 240%) และทุก 2 เทิร์นสามารถผนึกดีบัฟควบคุมระดับ 1/2 ได้ 1 ครั้ง หากเงื่อนไขตรงจะ具象กลายเป็นสนามระดับสูงของพลังจิต ทำให้พลังจิตฝ่ายเรารับความเสียหายลดลง 10% และศัตรูรับความเสียหายพลังจิตเพิ่ม 10%\n#C0xF13B54#【ร่างจิต】#C0x5B545B#\nฟอร์มพิเศษของพลังจิต สืบทอดทุกค่าสถานะของร่างหลัก ใช้โกรธและเอฟเฟกต์ร่วมกัน; หากร่างหลักยังไม่ตาย เมื่อร่างจิตตายจะกลับเป็นร่างหลัก\n#C0xF13B54#【เปิดโลกในจิต】#C0x5B545B#\nศัตรูจะถูกดึงเข้าสู่โลกในจิตของ Mega Mewtwo Y เผชิญหน้ากับร่างจิต 3 ตัวขึ้นไป (จำนวนขึ้นกับพวกเดียวกันที่เป็นสายพลังจิต) ต้องเลือกโจมตีร่างหลัก หากเลือกถูก จะปล่อยสกิลสร้างความเสียหาย 30% ก่อนออกจากโลกในจิต หากเลือกผิด การกระทำจะล้มเหลวและจะได้รับความเสียหายสะท้อน 120% พลังโจมตีพิเศษ\n#C0xF13B54#【具象พลังจิต】#C0x5B545B#\nการกระทำพิเศษ เปลี่ยนโลกในจิตเป็นจริง สร้างความเสียหายพลังโจมตีพิเศษ 100% + ความเสียหายที่ผนึกไว้แบบกระจาย (เป้าหมายแต่ละตัวรับได้สูงสุด 150% พลังโจมตีพิเศษ ความเสียหายรวมสูงสุดไม่เกิน 900% พลังโจมตีพิเศษของผู้ใช้) ความเสียหายนี้ไม่สนโล่และสิ่งกีดขวาง',
		simDesc = '#C0xC0C0C0#ต้องได้รับอนุญาตก่อนถึงจะออกได้#C0x5B545B#\nMega Mewtwo X ใช้ True Chi Fist ที่มีพลังเป็น 2 เท่าโจมตีเป้าหมายเดี่ยว แล้วนำเป้าหมายนั้นเข้าสู่【Asura Field】\n\n#F40##L10#Asura Field#L0#: Mega Mewtwo X จะไม่โดนผลจากดาเมจแฝง/ดาเมจพาสซีฟ และไม่ถูกรบกวนด้วยเอฟเฟกต์หรือเทิร์นรอบนอก ทั้งสองฝ่ายจะสู้กันด้วยการโจมตีธรรมดา (โดยไม่เพิ่ม Chi Intent) ในสนามนี้จะเริ่มต้นที่ 3 เทิร์น True Chi Fist แต่ละขั้นจะเพิ่มระยะเวลาอีก 1 เทิร์น ในสนาม หาก Mega Mewtwo X มี Physical Attack สูงกว่าศัตรู จะได้รับ【Intimidate】: ทำให้ศัตรูเสีย 30% HP ปัจจุบัน และ Speed ของศัตรูจะต่ำกว่าแน่นอน หากพลังโจมตีต่ำกว่าจะได้รับ Damage Reduction แทน สนามจะจบลงเมื่อมีฝ่ายใดฝ่ายหนึ่งตาย',
		starEffect = __data_t__starEffect[7694],
		-- {11}
		starEffectDesc = '\nหลังใช้ท่าไม้ตาย ความเสียหายที่เพื่อนร่วมทีมทั้งหมดสร้างจะถูกบันทึกไว้ใน【Reverse Realm】 เมื่อจบเทิร์นใหญ่ถัดไป จะปลดปล่อยเป็น【Mind Projection】',
		zawakeEffect = __data_t__zawakeEffect[7694],
		-- {79003}
		zawakeEffectDesc = 'โจมตีศัตรูทั้งหมด สร้างความเสียหาย#C0x3D8A99#180%พลังโจมตีพิเศษ#C0x5B545B#+$(skillLevel*4*36)$เป็น#C0xF13B54#ความเสียหายพิเศษ#C0x5B545B#\nตนเองเข้าสู่ร่าง【Spirit Form】\nปล่อยดีบัฟที่ผนึกไว้ใน【Reverse World】ใส่ศัตรูทั้งหมด 2 เทิร์น\nในเทิร์นถัดไป ศัตรูที่มีลำดับการเคลื่อนไหวก่อนจะกระตุ้น【Reverse Unfold】\n#C0xF13B54#【Reverse World】#C0x5B545B#\nสนามพิเศษในจิตใต้สำนึกต้นฉบับ ใช้ผนึกผลดีบัฟและความเสียหายได้ ทุกเทิร์นสามารถผนึกความเสียหายจาก Sp. ATK ได้สูงสุด 120% (รวมสูงสุด 240%) ทุก 2 เทิร์นสามารถผนึกผลควบคุมระดับ 1/2 ได้ 1 อย่าง เมื่อเข้าเงื่อนไขพิเศษจะ เป็นสนามทั้งฉาก ธาตุ Psychic พิเศษ ลดความเสียหายที่ฝ่ายเราสาย Psychic ได้รับลง 10% ศัตรูทั้งหมดจะได้รับความเปราะต่อท่า Psychic เพิ่มขึ้น 10%\n#C0xF13B54#【Spirit Form】#C0x5B545B#\nร่างพิเศษเฉพาะสาย Psychic สืบทอดคุณสมบัติทั้งหมดจากร่างต้นฉบับ ใช้ค่าโกรธและสถานะร่วมกัน หากร่างต้นฉบับยังมีชีวิตอยู่ เมื่อร่างจิต HP หมด จะกลับไปยังร่างต้นฉบับ\n#C0xF13B54#【Reverse Unfold】#C0x5B545B#\nศัตรูจะถูกดูดเข้าสู่ Reverse World ของ Mega Mewtwo Y และพบเจอกับร่างจิตอย่างน้อย 3 ตัว (เพิ่ม 1 ตัวต่อตัวละครสาย Psychic ในทีม) ต้องเลือกจู่โจมร่างต้นฉบับ หากเลือกถูก จะปล่อยสกิลสร้างความเสียหาย 30% หลังจากออกจาก Reverse World หากเลือกผิด การกระทำล้มเหลวและจะได้รับความเสียหายจากการสะท้อน 120% พลังโจมตีพิเศษ  \n#C0xF13B54#【Mental Projection】#C0x5B545B#\nการกระทำพิเศษ ทำให้ Reverse World สู่โลกความจริง โจมตีศัตรูทั้งหมดด้วยความเสียหาย 100% พลังโจมตีพิเศษ + ความเสียหายที่บันทึกไว้ (เป้าหมายแต่ละตัวจะได้รับไม่เกิน 150% และรวมไม่เกิน 900% พลังโจมตีพิเศษของผู้ใช้) ความเสียหายนี้ไม่สนโล่และสิ่งกีดขวาง',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '#C0x5c9970#ค่าสัดส่วนดาเมจพื้นฐานเพิ่มเป็น 200%, หลังใช้ท่าไม้ตาย 2 ครั้ง สนาม Inner World จะคงอยู่ในโลกจริงอีก 1 เทิร์น และกลายเป็นสนาม Psychic ระดับสูงทั้งสนาม: เมื่อเป้าหมายที่โดน backlash ออกจาก Inner World ศัตรูทุกตัวจะได้รับความเสียหายเพิ่ม 50% จาก Sp.Atk ของ Mewtwo Y',
