	[12556] = {
		id = 12556,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#F40##L10#Basalt Armor：#L0#\nเมื่อถูกโจมตีแบบแอคทีฟ 1 ครั้ง จะสะสม Basalt Armor 1 ชั้น\nเมื่อสะสมครบ 10 ชั้น จะคงอยู่ 2 เทิร์น แล้วล้างชั้นทั้งหมดเพื่อเริ่มสะสมใหม่\n#C0xF13B54#【Basalt Armor】#C0x5B545B#\nบัฟระดับ 3 แต่ละชั้นเพิ่มพลังป้องกันกายภาพและพิเศษ 20% และลดความเสียหายที่ได้รับ 10% เมื่อซ้อนถึงขีดสุด การซ้อนเพิ่มอีกจะฟื้น HP ตัวเอง 20% ของ HP สูงสุด\n#C0xF13B54#【Berserk State】#C0x5B545B#\nสถานะพิเศษ ลบสถานะควบคุมระดับ 3 ลงไปทั้งหมด และเติมเกจพลังจนเต็ม เพิ่มคริติคอลเรต 50% ความแรงคริติคอล 20% ความเร็ว 12%; ความเสียหายและสถานะควบคุมที่ได้รับในช่วงนี้จะถูกรวมและจัดการเมื่อจบสถานะ\n#C0xF13B54#【Fortress Armor】#C0x5B545B#\nเอฟเฟกต์พิเศษ สิ่งกีดขวางธาตุหินลดดาเมจทั่วไปและดาเมจจริง 50% และป้องกันดาเมจธาตุทุกประเภท \n#F20#\n#F40#【#L10#Divine Sandstorm#L0#】เมื่อ Mega Tyranitar เข้าสู่สนาม ทีมจะได้รับสภาพอากาศ【Divine Sandstorm】ช่วงจัดทีม (สุ่มเปิดใช้แต่ละเทิร์น อยู่ได้ 3 เทิร์นต่อรอบ) ทำให้โปเกมอนธาตุหิน/ดินทั้งสองฝ่ายมีพลังป้องกันทั้งสองเพิ่มขึ้น 30% และเพิ่มดาเมจสกิล 20% (สุ่มเปิดใช้แต่ละเทิร์น อยู่ได้ 3 เทิร์น)',
		starEffect = __data_t__starEffect[12556],
		-- {6}
		starEffectDesc = 'Pokémon สาย Rock/Ground ที่อยู่แถวหน้าจะกันการสลับตำแหน่ง และได้รับโบนัสพลังป้องกันสองประเภท $(10+(skillLevel-1)*0.15)$% และลดความเสียหายเพิ่มอีก $(10+(skillLevel-1)*0.15)$%  \n#F40##L10#สัญชาตญาณแห่งการทำลาย:#L0# เมื่อ HP ลดต่ำกว่า 45% เป็นครั้งแรก จะฟื้นฟู HP 30% และเข้าสู่【Berserk Mode】เป็นเวลา 2 เทิร์น',
		zawakeEffect = __data_t__zawakeEffect[12556],
		-- {79004}
		zawakeEffectDesc = '#F40##L10#Basalt Armor：#L0#\nเมื่อได้รับการโจมตีเชิงรุก 1 ครั้ง จะสะสม 1 ชั้นของ【Basalt Armor】\nเมื่อสะสมครบ 10 ชั้น จะคงอยู่ 2 เทิร์น แล้วรีเซ็ตชั้นทั้งหมดเพื่อนับใหม่\n#C0xF13B54#【Basalt Armor】#C0x5B545B#\nบัฟระดับ 3 แต่ละชั้นเพิ่มค่าป้องกันกายภาพและพิเศษ 20% และลดความเสียหายที่ได้รับ 10% เมื่อถึงขีดจำกัด หากซ้อนเพิ่มอีกจะฟื้นฟูพลังชีวิต 20% ของสูงสุด\n#C0xF13B54#【Berserk State】#C0x5B545B#\nสถานะเฉพาะ ลบการควบคุมระดับ 3 ลงไปทั้งหมด เติมเกจความโกรธเต็มทันที เพิ่มอัตราคริติคอล 50% ความเสียหายคริติคอล 20% และความเร็ว 12% ขณะอยู่ในสถานะจะสะสมความเสียหายและเอฟเฟกต์ควบคุม และจะถูกคำนวณเมื่อจบสถานะ\n#C0xF13B54#【Fortified Armor】#C0x5B545B#\nเอฟเฟกต์พิเศษ สิ่งกีดขวางธาตุหินจะมีการลดความเสียหาย 50% ทั้งแบบปกติและแบบจริง และยังกันธาตุได้ทั้งหมด\n#F20#\n#F40#【#L10#Divine Sandstorm#L0#】เมื่อ Shining Mega Tyranitar ลงสนาม ทีมจะได้รับเอฟเฟกต์สภาพอากาศ【Divine Sandstorm】ในช่วงจัดตำแหน่งการต่อสู้ (จะเปิดใช้งานแบบสุ่มทุกเทิร์น โดยแต่ละครั้งจะอยู่ 3 เทิร์น) ทำให้โปเกมอนธาตุหิน/ดินในทั้งสองทีมได้รับค่าป้องกันกายภาพและพิเศษเพิ่มขึ้น 30% และเพิ่มความเสียหายของสกิลอีก 20% (สุ่มเปิดใช้งานทุกเทิร์น ครั้งละ 3 เทิร์น)',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#เมื่ออยู่แถวหน้าในการเข้าสนาม จะได้รับ 5 ชั้นของ【Basalt Armor】และ 1 ชั้นของ【Rock Wall】 เมื่อทุกชั้นถูกลบ จะสร้าง【Rock Wall】1 เทิร์นให้ตนเอง; ขณะอยู่ใน【Rampage State】จะปล่อย【Destructive Ripple】ทุกครั้งที่เคลื่อนไหว',
