	[12813] = {
		id = 12813,
		skillName = 'ท่าไม้ตาย',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#ถ้าได้ยินเสียงจากป่า ห้ามขยับตัวนะ~#C0x5B545B#\n#F10#\n#F40#เมื่อ Celebi ล่องผ่านป่าและมิติเวลา ใช้พลังของกาลเวลาโจมตีศัตรูทุกตัว สร้างความเสียหายพิเศษ #C0x3D8A99#180% พลังโจมตีพิเศษ (Sp.Atk)#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# ความเสียหายพิเศษ#C0x5B545B# พร้อมดึงทุกเป้าหมายเข้าสู่【Time Turbulence】เป็นเวลา 2 รอบใหญ่\n#F10#\n#F40##L10#Time Turbulence：#L0#ลดความเร็วศัตรูทุกตัว 10~30% ลดระยะเวลาบัฟลง 1 เทิร์น เพิ่มระยะเวลาดีบัฟขึ้น 1 เทิร์น ฝ่ายเราจะเพิ่มความเร็วขึ้น 20% เพิ่มระยะเวลาบัฟ 1 เทิร์น ลดระยะเวลาดีบัฟ 1 เทิร์น ระหว่างนี้ ศัตรู 3 ตัวแรกที่เกจพลังเต็มจะถูกรีเซตกลับไปยังสถานะเทิร์นก่อนหน้าที่เกจยังไม่เต็ม',
		simDesc = 'Celebi เดินทางผ่านป่าและกาลเวลา สลักวงปีใส่ศัตรูทั้งทีม ดึงทุกโปเกมอนเข้าสู่กระแสเวลาปั่นป่วน ลด Speed, Buff ของศัตรู และเพิ่ม Debuff ศัตรู ฝ่ายเราจะได้รับผลกลับกัน พร้อมลด Rage ฝ่ายศัตรูลง  ',
		starEffect = __data_t__starEffect[12813],
		-- {11}
		starEffectDesc = '【Time Turbulence】อยู่ได้นาน 3 เทิร์นใหญ่ เป้าหมายของเอฟเฟกต์ย้อนเกจพลังงานจะเปลี่ยนเป็นศัตรูทุกตัวในสนาม หากมีศัตรูที่เคยติด【Seed Bomb】จะได้รับอีก 1 ลูก หากไม่มีเลย จะสุ่มใส่ 1 ลูก',
		zawakeEffect = __data_t__zawakeEffect[12813],
		-- {79003}
		zawakeEffectDesc = '#C0xC0C0C0#จะพาเธอไปสู่อนาคต!#C0x5B545B#\n#F10#\n#F40#Celebi ดึงสายธนูแห่งแสง ยิงศรแห่งกาลเวลา สร้างวงปีแห่งเวลาใส่ศัตรูทุกตัว สร้างความเสียหาย #C0x3D8A99#180% พลังโจมตีพิเศษ#C0x5B545B#+$(skillLevel*4*60)$ เป็น#C0xF13B54#ความเสียหายพิเศษ#C0x5B545B# พร้อมดึงทุกยูนิตเข้าสู่【Time Turbulence】นาน 2 รอบใหญ่\n#F10#\n#F40##L10#Time Turbulence：#L0#ศัตรูทั้งหมดจะมีความเร็วลดลง 10~30% ระยะเวลาบัฟลดลง 1 เทิร์น ดีบัฟเพิ่มขึ้น 1 เทิร์น ฝ่ายเราจะมีความเร็วเพิ่มขึ้น 20% ระยะเวลาบัฟเพิ่มขึ้น 1 เทิร์น และดีบัฟลดลง 1 เทิร์น；ในช่วงนี้ ศัตรู 3 ตัวแรกที่เกจโกรธเต็ม จะถูกรีเซ็ตกลับไปยังสถานะเกจโกรธก่อนหน้า',
