	[12816] = {
		id = 12816,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#เพื่อเชื่อมโยงอดีตอันห่างไกล และอนาคตอันไกลโพ้น~#C0x5B545B#\n#F10#\n#F40##L10#Time Mark:#L0# เมื่อเข้าสู่สนาม จะมอบ【Time Mark】ให้ตนเองและเพื่อนร่วมทีมที่มีพลังโจมตีสูงสุด บันทึกค่า HP และเกจพลังขณะนั้น หากได้รับความเสียหายร้ายแรง จะใช้ Time Mark เพื่อกระตุ้น【Time Rewind】 ป้องกันความเสียหายนั้น และย้อน HP/เกจพลังกลับ (ไม่รับผลการฟื้น HP หรือเร่งเกจ) ล้างควบคุมและผลลบทั้งหมด และเพิ่มอัตราลดความเสียหายสุดท้าย #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# เป็นเวลา 2 เทิร์น\n#F10#\n#F40##L10#Foresee the Future:#L0# คาดการณ์อันตรายในอนาคต หลบความเสียหายจากสกิล 1 ครั้ง (เกิดได้ทุก 5 ครั้งที่ถูกโจมตี)\n#F10#\n#F40##L10#Time Ripple:#L0# ทุกครั้งที่ Celebi ดำเนินการหรือเกิด Time Rewind จะสร้าง【Time Ripple】 ทำให้สกิลย่อยของเพื่อนร่วมทีมแบบสุ่มลดคูลดาวน์ 1 เทิร์น และของศัตรูแบบสุ่มเพิ่มคูลดาวน์ 1 เทิร์น พร้อมเร่งเวลา Seed Bomb บนสนามศัตรูให้ระเบิดเร็วขึ้น 1 เทิร์น\n#F10#\n#F40##L10#Forest Purification:#L0# เมื่อฝ่ายเราได้รับผลลบครบ 3 ครั้ง จะลบผลลบ 2 อย่างออกจากฝ่ายเราทันที',
		starEffect = __data_t__starEffect[12816],
		-- {8}
		starEffectDesc = 'ทุก ๆ 1 เทิร์นใหญ่ จะมอบ【Time Mark】ให้ยูนิตฝ่ายเราแบบสุ่ม 1 ตัว (ยูนิตแต่ละตัวจะได้รับผลจาก Time Mark ได้เพียงครั้งเดียว)',
		zawakeEffect = __data_t__zawakeEffect[12816],
		-- {79004}
		zawakeEffectDesc = '#C0xC0C0C0#เวลาของฉัน ฉันคือผู้ควบคุม!#C0x5B545B#\n#F10#\n#F40##L10#Time Imprint：#L0#เมื่อเข้าสนาม จะมอบ【Time Imprint】ให้ตนเองและเพื่อนร่วมทีมที่มีพลังโจมตีสูงสุด โดยจะบันทึกค่า HP และเกจโกรธ ณ เวลาที่ได้รับ เมื่อได้รับความเสียหายร้ายแรงจะใช้【Time Imprint】เพื่อกระตุ้น【Time Reversal】 ยกเลิกความเสียหายนั้น และย้อน HP กับเกจโกรธกลับไปยังค่าที่บันทึกไว้ (ไม่รับผลจากการฟื้นฟูหรือเร่งเกจ และจะไม่ลดเกจน้อยกว่าปัจจุบัน) พร้อมล้างสถานะควบคุมและดีบัฟทั้งหมด และเพิ่มการลดความเสียหายสุดท้ายให้ตนเอง #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# นาน 2 เทิร์น\n#F10#\n#F40##L10#Foresee the Future：#L0#ล่วงรู้ถึงอันตรายในอนาคต หลีกเลี่ยงความเสียหายจากสกิลได้ 1 ครั้ง (คูลดาวน์เอฟเฟกต์นี้ทุก 5 ครั้งที่ถูกโจมตี)\n#F10#\n#F40##L10#Time Ripple：#L0#เมื่อ Celebi กระทำการ หรือเมื่อเกิดเอฟเฟกต์ย้อนเวลา จะสร้าง【Time Ripple】ลดคูลดาวน์สกิลเล็กของเพื่อนร่วมทีมแบบสุ่ม 1 ตัวลง 1 เทิร์น และเพิ่มคูลดาวน์สกิลเล็กของศัตรูแบบสุ่ม 1 ตัวขึ้น 1 เทิร์น พร้อมเร่งเวลาให้【Seed Bomb】ทั้งหมดของศัตรูระเบิดเร็วขึ้น 1 เทิร์น\n#F10#\n#F40##L10#Forest Purification：#L0#เมื่อพวกเดียวกันได้รับดีบัฟครบ 3 ครั้ง จะล้างดีบัฟออกจากฝั่งเรา 2 ชิ้นทันที',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '#C0x5c9970#เมื่อโปเกมอนสาย Grass หรือ Psychic ได้รับ【Time Mark】，จะเพิ่มดาเมจ 10%; เมื่อ【Time Mark】หมด จะทำให้เป้าหมายใช้【Dispel III】อัตโนมัติ 1 ครั้ง',
		upLvDesc = '最终伤害减免效果提升',
