	[12826] = {
		id = 12826,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#เวลาของฉัน ฉันเป็นคนกำหนด!#C0x5B545B#\n#F10#\n#F40##L10#Time Mark:#L0# เมื่อเข้าสู่สนาม จะมอบสถานะ【Time Mark】ให้ตนเองและเพื่อนร่วมทีมที่มีพลังโจมตีสูงที่สุด เมื่อมอบ Time Mark จะบันทึกค่า HP และเกจพลัง ณ เวลานั้น หากได้รับความเสียหายร้ายแรงจะใช้ Time Mark เพื่อกระตุ้น【Temporal Rewind】 ป้องกันความเสียหายนั้น และย้อน HP กับเกจพลังกลับสู่ค่าที่บันทึกไว้ (ไม่รับผลจากการรักษาหรือฟื้นเกจ และจะไม่ลดเกจต่ำกว่าปัจจุบัน) ล้างสถานะควบคุมและผลลบทั้งหมด และเพิ่มอัตราลดความเสียหายสุดท้าย #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# เป็นเวลา 2 เทิร์น\n#F10#\n#F40##L10#Foresee the Future:#L0# สามารถล่วงรู้ถึงอันตรายที่กำลังจะเกิดขึ้น หลบหลีกความเสียหายจากสกิลหนึ่งครั้งโดยสมบูรณ์ (สามารถเกิดได้ทุก 5 ครั้งที่โดนโจมตี)\n#F10#\n#F40##L10#Time Ripple:#L0# ทุกครั้งที่ Celebi ดำเนินการหรือ Time Rewind ทำงาน จะเกิดคลื่นเวลา ทำให้คูลดาวน์ของสกิลย่อยของเพื่อนร่วมทีมแบบสุ่มลดลง 1 เทิร์น และคูลดาวน์ของศัตรูแบบสุ่มเพิ่มขึ้น 1 เทิร์น พร้อมทั้งเร่งเวลาระเบิดของ【Seed Bomb】ของศัตรูในสนามเร็วขึ้น 1 เทิร์น\n#F10#\n#F40##L10#Forest Purification:#L0# ทุกครั้งที่เพื่อนร่วมทีมได้รับผลลบครบ 3 อัน จะลบผลลบ 2 อันแบบสุ่มจากฝ่ายเราในทันที',
		starEffect = __data_t__starEffect[12826],
		-- {8}
		starEffectDesc = 'ทุก ๆ 1 เทิร์นใหญ่ จะมอบ【Time Mark】ให้ยูนิตฝ่ายเราแบบสุ่ม 1 ตัว (ยูนิตแต่ละตัวจะได้รับผลจาก Time Mark ได้เพียงครั้งเดียว)',
		zawakeEffect = __data_t__zawakeEffect[12826],
		-- {79004}
		zawakeEffectDesc = '#C0xC0C0C0#เวลาของฉัน ฉันคือผู้ควบคุม!#C0x5B545B#\n#F10#\n#F40##L10#Time Imprint：#L0#เมื่อเข้าสนาม จะมอบ【Time Imprint】ให้ตนเองและเพื่อนร่วมทีมที่มีพลังโจมตีสูงสุด โดยจะบันทึกค่า HP และเกจโกรธ ณ เวลาที่ได้รับ เมื่อได้รับความเสียหายร้ายแรงจะใช้【Time Imprint】เพื่อกระตุ้น【Time Reversal】 ยกเลิกความเสียหายนั้น และย้อน HP กับเกจโกรธกลับไปยังค่าที่บันทึกไว้ (ไม่รับผลจากการฟื้นฟูหรือเร่งเกจ และจะไม่ลดเกจน้อยกว่าปัจจุบัน) พร้อมล้างสถานะควบคุมและดีบัฟทั้งหมด และเพิ่มการลดความเสียหายสุดท้ายให้ตนเอง #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# นาน 2 เทิร์น\n#F10#\n#F40##L10#Foresee the Future：#L0#ล่วงรู้ถึงอันตรายในอนาคต หลีกเลี่ยงความเสียหายจากสกิลได้ 1 ครั้ง (คูลดาวน์เอฟเฟกต์นี้ทุก 5 ครั้งที่ถูกโจมตี)\n#F10#\n#F40##L10#Time Ripple：#L0#เมื่อ Celebi กระทำการ หรือเมื่อเกิดเอฟเฟกต์ย้อนเวลา จะสร้าง【Time Ripple】ลดคูลดาวน์สกิลเล็กของเพื่อนร่วมทีมแบบสุ่ม 1 ตัวลง 1 เทิร์น และเพิ่มคูลดาวน์สกิลเล็กของศัตรูแบบสุ่ม 1 ตัวขึ้น 1 เทิร์น พร้อมเร่งเวลาให้【Seed Bomb】ทั้งหมดของศัตรูระเบิดเร็วขึ้น 1 เทิร์น\n#F10#\n#F40##L10#Forest Purification：#L0#เมื่อพวกเดียวกันได้รับดีบัฟครบ 3 ครั้ง จะล้างดีบัฟออกจากฝั่งเรา 2 ชิ้นทันที',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '#C0x5c9970#เมื่อโปเกมอนสาย Grass หรือ Psychic ได้รับ【Time Mark】，จะได้รับโบนัสความเสียหาย 10%; เมื่อ【Time Mark】หมด จะทำให้เป้าหมายใช้【Dispel III】อัตโนมัติ 1 ครั้ง',
