	[19643] = {
		id = 19643,
		skillName = 'ท่าไม้ตาย',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#เรียกลมเรียกฝน ขยายอาณาเขตแห่งท้องทะเล#C0x5B545B#\n#F10#\n#F40#เรียกคลื่นยักษ์พุ่งกระแทกศัตรู คลื่นจะสะท้อนไปยังศัตรูเดี่ยวอีก 6 ครั้ง แต่ละครั้งสร้างความเสียหายพิเศษ #C0x3D8A99#330% พลังโจมตีพิเศษ #C0x5B545B#+$(skillLevel*4*24)$ เป็น #C0xF13B54#ความเสียหายพิเศษ#C0x5B545B# (เป้าหมายสะท้อนต้องไม่ซ้ำกัน หากมีเป้าหมายเดียวจะไม่สะท้อน ความเสียหายเพิ่ม 100% หากอยู่คนเดียวหรือ Rain Veil จบ) แต่ละครั้งลดความเร็ว 10% และเพิ่มความเปราะธาตุน้ำ 8% (สูงสุด 5 ชั้น) เป็นเวลา 2 เทิร์น\n#F20#\n#F40#เป้าหมายที่โดนสะท้อนจะได้รับลดดาเมจที่สร้างได้ 20% เป็นเวลา 2 เทิร์น (ไม่ซ้อนกัน) หากเป้าหมายอยู่ในสถานะ Chaos Speed มีโอกาส 50% ที่จะติด Confuse 1 เทิร์น\n#F20#\n#F40#ศัตรูที่โดนสะท้อน 2 ครั้งจะติดสถานะ【Water Prison】 1 เทิร์น (หากมี【Rain Veil】จะเพิ่มเป็น 2 เทิร์น)【Water Prison】: ไม่สามารถกระทำได้ และจะดึงยูนิตใกล้เคียง 1 ตัวที่ไม่ได้อยู่ในคุกน้ำมารับดาเมจร่วม โปเกมอนธาตุน้ำฝ่ายเราจะโจมตีเป้าหมายในคุกน้ำก่อน หากคุกน้ำสะสมดาเมจถึง 65% HP ของเป้าหมาย คุกจะแตก แต่ละครั้งที่ใช้ท่าไม้ตายจะมีได้ไม่เกิน 2 คุกน้ำ',
		simDesc = 'Kyogre เรียกคลื่นยักษ์ถาโถมใส่ศัตรู คลื่นจะกระเด้งไปยังเป้าหมายเดี่ยวอื่น ๆ ของศัตรู ทุกครั้งที่กระเด้งจะลด Speed ของเป้าหมาย',
		starEffect = __data_t__starEffect[19643],
		-- {11}
		starEffectDesc = 'เอฟเฟกต์เสริม: เป้าหมายที่ถูกกระเด็นใส่จะถูกลบ Buff 2 รายการแบบสุ่ม; Pokémon ที่อยู่ใน【Water Prison】จะไม่สามารถได้รับ Buff เพิ่มเติม 1 เทิร์น และได้รับสถานะ Water Vulnerability 30% และเมื่อ Water Prison เริ่มและจบจะสร้างความเสียหายธาตุน้ำเท่ากับ 200% ของ Sp. Atk ของ Kyogre (ความเสียหายนี้ไม่คิดรวมกับการรับความเสียหายของ Water Prison)\n#F20#\n#F40#เมื่อศัตรูหลุดออกจาก【Water Prison】จะสูญเสียความสามารถในการต้านทานสถานะ Water Control, Bind, Freeze เป็นเวลา 1 เทิร์น หากโดนโจมตีโดย Pokémon ธาตุน้ำ/หญ้า/น้ำแข็ง จะฟื้นฟู HP ของผู้โจมตี 5%  ',
		zawakeEffect = __data_t__zawakeEffect[19643],
		-- {79003}
		zawakeEffectDesc = '#C0xC0C0C0#Call the Wind and Rain, Expand the Sea#C0x5B545B#\n#F10#\n#F40#เรียกคลื่นพายุขนาดใหญ่ ซึ่งจะสะท้อนไปยังศัตรูเดี่ยว 6 ครั้ง แต่ละครั้งสร้างความเสียหายพิเศษ #C0x3D8A99#330% Sp. Atk#C0x5B545B#+$(skillLevel*4*24)$ (เป้าหมายของการสะท้อนจะไม่ซ้ำกัน หากมีเป้าหมายเดียวจะไม่สะท้อน หากเป็นการต่อสู้เดี่ยวหรือ Rain Screen สิ้นสุด ความเสียหายจะเพิ่ม 100%) แต่ละครั้งจะลด Speed ของเป้าหมาย 10% และเพิ่ม Water Vulnerability 8% (สะสมได้สูงสุด 5 ชั้น) เป็นเวลา 2 เทิร์น\n#F20#\n#F40#เป้าหมายที่ถูกสะท้อนจะลด Damage Bonus 20% เป็นเวลา 2 เทิร์น (ไม่สามารถซ้อนทับได้) หากเป้าหมายอยู่ในสถานะ Speed Chaos จะมีโอกาส 50% ติดสถานะ Confused เป็นเวลา 1 เทิร์น\n#F20#\n#F40#เป้าหมายที่โดนสะท้อน 2 ครั้งจะติด【Water Prison】เป็นเวลา 1 เทิร์น (เมื่อมี【Rain Screen】จะเพิ่มเป็น 2 เทิร์น), 【Water Prison】: ไม่สามารถเคลื่อนไหวได้ และจะดึงยูนิตรอบข้างที่ไม่อยู่ใน Water Prison มารับความเสียหาร่วมกัน Pokémon ธาตุน้ำฝ่ายเราจะโจมตีเป้าหมายใน Water Prison ก่อนเสมอ Water Prison จะแตกเมื่อรับความเสียหายสะสมถึง 65% ของ Max HP เป้าหมาย ท่าไม้ตายแต่ละครั้งสามารถสร้างได้สูงสุด 2 Water Prison; เป้าหมายที่หลุดออกจาก Water Prison จะติดสถานะ【Whirlpool】เป็นเวลา 1 เทิร์น, 【Whirlpool】: เป็นดีบัฟพิเศษ ไม่สามารถลบได้ ลด Base Speed และ Base Anger Regen Speed 60% ทุกครั้งที่เกิด Whirlpool ครบ 3 ครั้งจะพัฒนาเป็น【Suffocate】 (หลังเกิดจะรีเซ็ตการนับ), 【Suffocate】: เป็นสถานะควบคุม ไม่สามารถลบ/ชำระล้าง จะได้รับความเสียหายน้ำทันที 20% ของ HP ปัจจุบัน ไม่สามารถเคลื่อนไหวและไม่สามารถฟื้น Anger; ความเสียหายจาก Active Skill ของ Water-type Pokémon ฝ่ายเราจะกลายเป็น Water-element Damage ใส่เป้าหมายที่อยู่ใน Whirlpool/Suffocate และจะฟื้น HP 80% ของความเสียหายให้ Water-type Pokémon ที่มี HP น้อยที่สุดในทีม',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#หน่วยที่ถูกควบคุมด้วย Water Prison จะติดสถานะ【Whirlpool】1 เทิร์นหลังจาก Water Prison หายไป 【Whirlpool】: เอฟเฟกต์ดีบัฟพิเศษ ไม่สามารถลบล้างได้ เป้าหมายที่อยู่ใน Whirlpool จะลดความเร็วพื้นฐานและอัตราฟื้นฟูเกจโกรธพื้นฐานลง 60% เมื่อเกิด【Whirlpool】ครบ 3 ครั้ง จะพัฒนาเป็น【Asphyxia】 (หลังจาก Asphyxia จะเริ่มนับใหม่) 【Asphyxia】: เอฟเฟกต์ควบคุม ไม่สามารถลบล้าง/ชำระล้าง สูญเสีย HP ปัจจุบัน 20% เป็นความเสียหายธาตุน้ำทันที และไม่สามารถเคลื่อนไหวหรือฟื้นเกจโกรธได้ การโจมตีของโปเกมอนธาตุน้ำฝ่ายเราที่ใช้สกิลจะส่งผลเป็นความเสียหายธาตุน้ำใส่เป้าหมายที่อยู่ใน【Whirlpool/Asphyxia】และฟื้นฟู 80% ของความเสียหายที่ทำได้ให้กับโปเกมอนธาตุน้ำของเราที่มี HP ต่ำที่สุด',
