	[19926] = {
		id = 19926,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xB15BFF#<เซิร์ฟเวอร์ทดสอบ>#C0x5B545B##L10#Wishing Paper:#L0# Jirachi จะใช้สุ่มหนึ่งใน 【Wishing Paper】 เพื่ออธิษฐานหลังจบเทิร์นของตนเอง เอฟเฟกต์คงอยู่ 1 เทิร์น\n#F10#\n#F40#① Wish of Healing: ฟื้นฟู 50% HP ที่สูญเสียให้กับเป้าหมายที่ HP ต่ำที่สุด และเพิ่มพลังป้องกันความเสียหาย 30%-#C0xEE0000#50%#C0x5B545B#\n② Power of Meteors: เพิ่มอัตราคริติคอลและดาเมจคริติคอล 30% ให้เป้าหมายที่มีคริติคอลสูงสุด หากคริติคอลจะยิง Meteor Beam ใส่ศัตรูสุ่ม 1 ตัว สร้างความเสียหายทางกายภาพ 180% พลังโจมตีกายภาพของ Jirachi และมีโอกาส #C0xFFB90F#100%#C0x5B545B# ทำให้เป้าหมายติดสถานะ Stun 1 เทิร์น\n③ Mysterious Guard: จะล้างสถานะควบคุมที่สามารถล้างได้ให้เพื่อนที่กำลังถูกควบคุมก่อน และทำให้ได้รับการป้องกันควบคุมที่ล้างได้\n#F10#\n#F40#เมื่ออธิษฐานด้วย Wishing Paper ใด ๆ Jirachi จะได้รับ 1 ชั้นของ 【Star Wish】 และรีเซ็ตคูลดาวน์สกิลย่อย (Star Wish: เอฟเฟกต์เสริม, ไม่สามารถลบได้, เพิ่มค่าสถานะพื้นฐาน 10%, เพิ่มดาเมจจาก Meteor 30%, และเพิ่มโอกาสฟักไข่ 10% สะสมได้สูงสุด 5 ชั้น)\n#F20#\n#F40##L10#Cocoon of Slumber:#L0# เมื่อตกอยู่ในสถานะใกล้ตาย Jirachi จะถูกปิดผนึกเข้าสู่ Cocoon of Slumber ซึ่งจะหยุดการอธิษฐาน ในขณะอยู่ในรังนั้นจะมี HP เท่ากับ 50% ของ Jirachi และศัตรูที่โจมตี Cocoon จะถูกโจมตีกลับด้วย Meteor Counter สร้างความเสียหาย 180% พลังโจมตีกายภาพของ Jirachi และมีโอกาส #C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B# ทำให้เป้าหมายติดสถานะ Stun 1 เทิร์น\n#F20#\n#F40##L10#Beast of the Earth:#L0# เมื่อตาย Jirachi มีโอกาส 30% ที่จะฟักเป็น “Beast of the Earth” โจมตีศัตรูทุกตัวด้วยความเสียหายทางกายภาพ 400%-#C0xEE0000#1000%#C0x5B545B# ของพลังโจมตี Jirachi ก่อนจะหายตัวไป',
		starEffect = __data_t__starEffect[19926],
		-- {8}
		starEffectDesc = 'ก่อนเริ่ม 3 เทิร์นใหญ่แรกของการลงสนาม จะสามารถใช้【Wish Paper】ได้เพิ่มเติม 1 ครั้ง และเอฟเฟกต์ของ Wish Paper จะถูกเพิ่มพลังแบบถาวร',
		zawakeEffect = __data_t__zawakeEffect[19926],
		-- {79004}
		zawakeEffectDesc = '#C0xC0C0C0#★Listen, the stars are speaking~☆#C0x5B545B#\n#F10#\n#F40##L10#Wishing Note:#L0# หลังสิ้นสุดเทิร์น Jirachi จะสุ่มใช้ Wishing Note 1 แบบเพื่ออธิษฐาน (มีโอกาส 7% ที่จะเกิด Heaven’s Grace: ปล่อยทั้ง 3 แบบพร้อมกัน), เอฟเฟกต์คงอยู่ 1 เทิร์น\n#F10#\n#F40#① #C0x32CD32#Wish of Healing:#C0x5B545B# เลือกเป้าหมายที่มี HP เปอร์เซ็นต์ต่ำสุด เพิ่ม Damage Reduction 30% (หากเต็ม HP จะได้เพิ่มอีก 20%), ฟื้น HP 40% ทันที และอีก 30% เมื่อเริ่มเทิร์นของเป้าหมาย\n② #C0x9932CC#Meteor Power:#C0x5B545B# เพิ่ม Critical Rate และ Damage Bonus 35% ให้กับเป้าหมายที่มี Crit สูงสุด, เมื่อทำคริติคอลจะปล่อย Meteor Beam สร้าง Physical Damage #C0xE69900#170% Atk#C0x5B545B# แก่ศัตรูแบบสุ่ม และมีโอกาส 90% ทำให้ติด【Stun】1 เทิร์น\n③ #C0x87CEFA#Mystic Protection:#C0x5B545B# เลือกเพื่อนที่ติดสถานะควบคุมเพื่อลบและมอบ Immunity ต่อสถานะควบคุมที่สามารถลบได้, หากไม่มีสถานะควบคุม จะลบดีบัฟสูงสุด 3 อัน\n#F10#\n#F40#ทุกครั้งที่อธิษฐานครบชุด Wishing Note ทั้ง 3 แบบ Jirachi จะได้รับ 1 ชั้นของ【Star Wish】และรีเซ็ตคูลดาวน์สกิลทั่วไป (Star Wish: บัฟ ไม่สามารถลบ เพิ่มค่าสถานะพื้นฐาน 10%, สูงสุด 5 ชั้น)\n#F20#\n#F40##L10#Cocoon of Slumber:#L0# เมื่อได้รับดาเมจ致死 Jirachi จะเข้าสู่ Cocoon of Slumber และหยุดการอธิษฐาน, Cocoon มี HP เท่ากับ 70% ของ Jirachi และศัตรูที่โจมตี Cocoon จะโดน Meteor Counter สร้าง Physical Damage #C0xE69900#170% Atk#C0x5B545B# และมีโอกาส #C0x5c9970#$(20+skillLevel*0.3-0.3)$%#C0x5B545B# ทำให้ติด【Stun】1 เทิร์น\n#F20#\n#F40##L10#Creature of the Earth:#L0# เมื่อ Jirachi ตาย จะมีโอกาส 35% เรียก Creature of the Earth โจมตีศัตรูทั้งหมด สร้าง Physical Damage #C0xE69900#570% Atk#C0x5B545B# แล้วหายไป, ทุกครั้งที่ได้รับดีบัฟหรือสถานะควบคุม จะเพิ่มโอกาสเกิดขึ้นอีก 3%',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'ค่าสัมประสิทธิ์ความเสียหายพื้นฐานเพิ่มขึ้น (รายละเอียดเอฟเฟกต์จะมีการปรับปรุงในอนาคต)',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
