	[24216] = {
		id = 24216,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#mana~ มาเล่นที่วิหารทะเลกันเถอะ!#C0x5B545B#\n#F10#\n#F40##L10#Wishiwashi Swarm#L0#: ทุกเทิร์นของ Manaphy จะเรียก Wishiwashi ไปก่อกวนศัตรูแบบสุ่ม เป้าหมายจะได้รับสถานะ【Aqua Weaken】；หากมี Wishiwashi สะสมครบ 5 ตัว จะรวมตัวกลายเป็นฝูงล้อมเป้าหมายที่มีมากที่สุด สร้างความเสียหายพิเศษ 450% ไม่สามารถโจมตีศัตรูโดยตรงได้ 1 ครั้งหรือ 1 เทิร์น แล้วจะสลาย\n#F10#\n#F40#【Aqua Weaken】: รับความเสียหายจากน้ำเพิ่ม 5% และโจมตีธาตุน้ำแรงน้อยลง 5%, สะสมได้สูงสุด 5 ชั้น\n#F40##L10#Seadra Guardian#L0#: เมื่อลงสนามและทุกเทิร์นจะเรียก Seadra (มี HP และค่าสถานะ 100% ตาม Manaphy) เมื่อ Manaphy โจมตี Seadra จะโจมตีด้วยความเสียหายพิเศษ 200% และใส่【Poison】2 เทิร์น (ทุกเทิร์นเป้าหมายจะโดนความเสียหายธาตุพิษตาม 100% พลังพิเศษของ Seadra) หาก Manaphy ถูกโจมตีด้วยสกิล Seadra มีโอกาส 50% รับความเสียหายแทน\n#F10#\n#F40##L10#Ocean’s Blessing#L0#: เมื่อฝ่ายเรามีการอัญเชิญโปเกมอนธาตุน้ำ จะลบดีบัฟ 1 อย่างจาก Manaphy；หากไม่มีดีบัฟ จะฟื้น HP 10% ให้กับโปเกมอนน้ำหรือเยือกแข็งแบบสุ่ม；เมื่อโปเกมอนน้ำ/น้ำแข็งโจมตี จะใส่สถานะ【Water Slow】ให้ศัตรู หากทีมเรามีโปเกมอนน้ำ/น้ำแข็งที่ไม่ใช่ซัมมอนครบ 3 ตัว จะป้องกันไม่ให้โดนลดโกรธหรือ Blind；【Water Slow】: ลดความเร็วและคริติคอล 5% นาน 2 เทิร์น สะสมได้ 4 ชั้น',
		starEffect = __data_t__starEffect[24216],
		-- {8}
		starEffectDesc = '\nเอฟเฟกต์เสริม: เพิ่ม HP 20% และ Damage 10% ให้กับหน่วยที่ถูกเรียกทั้งหมดในสนาม\n#F10# \n#F40#Schooling Wishiwashi เสริม: Pokémon ธาตุน้ำจะเรียก Wishiwashi โจมตีศัตรูแบบสุ่มทุกครั้งที่เคลื่อนไหว\n#F10# \n#F40#Sea Dragon Guard เสริม: ปรับเป็นการเรียก Sea Dragon ทุกๆ 1 เทิร์น',
		zawakeEffect = __data_t__zawakeEffect[24216],
		-- {79004}
		zawakeEffectDesc = '#C0xC0C0C0#mana~ มาเล่นด้วยกันในวิหารแห่งท้องทะเลเถอะ!#C0x5B545B#\n#F10#\n#F40##L10#Wishiwashi Swarm#L0#：เทิร์นของ Manaphy จะเรียก Wishiwashi โจมตีศัตรูแบบสุ่ม แต่ละตัวจะทำให้ติด【Soft Water】；เมื่อศัตรูมี Wishiwashi ครบ 5 ตัว จะรวมฝูงโจมตีศัตรูที่มีมากสุดทันที สร้าง 450% Sp.Atk ความเสียหาย พวกที่โดนฝูงล้อมจะไม่สามารถเลือกเป้าหมายโจมตีได้โดยตรง และจะหลุดจากฝูงเมื่อโจมตี 1 ครั้งหรือผ่านไป 1 เทิร์น\n#F10#\n#F40#【Soft Water】：ได้รับ Water Vulnerability 5% ลดดาเมจที่ทำต่อ Water-type 5% ซ้อนสูงสุด 5 ชั้น\n#F40##L10#Seadra’s Guard#L0#：เมื่อเข้าสนามและทุกเทิร์น จะอัญเชิญ Seadra 1 ตัว (สืบทอด HP 100% และค่าสถานะอื่น 100%) เมื่อ Manaphy โจมตี Seadra จะช่วยโจมตีด้วย 200% Sp.Atk พร้อมติด Poison 2 เทิร์น (แต่ละเทิร์นสร้าง Poison ดาเมจตาม 100% Sp.Atk ของ Seadra) เมื่อ Manaphy โดนท่าไม้ตาย มีโอกาส 50% ให้ Seadra รับแทน\n#F10#\n#F40##L10#Sea God\'s Blessing#L0#：ทุกครั้งที่อัญเชิญโปเกมอนสาย Water จะลบสถานะผิดปกติ 1 อย่างจาก Manaphy；หากไม่มีสถานะผิดปกติ จะฟื้น HP 10% ให้พวกพ้องสาย Water หรือ Ice；เมื่อโจมตีด้วยโปเกมอน Water/Ice จะติด【Water Slow】 หากมีโปเกมอน Water/Ice (ไม่ใช่อัญเชิญ) อย่างน้อย 3 ตัว จะกันการลดเกจโกรธและ Blind【Water Slow】：ลด SPD 5% ลดคริติคอล 5% นาน 2 เทิร์น ซ้อนสูงสุด 4 ชั้น',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '#C0x5c9970#【Dragalge】สืบทอดค่าสถานะของผู้เรียก 150%, เมื่อ HP ของ Manaphy ต่ำกว่า 50% เป็นครั้งแรก จะเพิ่มค่าสถานะทั้งหมดของตนเอง 10%',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
