	[24316] = {
		id = 24316,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = 'ออร่าพิเศษ: เมื่อโปเกมอนธาตุ Dark ฝ่ายเราใช้การโจมตีปกติ จะขโมยพลังโจมตีทั้งสองประเภทของเป้าหมาย #C0x5c9970#$(3+skillLevel*0.03-0.03)$%#C0x5B545B# อย่างถาวร (คืนเมื่อเสียชีวิต)；\nก่อนเริ่มการกระทำ Darkrai มีโอกาส 50% ทำให้ยูนิตสุ่ม 1 ตัวเข้าสู่【Deep Sleep】1 เทิร์น (ไม่สามารถกระทำการ ถูกปลุกเมื่อถูกสกิลโจมตี 2 ครั้ง หรือลบสถานะได้)；\nDarkrai จะไม่ปลุกเป้าหมายเมื่อโจมตีเป้าหมายที่อยู่ในสถานะ Sleep หรือ Nightmare',
		starEffect = __data_t__starEffect[24316],
		-- {8}
		starEffectDesc = 'เอฟเฟกต์เสริม: Darkrai ไม่ติด Sleep และ Nightmare และเมื่อโจมตีเป้าหมายที่อยู่ในสถานะ Sleep หรือ Nightmare จะขโมย Buff 1 อย่างของเป้าหมาย',
		zawakeEffect = __data_t__zawakeEffect[24316],
		-- {79004}
		zawakeEffectDesc = 'ออร่าพิเศษ: เมื่อโปเกมอนฝ่ายเราประเภท Dark/Ghost ใช้การโจมตีธรรมดาหรือสกิลเล็กโจมตี จะขโมย Atk และ Sp.Atk พื้นฐานของเป้าหมายที่โดนโจมตีแบบถาวร #C0x5c9970#$(3+skillLevel*0.03-0.03)$%#C0x5B545B# (จะคืนกลับเมื่อเสียชีวิต)\nในเทิร์นแรกของการต่อสู้ หากมีโปเกมอนประเภท Dark/Ghost ฝ่ายเราตั้งแต่ 2 ตัวขึ้นไป จะทำการขโมยเกจโกรธของศัตรูแบบสุ่ม 4 ตัว ตัวละ 100 แต้ม รวมทั้งหมดจะถูกแบ่งเท่าๆ กันให้โปเกมอน Dark/Ghost ฝ่ายเรา',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'ออร่า Dark พัฒนาเป็นออร่า Dark Ghost: เมื่อโปเกมอนธาตุ Dark/Ghost ฝ่ายเราโจมตีด้วยการโจมตีปกติหรือสกิลย่อย จะขโมยพลังโจมตีพื้นฐานทั้งสองของเป้าหมายแบบถาวร\nเมื่อเริ่มการต่อสู้ หากมีโปเกมอนธาตุ Dark/Ghost 2 ตัวขึ้นไป จะขโมยเกจโกรธ 100 หน่วยจากศัตรูแบบสุ่ม 4 ตัว และแบ่งเกจโกรธที่ขโมยได้อย่างเท่าเทียมให้โปเกมอนธาตุ Dark/Ghost ฝ่ายเรา',
