	[24416] = {
		id = 24416,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = 'ในสนามเทิร์นที่ 1–3 อยู่ใน【Land Forme】เทิร์นที่ 4–6 เปลี่ยนเป็น【Sky Forme】 (สลับไปมาแบบนี้)\n#F20# \n#F40#【Land Forme】สามารถสร้าง【Barrier】ให้ทีมเพื่อบล็อคการโจมตีแบบเส้นตรง 3 ครั้งในเทิร์นใหญ่ (แนวหน้าบล็อคได้ #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# แนวหลัง #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B#)\n#F20# \n#F40#ทุกครั้งที่ปรากฏใน【Land Forme】จะวาง【Bouquet Seed】ไว้หน้าทีม มีผล 2 เทิร์นใหญ่: ยูนิต 3 ตัวที่ HP ต่ำสุดจะฟื้น HP ก่อนเทิร์น (60% พลังพิเศษของ Shaymin)\n#F20# \n#F40#เมื่อ【Bouquet Seed】หายไป Shaymin ฟื้นโกรธ 500 แต้ม และมีโอกาส 40% ทำให้ศัตรูทั้งหมดติด【Bind】1 เทิร์น\n#F20# \n#F40#【Sunny Day】เมื่อ Shaymin ลงสนาม ทีมจะได้รับสภาพอากาศ【Sunny Day】ที่ช่วยให้โปเกมอนธาตุ Grass ของทั้งสองฝ่าย เพิ่มอัตราการฟื้นฟู 30% ความเสียหาย 20% และฟื้น HP 10% ต่อเทิร์น (สุ่มเริ่มแต่ละครั้งนาน 3 เทิร์น)',
		starEffect = __data_t__starEffect[24416],
		-- {8}
		starEffectDesc = 'เอฟเฟกต์เสริม: ขณะมี Bouquet Seed อยู่ Shaymin จะเปลี่ยน 12% ของความเสียหายที่ได้รับให้กลายเป็นการฟื้น HP',
		zawakeEffect = __data_t__zawakeEffect[24416],
		-- {79004}
		zawakeEffectDesc = 'ในสนาม เทิร์นที่ 1–3 จะอยู่ใน【#L10#Land Forme#L0#】 เทิร์นที่ 4–6 จะเปลี่ยนเป็น【#L10#Sky Forme#L0#】 (วนลูป)\n#F20# \n#F40#【#L10#Land Forme#L0#】สามารถสร้าง【#L10#Barrier#L0#】เพื่อป้องกันการโจมตีแบบเส้นตรง 3 ครั้งแรกในรอบใหญ่ (ยูนิตหน้าได้รับการลดดาเมจ #C0x5c9970#$(10+skillLevel*0.1-0.1)$%#C0x5B545B# ยูนิตหลังลด #C0x5c9970#$(20+skillLevel*0.2-0.2)$%#C0x5B545B#)\n#F20# \n#F40#เมื่อเข้าสู่สนามใน【#L10#Land Forme#L0#】จะวาง【#L10#Bouquet Seed#L0#】หน้าแนวรบฝ่ายเรานาน 2 รอบใหญ่: ยูนิต 3 ตัวที่มี HP ต่ำสุดจะฟื้น HP ก่อนเคลื่อนไหว (60% Sp.Atk ของ Shaymin)\n#F20# \n#F40#เมื่อ【#L10#Bouquet Seed#L0#】หายไป Shaymin จะฟื้น 500 เกจโกรธ และมีโอกาส 40% ทำให้ศัตรูแต่ละตัวติด Bind 1 เทิร์น\n#F20# \n#F40#【#L10#Sunny Day#L0#】เมื่อ Shaymin เข้าสนาม จะสร้างสภาพอากาศ Sunny Day ช่วงจัดทีม ทำให้โปเกมอนสาย Grass ทั้งสองฝ่ายเพิ่ม Healing Rate 30% เพิ่มดาเมจ 20% และฟื้นฟู HP 10% ทุกเทิร์น (สุ่มเปิดแต่ละครั้งอยู่ 3 เทิร์น)',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '【Flower Seed】เอฟเฟกต์เพิ่มขึ้น: เพื่อนร่วมทีมทั้งหมดสามารถรับการฟื้นฟูได้ ฟื้นฟูโปเกมอนธาตุ Fairy, Grass, Ground เพิ่มขึ้นอีก 50%; เมื่อเข้าสนาม Shaymin จะได้รับเอฟเฟกต์【Gratitude of Heart】 (จำกัด 1 ครั้งต่อการต่อสู้)',
