	[24426] = {
		id = 24426,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = 'ในสนามเทิร์นที่ 1–3 อยู่ใน【Sky Forme】เทิร์นที่ 4–6 เปลี่ยนเป็น【Land Forme】 (สลับไปมาแบบนี้)\n#F20# \n#F40#ทุกครั้งที่เริ่มเทิร์นใหญ่ใน【Sky Forme】 ลดประสิทธิภาพการรักษาและพลังป้องกันทั้งสองประเภทของศัตรูแถวหน้าแบบสุ่ม 2 ตัว #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# นาน 1 เทิร์นใหญ่\n#F20# \n#F40#ทุกครั้งที่ปรากฏใน【Sky Forme】จะวาง【Sky Bloom】ไว้หน้าทีม มีผล 2 เทิร์นใหญ่: ก่อนเทิร์น Shaymin จะฟื้นโกรธ 150 แต้ม และยูนิต 3 ตัวแรกของทีมที่ได้เทิร์นจะได้รับบัฟเพิ่มพลังโจมตีทั้งสอง 12% และอัตราคริติคอล 12% นาน 1 เทิร์น\n#F20# \n#F40#เมื่อ【Sky Bloom】หายไป หรือใช้ท่าไม้ตายครั้งแรกใน【Sky Forme】จะเพิ่มพลังพิเศษและโบนัสความเสียหายถาวร 20% ให้กับ Shaymin (ไม่สามารถซ้อนทับ) \n#F20# \n#F40#【Sunny Day】เมื่อ Shaymin ลงสนาม ทีมจะได้รับสภาพอากาศ【Sunny Day】ที่ช่วยให้โปเกมอนธาตุ Grass ของทั้งสองฝ่าย เพิ่มอัตราการฟื้นฟู 30% ความเสียหาย 20% และฟื้น HP 10% ต่อเทิร์น (สุ่มเริ่มแต่ละครั้งนาน 3 เทิร์น)',
		starEffect = __data_t__starEffect[24426],
		-- {8}
		starEffectDesc = 'เอฟเฟกต์เสริม: ขณะมี Sky Flower อยู่ จะได้รับ Healing Bonus จากการโจมตี 20% (ความเสียหายที่สร้างสามารถฟื้น HP ตามสัดส่วน)',
		zawakeEffect = __data_t__zawakeEffect[24426],
		-- {79004}
		zawakeEffectDesc = 'ในสนาม เทิร์นที่ 1–3 จะอยู่ใน【#L10#Sky Forme#L0#】 เทิร์นที่ 4–6 จะเปลี่ยนเป็น【#L10#Land Forme#L0#】 (วนลูป)\n#F20# \n#F40#ในแต่ละรอบใหญ่ของ【#L10#Sky Forme#L0#】จะลด Healing Received และ Def/Sp.Def ของศัตรูแถวหน้าสุ่ม 2 ตัวลง #C0x5c9970#$(30+skillLevel*0.2-0.2)$%#C0x5B545B# นาน 1 รอบใหญ่\n#F20# \n#F40#เมื่อเข้าสู่สนามใน【#L10#Sky Forme#L0#】จะวาง【#L10#Sky Flower#L0#】หน้าแนวรบฝ่ายเรานาน 2 รอบใหญ่: ก่อนเคลื่อนไหว Shaymin ฟื้น 150 เกจโกรธ เพิ่ม Atk/Sp.Atk 12% และ Crit Rate 12% ให้ยูนิต 3 ตัวแรกที่เคลื่อนไหว (1 เทิร์น)\n#F20# \n#F40#เมื่อ【#L10#Sky Flower#L0#】หายไป หรือใช้ท่าไม้ตายครั้งแรกใน【#L10#Sky Forme#L0#】จะเพิ่มถาวร Sp.Atk และ Damage Bonus ของ Shaymin 20% (ไม่สามารถซ้อน)\n#F20# \n#F40#【#L10#Sunny Day#L0#】เมื่อ Shaymin เข้าสนาม จะสร้างสภาพอากาศ Sunny Day ช่วงจัดทีม ทำให้โปเกมอนสาย Grass ทั้งสองฝ่ายเพิ่ม Healing Rate 30% เพิ่มดาเมจ 20% และฟื้นฟู HP 10% ทุกเทิร์น (สุ่มเปิดแต่ละครั้งอยู่ 3 เทิร์น)',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '【Sky Bloom】เอฟเฟกต์เพิ่มขึ้น: เพื่อนร่วมทีมทุกตัวจะได้รับโบนัส 12% พลังโจมตีสองด้านและคริติคอลเรต ก่อนเทิร์นเริ่มต้น (1 เทิร์น) และหลังจากเทิร์นจะฟื้นฟู HP เท่ากับ 60% ของพลังโจมตีสองด้านของตนเอง; เมื่อเข้าสนาม Shaymin จะได้รับเอฟเฟกต์【Gratitude of Heart】 (จำกัด 1 ครั้งต่อการต่อสู้)',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		changeUnitTrigger = true,
		isCombat = true,
		skillType = 3,
		skillType2 = 3,
