	[24612] = {
		id = 24612,
		skillName = 'สกิลพิเศษ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#V เย่! จับได้แล้วล่ะ!V#C0x5B545B#\n#F10#\n#F40#Victini โจมตีเป้าหมายหน้าและหลังอย่างละ 1 ตัว สร้างความเสียหายพิเศษ 90% + $(skillLevel*4*60)$ เป็นความเสียหายพิเศษ ติดสถานะ【Blazing Chain】และ【Burn】2 เทิร์น และเข้าสู่สถานะ【Spirit Flame】จนจบเทิร์นใหญ่ถัดไป\n#F10#\n#F40#【Blazing Chain】: สถานะควบคุมประเภทบังคับ ยกเลิกเมื่อสถานะ Spirit Flame จบหรือถูกขัดจังหวะ\n#F10#\n#F40#【Spirit Flame】: สถานะพิเศษ ไม่สามารถกระทำการ ไม่ได้รับความเสียหายแต่ยังคงได้รับผลต่าง ๆ (ถูกควบคุมจะถูกขัดจังหวะได้) มอบพลังป้องกัน 50% ให้แนวหน้า และมอบพลังโจมตี 20% ให้แนวหลังแบบสุ่ม (โปเกมอนไฟ/พลังจิตจะมีลำดับก่อน) ถูกโจมตีจะฟื้นโกรธ 150 แต้ม；เมื่อสิ้นสุดสถานะจะได้รับ【Flame Armor】2 เทิร์น',
		zawakeEffect = __data_t__zawakeEffect[24612],
		-- {79002}
		zawakeEffectDesc = '#C0xC0C0C0#V เย่! จับเธอได้แล้ว!V#C0x5B545B#\n#F10#\n#F40#Victini โจมตีศัตรูแถวหน้าและหลังอย่างละตัว สร้าง#C0x3D8A99#90% Sp.Atk#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54#ความเสียหายพิเศษ#C0x5B545B# ทำให้ติด【Flame Bind】และ Burn 2 เทิร์น ตนเองเข้าสู่สถานะ【Blazing Spirit】จนจบรอบใหญ่ถัดไป\n#F10#\n#F40#【Flame Bind】：เอฟเฟกต์ควบคุมแบบครอบงำ จะหายเมื่อ Blazing Spirit สิ้นสุดหรือถูกขัดจังหวะ\n#F10#\n#F40#【Blazing Spirit】：สถานะพิเศษ ไม่สามารถเคลื่อนไหว ไม่รับความเสียหาย แต่สามารถโดนดีบัฟ (ถ้าโดนควบคุมแบบขัดขวางจะถูกยกเลิก) แบ่ง Def และ Sp.Def 50% ให้แถวหน้าฝ่ายเรา และแบ่ง Atk และ Sp.Atk 20% ให้แถวหลังแบบสุ่ม (สาย Fire/Psychic มีสิทธิมากกว่า) โดนสกิลจะฟื้น 150 เกจโกรธ ตนเอง SPD +10% (สะสม 3 ชั้น) และทำให้ผู้โจมตีติด Burn 2 เทิร์น เมื่อ Blazing Spirit สิ้นสุดหรือถูกยกเลิก จะได้【Flame Armor】2 เทิร์น',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'ขณะอยู่ในสถานะ Flame Spirit การได้รับสกิลดาเมจจะเพิ่มความเร็ว 10% (สะสมได้ 3 ชั้น) และทำให้ผู้โจมตีติด Burn 2 เทิร์น',
