	[24636] = {
		id = 24636,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#V ง่ำ ๆ... อยากลองมาการองบ้างมั้ย?V#C0x5B545B#\n#F10#\n#F40##L10#Blazing Inferno#L0#: ขณะอยู่ในสนาม โปเกมอนธาตุไฟฝ่ายเราจะไม่ติด Freeze และ Bind ความเสียหายจากสถานะ Burn เพิ่มขึ้น #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# และเพิ่มระยะเวลาขึ้น 1 เทิร์น\nเมื่อวาง Burn ครบ 3 ชั้นจะทำให้เป้าหมายติด Fire Weakness 12% ครบ 4 ชั้นจะไม่สามารถสะสมโกรธจาก Burn ครบ 5 ชั้นจะสร้างความเสียหายพิเศษ 100% ของพลังพิเศษของ Victini (เพิ่มอีก 50% ต่อโปเกมอนไฟในทีม 1 ตัว, คูลดาวน์ 2 เทิร์น)\n#F10#\n#F40#เมื่อลงสนาม Victini จะได้รับ【Flame Armor】2 เทิร์น และเมื่อได้ Flame Armor จะเพิ่มพลังป้องกัน 40%\n#F10#\n#F40##L10#Victory Dawn#L0#: ทุกครั้งที่เราสังหารศัตรู 1 ตัว ฝ่ายเราจะได้รับกำลังใจ เพิ่มความเร็วและพลังโจมตีเริ่มต้น 20% นาน 2 เทิร์น โปเกมอนไฟจะได้พลังโกรธ 200 แต้ม (ยังคงมีผลในช่วง Victory Flame) และ Victini จะใช้ท่าไม้ตาย【Meteor Flame】อีกครั้งทันที\n#F10#\n#F40##L10#Victory Flame#L0#: เมื่อตายจะกลายเป็น【Victory Flame】 กระตุ้นฝ่ายเราให้ได้รับโกรธเพิ่มขึ้น 50% และคริติคอล+ความแรงคริติคอล 20% นาน 2 เทิร์น โปเกมอนไฟได้พลังโกรธ 300 แต้ม หากพลังโกรธเต็ม จะลบสถานะควบคุมที่ไม่ใช่บังคับทั้งหมดและใช้ท่าไม้ตายทันที โปเกมอนไฟตัวสุดท้ายที่เหลือจะหลอมรวมกับ Victory Flame ฟื้น HP 50% และรับพลังโจมตีจาก Victini 20% ลบสถานะควบคุมและดีบัฟทั้งหมด รอดจากความตาย 1 ครั้ง และได้รับ【Double Flame Armor】',
		starEffect = __data_t__starEffect[24636],
		-- {8}
		starEffectDesc = 'ก่อนแต่ละเทิร์นใหญ่ มอบ Macaron ให้กับ Pokémon ฝ่ายเดียวกันทุกตัว 1 ชิ้น (Pokémon ธาตุไฟได้รับเพิ่มอีก 1 ชิ้น สะสมได้สูงสุด 3 ชิ้น)【Macaron】: เมื่อ Pokémon ธาตุไฟติดสถานะควบคุม หรือ Pokémon อื่นติดดีบัฟ จะกิน Macaron เพื่อป้องกันเอฟเฟกต์นั้น และหากเป็น Pokémon ธาตุไฟจะฟื้น HP 8% และเพิ่ม Atk/Sp. Atk 10% เป็นเวลา 2 เทิร์น; เมื่อจบเทิร์นใหญ่จะเก็บไว้ได้สูงสุด 1 ชิ้น และกินส่วนเกิน\nในเทิร์นเริ่มต้นของการต่อสู้ จะเผาศัตรูทั้งหมดเป็นเวลา 2 เทิร์นทุก 2 เทิร์น และ Flame Armor ของ Victini สามารถซ้อนทับกลายเป็น Double Flame Armor',
		zawakeEffect = __data_t__zawakeEffect[24636],
		-- {79004}
		zawakeEffectDesc = '#C0xC0C0C0#V งั่มๆ… อยากกินมาการองด้วยกันไหม?V#C0x5B545B#\n#F10#\n#F40##L10#Blazing Field#L0#：ขณะอยู่ในสนาม โปเกมอนสาย Fire ฝ่ายเราจะกัน Freeze และ Bind ดาเมจจาก Burn เพิ่ม #C0x5c9970#$(40+skillLevel*0.4-0.4)$%#C0x5B545B# และระยะเวลา Burn +1 เทิร์น\nเมื่อมี Burn อย่างน้อย 3 ชั้นในสนาม จะทำให้ศัตรูติด Fire Vulnerability 12% เมื่อมี 4 ชั้น ศัตรูจะไม่ได้รับโกรธจาก Burn ดาเมจ\nเมื่อมี 5 ชั้น จะสร้างดาเมจ 100% Sp.Atk ของ Victini (แต่ละสาย Fire ที่อยู่ เพิ่มดาเมจอีก 50% Sp.Atk ของ Victini ใช้ได้ทุก 2 เทิร์น)\n#F10#\n#F40#เมื่อเข้าร่วมสนาม Victini ได้【Flame Armor】2 เทิร์น และขณะได้รับ Flame Armor เพิ่ม Def และ Sp.Def 40%\n#F10#\n#F40##L10#Victory Dawn：#L0#ทุกครั้งที่เลือดศัตรูลดต่ำกว่า 40% ครั้งแรก หรือเมื่อกำจัดศัตรูได้ จะกระตุ้นขวัญกำลังใจฝ่ายเราทั้งทีม：เพิ่ม SPD และ Atk/Sp.Atk 20% นาน 2 เทิร์น；เมื่อกำจัดศัตรูได้ สาย Fire จะได้โกรธ 200 แต้ม (ยังคงทำงานแม้ขณะอยู่ในสถานะ Victory Flame)；และ Victini จะใช้ #L10#Fire Meteor 1 ครั้งทันที\n#F10#\n#F40##L10#Victory Flame：#L0#เมื่อถูก K.O. จะกลายเป็น【Victory Flame】ทันที สร้างดาเมจพิเศษ 400% Sp.Atk ให้ศัตรูที่มีโกรธสูงสุด และเผาโกรธของเป้าหมายทิ้ง ทำให้ฝ่ายเราทั้งทีมเข้าสู่สถานะ Rage ฟื้นเกจโกรธไวขึ้น 50% เพิ่ม Crit & Crit Dmg 20% นาน 2 เทิร์น；สาย Fire ได้โกรธ 300 แต้ม หากเต็มจะล้างดีบัฟที่ไม่ใช่ควบคุมแบบครอบงำและใช้ท่าไม้ตายทันที；โปเกมอนสาย Fire ตัวสุดท้ายที่อยู่รอดจะรวมร่างกับ Victory Flame ฟื้น 50% HP สูงสุด และได้ Atk/Sp.Atk จาก Victini 20% พร้อม Damage Bonus และ Damage Resist 20% นาน 2 เทิร์น；ล้างสถานะผิดปกติทั้งหมด เมื่อตายจะชะลอ 1 เทิร์น พร้อมได้ Flame Armor ซ้อน 2 ชั้น',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'เมื่อใดก็ตามที่ HP ของโปเกมอนศัตรูลดลงต่ำกว่า 40% เป็นครั้งแรก ทีมเราจะได้รับแรงบันดาลใจ: เพิ่มความเร็วเริ่มต้นและพลังโจมตีสองด้าน 20% นาน 2 เทิร์น (สะสมได้ 2 ชั้น); เมื่อ【Victory Flame】ถูกกระตุ้น จะสร้างความเสียหายพิเศษ 400% Sp.ATK ใส่ศัตรูที่มีเกจโกรธมากที่สุด และลดเกจโกรธของเป้าหมายลงทั้งหมด ในการหลอมรวม【Victory Flame】จะเพิ่มโบนัสความเสียหายและลดความเสียหายของโปเกมอนธาตุไฟที่เหลือรอดตัวสุดท้ายอีก 20% นาน 2 เทิร์น',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
