	[32216] = {
		id = 32216,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#L10#Charge Load：#L0#ได้รับ【Charge】หนึ่งก้อนทุกครั้งที่โจมตีหรือสูญเสีย HP ไป 10% ( #L10#Charge：#L0#บัฟ ไม่สามารถถูกลบด้วยการลบดีบัฟทั่วไป เพิ่มความเสียหายธาตุไฟฟ้า 5% ต่อก้อน สูงสุด 6 ก้อน เมื่อ Charge หายไปจะฟื้นฟูพลังโกรธ 50 แต้มต่อก้อน)\n#F10# \n#F40#เมื่อมี【Charge】ครบ 6 ก้อน จะเข้าสู่สถานะ【Overclock Frenzy】เป็นเวลา 2 เทิร์น\n#F10# \n#F40##L10#Overclock Frenzy：#L0#เพิ่มพลังโจมตีกายภาพเริ่มต้นและอัตราคริติคอลของตัวเอง #C0x5c9970#$(25+skillLevel*0.1-0.1)$%#C0x5B545B# (ไม่สามารถถูกลบ โอน หรือเปลี่ยนแปลงได้) ลบและกันสถานะหลับ, ฝันร้าย, อัมพาต และลดพลังโกรธ แต่ละ Charge จะให้หลบหลีกเพิ่ม 10%\n#F10# \n#F40#ระหว่าง Overclock จะไม่สะสม Charge ใหม่ การโจมตีแต่ละครั้งจะใช้ Charge 1 ก้อน หลังหมด Overclock จะติดสถานะ【Exhausted】1 เทิร์น (Exhausted: สถานะควบคุม ไม่สามารถเคลื่อนไหวได้ สามารถลบได้)\n#F10# \n#F40##L10#Physical Conduction：#L0#ใน 3 เทิร์นใหญ่แรกหลังเข้าสนาม ฝ่ายเราจะได้รับพลังโกรธ 300/200/100 แต้มตามลำดับเมื่อใช้สกิลโจมตีกายภาพแบบใช้งาน',
		starEffect = __data_t__starEffect[32216],
		-- {8}
		starEffectDesc = 'เอฟเฟกต์เสริม: เมื่อเข้าสู่สนามจะได้รับ 3 Charge และเมื่อ Overclock สิ้นสุด แต่ละ Charge จะสร้างความเสียหายกายภาพ 50% ของ Atk ให้กับศัตรูที่มี HP ต่ำที่สุด',
		zawakeEffect = __data_t__zawakeEffect[32216],
		-- {79004}
		zawakeEffectDesc = '#L10#Charge Load：#L0#ทุกครั้งที่โจมหรือสูญเสีย HP 10% จะได้รับ 1 ชิ้น【Charge】（#L10#Charge：#L0#บัฟ ล้างได้ เพิ่ม 5% Electric Damage สูงสุด 6 ชิ้น เมื่อหายจะฟื้นโกรธ 50 ต่อชิ้น）\n#F10# \n#F40#เมื่อ【Charge】ครบ 6 จะเข้าสู่【Overclock Frenzy】2 เทิร์น\n#F10# \n#F40##L10#Overclock Frenzy：#L0#เพิ่ม #C0x5c9970#$(30+skillLevel*0.1-0.1)$%#C0x5B545B# ATK พื้นฐาน, CRIT, และ 40% ต้านทานควบคุม (ล้างไม่ได้)；เพื่อนสาย Electric เพิ่ม 15% CRIT และ ATK/Sp.ATK；Zekrom ลบและกันผล Sleep, Nightmare, Paralyze, ลดโกรธ；แต่ละ Charge ให้ 10% หลบหลีก\n#F10# \n#F40#ระหว่าง Overclock จะไม่ได้รับ Charge เพิ่ม แต่ละการโจมตีจะใช้ 1 ชิ้น Charge เมื่อหมดโหมดจะติด【Exhaust】1 เทิร์น (Exhaust: ควบคุม ห้ามเคลื่อนไหว ล้างได้)\n#F10# \n#F40##L10#Physical Conduction：#L0#3 รอบใหญ่แรกเมื่อเข้าสนาม ท่าไม้ตายกายภาพจะทำให้เพื่อนทีมได้รับโกรธ 300/200/100 ตามลำดับ；เมื่อเพื่อนสาย Electric ใช้สกิลโจมตี Zekrom จะได้รับ Charge เพิ่มอีก 1 ชิ้น',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'เมื่อเข้าสู่โหมด Overdrive จะเพิ่มอัตราต้านควบคุมของตนเอง 40%，โปเกมอนธาตุไฟฟ้าฝ่ายเราจะได้รับคริติคอลและพลังโจมตีทั้งสองด้านเพิ่ม 15%；เมื่อโปเกมอนธาตุไฟฟ้าใช้สกิลโจมตี Zekrom จะได้รับพลังงานไฟฟ้าเพิ่ม 1 ลูก',
		changeUnitTrigger = true,
		isCombat = true,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = __data_t__skillProcess[32216],
