	[32443] = {
		id = 32443,
		skillName = 'ท่าไม้ตาย',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#เกิดในน้ำแข็ง จบในน้ำแข็ง#C0x5B545B#\n① โจมตีเป้าหมายในตำแหน่งกากบาท สร้างความเสียหายพิเศษ\n#C0x3D8A99#220% พลังพิเศษ\n#C0x5B545B#+$(skillLevel*4*24)$\n#C0xF13B54#Special Damage\n#C0x5B545B# และจุด【กำแพง Frostflame】 1 เทิร์น (หากมีอยู่แล้วจะขยายเวลาอีก 1 เทิร์น)\n② ปกป้องพันธมิตรสาย Dragon/Ice/Fire ที่เคลื่อนไหวก่อนหน้า 1 ตัว ด้วย【ประติมากรรมน้ำแข็ง】จนถึงต้นเทิร์นถัดไป\n③ เปลี่ยนสนามเป็น【ค่ำคืนอันเป็นนิรันดร์ของน้ำแข็ง】 1 เทิร์น',
		starEffect = __data_t__starEffect[32443],
		-- {11}
		starEffectDesc = '\n④ ขณะอยู่ในโหมด Overclock ค่าสูตรความเสียหายจะเพิ่มขึ้น 2 เท่า และสร้างความเสียหายจาก Frostflame Wall ใส่ศัตรูทุกตัวทันที\n⑤ เมื่อ Frozen Mold สิ้นสุด มีโอกาส 50% ที่จะทำให้ศัตรูแบบสุ่ม 1 ตัวติดสถานะ Permafrost 1 เทิร์น',
		zawakeEffect = __data_t__zawakeEffect[32443],
		-- {79003}
		zawakeEffectDesc = '#C0xC0C0C0#เกิดในน้ำแข็ง จบในน้ำแข็ง#C0x5B545B#\n\n① โจมตีพื้นที่กากบาท สร้างความเสียหายพิเศษ #C0x3D8A99#220% Sp.ATK#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54# พิเศษ#C0x5B545B# สร้าง【Frostflame Wall】1 เทิร์น (หากมีอยู่แล้วจะขยายอีก 1 เทิร์น)\n② ผนึกเพื่อน 1 ตัวสาย Dragon/Ice/Fire ที่ลงมือก่อนหน้าไว้ใน【Frozen Mold】จนถึงเทิร์นถัดไป\n③ เปลี่ยนสนามเป็น【Eternal Winter】1 เทิร์น',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '#C0x5c9970#เพิ่มค่าสัมประสิทธิ์ความเสียหายพื้นฐานเป็น 440%; ใน 2 ครั้งแรกที่เข้าสู่【Dark Overclock】จะสามารถใช้ท่าไม้ตายที่มีพลัง 50% ฟรีก่อนเทิร์นถัดไป；เมื่อ【Frost Thundercloud Cluster】หายไป จะกระจายออกเป็น 2 ก้อน【Frost Thundercloud】',
