	[32446] = {
		id = 32446,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#ความจริงคือสิ่งที่ข้าเลือกด้วย DNA ของตนเอง#C0x5B545B#\n① ต้านทานสถานะแช่แข็ง และสามารถถูกนับเป็นสาย Fire โดยเพื่อนร่วมทีม\n② เพิ่มการลดความเสียหายจริง 15% และดาเมจสะท้อนจะได้รับโบนัสจากอัตราสะท้อน\n③ โจมตีเป้าหมายที่มี【เลือดเยือกแข็ง】จะดูดเลือดเยือกแข็งทั้งหมด\n④ เข้าสนามและทุก 2 เทิร์น จะจุด【กำแพง Frostflame】ที่อยู่ 2 เทิร์น\n#C0xF13B54#【ปลดล็อก 6 ดาว】: ผสานเกล็ดหิมะ#C0x5B545B#\n⑤ ความเสียหายจากการถูกสกิลโจมตีจะไม่เกิน (15%-1% × จำนวนพันธมิตรสาย Dragon/Ice/Fire) ของ HP สูงสุด (หากมาจาก Water/Fighting จะเป็น 30%) จำกัด 3 ครั้งต่อเทิร์น\n⑥ เมื่อโดนโจมตี มีโอกาส 50% ทำให้ผู้โจมตีติด【Frozen Eternity】 1 เทิร์น (คูลดาวน์ 2 เทิร์น)\n#C0xF13B54#【ปลดล็อก 7 ดาว】: โครงสร้างแห่งความจริง#C0x5B545B#\n⑦ การโจมตีปกติจะพ่วงด้วย【Frostflame Breath】 (คูลดาวน์ 1 เทิร์น); เมื่อตัวอื่นใช้ ลมหายใจมังกร ครั้งแรกในแต่ละเทิร์น Kyurem จะดูดซับและใช้ร่วมกับการโจมตีถัดไป พร้อมได้รับบัฟ【HP สูงสุดⅡ】ถาวร (สะสมสูงสุด 4 ชั้น)',
		starEffect = __data_t__starEffect[32446],
		-- {8}
		starEffectDesc = '\n⑧ ก่อนเริ่ม 2 เทิร์นใหญ่แรก จะมีโอกาส 100%/50% ที่จะเปิดใช้งาน Frozen Mold ต่อเนื่องจนกว่าจะถึงการกระทำของตนเอง; เมื่อตัวแรกในทีม Dragon/Fire/Ice ถูกโจมตีรุนแรงถึงตาย จะถูกแช่ใน Frozen Mold เพื่อป้องกันจนกว่าจะถึงการกระทำของเป้าหมาย และฟื้นฟู HP 25%\n⑨ เมื่อได้รับความเสียหายถึงตาย จะเข้าสู่ Whiteflame Overclock เป็นเวลา 3 เทิร์น; หลัง Overclock จบ จะสูญเสียเอฟเฟกต์ติดตัว Fusion Snowflake\n#C0xF13B54#Whiteflame Overclock#C0x5B545B#\nร่างพิเศษ: ล้างสถานะทั้งหมดของตนเอง ฟื้น HP และ Rage เต็ม เพิ่ม Critical, Final Damage Bonus และ Final Damage Reduction 100% และเพิ่ม HP สูงสุด 100%  ',
		zawakeEffect = __data_t__zawakeEffect[32446],
		-- {79004}
		zawakeEffectDesc = '#C0xC0C0C0#ความจริง คือ Keystone ทางเลือกของข้า#C0x5B545B#\n\n① ต้านทาน Freeze；ถือเป็น Fire-type โดยเพื่อน\n② เพิ่ม True Damage Reduction 15%；สะท้อนจะได้รับผลจาก Reflect Rate\n③ โจมตีเป้าหมายที่มี【Frozen Blood】 จะขโมยเลือดทั้งหมด\n④ เข้าสนามและทุก 2 เทิร์น จะสร้าง【Frostflame Wall】นาน 2 เทิร์น\n\n#C0xF13B54#【ปลดล็อค 6★】: ผสาน Snowflake#C0x5B545B#\n⑤ Damage ที่ได้รับจากการโจมตีจะไม่เกิน (15%-1%xจำนวนเพื่อน Dragon/Ice/Fire) ของ HP Max (Water/Fighting จะนับเป็น 30%) จำกัด 3 ครั้งต่อเทิร์น\n⑥ โดนตีมีโอกาส 50% ทำให้ผู้ตีติด【Permafrost】1 เทิร์น (CD 2 เทิร์น)\n\n#C0xF13B54#【ปลดล็อค 7★】: สร้างร่างแห่งความจริง#C0x5B545B#\n⑦ การโจมตีจะพ่วง【Frostflame Breath】(CD 1 เทิร์น)；เมื่อเพื่อนใช้ Dragon Breath ครั้งแรกในแต่ละเทิร์น Kyurem จะดูดซับและใช้ Dragon Breath นั้นในการโจมตีถัดไป และได้รับ【Max HP II】ถาวร (สูงสุด 4 ชั้น)',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '#C0x5c9970#ในครั้งแรกของ【Dark Overclock】 ความเสียหายรวมที่ได้รับจะไม่เกิน 30% ของ HP สูงสุด；เมื่อโปเกมอนธาตุมังกร/น้ำแข็ง/ไฟฟ้าฝ่ายเราล้ม จะทิ้ง【Crystal Core Remains】ไว้ในตำแหน่งนั้น',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		changeUnitTrigger = true,
		isCombat = true,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = {3253611, 325362, 324363, 324364, 3253651, 324366},
		posC = __data_t__posC[32446],
		-- {['y'] = 0, ['x'] = 0, __size = 2}
