	[32463] = {
		id = 32463,
		skillName = 'ท่าไม้ตาย',
		skillTypeShow = 'ทักษะสังหาร',
		describe = 'โจมตีเป้าหมายแนวเดียวกันของฝ่ายศัตรู สร้างความเสียหายกายภาพ\n#C0xE69900#400% พลังโจมตีกายภาพ\n#C0x5B545B#+$(skillLevel*4*60)$\n#C0xF13B54#Physical Damage\n#C0x5B545B# (3 ครั้งแรกจะได้รับค่าสัมประสิทธิ์ท่าไม้ตายเพิ่มเติม 30%) ก่อนใช้จะขับเคลื่อนคริสตัลคอร์ 2 ครั้ง และใส่สถานะ【กระแสไม่เสถียร】ให้กับทั้งตนเองและเป้าหมายเป็นเวลา 2 เทิร์น จากนั้นจะสร้าง【เมฆสายฟ้าน้ำแข็ง】 1 ก้อน และสุ่มใส่สถานะ【เป้าหมายล่าโดย Frost Thunder】ให้ศัตรู 1 ตัวเป็นเวลา 2 เทิร์น หากอยู่ในสถานะ【Dark Overclock】จะปล่อย【Frost Thunder Roar】โจมตีเป้าหมายรูปกากบาท สร้างความเสียหายกายภาพ 170%',
		starEffect = __data_t__starEffect[32463],
		-- {11}
		starEffectDesc = '\nเมื่อเข้าสู่ Dark Overclock เป็นครั้งแรก จะสามารถใช้ท่าไม้ตายที่มีพลัง 50% ได้ฟรีก่อนการกระทำถัดไป (ต้องผ่าน Z-Awakening)\nหลังใช้ท่าไม้ตาย จะทำให้ Froststorm Cloud แพร่ขยายกลายเป็น Froststorm Cluster และได้รับ【Atk I】แบบถาวร (สูงสุด 4 ชั้น)\n#L10#Crystal Core Drive:#L0# ได้รับความสามารถ Crystal Core Drive ทุก ๆ 3 การขับเคลื่อน จะทำให้ Froststorm Cloud บนสนามแพร่กระจาย 1 ครั้ง (หากไม่มีเมฆจะสร้างใหม่ทันที); เมื่อขับเคลื่อนถึงขีดสูงสุด จะมอบให้เพื่อน Dragon 1 ตัว และเมื่อโจมตีจะพ่วง Froststorm Cloud 1 เทิร์น',
		zawakeEffect = __data_t__zawakeEffect[32463],
		-- {79003}
		zawakeEffectDesc = 'โจมตีเป้าหมายแถวหน้า สร้างความเสียหายกายภาพ #C0xE69900#400% ATK#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# กายภาพ#C0x5B545B# (3 ครั้งแรกของท่าไม้ตายจะได้รับค่าสัมประสิทธิ์พิเศษเพิ่ม 30%)\nก่อนใช้จะกระตุ้น Crystal Core 2 ครั้ง และมอบสถานะ【Unstable Current】ให้ทั้งตนเองและเป้าหมายเป็นเวลา 2 เทิร์น\nจากนั้นสร้าง【Frost Thundercloud】1 ลูก และสุ่มกำหนดเป้าหมายฝ่ายศัตรู 1 ตัวให้ติด【Frost Thunder Hunt】2 เทิร์น\nในสถานะ【Dark Overclock】จะปล่อย【Frost Thunder Roar】1 ครั้ง สร้างความเสียหายกายภาพ 170% ATK แก่เป้าหมายในพื้นที่รูปกากบาท',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '#C0x5c9970#เพิ่มค่าสัมประสิทธิ์ความเสียหายพื้นฐานเป็น 440%; ใน 2 ครั้งแรกที่เข้าสู่【Dark Overclock】จะสามารถใช้ท่าไม้ตายที่มีพลัง 50% ฟรีก่อนเทิร์นถัดไป；เมื่อ【Frost Thundercloud Cluster】หายไป จะกระจายออกเป็น 2 ก้อน【Frost Thundercloud】',
		upLvDesc = 'เพิ่มความเสียหายคงที่+240',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		changeUnitTrigger = true,
