	[32526] = {
		id = 32526,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#ดาบของข้าคือเจตจำนงของข้า!#C0x5B545B#\nวิชาดาบคลื่นน้ำ: เมื่อโปเกมอนสาย Water ได้รับ Purify หรือสาย Fighting ได้รับบัฟต้านทาน จะเพิ่มบัฟ【จิตดาบคลื่น】ให้กับทั้งตนเองและเพื่อน; หากตนเองโจมตีแล้วศัตรูไม่ติดต้านทาน ก็จะได้รับจิตดาบคลื่นเพิ่มอีก 1 ชั้น; ในแต่ละเทิร์น หากโดนควบคุม 2 ครั้งแรก จะเปลี่ยนเป็น 1 ชั้นจิตดาบคลื่น\n【จิตดาบคลื่น】: เพิ่มความเสียหาย +5%, ลดความเสียหาย +5%, เจาะต้านทาน +5%; การโจมตีมีโอกาส 10% โจมตีปกติอีก 1 ครั้ง สะสมได้สูงสุด 5 ชั้น\n#F40##L10#กระแสดาบไหลเวียน#L0#: เมื่อจิตดาบคลื่นเต็ม 5 ชั้น จะเข้าสู่【ใจดาบแน่วแน่ I】 2 เทิร์น พร้อมถ่ายโอนจิตดาบคลื่นให้พันธมิตรสาย Water/Fighting/Sword Dance ที่มีพลังโจมตีสูงสุด (หากเต็มแล้วจะไหลไปยังตัวถัดไป)【ใจดาบแน่วแน่ I】: ไม่สามารถลบหรือซ้อนทับได้ เพิ่มพลังพิเศษ 30%, ความเสียหาย +50%, ลดความเสียหาย +50%, เจาะต้านทาน +50%, โจมตีทะลุบัฟกันดาเมจ ต้านควบคุม +30%, ต้านคริติคอล +30%, โจมตีเสร็จมีโอกาส 80% และ 60% โจมตีอีกครั้ง และฟื้น HP 5% เมื่อโดนความเสียหาย\n#F40##L10#เหนือกว่าครู!#L0#: เมื่อเกิดเอฟเฟกต์โจมตี จะสุ่มได้รับผลจาก【ดาบไม้】/【ดาบเหล็ก】/【ดาบหิน】อย่างใดอย่างหนึ่ง (ไม่ซ้ำกับรอบก่อนหน้า) สร้างความเสียหายธาตุ 200% พลังพิเศษ;\n【ดาบไม้】: ดูดเลือด 20% และฟื้น HP 20%;\n【ดาบเหล็ก】: สร้างโล่ 30% HP สูงสุด และหากแตกจะสร้างดาเมจจริงเท่ากับปริมาณโล่;\n【ดาบหิน】: ลดความเสียหาย 2 ครั้งถัดไป 50% และ 30%; พันธมิตรสาย Sword Dance 1 ตัวจะสุ่มได้รับดาบ 1 ชนิดด้วย',
		zawakeEffect = __data_t__zawakeEffect[32526],
		-- {79004}
		zawakeEffectDesc = '#C0xC0C0C0#ดาบของข้า คือจิตใจของข้า#C0x5B545B#\n\n【Waveblade Style】: เมื่อตัวละครสาย Water ล้างดีบัฟ / สาย Fighting สร้างการป้องกัน ทั้งตนเองและเพื่อนจะได้รับ【Waveblade Spirit】1 ชั้น；หากผู้ใช้โจมตีโดยไม่ถูกป้องกัน จะได้รับ 1 ชั้นเช่นกัน；ในแต่ละเทิร์น หากถูกควบคุม 2 ครั้งแรกจะเปลี่ยนเป็น【Waveblade Spirit】\n\n【Waveblade Spirit】: เพิ่ม Damage Bonus, Damage Reduction, Pierce Guard อย่างละ 5% โจมตีมีโอกาส 10% ได้连击 1 ครั้ง สูงสุดสะสมได้ 5 ชั้น\n\n#F40##L10#Sword Intent Flow#L0#: เมื่อมี【Waveblade Spirit】ถึงขีดจำกัด จะใช้ทั้งหมดเพื่อเข้าสู่【Sword Focus 1】2 เทิร์น ขณะอยู่ในสถานะนี้ Waveblade Spirit ใหม่จะส่งต่อไปยังเพื่อนสาย Water/Fighting หรือ Sword Dance ที่มี ATK สูงสุด (หากเต็มแล้วจะวนต่อ)【Sword Focus 1】: ไม่สามารถซ้อนหรือลบได้ เพิ่ม Sp.ATK 30%, Damage Bonus/Damage Reduction/Pierce Guard อย่างละ 50%, โจมตีทะลุ Damage Immunity, เพิ่ม RES และ CRIT RES 30%, หลังการโจมตีจะ连击 ธรรมดา 1 ครั้ง และมีโอกาส 80% และ 60% ที่连击 ซ้ำอีก 1 ครั้ง ฟื้นฟู HP 5% เมื่อได้รับความเสียหายแบบกระจาย\n\n#F40##L10#Surpass the Blue#L0#: เมื่อใช้连击 จะสุ่มติดเอฟเฟกต์【Grass Sword】/【Steel Sword】/【Rock Sword】อย่างใดอย่างหนึ่ง (ไม่ซ้ำกันสองรอบติด) สร้างความเสียหายธาตุ Grass/Steel/Rock 200% Sp.ATK；เพื่อนสาย Sword Dance 1 ตัวจะสุ่มได้รับเอฟเฟกต์ 1 แบบเช่นกัน【Grass Sword】: ดูดเลือด 20% และฟื้นฟู 20% HP【Steel Sword】: ได้โล่ 30% Max HP หากโล่แตกจะสร้าง True Damage แก่ผู้โจมตีเท่ากับค่าโล่ที่หายไป【Rock Sword】: ลดความเสียหายที่ได้รับ 2 ครั้งถัดไป 50%/30%',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '#C0x5c9970#เมื่อเริ่มแต่ละเทิร์นใหญ่ จะได้รับ 1 ชั้นของ【Wave Sword Intent】；เมื่อเข้าสนาม จะอัญเชิญ【Wave Sword Envoy】ให้กับโปเกมอนธาตุน้ำ/ต่อสู้/ดาบเต้นที่มี ATK สูงสุดในทีม',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
