	[32636] = {
		id = 32636,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#L10#Symbiosis: #L0#Meloetta ร่างคู่จะผลัดกันโจมตีในสนามรบ แชร์พลังชีวิต ค่าโกรธ และเอฟเฟกต์ร่วมกัน เพิ่ม HP สูงสุด 30% แต่การฟื้นโกรธจากการโจมตีของแต่ละร่างจะลดลง 30%\n#F20#\n#F40##L10#Twin Melody Charms: #L0#ขณะอยู่ในร่างเต้นจะใช้【ผลไม้เมโลดี้สีชมพู】: มีโอกาส 20% ทำให้ศัตรูแบบสุ่ม 1 ตัวติด【Charm】 1 เทิร์น; ขณะอยู่ในร่างร้องจะใช้【ผลไม้เมโลดี้สีแดง】: จะเลือกโจมตีเป้าหมายที่ติด【Charm】หรือ【Taunt】ก่อน และหากเป้าหมายเคยโดนตนเองทำให้ติด Charm จะเจาะทะลุการลดความเสียหาย 40%; Meloetta จะไม่ติด Charm และ Taunt\n#F20#\n#F40##L10#Melody Tree: #L0#เมื่อใช้ผลไม้เมโลดี้ครบทั้ง 5 สี หากได้รับความเสียหายจนตาย จะเข้าสู่ต้นไม้แห่งเมโลดี้แทน (Melody Tree) โดย Melody Tree จะสืบทอดค่าพลัง 100% และมีพลังชีวิตเท่ากับ\n#C0x5c9970#$(50+skillLevel*0.3-0.3)$%\n#C0x5B545B#ของ HP สูงสุด หากไม่ถูกทำลายจนจบเทิร์นใหญ่ Meloetta จะคืนชีพด้วย HP เท่ากับ\n#C0x5c9970#$(50+skillLevel*0.3-0.3)$%\n#C0x5B545B#ของ HP สูงสุด พร้อมฟื้นโกรธ 500 แต้ม',
		starEffect = __data_t__starEffect[32636],
		-- {8}
		starEffectDesc = 'เมื่อยูนิตศัตรูที่อยู่ในสถานะ Phantom ทำการกระทำ Meloetta จะฟื้นฟู HP เท่ากับ 50% ของค่ารวมระหว่าง Atk และ Sp. Atk ของตนเอง',
		zawakeEffect = __data_t__zawakeEffect[32636],
		-- {79004, 1}
		zawakeEffectDesc = '#L10#Symbiosis：#L0#Meloetta Twin จะเคลื่อนไหวแยกกันในสนามรบ แต่แชร์ HP, Energy และเอฟเฟกต์การต่อสู้ Max HP เพิ่มขึ้น 30% ทั้งคู่จะได้รับ Energy จากการโจมตีลดลง 30% หลัง Dance Forme เคลื่อนไหว จะเพิ่ม ATK และ Sp.Atk ของ Song Forme 20% หลัง Song Forme เคลื่อนไหว จะเพิ่ม Speed ของ Dance Forme 15%\n#F20# \n#F40##L10#Twin Fraud：#L0#เมื่อ Dance Forme โจมตีจะใช้【Pink Melody Fruit】：มีโอกาส 20% ทำให้ศัตรูสุ่ม 1 ตัวติด *Fraud* 1 เทิร์น ส่วน Song Forme โจมตีจะใช้【Red Melody Fruit】：เลือกเป้าหมายที่ติด *Fraud* หรือ *Charm* ก่อน หากเป้าหมายเคยโดน Meloetta ทำให้ *Fraud* จะละเว้น Damage Reduction 40% Meloetta Immune ต่อ *Fraud* และ *Charm*\n#F20# \n#F40##L10#Melody Tree：#L0#หลังใช้ Melody Fruit ทั้ง 5 สี หากได้รับความเสียหายจนถึงตาย Meloetta จะเข้าสู่ Melody Tree ซึ่งสืบทอดค่าพลัง 100% และมี HP เท่ากับ #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# ของ Max HP หากยังไม่ถูกทำลายในตอนจบรอบใหญ่ Meloetta จะกลับมาพร้อมฟื้น HP #C0x5c9970#$(50+skillLevel*0.3-0.3)$%#C0x5B545B# และได้ Energy 500 แต้ม หากได้รับ Melody Fruit สีอื่นครั้งแรก (ยกเว้นสีม่วง) จะใช้ท่าไม้ตายพิเศษทันทีและใช้ Energy ที่มีอยู่ทั้งหมด',
