	[33043] = {
		id = 33043,
		skillName = 'ท่าไม้ตาย',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#งั้นฉันจะให้ดูพลังแห่งสายสัมพันธ์ของพวกเรา!#C0x5B545B#\n#F10#\n#F40#Greninja (ซาโตชิรูปแบบ) ใช้สุดยอดวิชานินจาน้ำ ขว้างกระบองน้ำยักษ์สีทองใส่เป้าหมายเดี่ยว (เน้นเป้าหมายที่ช้าที่สุด) ขโมยอัตราคริติคอล 30% และโบนัสคริติคอล 40% ของเป้าหมายเป็นเวลา 2 เทิร์น สร้างความเสียหายพิเศษ\n#C0x3D8A99#540% พลังพิเศษ\n#C0x5B545B#+$(skillLevel*4*90)$\n#C0xF13B54#Special Damage\n#C0x5B545B# พร้อมดูดเลือด 30%; หากเป้าหมายมีความเร็วน้อยกว่าตนเองอย่างน้อย 40% หรือหลังจากการโจมตี HP ของเป้าหมายต่ำกว่า 10% (รวมถึงตาย) จะโจมตีศัตรูทั้งทีมด้วย【Slash ทะลุคลื่น】เพิ่มเติม (จำกัดการเกิด 2 ครั้ง)\n#F10#\n#F40##C0x4682B4##L10#Slash ทะลุคลื่น: #L0##C0x5B545B#สร้างความเสียหายจริงเท่ากับ\n#C0x3D8A99#50% พลังพิเศษ\n#C0x5B545B#+ 10% ของ HP สูงสุดของเป้าหมาย (สูงสุดไม่เกิน 1000% พลังพิเศษของตนเอง); ความเสียหายนี้จะคูณ 2 เท่าเมื่อใช้กับบอส และจะเกิดขึ้นแน่นอน',
		simDesc = 'Ash-Greninja ใช้ท่าสุดยอดโยนชูริเคนน้ำสีทองใส่เป้าหมายเดี่ยว ขโมย Critical Rate และ Critical Damage พร้อมดูดเลือด และฟันคลื่นโจมตีศัตรูทั้งทีมอีกครั้ง',
		starEffect = __data_t__starEffect[33043],
		-- {11}
		starEffectDesc = 'ทุกครั้งที่โจมตีปกติครบ 3 ครั้ง จะเข้าสู่สถานะ【Shadow Kill】เรียก Water Clone มาแทนตัว และเพิ่มพลังท่าไม้ตายครั้งถัดไปให้ได้รับเอฟเฟกต์【Water Shadow Combo】\n#F10#\n#F40##L10#Water Shadow Combo: #L0#เรียก Water Clone ขึ้นสูงสุด 5 ตัว (พื้นฐาน 2 ตัว เพิ่ม 1 ตัวทุกๆ 15% ของ Speed ที่เพิ่มจากค่าเริ่มต้น) เพื่อปล่อย Water Shuriken โจมตีเป้าหมายแบบสุ่ม สร้างความเสียหาย 200% Sp. Atk ของแต่ละร่างเงาน้ำ',
