	[33046] = {
		id = 33046,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#งั้นฉันเลือกนาย! ซาโตชิ!#C0x5B545B#\n#F10#\n#F40##L10#วิชานินจาน้ำ: #L0#เมื่อโจมตีเป้าหมายที่มีความเร็วต่ำกว่าตนเอง จะเจาะทะลุป้องกันพิเศษของเป้าหมาย\n#C0x5c9970#$(20+skillLevel*0.1-0.1)$%\n#C0x5B545B#; ยิ่งช่องว่างของความเร็วระหว่างตนเองกับเป้าหมายมากเท่าใด ความเสียหายเพิ่มเติมจะยิ่งสูงขึ้น ทุก ๆ ความเร็วต่างกัน 1% จะเพิ่มความเสียหาย 3% สูงสุดเพิ่มได้ถึง 100%;\nหลังโจมตี มีโอกาสเท่ากับสัดส่วนความเร็วที่ต่างกันในการติด【สัญลักษณ์กระบองน้ำ】ให้เป้าหมาย\n【สัญลักษณ์กระบองน้ำ】: ทำให้เป้าหมายได้รับความเสียหายจากท่าน้ำเพิ่มขึ้น 10%; เมื่อพันธมิตรโจมตีเป้าหมายนี้ จะร่วมโจมตีด้วยการโจมตีปกติ 1 ครั้ง และล้างสัญลักษณ์นี้ออก\n#F10#\n#F40##L10#สายน้ำแปรดาบ: #L0#เมื่อโปเกมอนสาย Water ฝ่ายเราดำเนินการ จะได้รับ 1 ชั้น【สายน้ำ】; เมื่อชำระล้างดีบัฟจากตนเองหรือบัฟจากศัตรู จะได้รับ 1 ชั้น; เมื่อผลควบคุมหมดอายุ จะได้รับ 4 ชั้น; เมื่อถึง 6 ชั้น จะเรียก【มังกรน้ำวน】มาห่อหุ้มตนเอง (มังกรน้ำวน: โล่ที่ดูดซับความเสียหายจากพลังพิเศษได้ 400%, เพิ่มต้านคริติคอล 100%, เพิ่มความเสียหายจากท่าน้ำ 30%, คงอยู่จนโล่แตกหรือจบเทิร์นใหญ่); เมื่อโล่หาย จะรวมตัวเป็นกระบองน้ำยักษ์และได้เทิร์นใหม่ทันที ขณะถือกระบองน้ำยักษ์ ท่าไม้ตายสามารถปล่อยโดยไม่ใช้เกจโกรธ (คูลดาวน์ 2 เทิร์นใหญ่)\n【สายน้ำ】: เอฟเฟกต์พิเศษ เพิ่มความเร็ว 5% และต้านคริติคอล 10%\n#F10#\n#F40##L10#พลังแห่งสายสัมพันธ์: #L0#เมื่อเข้าสนาม หากมีโปเกมอนสาย Water หรือ Dark อยู่ จะได้รับจำนวนชั้น【พลังสายสัมพันธ์】ตามจำนวน (เอฟเฟกต์พิเศษ เพิ่มพลังพิเศษ 2%, ดูดเลือด 2%, สูงสุด 15 ชั้น); เมื่อร่วมโจมตีจะได้รับ 1 ชั้น; เมื่อถูกเชิญโจมตีหรือได้รับการป้องกัน จะได้รับ 2 ชั้น; ขณะมีพลังสายสัมพันธ์อยู่ หากได้รับความเสียหายที่ทำให้ตาย และยังมีพันธมิตรในสนาม จะสามารถเลื่อนการตายไปอีก 1 เทิร์นได้',
		starEffect = __data_t__starEffect[33046],
		-- {8}
		starEffectDesc = 'เปิดการต่อสู้โดยได้รับจำนวนชั้นของ【Wave Glide】ตามจำนวน Pokémon ธาตุน้ำฝ่ายเรา; โบนัส Speed จาก Wave Glide จะถูกเก็บไว้ 50% เมื่อถูกใช้หมด; เมื่อได้รับความเสียหายถึงตายครั้งแรก จะเปิด Water Whirlpool Shield ทันที\n#F10#\n#F40##L10#Water Shadow Ambush: #L0#ก่อนเริ่มแต่ละเทิร์นใหญ่ จะสุ่มใส่【Water Shuriken Mark】ให้ศัตรู 1 ตัว และสร้างความเสียหาย 80% Sp. Atk',
		zawakeEffect = __data_t__zawakeEffect[33046],
		-- {79004}
		zawakeEffectDesc = '#C0xC0C0C0#งั้นฉันเลือกนายละนะ Ash!#C0x5B545B#\n#F10#\n#F40##L10#Water Ninja Secret：#L0#เมื่อโจมตีเป้าหมายที่มีความเร็วน้อยกว่าตัวเอง จะไม่สนค่า#C0x5c9970#$(20+skillLevel*0.1-0.1)$%#C0x5B545B#ของ Sp.Def；ความต่างของความเร็วระหว่างตัวเองกับเป้าหมายยิ่งมาก ความเสียหายเพิ่มเติมจะยิ่งสูงขึ้น ทุก ๆ ความเร็วต่าง 1% จะเพิ่มความเสียหายของตัวเอง 3% สูงสุดเพิ่มได้ 100%；\nหลังโจมตีจะมีโอกาสตามสัดส่วนความต่างของความเร็วระหว่างกัน ในการใส่เครื่องหมาย【Water Shuriken】ให้กับเป้าหมาย\nWater Shuriken：เพิ่ม Water Vulnerability 10%，เมื่อเพื่อนโจมตีเป้าหมายนี้ จะทำการโจมตีธรรมดาเสริม 1 ครั้ง และลบเครื่องหมายนั้นทิ้ง\n#F10#\n#F40##L10#Waveform Blade：#L0#เมื่อ Water-type ฝ่ายเราใช้เทิร์น จะได้รับ 1 ชั้น【Waveform】；เมื่อลบดีบัฟหรือควบคุมของตัวเอง หรือเมื่อลบ Buff ของศัตรู จะได้รับ 1 ชั้น【Waveform】；เมื่อเอฟเฟกต์ควบคุมหมดอายุเอง จะได้รับ 4 ชั้น；เมื่อสะสมครบ 6 ชั้น จะใช้ทั้งหมดเพื่อเรียก【Water Whirlwind】มาปกคลุมตัวเอง (Water Whirlwind: โล่ดูดซับความเสียหายจาก Sp.Atk 400%，เพิ่ม Crit Resistance 100%，เพิ่มความเสียหายจากสกิลน้ำ 30%，อยู่จนกว่าโล่แตกหรือจบรอบใหญ่) เมื่อ Water Whirlwind หายไป น้ำจะรวมตัวกันเป็นชูริเคนน้ำขนาดยักษ์และได้รับเทิร์นใหม่ หากถือครองชูริเคนยักษ์ จะสามารถใช้ Ultimate Skill ได้โดยไม่เสีย Rage มีคูลดาวน์ 2 รอบใหญ่\nWaveform: เอฟเฟกต์พิเศษ เพิ่ม Speed 5% และ Crit Resistance 10%\n#F10#\n#F40##L10#Bond Power：#L0#เมื่อเข้าสู่สนาม หากมี Water-type หรือ Dark-type เพื่อนร่วมทีม จะได้รับจำนวนชั้น【Bond Power】ตามจำนวนนั้น (เอฟเฟกต์พิเศษ เพิ่ม Sp.Atk 2%，Lifesteal 2%，สะสมได้สูงสุด 15 ชั้น) เมื่อช่วยโจมตีจะได้รับอีก 1 ชั้น【Bond Power】；เมื่อถูกเชิญให้โจมหรือถูกป้องกัน จะได้รับอีก 2 ชั้น；หากมี【Bond Power】อยู่ เมื่อได้รับความเสียหายถึงตาย และยังมีเพื่อนร่วมทีมอยู่ จะสามารถเลื่อนการตายออกไปได้ 1 เทิร์น',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '#C0x5c9970#เมื่อเข้าสนามจะได้รับ【Water Shuriken】 2 ชิ้น และเมื่อ【Water Clone】หายไปครั้งแรก จะเรียกอีกตัวทันที',
