	[36013] = {
		id = 36013,
		skillName = 'ท่าไม้ตาย',
		skillTypeShow = 'ทักษะสังหาร',
		describe = 'Xerneasยืมพลังจากป่าโจมตีศัตรูทุกตัว สร้างความเสียหายพิเศษ\n#C0x3D8A99#200% พลังพิเศษ\n#C0x5B545B#+$(skillLevel*4*60)$\n#C0xF13B54#Special Damage\n#C0x5B545B# และเชื่อมพลังชีวิตของพันธมิตรทุกตัวเข้าด้วยกันผ่านพลังแห่งป่า กลายเป็น【Life Link】\n#F20#\n#F40##L10#Life Link: #L0#เพิ่มการลดความเสียหายสุดท้าย 35% (หากเพิ่มซ้ำแต่ละครั้งจะลดลง 10% ต่ำสุดเหลือ 15%; หน่วยที่ล่องหนจะได้รับโบนัสอีก 15%) เมื่อหน่วยที่มี Life Link โดนโจมตี จะกระจาย 60% ของความเสียหายให้กับหน่วยอื่นที่เชื่อมโยงด้วยกัน เมื่อเริ่ม Life Link จะฟื้นฟู HP ให้กับพันธมิตรแต่ละตัวเท่ากับ 15% ของ HP เริ่มต้นของ Xerneas; เอฟเฟกต์จะสิ้นสุดหลังจาก Xerneas ลงมือ 1 ครั้ง (หากอยู่ในร่างวิญญาณของกวาง เอฟเฟกต์จะสิ้นสุดหลังจากวิญญาณโจมตี 1 ครั้ง)',
		simDesc = 'Xerneas ใช้พลังแห่งป่าโจมตีศัตรูทั้งทีมด้วย Special Damage พร้อมให้สถานะ【Life Link】แก่พวกพ้องทั้งหมด',
		starEffect = __data_t__starEffect[36013],
		-- {11}
		starEffectDesc = 'เอฟเฟกต์เสริม: การเชื่อมโยงจะคงอยู่ 2 เทิร์นใหญ่ และยูนิตที่เชื่อมโยงจะไม่สนผลลด Healing; หลังจากศัตรูทำการ 3 ครั้งแรก จะฟื้น HP ให้ยูนิตที่เชื่อมโยงเท่ากับ 5% HP สูงสุดพื้นฐานของ Xerneas',
		zawakeEffect = __data_t__zawakeEffect[36013],
		-- {79003}
		zawakeEffectDesc = 'Xerneas ยืมพลังจากป่าโจมตีศัตรูทุกตัว สร้างความเสียหายพิเศษ#C0x3D8A99#200% Sp.Atk#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54##C0x5B545B# และเชื่อมโยงพลังชีวิตของเพื่อนร่วมทีมทั้งหมดด้วยพลังแห่งป่า กลายเป็น【Life Link】\n#F20# \n#F40##L10#Life Link：#L0#เพิ่ม Final Damage Reduction 35% (การใช้ใหม่แต่ละครั้งจะลดลง 10% ต่ำสุด 15%；ยูนิตที่อยู่ในสถานะซ่อนตัวได้รับเพิ่มอีก 15%) เมื่อยูนิตที่เชื่อมโยงได้รับความเสียหาย จะมีการแบ่งความเสียหาย 60% ไปยังเพื่อนร่วมทีมที่เชื่อมโยงอยู่ด้วย เมื่อเริ่มเชื่อมโยง จะฟื้นฟู HP ให้กับยูนิตที่เชื่อมโยงแต่ละตัว เท่ากับ 15% ของ Max HP พื้นฐานของ Xerneas การเชื่อมโยงจะสิ้นสุดหลัง Xerneas เคลื่อนไหว 1 ครั้ง (ในสถานะ Spirit Form จะสิ้นสุดหลังร่างวิญญาณเคลื่อนไหว 1 ครั้ง)',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '#C0x5c9970#เพิ่มค่าสัมประสิทธิ์ความเสียหายพื้นฐานเป็น 200%; ในการใช้ท่าไม้ตายครั้งแรกและครั้งที่สอง จะมอบ【Active Mode】1 เทิร์น และ【Relax Mode】1 เทิร์นให้กับเป้าหมายที่เชื่อมโยง; ทุกครั้งที่ใช้ท่าไม้ตาย จะถ่ายโอน 20% ของอัตราลดความเสียหายของตนเองให้กับเป้าหมายที่เชื่อมโยง',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
