	[36016] = {
		id = 36016,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#L10#ออร่าแห่งชีวิต: #L0#ออร่าฮีล เพิ่ม HP สูงสุดของพันธมิตรทุกตัวตามผลรวม 20% ของ HP เริ่มต้นของตัวเองและ Xerneas; เมื่อโปเกมอนฝ่ายเรามี HP ต่ำกว่า 40% เป็นครั้งแรก จะได้รับ【Active Mode】เป็นเวลา 2 เทิร์น\n#F20#\n#F40#【Active Mode】: ก่อนเริ่มเทิร์น ฟื้นฟู HP เท่ากับ\n#C0x5c9970#$(15+skillLevel*0.1-0.1)$%\n#C0x5B545B#ของ HP เริ่มต้น\n#F20#\n#F40##L10#สนามออร่าของสาย Fairy: #L0#ออร่าฮีลจากธรรมชาติ ฟื้นฟูของโปเกมอนทั้งหมดเพิ่มขึ้น 30%, โปเกมอนสาย Fairy, Grass, Ground ได้รับผลคูณ x2; โปเกมอนสาย Fairy, Grass, Ground ได้รับโบนัสความได้เปรียบทางธาตุธรรมชาติ +20%; ความต้านทานธาตุธรรมชาติเพิ่มขึ้นอีก 20%\n#F20#\n#F40##L10#เสียงกวางร้องจากวิญญาณ: #L0#เมื่อ HP ต่ำกว่า 50% เป็นครั้งแรก จะเข้าสู่ร่าง “กวางวิญญาณ” ไม่สามารถถูกโจมตีหรือรับผลกระทบใด ๆ และจะ【Possess】โปเกมอนฝ่ายเราที่มีพลังโจมตีสูงสุดเป็นเวลา 3 เทิร์น\n#F20#\n#F40#【Possess】: เอฟเฟกต์พิเศษ เพิ่มต้านคริติคอล 50%, ต้านสถานะ, ความเร็วฟื้นโกรธ และ HP สูงสุดเท่ากับ 100% ของ HP เริ่มต้นของ Xerneas; ขณะอยู่ในสถานะ Possess ทุกครั้งที่โปเกมอนที่ถูกสิงโจมตีจะปล่อยสกิลระดับเดียวกับ Xerneas; วิญญาณกวางจะโจมตีปกติอัตโนมัติในแต่ละเทิร์น สร้างความเสียหายพิเศษ\n#C0x3D8A99#300% พลังพิเศษ\n#C0x5B545B#+$(skillLevel*4*24)$\n#C0xF13B54#Special Damage\n#C0x5B545B# เมื่อการสิงสิ้นสุด วิญญาณจะกลับคืน Xerneas และฟื้น HP เต็ม 100%',
		starEffect = __data_t__starEffect[36016],
		-- {8}
		starEffectDesc = 'เอฟเฟกต์เสริม: เมื่อเริ่มการต่อสู้ จะเชื่อมโยง Life Link กับพันธมิตรทั้งหมดจนถึงหลังการกระทำของตนในเทิร์นใหญ่ถัดไป; ยูนิตที่ถูก Possess หากได้รับความเสียหายรุนแรงจนตาย จะป้องกันการตายครั้งนั้นและออกจากสถานะ Possess',
		zawakeEffect = __data_t__zawakeEffect[36016],
		-- {79004}
		zawakeEffectDesc = '#L10#Life Aura：#L0#Aura Skill เพิ่ม Max HP ของเพื่อนร่วมทีมทั้งหมด ตามผลรวมของ Max HP พื้นฐานจากตนเองและ Xerneas 20%；เมื่อ HP ของเพื่อนร่วมทีมต่ำกว่า 40% เป็นครั้งแรก จะได้รับ【Active Mode】เป็นเวลา 2 เทิร์น\n#F20# \n#F40#【Active Mode】：ก่อนเริ่มเทิร์น จะฟื้นฟู HP ของตัวเอง#C0x5c9970#$(15+skillLevel*0.1-0.1)$%#C0x5B545B#ของ Max HP พื้นฐาน\n#F20# \n#F40##L10#Fairy Terrain：#L0#Aura Skill พลังธรรมชาติตื่นฟื้น พืชผลิบาน เอฟเฟกต์การฟื้นฟูที่ได้รับของทุกยูนิตเพิ่มขึ้น 30%，ยูนิต Fairy, Grass, Ground จะได้รับผลคูณ 2；ยูนิตประเภท Fairy, Grass, Ground จะมีความสามารถในการโจมตีแบบแพ้ทางเพิ่มขึ้น 20%；และเพิ่ม Resistance ต่อธรรมชาติ 20%\n#F20# \n#F40##L10#Call of the Forest：#L0#เมื่อ HP ต่ำกว่า 50% เป็นครั้งแรก จะเปลี่ยนร่างเป็น Deer Spirit ไม่สามารถถูกโจมตี และไม่สามารถได้รับเอฟเฟกต์ใด ๆ และจะส่งวิญญาณบางส่วนไป【Possess】ยูนิตฝ่ายเราที่มี ATK สูงสุดเป็นเวลา 3 เทิร์น\n#F20# \n#F40#【Possession】：เอฟเฟกต์พิเศษ เพิ่ม Crit Resistance, Control Immunity, Rage Recovery Speed 50% และเพิ่ม Max HP เท่ากับ 100% ของ Max HP พื้นฐานจาก Xerneas；เมื่อยูนิตที่ถูกสิงโจมตี จะทำให้วิญญาณปล่อยสกิลตามระดับของ Xerneas；ขณะเป็น Deer Spirit จะทำการโจมตีธรรมดาอัตโนมัติในแต่ละเทิร์น สร้างความเสียหายพิเศษ#C0x3D8A99#300% Sp.Atk#C0x5B545B#+$(skillLevel*4*24)$#C0xF13B54##C0x5B545B# ใส่ศัตรูเดี่ยว；เมื่อสิ้นสุดการ Possess วิญญาณจะกลับคืนร่าง Deer Spirit และฟื้นฟู HP ของ Xerneas กลับเป็น 100%',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '#C0x5c9970#เมื่อพ่ายแพ้จะกลายเป็น【Tree of Life】2 เทิร์น; 【Tree of Life】: สถานะพิเศษ ไม่สามารถถูกโจมตีหรือติดสถานะอื่น เมื่อปรากฏจะฟื้นฟู HP 15% ของ HP สูงสุดให้เพื่อนร่วมทีม และเมื่อถึงเทิร์นจะฟื้นฟูอีก 10% โดยไม่สนผลลดการรักษา',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		changeUnitTrigger = true,
