	[36035] = {
		id = 36035,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#L10#ออร่าแห่งชีวิต: #L0#ออร่าฮีล เพิ่ม HP สูงสุดของฝ่ายเราทั้งหมดตามผลรวม 20% ของ HP เริ่มต้นของตัวเองและ Xerneas; เมื่อโปเกมอนฝ่ายเรา HP ต่ำกว่า 40% เป็นครั้งแรก จะได้รับ【Active Mode】2 เทิร์น\n#F20#\n#F40#【Active Mode】: ฟื้นฟู HP เท่ากับ\n#C0x5c9970#$(15+skillLevel*0.1-0.1)$%\n#C0x5B545B#ของ HP เริ่มต้นก่อนเริ่มเทิร์นของตนเอง\n#F20#\n#F40##L10#สนามออร่าของสาย Fairy: #L0#ออร่าฮีลแห่งธรรมชาติ ฟื้นฟูของโปเกมอนทุกตัวเพิ่มขึ้น 30%, สาย Fairy, Grass, Ground ได้รับผลคูณ x2; สาย Fairy, Grass, Ground ได้รับโบนัสต้านธาตุธรรมชาติ +20%, ความต้านทานธาตุธรรมชาติเพิ่มขึ้นอีก 20%\n#F20#\n#F40##L10#เสียงเรียกแห่งกวางศักดิ์สิทธิ์: #L0#เมื่อ HP ต่ำกว่า 50% เป็นครั้งแรก จะเข้าสู่ร่างกวางวิญญาณ ไม่สามารถถูกโจมตีหรือได้รับเอฟเฟกต์ใด ๆ และจะ【Possess】โปเกมอนฝ่ายเราที่มีพลังโจมตีสูงที่สุดเป็นเวลา 3 เทิร์น\n#F20#\n#F40#【Possess】: เอฟเฟกต์พิเศษ เพิ่มต้านคริ 50%, อัตราต้านสถานะ, ความเร็วฟื้นฟูโกรธ และ HP สูงสุดเท่ากับ 100% ของ HP เริ่มต้นของ Xerneas; ขณะสิงร่าง ทุกครั้งที่โจมตีจะปล่อยสกิลตามระดับของ Xerneas; วิญญาณจะโจมตีปกติอัตโนมัติทุกเทิร์น สร้างความเสียหายพิเศษ\n#C0x3D8A99#300% พลังพิเศษ\n#C0x5B545B#+$(skillLevel*4*24)$\n#C0xF13B54#Special Damage\n#C0x5B545B#; เมื่อสิ้นสุดการสิง วิญญาณจะกลับคืนสู่ Xerneas และฟื้น HP เต็ม 100%',
		starEffect = __data_t__starEffect[36035],
