	[36113] = {
		id = 36113,
		skillName = 'ท่าไม้ตาย',
		skillTypeShow = 'ทักษะสังหาร',
		describe = 'Yveltalบินขึ้นฟ้าแล้วโจมตีเป้าหมายที่มี HP น้อยที่สุดในแนวหลังของฝ่ายศัตรู สร้างความเสียหายพิเศษ\n#C0x3D8A99#500% พลังพิเศษ\n#C0x5B545B#+$(skillLevel*4*90)$\n#C0xF13B54#Special Damage\n#C0x5B545B# พร้อมสร้าง【Death Link】ระหว่างเป้าหมายกับโปเกมอนฝ่ายศัตรูแนวหน้าแบบสุ่มอีก 2 ตัว เป็นเวลา 3 เทิร์น\n【Death Link】: เมื่อหนึ่งในหน่วยที่เชื่อมโยงถูกโจมตี หน่วยอื่นที่เชื่อมโยงจะได้รับความเสียหาย 25% ของความเสียหายที่ได้รับ และเมื่อหน่วยที่ติด【Death Link】ถูกโจมตีโดย Yveltal อีกครั้ง จะมีโอกาส 35% ติด【Petrify】1 เทิร์น\n#F20#\n#F40#จากนั้นตนเองเข้าสู่สถานะ【Ruthless Execution】เป็นเวลา 1 เทิร์น: มีปีกแห่งความตาย 2 อันหมุนรอบตัวเอง ระหว่างนี้หากศัตรูคนใดมี HP ต่ำกว่า 25% ของ HP สูงสุดตอนเริ่มต่อสู้ Yveltal จะใช้ปีก 1 อันโจมตีด้วย【Purgatory Death Wing】: สร้างความเสียหายพิเศษเท่ากับ\n#C0x3D8A99#360% พลังพิเศษ\n#C0x5B545B#+ 50% ของ HP ที่สูญเสียของเป้าหมาย\n#C0xF13B54#Special Damage\n#C0x5B545B#; เมื่อจบการสังหาร หากยังเหลือปีก จะดูด HP เท่ากับ 15% ของ HP สูงสุดของเป้าหมายแบบสุ่ม (เลือกจากเป้าหมายที่มี HP มากที่สุดก่อน)',
		simDesc = 'Yveltal บินขึ้นโจมตีเป้าหมายแถวหลังที่มี HP ต่ำสุด สร้างความเสียหายแบบพิเศษ แล้วเชื่อมเป้าหมายกับแนวหน้าศัตรูด้วย【Death Link】จากนั้นตนเองเข้าสู่สถานะ【Endless Carnage】เป็นเวลา 1 เทิร์น',
		starEffect = __data_t__starEffect[36113],
		-- {11}
		starEffectDesc = 'อัตราส่วนความเสียหายจาก Fatal Link เพิ่มเป็น 35%; Infernal Death Wing จะทำให้เป้าหมายสูญเสีย 50% ของ HP สูงสุดตามปริมาณความเสียหาย (2 เทิร์น และจะไม่ฟื้น HP กลับหลังจบเทิร์น)',
		zawakeEffect = __data_t__zawakeEffect[36113],
		-- {79003}
		zawakeEffectDesc = 'Yveltal บินขึ้นและโจมตีเป้าหมายแนวหลังที่มี HP ต่ำที่สุด สร้างความเสียหายพิเศษ#C0x3D8A99#500% Sp.Atk#C0x5B545B#+$(skillLevel*4*90)$#C0xF13B54##C0x5B545B# จากนั้นเชื่อมโยงเป้าหมายนี้กับศัตรูแนวหน้าแบบสุ่มอีก 2 ตัวเป็น【Death Link】เป็นเวลา 3 เทิร์น；【Death Link】：เมื่อมีใครในกลุ่มที่เชื่อมโยงได้รับความเสียหาย จะกระจายความเสียหาย 25% ไปยังอีกสองคนในลิงก์；ยูนิตใน Death Link ที่ถูก Yveltal โจมตีซ้ำ จะมีโอกาส 35% ถูก【Petrify】 1 เทิร์น\n#F20# \n#F40#จากนั้น Yveltal เข้าสู่สถานะ【Endless Slaughter】เป็นเวลา 1 เทิร์น: รอบตัวจะล้อมด้วย Death Wings 2 อัน หากมีศัตรูใด HP ต่ำกว่า 25% ของ Max HP พื้นฐาน จะใช้ Death Wing 1 อันเพื่อร่าย【Purgatory Death Wing】：สร้างความเสียหายพิเศษ#C0x3D8A99#360% Sp.Atk#C0x5B545B#+50% HP ที่เป้าหมายสูญเสีย#C0xF13B54##C0x5B545B#；เมื่อสภาวะจบลง หากมี Death Wing เหลือ จะดูดซับ HP 15% Max HP จากศัตรูที่มี HP สูงสุดแบบสุ่ม 1 ตัว',
