	[36233] = {
		id = 36233,
		skillName = 'ท่าไม้ตาย',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#ข้าจงดูถูกทุกสรรพสิ่ง...#C0x5B545B#\nZygarde 10% Form: ไม่มีท่าไม้ตาย เมื่อเกจโกรธเต็มจะเพิ่มดูดเลือด 30% และโบนัสความเสียหายจริง\nZygarde 50% Form: ยิงคลื่นแสงรูป Z ใส่ศัตรูแบบสุ่ม 2 ตัว สร้างความเสียหายกายภาพ\n#C0xE69900#240% พลังโจมตีกายภาพ\n#C0x5B545B#+$(skillLevel*4*48)$\n#C0xF13B54#Physical Damage\n#C0x5B545B# และเสีย HP 20% ของตนเอง ติด【Cell】ให้แต่ละเป้าหมาย และกระตุ้น【Core Punishment】ของ Cell ทุกอัน เป็นเวลา 1 เทิร์น\nZygarde Complete Form: ปล่อยพลังสูงสุด ยิงคลื่นแสงรูป Z ใส่ศัตรูแบบสุ่ม 3 ตัว สร้างความเสียหายกายภาพ\n#C0xE69900#220% พลังโจมตีกายภาพ\n#C0x5B545B#+$(skillLevel*4*24)$\n#C0xF13B54#Physical Damage\n#C0x5B545B# และเสีย HP 20% ของตนเอง ติด【Cell】ให้แต่ละเป้าหมาย และกระตุ้น【Core Punishment】ของ Cell ทุกอัน เป็นเวลา 1 เทิร์น\n#F20#\n#F40#【Core Punishment】: ไม่สามารถซ้อนทับหรือชำระล้างได้ เมื่อเป้าหมายโจมตีโปเกมอนสาย Ground หรือ Dragon ในครั้งถัดไป จะไม่สามารถใช้เอฟเฟกต์จากสกิลได้ มีเพียงความเสียหายเท่านั้นที่จะถูกสร้างขึ้น',
		simDesc = 'Zygarde·Complete Forme ปลดปล่อยพลังทั้งหมด ยิงลำแสงตัว Z โจมตีเป้าหมายศัตรูแบบสุ่ม 3 ตัว พร้อมทำให้ผลของการโจมตีต่อไปของเป้าหมายทั้งหมดกลายเป็นไร้ผล',
		starEffect = __data_t__starEffect[36233],
		-- {11}
		starEffectDesc = 'เอฟเฟกต์พิเศษ: เอฟเฟกต์ Core Punishment คงอยู่ 2 เทิร์น \n Complete Forme: จำนวนเป้าหมายโจมตี +1, เมื่อเปิดใช้งาน Core Punishment จะสร้างความเสียหายเท่ากับ 10% ของ HP สูงสุด (ไม่เกิน 300% Atk)  \n 50% Forme: จำนวนเป้าหมายโจมตี +1, เมื่อเปิดใช้งาน Core Punishment จะใส่ Venom Arrow เพิ่มอีก 1 ชั้น  \n 10% Forme: การโจมตีปกติจะได้รับโบนัสค่าสถานะเป็น 2 เท่า และสามารถซ้อนทับได้สูงสุด 5 ชั้น; ลดความเสียหายเพิ่มเติมและ Passive Damage จากเป้าหมายที่ติด Core Punishment ลง 50%  ',
		zawakeEffect = __data_t__zawakeEffect[36233],
		-- {79003, 1}
		zawakeEffectDesc = 'เอฟเฟกต์เสริม: เอฟเฟกต์ 【Core Punishment】 คงอยู่ 2 เทิร์น\nComplete Form: จำนวนเป้าหมายที่โจมตี +1 เมื่อเปิดใช้งาน 【Core Punishment】 จะสร้างความเสียหายเพิ่มเติมเท่ากับ 10% ของ Max HP ตนเอง (ไม่เกิน 500% Physical ATK ของตนเอง) และลด Accuracy ของเป้าหมายลง 10% เป็นเวลา 1 เทิร์น\n50% Form: จำนวนเป้าหมายที่โจมตี +1 เมื่อเปิดใช้งาน 【Core Punishment】 จะเพิ่ม 1 ชั้นของ 【Bone-Corrosive Venom Arrow】 และทำให้เกิดความเสียหายทันทีเมื่อใส่\n10% Form: Normal Attack ของตนเองจะเพิ่มบัฟให้กับ Zygarde 10% Form ทั้งหมด เอฟเฟกต์บัฟจะเพิ่มเป็น 2 เท่า และสามารถซ้อนทับได้สูงสุด 5 ชั้น ลดความเสียหายเพิ่มเติม/ความเสียหายแบบ Passive จากเป้าหมายที่ติด 【Core Punishment】 ลง 50%',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#ฟอร์มสมบูรณ์: สามารถโจมตีศัตรูได้เพิ่ม +1 เป้าหมาย และเมื่อกระตุ้น【Core Punishment】จะสร้างความเสียหายเพิ่มเติมเท่ากับ 10% ของ HP สูงสุดของตัวเอง (ไม่เกิน 500% ATK) และลดโอกาสโจมตีของเป้าหมาย 10% เป็นเวลา 1 เทิร์น\nฟอร์ม 50%: สามารถโจมตีศัตรูได้เพิ่ม +1 เป้าหมาย และเมื่อกระตุ้น【Core Punishment】จะใส่【Toxic Spike】เพิ่ม 1 ชั้นและสร้างดาเมจของ Toxic Spike ทันที\nฟอร์ม 10%: เมื่อโจมตีปกติจะเพิ่มบัฟเสริมให้กับทุกฟอร์ม 10% เอฟเฟกต์จะทวีคูณและสะสมได้สูงสุด 5 ชั้น；เป้าหมายที่ติด【Core Punishment】จะสร้างดาเมจเพิ่มเติม/พาสซีฟใส่ตนเองลดลง 50%#C0x5B545B#',
