	[36256] = {
		id = 36256,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#ซี๊ด...ข้ากำลังแยกตัว#C0x5B545B#\n#L10#Cell Division: #L0#เมื่อได้รับความเสียหายถึงขั้นเสียชีวิต จะทำการแบ่งร่างออกเป็นสองร่างที่มีรูปแบบต่ำกว่าที่ตำแหน่งว่างแบบสุ่มในทีม (ต่ำสุดคือร่าง 10% ค่าสถานะของร่างที่แยกจะถูกปรับตามค่า Base Stat และสืบทอดค่าความโกรธจากร่างต้นแบบ ไม่สืบทอดบัฟและเอฟเฟกต์ของไอเทม) เมื่อแบ่งร่าง จะสุ่มติดสถานะ【Cell】ใส่ศัตรู 2 ตัว\n#F20#\n#F40##L10#Balance of Vital Source (Aura): #L0#เมื่อ Zygarde ถูกโจมตีโดยโปเกมอนที่มี HP สูงสุดน้อยกว่าตน ความเสียหายที่ได้รับจะลดลง\n#C0x5c9970#$(20+skillLevel*0.2-0.2)$%\n#C0x5B545B#; เมื่อโจมตีโปเกมอนที่มี HP สูงสุดมากกว่าตน ความเสียหายจะเพิ่มขึ้น\n#C0x5c9970#$(20+skillLevel*0.2-0.2)$%\n#C0x5B545B#; เมื่อเข้าสนามรบในร่าง Complete Form จะเพิ่ม HP สูงสุด 30% ตั้งแต่ต้นเกม; หากถูกโจมตีโดยศัตรูที่มีสถานะ【Cell】:\nComplete Form: ความเสียหายจากการโจมตีครั้งนี้ลดลง 15% หาก HP ของตนต่ำกว่า 70% หลังโดนโจมตี จะดูด Cell จากผู้โจมตีกลับมา และฟื้นฟู HP ให้ตนเอง 4% ของ HP สูงสุด (มีพันธมิตรรอดชีวิตเพิ่ม 1 ตัว จะเพิ่มอัตราการฟื้นฟูอีก 4% สูงสุดไม่เกิน 300% พลังโจมตีกายภาพ)\n50% Form: ความเสียหายจากการโจมตีครั้งนี้ลดลง 10% และติดสถานะ【Bone-Corroding Poison Arrow】1 ชั้นให้ผู้โจมตี\n10% Form: ความเสียหายจากการโจมตีครั้งนี้ลดลง 5% และสวนกลับด้วยการโจมตีปกติใส่ผู้โจมตี\n#F20#\n#F40##L10#Field Disruption (Aura): #L0#ฝั่งเรามีโปเกมอนสาย Fairy 1 ตัว จะเพิ่มอัตราการฟื้นฟูของฝ่ายเรา 10% และลดอัตราการฟื้นฟูของศัตรู 10% (สูงสุด 30%)\nฝั่งเรามีโปเกมอนสาย Dark 1 ตัว จะลด HP สูงสุดเริ่มต้นของศัตรู 10% (สูงสุด 30%)\nฝั่งเรามีโปเกมอนสาย Dragon 1 ตัว จะเพิ่มความเสียหายของโปเกมอนสาย Dragon ฝ่ายเรา 10% (สูงสุด 30%)\nฝั่งเรามีโปเกมอนสาย Ground 1 ตัว จะเพิ่มการลดความเสียหายจริงของโปเกมอนสาย Ground ฝ่ายเรา 10% (สูงสุด 30%)\n#F20#\n#F40#【Cell】: ไม่สามารถซ้อนทับหรือชำระล้างได้ ลดความเร็ว 10% และลดพลังโจมตีกายภาพ/พลังพิเศษ 10% ของเป้าหมาย เมื่อ Cell ถูกเพิ่มซ้ำ จะดูด Cell เก่ากลับมาและฟื้นฟู HP ให้ Zygarde ฝ่ายเราที่มี HP สัดส่วนน้อยที่สุด โดยฟื้นเท่ากับ 10% ของ HP สูงสุดของ Zygarde Complete Form (ไม่เกิน 300% พลังโจมตีกายภาพ)',
		starEffect = __data_t__starEffect[36256],
		-- {8}
		starEffectDesc = 'เอฟเฟกต์เสริม: เมื่ออยู่ใน Split Form ครบ 2 เทิร์น จะดูดร่าง Zygarde ทั้งหมดในสนามรวมเป็นร่างขั้นสูง และฟื้น HP ตามจำนวนที่ดูดได้ พร้อมล้างสถานะผิดปกติทั้งหมด (เกิดได้ครั้งเดียว) \n เมื่อเข้าสู่สนามหรือแยกร่าง จะสุ่มใส่ Cell ให้ศัตรู 3 ตัว และทำให้ Cell ทุกอันเปิดใช้งาน【Core Punishment】',
		zawakeEffect = __data_t__zawakeEffect[36256],
		-- {79004, 1}
		zawakeEffectDesc = 'เอฟเฟกต์เสริม: เมื่อ Split Form อยู่รอดครบ 2 เทิร์น จะดูดซับ Zygarde ทุกรูปแบบในสนาม รวมร่างเป็นฟอร์มที่สูงขึ้น และฟื้นฟู HP ของตนเองตามจำนวนยูนิตที่ดูดซับได้ การรวมร่างจะล้างสถานะผิดปกติทั้งหมด\nเมื่อ Zygarde Complete Form เข้าสนามหรือรวมร่างเข้าสนาม จะใส่สถานะ Cell ให้กับศัตรูทุกตัว และเปิดใช้งานเอฟเฟกต์ 【Core Punishment】 ของ Cell ทั้งหมด เมื่อฟอร์มใดก็ตามเข้าสู่ Split Form จะสุ่มใส่ Cell ให้กับศัตรู 3 ตัว และเปิดใช้งานเอฟเฟกต์ 【Core Punishment】 ของ Cell ทั้งหมด\nเมื่อ Zygarde เข้าสนาม จะเพิ่ม Final Damage Reduction ของตนเอง 15% และลดลง 3% ในทุกเทิร์นถัดไป',
