	[36331] = {
		id = 36331,
		skillName = 'สกิลทั่วไป',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#แข็งแกร่งไร้เทียมทาน ทำลายได้ทุกสิ่ง#C0x5B545B#\n#F10#\n#F40#Mega Diancie เรียกผลึกคริสตัลโจมตีเป้าหมายเดี่ยว สร้างความเสียหายพิเศษ #C0x3D8A99#140% พลังโจมตีพิเศษ#C0x5B545B#+$(skillLevel*4*24)$ของ#C0xF13B54#ความเสียหายพิเศษ#C0x5B545B# เพิ่มพลังป้องกันสองด้าน 100% พลังโจมตีสองด้าน 40% และเพิ่มพลังโจมตีพิเศษตาม 100% ของค่าป้องกันพิเศษ เป็นเวลา 2 เทิร์น\n#F20#\n#F40#เมื่อใช้ Sword Dance จะปล่อยสกิลนี้อีกครั้ง',
		zawakeEffect = __data_t__zawakeEffect[36331],
		-- {79001}
		zawakeEffectDesc = '#C0xC0C0C0#Unbreakable, Unstoppable#C0x5B545B#\n#F10#\n#F40#Mega Diancie อัญเชิญ Crystal Rock โจมตีเป้าหมายศัตรูเดี่ยว สร้างความเสียหาย #C0x3D8A99#100% Special ATK#C0x5B545B# + $(skillLevel*4*24)$ เป็น #C0xF13B54#Special Damage#C0x5B545B# เพิ่ม Double Defense 100% และ Double ATK 40% พร้อมเพิ่ม Special ATK ตาม 100% ของ Special Defense ทั้งหมด นาน 2 เทิร์น；หากอยู่ในสถานะ Lightblade จะกระตุ้น Sword Dance เพิ่มเติม 1 ครั้ง (คูลดาวน์ 1 เทิร์น)\n#F20#\n#F40#เมื่อลง Sword Dance จะกระตุ้นเอฟเฟกต์ของสกิลนี้อีก 1 ครั้ง',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'หากอยู่ในฟอร์ม Sacred Sword จะกระตุ้น【Sword Dance】อีก 1 ครั้ง (คูลดาวน์ 1 เทิร์น)',
		upLvDesc = 'เพิ่มความเสียหายคงที่+96',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		changeUnitTrigger = true,
		isCombat = true,
		passivePriority = 100,
		skillType2 = 0,
		skillDamageType = 1,
		skillNatureType = 13,
		posChoose = 1,
		targetTypeDesc = 'ศัตรูเดี่ยว',
		targetChooseType = 'single',
		damageFormula = 'self:specialDamage()*1.2+(self:flag(99) and skillLevel or skillLevel*4)*24',
		skillProcess = {363311, 363312, 363313, 363314},
