	[36332] = {
		id = 36332,
		skillName = 'สกิลพิเศษ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#ข้าจะกลายเป็นแสงแห่งเพชรที่ส่องทางให้ทุกคน#C0x5B545B#\n#F10#\n#F40#Mega Diancie ปล่อยแสงจากอัญมณีบนหัว รักษาตัวเอง เพื่อนที่มีพลังโจมตีสูงสุด และเพื่อนธาตุ Fairy/Rock แบบสุ่ม 1 ตัว ฟื้น HP เท่ากับ #C0x3D8A99#220% พลังโจมตีพิเศษ#C0x5B545B#+$(skillLevel*4*24)$พร้อมมอบ Mini Diamond Shield 3 เทิร์น ให้แต่ละเป้าหมาย ตนเองได้รับ Radiant Body 2 เทิร์น เพื่อนที่มี Mini Diamond Shield ได้รับพลังโจมตีสองด้านเพิ่ม 15% ได้รับครึ่งหนึ่งของ Radiant Body เอฟเฟกต์ Fairy ได้รับโบนัสฟื้นฟู +30% Rock ได้รับลดความเสียหาย +30%\n#F20#\n#F40##L10#Radiant Body: #L0#เพิ่มอัตราต้านสถานะและต้านดีบัฟ 100% เมื่อได้รับความเสียหายจะสะสม 40% กลายเป็น Radiant Beam ยิงใส่ศัตรู 2 ตัวแบบสุ่มสร้าง #C0xFF6EC7#ความเสียหายศักดิ์สิทธิ์#C0x5B545B# (สูงสุดไม่เกิน 300% พลังโจมตีพิเศษของตนเอง) และฟื้น HP 20% เมื่อจบเทิร์น\n#F20#\n#F40##L10#Mini Diamond Shield: #L0#เมื่อถูกโจมตีเชิงรุกครั้งแรกจะกันดาเมจได้ 1 ครั้ง หลังจากนั้นกลายเป็นโล่ที่มีค่าเท่ากับ 100% พลังโจมตีพิเศษ และเมื่อโล่แตกจะสะท้อน 30% ของค่าโล่กลับไปเป็น #C0xFF6EC7#ความเสียหายศักดิ์สิทธิ์#C0x5B545B#\n#F20#\n#F40#สกิลนี้มีคูลดาวน์ 4 เทิร์น เมื่อใช้ Sword Dance จะลดคูลดาวน์ลง 1 เทิร์น',
		zawakeEffect = __data_t__zawakeEffect[36332],
		-- {79002}
		zawakeEffectDesc = '#C0xC0C0C0#I Will Be the Diamond Light That Shines on Everyone#C0x5B545B#\n#F10#\n#F40#Mega Diancie ปล่อยแสงจากอัญมณีบนหัว รักษา HP ให้กับตนเอง, ยูนิตที่มี ATK สูงสุด และยูนิตประเภท Fairy/Rock แบบสุ่มอีก 1 ตัว ฟื้นฟู #C0x3D8A99#100% Special ATK#C0x5B545B# + $(skillLevel*4*24)$ และให้สถานะ 【Mini Diamond Shield】 3 เทิร์น；ตนเองได้รับสถานะ 【Radiant Body】 2 เทิร์น และทำให้เพื่อนร่วมทีมที่มี Mini Diamond Shield ได้รับบัฟ Double ATK +15% ชั่วคราว ก่อนโจมตี Fairy-type ได้รับ +30% Healing Rate และ Rock-type ได้รับ +30% Damage Reduction；ในเทิร์นแรกที่ได้รับ Radiant Body จะกันการลด Rage\n#F20#\n#F40##L10#【#L10#Radiant Body#L0#】：#L0#เพิ่มอัตราต้านทานสถานะควบคุมและดีบัฟ 100% (ดูรายละเอียดใน Battle Manual)；เมื่อได้รับความเสียหาย จะสะท้อน 40% ความเสียหายเป็น 2 ลำแสง 【#L10#Radiant Beam#L0#】 โจมตีศัตรู 2 ตัว สร้าง #C0xFF6EC7#Divine Damage#C0x5B545B# (สูงสุดไม่เกิน 300% Special ATK ของ Mega Diancie) และฟื้นฟู 20% Max HP ของตัวเองเมื่อจบเทิร์น\n#F20#\n#F40##L10#【#L10#Mini Diamond Shield#L0#】：#L0#เมื่อถูกโจมตีแบบ Active ครั้งแรก จะใช้เศษเพชรป้องกันการโจมตี และกลายเป็น Shield ที่เท่ากับ 100% ของ Special ATK；เมื่อ Shield แตก จะสะท้อน 30% ของมูลค่า Shield ที่หายไปเป็น #C0xFF6EC7#Divine Damage#C0x5B545B# ใส่ผู้โจมตี\n#F20#\n#F40#สกิลนี้มีคูลดาวน์ 3 เทิร์น เมื่อใช้ Sword Dance จะลดคูลดาวน์ลง 1 เทิร์น',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'ลดคูลดาวน์สกิล 1 เทิร์น; Mega Diancie จะได้รับ【Brilliant Body】ในเทิร์นแรกซึ่งกันการลดเกจโกรธ',
		upLvDesc = '治疗+96',
