	[36333] = {
		id = 36333,
		skillName = 'ท่าไม้ตาย',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#แสงศักดิ์สิทธิ์ จะปกป้องทุกสิ่งในแดนนี้#C0x5B545B#\n#F10#\n#F40#Mega Diancie อัดคาร์บอนในอากาศให้กลายเป็นเพชร โจมตีเป้าหมายเดี่ยว สร้างความเสียหายพิเศษ #C0x3D8A99#500% พลังโจมตีพิเศษ#C0x5B545B#+$(skillLevel*4*90)$ ของ#C0xF13B54#ความเสียหายพิเศษ#C0x5B545B# และใส่สถานะ Crystal Seal 1 เทิร์น จากนั้นสร้าง Diamond Starwall ให้กับทีม เมื่อ Starwall แตก จะฟื้น HP ให้เพื่อนทั้งหมดเท่ากับ 60% พลังโจมตีพิเศษของ Diancie (ส่วนที่เกินจะเปลี่ยนเป็นโล่) และยิง Starwall Beam จาก 8% ของค่า HP Starwall สร้าง #C0xFF6EC7#ความเสียหายศักดิ์สิทธิ์#C0x5B545B# ใส่ศัตรูทั้งหมด หากหลังใช้สกิลนี้ยังอยู่ในสถานะ Sword of Light จะรีเฟรชจำนวนครั้งของ Holy Sword Beam (หากเต็มจะปล่อยฟรีทันที 1 ครั้ง) และการใช้ Holy Sword Beam ครั้งถัดไปจะปล่อย Sword Dance เพิ่มอีก 1 ครั้ง สร้างความเสียหาย #C0x3D8A99#80% พลังโจมตีพิเศษ#C0x5B545B#+$(skillLevel*8000)$ ของ#C0xFF6EC7#ความเสียหายศักดิ์สิทธิ์#C0x5B545B# ใส่ศัตรูทั้งหมด\n#F20#\n#F40##L10#Crystal Seal: #L0#เอฟเฟกต์ควบคุมระดับครอบงำ เป้าหมายจะถูกแยกเข้าไปในผลึก ไม่สามารถกระทำหรือสะสมโกรธได้ เมื่อ Holy Sword Beam ทำงาน จะโจมตีเป้าหมายที่ติด Crystal Seal เพิ่มอีก 1 ครั้ง และกระตุ้น Crystal Refraction สร้างความเสียหาย #C0x3D8A99#100% พลังโจมตีพิเศษ#C0x5B545B#+$(skillLevel*3000)$ ของ#C0xFF6EC7#ความเสียหายศักดิ์สิทธิ์#C0x5B545B# ใส่ศัตรูในพื้นที่ 3x3',
		starEffect = __data_t__starEffect[36333],
		-- {11}
		starEffectDesc = 'มอบ【Diamond Prism】ให้กับยูนิตแบบสุ่ม 3 ตัว เป็นเวลา 2 เทิร์น: เมื่อได้รับสกิล【#L10#Starwall Beam#L0#】, 【#L10#Radiant Beam#L0#】, หรือ【#L10#Sacred Sword Beam#L0#】จาก Mega Diancie จะสะท้อนกลับไปยังเป้าหมายอื่นพร้อมสร้างความเสียหายแบบศักดิ์สิทธิ์เท่ากัน และสามารถสะท้อนได้ต่อเนื่องสูงสุด 3 ครั้ง  ',
		zawakeEffect = __data_t__zawakeEffect[36333],
		-- {79003}
		zawakeEffectDesc = '#C0xC0C0C0#Holy Light, Protect This Land#C0x5B545B#\n#F10#\n#F40#Mega Diancie บีบอัดธาตุคาร์บอนในอากาศให้กลายเป็นเพชร โจมตีศัตรูเดี่ยว สร้างความเสียหาย #C0x3D8A99#500% Special ATK#C0x5B545B# + $(skillLevel*4*90)$ เป็น #C0xF13B54#Special Damage#C0x5B545B# และทำให้ติดสถานะ 【Crystal Seal】 1 เทิร์น；จากนั้นสร้าง 【Diamond Star Wall】 ให้ทีมเรา (ดูรายละเอียดใน Battle Manual) เมื่อกำแพงแตก จะฟื้นฟู HP ให้ทั้งทีมเท่ากับ 60% Special ATK ของ Diancie (ส่วนเกินจะกลายเป็น Shield) และสร้างลำแสง 【#L10#Starwall Beam#L0#】 จาก 8% ของค่า HP กำแพง สร้าง #C0xFF6EC7#Divine Damage#C0x5B545B# ใส่ศัตรูทุกตัว；หากหลังใช้ Ultimate อยู่ในสถานะ Lightblade จะฟื้นฟูจำนวนครั้งใช้งานของ 【#L10#Holy Blade Beam#L0#】 (หากเต็มจะปลดใช้ 1 ครั้งฟรีทันที) และในการใช้งานครั้งถัดไปของ Holy Blade Beam จะกระตุ้น Sword Dance อีกครั้ง สร้างความเสียหาย #C0x3D8A99#80% Special ATK#C0x5B545B# + $(skillLevel*8000)$ เป็น #C0xFF6EC7#Divine Damage#C0x5B545B# ใส่ศัตรูทุกตัว\n#F20#\n#F40##L10#【#L10#Crystal Seal#L0#】：#L0#เป็นสถานะควบคุมแบบกดขี่ กักเป้าหมายไว้ในคริสตัล ไม่สามารถเคลื่อนไหว และถูกปิด Rage เมื่อมีการกระตุ้น 【Holy Blade Beam】 จะโจมตีเป้าหมายที่ติด Crystal Seal เพิ่มอีกครั้ง และทำให้เกิด Crystal Reflection สร้างความเสียหายเป็น #C0x3D8A99#100% Special ATK#C0x5B545B# + $(skillLevel*3000)$ เป็น #C0xFF6EC7#Divine Damage#C0x5B545B# ต่อศัตรูในกริด 9 ช่อง',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '#C0x5c9970#เพิ่มค่าสัมประสิทธิ์ความเสียหายพื้นฐานเป็น 550%; เมื่อใช้ท่าไม้ตายครั้งแรก จะสามารถใส่【Crystal Seal】ศัตรู 1 ตัวเป็นเวลา 1 เทิร์น；ก่อนปล่อยท่าไม้ตายจะได้รับหรือขยายระยะเวลา【Brilliant Body】1 เทิร์น และเมื่อ【Diamond Star Wall】แตก จะได้รับเอฟเฟกต์นี้ทันที (คูลดาวน์ 6 เทิร์น ใช้ได้ 2 ครั้งต่อการต่อสู้)',
		upLvDesc = 'เพิ่มความเสียหายคงที่+360',
