	[36336] = {
		id = 36336,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#เพราะมีพวกเธออยู่ข้างกาย ข้าจึงสร้างเพชรที่แท้จริงได้#C0x5B545B#\n#F10#\n#F40##L10#Starwall Guard: #L0#เมื่อเข้าสนามเป็นครั้งแรก จะเรียก Diamond Starwall โดยมีค่า HP เท่ากับ 400% ของพลังโจมตีสองด้านของ Diancie และจะเพิ่มอีก 50% ต่อเพื่อนร่วมทีมธาตุ Fairy/Rock/Ground แต่ละตัว เมื่อ Starwall แตกเป็นครั้งแรก จะสร้าง Mini Diamond Shield ให้กับเพื่อนธาตุ Fairy/Rock/Ground ทุกตัวเป็นเวลา 3 เทิร์น\n#F20#\n#F40##L10#Diamond Starwall: #L0#ขณะอยู่ในสนาม เพื่อนร่วมทีมทั้งหมดจะได้รับการลดความเสียหายเพิ่ม 30% ทุกดีบัฟที่เพื่อนร่วมทีมได้รับจะสะท้อนกลับไปยังผู้ร่าย สำหรับโปเกมอนสาย Fairy/Rock/Ground การฟื้น HP ส่วนเกิน 40% จะถูกเปลี่ยนเป็นการฟื้นฟูค่า HP ของ Starwall\n#F20#\n#F40##L10#Sword in Stone: #L0#ทุกครั้งที่ Starwall แตก เศษผลึกจะก่อตัวกลายเป็นดาบแสงเพชรและฟื้นโกรธ 150 แต้ม ขณะอยู่ในสถานะดาบจะได้รับต้านคริติคอล 50% ลดความเสียหาย 50% และเพิ่มอัตราป้องกัน 50% และจะฟื้นโกรธ 150 แต้มก่อนเริ่มเทิร์น หากได้รับการฟื้น HP สะสมครบ 15% หรือสามารถป้องกันสำเร็จ จะยิง Holy Sword Beam ใส่แหล่งที่มาของดาเมจล่าสุด สร้างความเสียหาย #C0x3D8A99#100% พลังโจมตีพิเศษ#C0x5B545B#+$(skillLevel*3000)$ ของ#C0xFF6EC7#ความเสียหายศักดิ์สิทธิ์#C0x5B545B# เมื่อปล่อยครบ 4 ครั้งจะสิ้นสุดสถานะดาบ\n#F20#\n#F40##L10#Fairy Rock Essence: #L0#เมื่อมีเพื่อนธาตุ Fairy/Rock/Ground อย่างน้อย 2 ตัว จะเรียก Fairy Rock ลอยขึ้นในสนาม ขณะมีอยู่ เพื่อนร่วมทีมจะฟื้น HP 5% ของ HP สูงสุดในทุกการกระทำ (ธาตุ Fairy/Rock/Ground ได้ 2 เท่า) Mega Diancie จะแชร์พลังโจมตีสองด้าน 50% ให้กับเพื่อนธาตุเดียวกัน เมื่อเพื่อนร่วมทีมได้รับดาเมจเกิน 100% พลังโจมตีพิเศษของ Diancie จะต้านดาเมจนั้นไว้ (จำกัด 5 ครั้งต่อรอบใหญ่) Fairy Rock คงอยู่ 2 เทิร์น คูลดาวน์ 2 เทิร์น และจะล้างสถานะควบคุมที่ไม่ใช่ระดับครอบงำ พร้อมปล่อยท่าไม้ตายฟรี 1 ครั้ง (เลือกเป้าหมายที่ไม่อยู่ใน Crystal Seal หากไม่มีเป้าหมายจะเรียก Diamond Starwall แทน)',
		starEffect = __data_t__starEffect[36336],
		-- {8}
		starEffectDesc = '#L10#Triple Starwall:#L0# เมื่อ Mega Diancie ได้รับความเสียหายถึงตาย หากยังมีพันธมิตรอยู่ จะยังคงอยู่ในสนามในสภาพไม่สามารถกระทำการใดๆ ได้ แต่จะสร้าง Triple Starwall ให้เพื่อนร่วมทีม โดยแต่ละชั้นมี HP เท่ากับ 600% ของ Atk + Sp. Atk ของ Diancie; หากยังมีโล่หลงเหลืออยู่หลังผ่านไป 1 เทิร์น จะฟื้นคืนชีพเต็ม HP และ Rage พร้อมรับบัฟ【Radiant Body】2 เทิร์น มิฉะนั้นหากโล่แตก Mega Diancie จะล้มลง (เกิดได้เพียงครั้งเดียว)',
		zawakeEffect = __data_t__zawakeEffect[36336],
		-- {79004}
		zawakeEffectDesc = '#L10#Fivefold Star Wall: #L0#เมื่อ Mega Diancie กำลังจะตาย หากยังมีเพื่อนร่วมทีมในสนาม จะยังคงยืนหยัดอยู่ โดยไม่สามารถกระทำการใด ๆ ได้ แต่จะสร้าง Fivefold 【Diamond Star Wall】 ให้ทีม แต่ละชั้นมี HP เท่ากับ 600% ของ Double ATK ของ Diancie เมื่อกำแพงทั้งหมดแตก จะสุ่มทำให้ศัตรู 1 ตัวติด 【Crystal Seal】；หากยังมี Star Wall เหลืออยู่หลังผ่าน 1 เทิร์น จะคืนชีพเต็มเลือดพร้อม Rage เต็ม และได้รับ 【Radiant Body】 2 เทิร์น；หากกำแพงแตกหมด Mega Diancie จะล้มลง (ทั้งแมตช์ใช้ได้ 1 ครั้งเท่านั้น)；หากมี Fairy-Rock อยู่ในสนาม Mega Diancie จะปล่อย 【Holy Blade Beam】 ใส่ศัตรูแบบสุ่ม 3 ตัวก่อนเริ่มเทิร์น',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'เมื่อได้รับความเสียหาย致命 จะอัปเกรดจาก【Triple Star Wall】เป็น【Quintuple Star Wall】; เมื่อ【Quintuple Star Wall】แตก จะสุ่มทำให้ศัตรู 1 ตัวติด【#L10#Crystal Seal#L0#】；หากมี Fairy Rock อยู่ในสนาม Mega Diancie จะปล่อย【Sacred Sword Beam】ใส่ศัตรูแบบสุ่ม 3 ตัวก่อนเริ่มเทิร์น',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
