	[36352] = {
		id = 36352,
		skillName = 'สกิลพิเศษ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#ข้าจะกลายเป็นแสงแห่งเพชรที่ส่องทางให้ทุกคน#C0x5B545B#\n#F10#\n#F40#Mega Diancie ปล่อยแสงเปล่งประกายจากอัญมณีบนหัว รักษาตัวเอง เพื่อนที่มีพลังโจมตีสูงสุด และเพื่อนธาตุ Fairy/Rock แบบสุ่ม 1 ตัว ฟื้น HP เท่ากับ #C0x3D8A99#200% พลังโจมตีพิเศษ#C0x5B545B#+$(skillLevel*4*24)$และมอบ Mini Diamond Shield 3 เทิร์น ให้แต่ละเป้าหมาย ตนเองได้รับ Radiant Body 2 เทิร์น เพื่อนที่มี Mini Diamond Shield ได้รับพลังโจมตีสองด้านเพิ่ม 15% Fairy ได้รับอัตราฟื้นฟู +30% Rock ได้รับลดความเสียหาย +30%\n#F20#\n#F40##L10#Radiant Body: #L0#เพิ่มอัตราต้านสถานะและต้านดีบัฟ 100% เมื่อได้รับความเสียหายจะสะสม 40% เป็น Radiant Beam ยิงใส่ศัตรู 2 ตัวแบบสุ่มสร้าง #C0xFF6EC7#ความเสียหายศักดิ์สิทธิ์#C0x5B545B# (สูงสุดไม่เกิน 300% พลังโจมตีพิเศษของ Mega Diancie) ฟื้น HP 20% เมื่อจบเทิร์น\n#F20#\n#F40##L10#Mini Diamond Shield: #L0#เมื่อถูกโจมตีเชิงรุกครั้งแรกจะกันดาเมจได้ 1 ครั้ง จากนั้นกลายเป็นโล่เท่ากับ 100% พลังโจมตีพิเศษ หากโล่แตกจะสะท้อน 30% ของค่าป้องกันกลับไปเป็น #C0xFF6EC7#ความเสียหายศักดิ์สิทธิ์#C0x5B545B#\n#F20#\n#F40#คูลดาวน์สกิล 4 เทิร์น การใช้ Sword Dance จะลดคูลดาวน์ลง 1 เทิร์น',
		zawakeEffect = __data_t__zawakeEffect[36352],
		-- {79002}
		zawakeEffectDesc = '#C0xC0C0C0#I will be the diamond starlight that shines on everyone#C0x5B545B#\n#F10#\n#F40#อัญมณีบนศีรษะของ Mega Diancie ส่องแสงเจิดจ้า รักษาตัวเอง, เป้าหมายที่มี ATK สูงสุด และ Pokémon ธาตุ Fairy หรือ Rock แบบสุ่มอีก 1 ตัว ฟื้นฟู HP ตาม#C0x3D8A99#100% Sp. ATK#C0x5B545B#+$(skillLevel*4*24)$ และให้ Small Diamond Shield เป็นเวลา 3 เทิร์น; ตัวเองได้รับ Radiant Body เป็นเวลา 2 เทิร์น ในขณะเดียวกันพันธมิตรที่มี Small Diamond Shield จะได้ ATK กับ Sp. ATK เพิ่ม 15% ชั่วคราว, ได้รับครึ่งหนึ่งของ Radiant Body เอฟเฟกต์, ธาตุ Fairy ได้อัตราฟื้นฟู 30%, ธาตุ Rock ได้รับ Damage Reduction 30%; ตัวเองได้ Immunity จากการลดเกจพลังในเทิร์นแรกของ Radiant Body\n#F20#\n#F40##L10#【#L10#Radiant Body#L0#】：#L0#เพิ่มอัตราต้านทานการควบคุมพิเศษและเอฟเฟกต์ลบล้าง 100% (ดูรายละเอียดใน Battle Manual); เมื่อได้รับความเสียหาย จะสะสม 40% ความเสียหายเป็นสองลำแสง【#L10#Radiant Beam#L0#】สะท้อนให้ศัตรู 2 ตัวแบบแบ่งเท่าๆ กัน สร้าง#C0xFF6EC7#Sacred Damage#C0x5B545B# (สูงสุด 300% Sp. ATK ของ Mega Diancie) และฟื้นฟู HP ตาม 20% ของ HP สูงสุดเมื่อจบ\n#F20#\n#F40##L10#【#L10#Small Diamond Shield#L0#】：#L0#ครั้งแรกที่โดนโจมตีแบบ Active จะมีเศษเพชรเล็กๆ ป้องกันหนึ่งครั้ง จากนั้นจะกลายเป็นโล่ที่มีค่าเท่ากับ 100% Sp. ATK; เมื่อโล่แตก จะสะท้อน 30% ของค่าป้องกันกลับไปที่ผู้โจมตี เป็น#C0xFF6EC7#Sacred Damage#C0x5B545B#\n#F20#\n#F40#คูลดาวน์ของสกิลนี้ 3 เทิร์น เมื่อใช้ Swords Dance จะลดคูลดาวน์ลง 1 เทิร์น',
