	[36356] = {
		id = 36356,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#เพราะมีพวกเธออยู่ ข้าจึงสามารถสร้างเพชรที่แท้จริงได้#C0x5B545B#\n#F10#\n#F40##L10#Starwall Guard: #L0#เมื่อเข้าสนามจะเรียก Diamond Starwall ที่มี HP เท่ากับ 400% พลังโจมตีสองด้านของ Diancie เพิ่มขึ้น 50% ต่อเพื่อนธาตุ Fairy/Rock/Ground 1 ตัว เมื่อ Starwall แตกครั้งแรกจะสร้าง Mini Diamond Shield ให้เพื่อนธาตุ Fairy/Rock/Ground ทุกตัว นาน 3 เทิร์น\n#F20#\n#F40##L10#Diamond Starwall: #L0#ระหว่างคงอยู่ เพื่อนทั้งหมดได้รับการลดความเสียหายเพิ่ม 30% สะท้อนดีบัฟทั้งหมดกลับไปยังผู้ร่าย และเพื่อนธาตุ Fairy/Rock/Ground จะฟื้น Starwall ตาม 40% ของการฟื้น HP ส่วนเกิน\n#F20#\n#F40##L10#Sword in Stone: #L0#เมื่อ Starwall แตกจะสร้าง Sword of Light 1 ดาบ ฟื้นโกรธ 150 แต้ม ขณะอยู่ในสถานะดาบ จะได้รับต้านคริติคอล 50%, ลดดาเมจ 50%, และอัตราป้องกัน 50% ก่อนเริ่มเทิร์นจะฟื้นโกรธ 150 แต้ม เมื่อการฟื้น HP สะสมครบ 15% หรือป้องกันสำเร็จ จะยิง Holy Sword Beam ใส่ศัตรูที่โจมตีก่อนหน้า (ดูรายละเอียดในคู่มือ) สร้างความเสียหาย #C0x3D8A99#100% พลังโจมตีพิเศษ#C0x5B545B#+$(skillLevel*3000)$ ของ#C0xFF6EC7#ความเสียหายศักดิ์สิทธิ์#C0x5B545B# หากปล่อยครบ 4 ครั้งจะสิ้นสุดสถานะดาบ  \n#F20#\n#F40##L10#Fairy Rock Essence: #L0#หากมีเพื่อนธาตุ Fairy/Rock/Ground อย่างน้อย 2 ตัว จะเรียก Fairy Rock ลอยขึ้น เมื่ออยู่จะฟื้น HP 5% ทุกเทิร์น (ธาตุ Fairy/Rock/Ground ได้ 2 เท่า) และ Diancie จะแชร์พลังโจมตีสองด้าน 50% ให้เพื่อนธาตุเดียวกัน หากเพื่อนถูกโจมตีเกิน 100% พลังโจมตีพิเศษของ Diancie จะต้านดาเมจนั้นได้ (สูงสุด 5 ครั้งต่อรอบใหญ่) Fairy Rock อยู่ 2 เทิร์น คูลดาวน์ 2 เทิร์น พร้อมล้างสถานะควบคุมที่ไม่ใช่แบบครอบงำ และปล่อยท่าไม้ตายฟรี 1 ครั้ง (เลือกเป้าหมายที่ไม่อยู่ใน Crystal Seal หากไม่มีเป้าหมายจะสร้าง Diamond Starwall แทน)',
		starEffect = __data_t__starEffect[36356],
		-- {8}
		starEffectDesc = '#L10#Triple Starwall:#L0# เมื่อ Mega Diancie ได้รับความเสียหายถึงตาย หากยังมีพันธมิตรอยู่ จะยังคงอยู่ในสนามในสภาพไม่สามารถกระทำการใดๆ ได้ แต่จะสร้าง Triple Starwall ให้เพื่อนร่วมทีม โดยแต่ละชั้นมี HP เท่ากับ 600% ของ Atk + Sp. Atk ของ Diancie; หากยังมีโล่หลงเหลืออยู่หลังผ่านไป 1 เทิร์น จะฟื้นคืนชีพเต็ม HP และ Rage พร้อมรับบัฟ【Radiant Body】2 เทิร์น มิฉะนั้นหากโล่แตก Mega Diancie จะล้มลง (เกิดได้เพียงครั้งเดียว)',
		zawakeEffect = __data_t__zawakeEffect[36356],
		-- {79004, 1}
		zawakeEffectDesc = '#L10#Five-Layer Star Wall：#L0#เมื่อ Mega Diancie ได้รับความเสียหายรุนแรงถึงขั้นตาย ถ้ายังมีเพื่อนร่วมทีมอยู่ Mega Diancie จะยังคงยืนหยัด แต่ไม่สามารถเคลื่อนไหวได้ พร้อมสร้าง Five-Layer【Diamond Star Wall】ให้เพื่อนร่วมทีม แต่ละชั้นมี HP เท่ากับ 600% ของรวม ATK และ Sp. ATK ของ Diancie หากพังหมด จะสุ่มใส่【#L10#Crystal Seal#L0#】ให้ศัตรู 1 ตัว; ถ้าใน 1 เทิร์นยังมี Star Wall เหลืออยู่ Mega Diancie จะฟื้นเต็ม HP และเกจพลัง พร้อมได้【Radiant Body】2 เทิร์น ถ้าไม่มีจะตายเมื่อ Star Wall พัง (เกิดได้ 1 ครั้งต่อเกม); ขณะ Fairy Rock อยู่ในสนาม Mega Diancie จะยิง【Holy Sword Beam】ใส่ศัตรู 3 ตัวแบบสุ่มก่อนเริ่มเทิร์น',
