	[36511] = {
		id = 36511,
		skillName = 'สกิลทั่วไป',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#สตาร์ตด้วยพลังไอน้ำ!#C0x5B545B#\n#F10#\n#F40#Volcanion สะสมพลังไอน้ำโจมตีเป้าหมายเดี่ยวของศัตรู สร้างความเสียหายพิเศษ #C0x3D8A99#80% พลังโจมตีพิเศษ#C0x5B545B#+$(skillLevel*4*24)$ของ#C0xF13B54#ความเสียหายพิเศษ#C0x5B545B# เพิ่มพลังโจมตีพิเศษและโบนัสธาตุน้ำ/ไฟของตนเอง 20% เป็นเวลา 2 เทิร์น และวาง Steam Trap ใต้เท้าของเป้าหมายเป็นเวลา 2 เทิร์น\n#F20#\n#F40#Steam Trap: กับดักพิเศษ จะระเบิดไอน้ำร้อนเมื่อเป้าหมายจบเทิร์นหรือจบการเคลื่อนที่ สร้างความเสียหายกับดัก 180% ของพลังโจมตีพิเศษแก่เป้าหมาย และสร้างความเสียหายครึ่งหนึ่งให้ศัตรูรอบข้าง (หากเป้าหมายไม่ได้ทำการใด ๆ ในเทิร์นปัจจุบัน ความเสียหายจะเพิ่มขึ้นอีก 50%)',
		zawakeEffect = __data_t__zawakeEffect[36511],
		-- {79001}
		zawakeEffectDesc = '#C0xC0C0C0#Steam Activation!#C0x5B545B#\n#F10#\n#F40#Volcanion รวบรวมพลังไอน้ำโจมตีเป้าหมายเดี่ยวศัตรู สร้างความเสียหาย#C0x3D8A99#80% Sp. ATK#C0x5B545B#+$(skillLevel*4*24)$ เป็น#C0xF13B54#Special Damage#C0x5B545B# และเพิ่ม Sp. ATK และ Water/Fire Elemental Damage ให้ตัวเองและ Pokémon ธาตุ Water หรือ Fire อีกหนึ่งตัว 20% เป็นเวลา 2 เทิร์น; พร้อมวาง【Steam Trap】ไว้ใต้เท้าศัตรูเป็นเวลา 2 เทิร์น\n#F20#\n#F40#【Steam Trap】：กับดักไอร้อน เมื่อเป้าหมายจบเทิร์นหรือสิ้นสุดการเคลื่อนที่ กับดักจะปล่อยไอน้ำร้อนโจมตี สร้างความเสียหายจาก Sp. ATK 180% แก่เป้าหมาย และครึ่งหนึ่งของความเสียหายกับศัตรูรอบข้าง (หากเป้าหมายไม่ได้กระทำการในเทิร์นนั้น ความเสียหายของกับดักจะเพิ่มขึ้นอีก 50% ในเทิร์นถัดไป)',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#เพิ่ม Sp.ATK และความเสียหายธาตุน้ำ/ไฟ 20% ให้กับโปเกมอนธาตุน้ำหรือไฟแบบสุ่ม 1 ตัว นาน 2 เทิร์น',
		upLvDesc = 'เพิ่มความเสียหายคงที่+96',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		changeUnitTrigger = true,
		isCombat = true,
		passivePriority = 100,
		skillType2 = 0,
