		targetChooseType = 'single',
		damageFormula = 'self:specialDamage()*0.8+(self:flag(99) and skillLevel or skillLevel*4)*24',
		skillProcess = {365111, 365112, 365113, 365114},
		recoverMp1 = 240,
		posC = __data_t__posC[36511],
		-- {['y'] = 0, ['x'] = -250, __size = 2}
