	[36512] = {
		id = 36512,
		skillName = 'สกิลพิเศษ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#จุดอ่อนที่ใหญ่ที่สุดของฉัน ก็คือตัวฉันเอง!#C0x5B545B#\n#F10#\n#F40#Volcanion พุ่งตัวด้วยแรงดันไอน้ำชนเป้าหมายเดี่ยว สร้างความเสียหายพิเศษ #C0x3D8A99#180% พลังโจมตีพิเศษ#C0x5B545B#+$(skillLevel*4*60)$ ของ#C0xF13B54#ความเสียหายพิเศษ#C0x5B545B# ผลักเป้าหมายไปยังช่องหลัง หากไม่สามารถถอยได้จะทำให้เป้าหมายติด Stun 1 เทิร์น จากนั้น Volcanion เข้าสู่สถานะ Steam Mist เป็นเวลา 1 เทิร์น\n#F20#\n#F40#Steam Mist: ไม่สามารถถูกเลือกเป็นเป้าหมาย ระหว่างคงอยู่ลดความเสียหายที่ได้รับ 30% และได้รับ Steam Power 3 แต้มทันที หากมี Geothermal Spring บนสนาม จะได้รับ Steam Power เพิ่มอีก 2 แต้ม และลดความเสียหายที่ได้รับครึ่งหนึ่ง',
		zawakeEffect = __data_t__zawakeEffect[36512],
		-- {79002}
		zawakeEffectDesc = '#C0xC0C0C0#My greatest weakness is myself!#C0x5B545B#\n#F10#\n#F40#Volcanion พุ่งเข้าใส่ศัตรูด้วยพลังจากไอน้ำ สร้างความเสียหาย#C0x3D8A99#180% Sp. ATK#C0x5B545B#+$(skillLevel*4*60)$ เป็น#C0xF13B54#Special Damage#C0x5B545B# พร้อมผลักเป้าหมายไปยังตำแหน่งว่างด้านหลัง หากไม่มีช่องว่างหรือไม่สามารถผลักได้ จะทำให้ศัตรูติด Stun 1 เทิร์น; จากนั้น Volcanion จะซ่อนตัวใน【Steam Mist】เป็นเวลา 1 เทิร์น\n#F20#\n#F40#【Steam Mist】：ไม่สามารถถูกเลือกเป้าหมายได้ ลด Final Damage ที่ได้รับลง 30% และทันทีได้รับ 3 แต้ม【Steam Power】; หากมี Geothermal Hot Spring อยู่ จะได้รับ Steam Power เพิ่มอีก 2 แต้ม และลด Final Damage ลงครึ่งหนึ่ง; Mist จะแพร่ไปยังหน่วยรอบข้าง 2 ตัวเป็นเวลา 1 เทิร์น หน่วยใน Mist จะมี Evasion Rate เพิ่มขึ้น 35%; และเมื่อพันธมิตรธาตุ Water หรือ Fire ภายใน Mist เคลื่อนไหว จะเพิ่ม Steam Power ให้ Volcanion 1 แต้ม',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'หมอกไอน้ำจะกระจายไปยังยูนิตรอบข้าง 2 ตัว นาน 1 เทิร์น；ยูนิตที่อยู่ในหมอกจะมีอัตราหลบหลีกเพิ่มขึ้น 35%；และเมื่อยูนิตธาตุน้ำหรือไฟในหมอกเคลื่อนไหว จะเพิ่ม【Steam Power】ให้ Volcanion 1 แต้ม',
		upLvDesc = 'เพิ่มความเสียหายคงที่+144',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		changeUnitTrigger = true,
		isCombat = true,
		passivePriority = 100,
		skillType2 = 1,
