		targetTypeDesc = 'ศัตรูเดี่ยว',
		targetChooseType = 'single',
		damageFormula = 'self:specialDamage()*1.8+(self:flag(99) and skillLevel or skillLevel*4)*60',
		skillProcess = {365121, 365122, 365123, 365124},
		recoverMp1 = 360,
		costID = 2,
		posC = __data_t__posC[36512],
