	[36513] = {
		id = 36513,
		skillName = 'ท่าไม้ตาย',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#นี่ไง~ โดนัทของเธอ~#C0x5B545B#\n#F10#\n#F40#Volcanion ตื่นขึ้นจากน้ำพุร้อนใต้พิภพแล้วใช้ไอน้ำโจมตีเป้าหมายเดี่ยว สร้างความเสียหายพิเศษ #C0x3D8A99#350% พลังโจมตีพิเศษ#C0x5B545B#+$(skillLevel*4*90)$ ของ#C0xF13B54#ความเสียหายพิเศษ#C0x5B545B# ลบ Buff ทั้งหมดของเป้าหมายและใส่สถานะ Evaporation เป็นเวลา 2 เทิร์น จากนั้นใช้พลังไอน้ำพุ่งเข้าหาศัตรู ปล่อย Wide-area Steam Explosion ใส่ศัตรูทุกตัว สร้างความเสียหายพิเศษ #C0x3D8A99#260% พลังโจมตีพิเศษ#C0x5B545B# ของ #C0xF13B54#ความเสียหายพิเศษ#C0x5B545B# สำหรับศัตรูแต่ละตัวที่มี Evaporation ความเสียหายจะเพิ่ม 10% หากศัตรูทุกตัวมี Evaporation ความเสียหายจะเพิ่มเป็นสองเท่า\n#F20#\n#F40#จากนั้นสุ่มวาง Heat Cyclone ไว้ในสนามเป็นเวลา 2 เทิร์น Heat Cyclone: หน่วยที่อยู่ในนั้นจะได้รับความเปราะธาตุน้ำ/ไฟ และลดความเร็วลง 15% โปเกมอนสาย Water/Fire จะได้รับคริติคอลเพิ่ม 15% เมื่อ Heat Cyclone โดนดาเมจธาตุน้ำหรือไฟ จะขยายไปยังตำแหน่งอื่นในสนาม หากครอบคลุมศัตรูทุกตัวจะระเบิดทันที สร้างความเสียหายธาตุน้ำและไฟ 180% ของพลังโจมตีพิเศษ',
		simDesc = 'Volcanion โจมตีเป้าหมายเดี่ยวด้วย Special Damage ลบ Buff ทั้งหมดของเป้าหมายแล้วใส่สถานะ【Vaporize】 จากนั้นปล่อย【Wide Steam Explosion】ใส่ศัตรูทั้งทีม สร้าง Special Damage และทิ้ง【Heat Cyclone】แบบสุ่มบนสนาม',
		starEffect = __data_t__starEffect[36513],
		-- {11}
		starEffectDesc = 'มอบ【Steam Power】3 แต้มให้กับ Pokémon ธาตุไฟและน้ำทุกตัวในสนาม: เพิ่มความเสียหายแบบ AOE ของ Pokémon ธาตุน้ำและไฟ 50%; ทุกครั้งที่พันธมิตรโจมตีแบบ Active จะใช้ Steam Power 1 แต้ม ฟื้นฟู Rage 100 และใส่สถานะ【Evaporate】ให้ศัตรู 2 เทิร์น; \n ภายใต้【Heatwave Cyclone】หาก Volcanion จะตายเพราะความเสียหาย จะรอดด้วย 1 HP และ Cyclone จะมีโอกาส 30% คงอยู่ในตำแหน่งสุ่มบนสนาม (เกิดได้สูงสุด 2 ครั้ง); \n ใน【Wide-Area Steam Explosion】ยูนิตที่โดนจะสร้างความเสียหายต่อ Volcanion ลดลง 30% เป็นเวลา 2 เทิร์น',
		zawakeEffect = __data_t__zawakeEffect[36513],
		-- {79003, 1}
		zawakeEffectDesc = 'Pokémon ธาตุ Fire และ Water ทั้งหมดได้รับ Steam Power 3 แต้ม: ความเสียหายแบบ AoE ของธาตุ Water และ Fire เพิ่มขึ้น 50%; เมื่อฝ่ายเราทำการโจมตีแบบ Active จะใช้ Steam Power 1 แต้ม เพื่อฟื้นฟูเกจพลัง 100 แต้ม และมอบสถานะ【Evaporation】ให้ศัตรู 2 เทิร์น; หาก Volcanion จะตายใน【Heatwave Cyclone】จะเหลือ 1 HP แทน และเมื่อ Cyclone ระเบิดจะมีโอกาส 100% ที่จะคงอยู่ในตำแหน่งสุ่ม (สูงสุด 3 ครั้งต่อเกม) การระเบิดของ Cyclone จะสร้าง Elemental Damage เพิ่มอีก 3% HP สูงสุดแก่ศัตรูที่ติด【Evaporation】; ใน【Wide-area Steam Explosion】หน่วยที่ได้รับผลจะสร้างความเสียหายต่อ Volcanion ลดลง 30% เป็นเวลา 2 เทิร์น และใน【Harmony of Water and Fire】Elemental Damage ของ Wide-area Steam Explosion จะเพิ่มขึ้น 50%',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#เมื่อ Cyclone ระเบิดแล้ว จะมีโอกาสคงอยู่ต่อ 100%，และสามารถคงอยู่ซ้ำได้สูงสุด 3 ครั้ง；ใน【Water-Fire Synergy】จะทำให้ดาเมจธาตุจาก【Wide-Area Steam Explosion】เพิ่มขึ้น 50%；เมื่อ Cyclone ระเบิด จะสร้างดาเมจธาตุน้ำ/ไฟเพิ่มเติม 3% ของ HP สูงสุดเป้าหมาย หากเป้าหมายติดสถานะ【Evaporate】',
