	[36516] = {
		id = 36516,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#ตราบใดที่เป็นเพื่อเธอ ต่อให้เป็นเพลิงนรก ฉันก็จะไป!#C0x5B545B#\n#F10#\n#F40##L10#Steam Burst: #L0#ทุกครั้งที่ Volcanion โจมตีเชิงรุกจะได้รับ Steam Power 2 แต้ม และใส่สถานะ Evaporation 1 ชั้นให้ศัตรู หากถูกโจมตีจะได้รับ Steam Power 1 แต้ม ทุกแต้มของ Steam Power จะเพิ่มคริติคอล ความเร็ว และลดความเสียหายที่ได้รับ 6% หากสะสมครบ 8 แต้มจะลบสถานะควบคุมที่ไม่ใช่ประเภทครอบงำทั้งหมด และพุ่งเข้ากลางศัตรูปล่อย Wide-area Steam Explosion  \n#F10#\n#F40##L10#Water-Fire Fusion: #L0#เมื่อใช้สกิลธาตุน้ำ จะสร้างความเสียหายธาตุไฟเพิ่มเติม #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# ของพลังโจมตีพิเศษ และเมื่อใช้สกิลธาตุไฟ จะสร้างความเสียหายธาตุน้ำเพิ่มเติม #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# ของพลังโจมตีพิเศษ หากโจมตีศัตรูที่ติด Burn หรือดีบัฟชะลอจากธาตุน้ำ จะลบ Buff 1 ชิ้นของเป้าหมายและใส่สถานะ Evaporation 1 ชั้น เป็นเวลา 2 เทิร์น ขณะ Volcanion อยู่ในสนาม เพื่อนร่วมทีมสาย Water/Fire จะได้รับการต้านทานธาตุเพิ่มขึ้น 30%  \n#F10#\n#F40##L10#Evaporation: #L0#ดีบัฟพิเศษ ลดพลังป้องกันสองด้าน 5% และลดการลดดาเมจ 3% ต่อชั้น แต่ละชั้นเพิ่มความเสียหายจาก AoE ของธาตุน้ำและไฟอีก 20% สูงสุด 5 ชั้น เมื่อครบ 5 ชั้นจะสร้างความเสียหายธาตุน้ำและไฟ 120% ของพลังโจมตีพิเศษทันที  \n#F10#\n#F40##L10#Steam Chain: #L0#ทุก 2 เทิร์นจะสุ่มวาง Steam Trap 1 ชิ้นใส่ศัตรู เมื่อกับดักทั้งหมดในสนามถูกกระตุ้น จะเรียก Steam Chain Explosion: สร้างความเสียหายกับดัก 200% ของพลังโจมตีพิเศษให้กับศัตรูสุ่ม 2 ตัวรอบกับดัก และใส่สถานะ Evaporation 2 เทิร์น แต่ละ Steam Trap สามารถกระตุ้น Steam Chain Explosion ได้สูงสุด 3 ครั้งต่อรอบใหญ่',
		starEffect = __data_t__starEffect[36516],
		-- {8}
		starEffectDesc = '#F40##L10#Geothermal Spring: #L0# ขณะ Volcanion อยู่ในสนาม จะเพิ่มความแรงของสกิล Active แบบ AOE ของพันธมิตรธาตุน้ำและไฟ: หากสกิลมีผลกับ 2/3/4/6 เป้าหมาย จะเพิ่มความเสียหาย 5%/10%/20%/40% ตามลำดับ; \n หากมี Pokémon ธาตุน้ำ/ไฟ ที่ไม่ใช่ยูนิตเรียกอย่างน้อย 4 ตัว จะสร้าง Geothermal Spring ที่เพิ่ม Damage Reduction 20% ให้กับธาตุน้ำ/ไฟ และเมื่อถูกโจมตีแบบ Active จะฟื้น HP เท่ากับ 80% Sp. Atk ของ Volcanion พร้อมลบ Buff 1 อย่างของผู้โจมตีและใส่สถานะ【Evaporate】 2 เทิร์น; หากเงื่อนไขไม่ครบ บ่อน้ำจะอยู่จนจบเทิร์นใหญ่ถัดไป  \n #F40##L10#Flying Fortress: #L0# ขณะ Magearna อยู่ในสนาม หาก HP เปอร์เซ็นต์รวมของพันธมิตรที่ไม่ใช่ยูนิตเรียกลดต่ำกว่า 50% หรือ Magearna ใกล้ตาย พันธมิตรที่เหลือจะถูกย้ายเข้า Flying Fortress เป็นเวลา 2 เทิร์น  \n Fortress จะมี HP รวมของพันธมิตรที่เหลือทั้งหมด และในระหว่างนั้นจะยิงปืนใหญ่ใส่ศัตรูทุกตัว สร้างความเสียหาย 180% Sp. Atk แบบพิเศษ (ดูรายละเอียดในคู่มือการต่อสู้) และใส่สถานะ【Evaporate】2 เทิร์นให้ศัตรูทั้งหมด',
		zawakeEffect = __data_t__zawakeEffect[36516],
		-- {79004, 1}
		zawakeEffectDesc = '#F40##L10#Steam Chain#L0# Enhancement：【Steam Trap】ระยะเวลาวางกับดักลดเหลือ 1 เทิร์น#F40##L10#Geothermal Hot Spring：#L0#เมื่อ Volcanion อยู่ในสนาม จะเพิ่มความแรงของสกิล AoE ให้เพื่อนร่วมทีมธาตุ Water และ Fire ตามจำนวนเป้าหมายของสกิล หากสกิลโจมตีโดนเป้าหมาย 2/3/4/6 ตัว จะเพิ่มความเสียหาย 5%/10%/20%/40% ตามลำดับ; หากมีพันธมิตรธาตุ Water หรือ Fire (ไม่นับ Summon) อย่างน้อย 4 ตัว จะสร้าง Geothermal Hot Spring ซึ่งจะเพิ่ม Damage Reduction 20% ให้ Water/Fire พร้อมฟื้น HP ตาม 80% Sp. ATK ของ Volcanion เมื่อได้รับการโจมตีแบบ Active และลบ Buff หนึ่งสถานะของผู้โจมตี พร้อมใส่สถานะ【Evaporation】2 เทิร์น; ทุกเทิร์น Geothermal Hot Spring จะระเบิดใส่ศัตรูแบบสุ่ม 2 ตัวด้วย Water/Fire Elemental Damage 80% Sp. ATK; เมื่อสิ้นสุด Hot Spring จะโจมตีศัตรูทั้งหมดด้วยความเสียหาย Water หรือ Fire 100% Sp. ATK และใส่สถานะ【Evaporation】2 เทิร์น; หากไม่เข้าเงื่อนไข Hot Spring จะอยู่จนจบ Big Turn ถัดไป\n#F40##L10#Aerial Fortress：#L0#เมื่อ Magearna อยู่ในสนาม และ HP รวมของหน่วยหลักฝ่ายเราทั้งหมด (ไม่นับ Summon) เหลือต่ำกว่า 50% หรือ Magearna ใกล้ตาย จะส่งพันธมิตรที่เหลือทั้งหมดไปยัง Aerial Fortress เป็นเวลา 2 เทิร์น; Aerial Fortress จะมี HP เท่ากับ 120% ของ HP สูงสุดรวมของพันธมิตรตอนเริ่มต้น และจะยิงปืนใหญ่โจมตีศัตรูทั้งหมดด้วย Special Damage 180% Sp. ATK ของทั้งสองฝ่ายรวมกัน (ดูรายละเอียดใน Battle Manual) และใส่สถานะ【Evaporation】2 เทิร์นแก่ศัตรูทั้งหมด',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'การเสริมพลัง【Steam Trap】: เวลาในการวางกับดักลดเหลือ 1 เทิร์น；การเสริมพลัง【Geothermal Spring】: เมื่อสิ้นสุดเทิร์นใหญ่แต่ละรอบ บ่อน้ำพุจะปะทุโจมตีศัตรูแบบสุ่ม 2 ตัวด้วยดาเมจธาตุน้ำหรือไฟ 80% Sp.ATK；เมื่อบ่อน้ำพุจบ จะสร้างความเสียหายธาตุน้ำหรือไฟ 100% Sp.ATK ใส่ศัตรูทั้งหมด และใส่สถานะ【Evaporate】2 เทิร์น；การเสริมพลัง【Flying Fortress】: HP ของป้อมลอยฟ้าเพิ่มเป็น 120% ของยูนิตที่มีชีวิต',
