	[40233] = {
		id = 40233,
		skillName = 'ท่าไม้ตาย',
		skillTypeShow = 'ทักษะสังหาร',
		describe = 'Solgaleo กลืนกินแสงอาทิตย์แล้วพุ่งลงสู่พื้นด้วยความเร็วสูง โจมตีศัตรูทุกตัว สร้างความเสียหายทางกายภาพ #C0xE69900#180% พลังโจมตีกายภาพ#C0x5B545B#+$(skillLevel*4*48)$ของ#C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# จากนั้นใส่สถานะ Taunt ให้ศัตรูทั้งหมด 1 เทิร์น ตนเองเข้าสู่ Radiant Form เป็นเวลา 2 เทิร์น และใส่สถานะ Intimidate ให้ศัตรูที่มีพลังโจมตีสูงสุด 2 ตัว เป็นเวลา 2 เทิร์น\n#F10#\n#F40#Radiant Form: เมื่อเข้าสู่สถานะนี้จะลบ Invisibility ของศัตรูทั้งหมดทันที ระหว่างที่คงอยู่ศัตรูจะไม่สามารถเข้าสู่ Invisibility ได้ ตนเองได้รับพลังป้องกันสองด้านเท่ากับค่าพลังโจมตี และเพิ่มความเสียหายจากการโต้กลับ 100%',
		simDesc = 'Solgaleo กลืนกินแสงอาทิตย์ กลายร่างเป็นพระอาทิตย์พุ่งชนพื้นโจมตีศัตรูทั้งทีม สร้างความเสียหายและใส่สถานะ Taunt จากนั้นเข้าสู่สถานะ “Sunrise”',
		starEffect = __data_t__starEffect[40233],
		-- {11}
		starEffectDesc = 'เอฟเฟกต์พิเศษ: ท่าไม้ตายจะอัปเกรดเป็น【Corona Impact】 สร้าง True Damage เพิ่มเติมเท่ากับ 100% ของค่ารวม Def และ Sp. Def ของ Solgaleo แก่ศัตรูทุกตัว และใส่【Strong Taunt】ให้ศัตรู 1 เทิร์น โดยการโจมตีครั้งนี้จะไม่ทำให้เกิดเอฟเฟกต์ตอบสนองของเป้าหมาย;',
		zawakeEffect = __data_t__zawakeEffect[40233],
		-- {79003, 1}
		zawakeEffectDesc = 'เอฟเฟกต์เสริม: ท่าไม้ตายอัปเกรดเป็น【Corona Impact】 โจมตีศัตรูทุกตัวพร้อมสร้างความเสียหายจริงเท่ากับ 100% ของ DEF และ Sp.DEF ปัจจุบันของ Solgaleo และทำให้ศัตรูติด【Strong Taunt】1 เทิร์น การโจมตีนี้จะไม่กระตุ้นเอฟเฟกต์รับความเสียหายของเป้าหมาย; ระหว่างสถานะ【Solar Ascent】ความเสียหายของ Pokémon ประเภท Psychic/Steel ฝ่ายเราจะถูกแบ่งมาให้ Solgaleo 30%; เมื่อเข้าสู่【Solar Ascent】จะลบทุกดีบัฟชีวภาพออกจากตนเอง (ดูรายละเอียดในคู่มือการต่อสู้) และจะต้านทานดีบัฟประเภทนี้ตลอดระยะเวลา【Solar Ascent】; ศัตรูที่ติด【Timid】จะกระตุ้นเอฟเฟกต์ของ【Timid】เมื่อโจมตี Pokémon ประเภท Psychic/Steel\n#F10#\n#F40#【Strong Taunt】: เอฟเฟกต์ควบคุม ไม่สามารถลบได้ ศัตรูจะต้องใช้การโจมตีธรรมดากับเป้าหมายที่ถูก Taunt',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '#C0x5c9970#เพิ่มค่าสัมประสิทธิ์ความเสียหายพื้นฐาน 20% ท่าไม้ตายจะพัฒนาเป็น【Solar Crown Strike】สร้างความเสียหายจริงเท่ากับผลรวมของพลังป้องกันสองด้าน 100%；ศัตรูทั้งหมดจะได้รับ【Taunt+】 1 เทิร์น',
