	[40246] = {
		id = 40246,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = 'Lunar Cycle: #L0# เมื่อเริ่มต้นแต่ละรอบใหญ่ รูปแบบของดวงจันทร์จะหมุนเวียนตามลำดับ New Moon, First Quarter, Full Moon, Last Quarter\nPhantom Guard: #L0# หาก HP ของตนเองมากกว่า 70% จะได้รับการลดความเสียหาย 30% โปเกมอนฝ่ายเราที่อยู่ในสถานะ Invisibility จะไม่สามารถถูกลิงก์ได้ และเพื่อนร่วมทีมสาย Ghost/Psychic ที่อยู่ในสถานะ Invisibility จะได้รับการลดความเสียหายเพิ่ม 10%\n#C0xF13B54#New Moon#C0x5B545B#\nเมื่อเข้าสู่เฟสนี้ ศัตรูแบบสุ่ม 3 ตัวจะมีขีดจำกัดโกรธเพิ่มขึ้น 150 หน่วย จนกว่าจะใช้ท่าไม้ตาย และสุ่มใส่สถานะ Lone Moon ให้ศัตรู 1 ตัว นาน 1 เทิร์น\n#C0xF13B54#First Quarter#C0x5B545B#\nเมื่อเข้าสู่เฟสนี้ ตนเองและเพื่อนร่วมทีมสาย Ghost ที่มีพลังโจมตีสูงสุด 2 ตัวจะได้รับสถานะ Invisibility นาน 2 เทิร์น\n#C0xF13B54#Full Moon#C0x5B545B#\nเมื่อเข้าสู่เฟสนี้ จะปล่อย Moonlight Wave 3 ครั้งทันที\n#C0xF13B54#Last Quarter#C0x5B545B#\nเมื่อเข้าสู่เฟสนี้ จะฟื้น HP ให้เพื่อนร่วมทีมสาย Ghost/Psychic 20% ของ HP สูงสุด และระหว่างเฟสนี้จะเพิ่มความเร็วให้พวกเขา 9%\n#C0xF13B54#Lunar Crest#C0x5B545B#\nบัฟระดับ 3 ไม่สามารถซ้อนทับได้ เมื่อได้รับความเสียหายที่ถึงตาย จะใช้เครื่องหมายนี้เพื่อคืนชีพด้วย HP เต็มก่อนถึงรอบการกระทำถัดไป',
		starEffect = __data_t__starEffect[40246],
		-- {8}
		starEffectDesc = '\nCycle of Rebirth: #L0# เมื่อเข้าสู่【Waning Moon】เป็นครั้งแรก ฟื้น HP 20% ของ HP สูงสุดของตนเอง  \nPokémon ธาตุ Ghost ทั้งทีมจะได้รับ【Moon Cycle Mark】  \nMoonlit Reunion: #L0# ทุกครั้งที่เกิด Cycle of Rebirth จะฟื้น HP 20% ของ HP สูงสุดให้ Pokémon ธาตุ Ghost ที่อยู่ในสนาม',
		zawakeEffect = __data_t__zawakeEffect[40246],
		-- {79004}
		zawakeEffectDesc = 'การหมุนเวียนของพระจันทร์: #L0#เมื่อเริ่มต้นแต่ละรอบใหญ่ รูปแบบพระจันทร์จะหมุนเวียนตามลำดับ 【New Moon】, 【First Quarter】, 【Full Moon】, 【Last Quarter】; Phantom Guard: #L0#เมื่อพลังชีวิตของตัวเองมากกว่า 70% จะได้รับการลดความเสียหาย 30% โปเกมอนฝ่ายเราที่อยู่ในสถานะประเภท Stealth ไม่สามารถถูกเชื่อมโยงได้ ทำให้เพื่อนร่วมทีมประเภท Ghost/Psychic ที่อยู่ในสถานะ Stealth ได้รับการลดความเสียหาย 10%; #C0xF13B54#【New Moon】#C0x5B545B#เมื่อเข้าสู่สนาม จะเพิ่มขีดจำกัดค่าเกจความโกรธให้ศัตรูแบบสุ่ม 3 ตัว เป็น 150 แต้ม จนกว่าจะใช้ท่าไม้ตายครั้งถัดไป; สุ่มใส่ศัตรู 1 ตัวด้วยสถานะ 【Lonely Moon】 เป็นเวลา 1 เทิร์น; #C0xF13B54#【First Quarter】#C0x5B545B#เมื่อเข้าสู่สนาม ตัวเองและเพื่อนร่วมทีมประเภท Ghost ที่มีพลังโจมตีสูงสุด 2 ตัวจะได้รับสถานะ 【Stealth】 เป็นเวลา 2 เทิร์น; #C0xF13B54#【Full Moon】#C0x5B545B#เมื่อเข้าสู่สนาม จะปล่อยคลื่นโจมตี 【Moonlight】 3 ระลอก; #C0xF13B54#【Last Quarter】#C0x5B545B#เมื่อเข้าสู่สนาม จะฟื้นฟู HP 20% ของพลังชีวิตสูงสุดให้เพื่อนร่วมทีมประเภท Ghost/Psychic และเพิ่มความเร็วให้พวกเขา 9% ตลอดระยะเวลาของสถานะ; #C0xF13B54#【Moon Cycle Mark】#C0x5B545B#บัฟระดับ 3 ไม่สามารถซ้อนทับกันได้ เมื่อได้รับความเสียหายรุนแรงถึงตาย จะใช้เครื่องหมายนี้เพื่อฟื้นฟูตัวเองเต็ม HP ก่อนการเคลื่อนไหวในเทิร์นถัดไป',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '#C0x5c9970#เมื่อเข้าสู่【New Moon】ครั้งแรก ศัตรูทั้งหมดเพิ่มเพดานเกจโกรธ 150 หน่วย และสุ่มใส่สถานะ【Lone Moon】ให้ศัตรู 3 ตัว 1 เทิร์น; ทุกครั้งที่ตนฟื้นคืนชีพจะเข้าสู่【Full Moon Mode】 1 เทิร์น และเมื่อเพื่อนธาตุ Ghost ฟื้นคืนชีพจะมี HP ฟื้นกลับมา 40%',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		changeUnitTrigger = true,
		isCombat = true,
		passivePriority = 95,
		skillType = 3,
