	[40272] = {
		id = 40272,
		skillName = 'สกิลพิเศษ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = 'Lunala โจมตีเป้าหมายเดี่ยวของศัตรู สร้างความเสียหายพิเศษ #C0x3D8A99#180% พลังโจมตีพิเศษ#C0x5B545B#+$(skillLevel*4*36)$ของ#C0xF13B54#ความเสียหายพิเศษ#C0x5B545B#\nตนเองและเพื่อนร่วมทีมสาย Ghost ที่มีพลังโจมตีสูงสุด 1 ตัวจะเข้าสู่สถานะ Invisibility เป็นเวลา 1 เทิร์น เมื่อสถานะ Invisibility จบลง จะปล่อย Moonlight Wave ใส่ศัตรูแบบสุ่ม 1 ครั้ง\n#C0xF13B54#Invisibility#C0x5B545B#\nไม่สามารถถูกล็อกเป้าโดยสกิลเชิงรุก แต่ยังได้รับผลจากสกิลโจมตีหมู่\n#C0xF13B54#Moonlight Wave#C0x5B545B#\nสร้างความเสียหายทะลุป้องกันพิเศษ เท่ากับ 6% ของ HP สูงสุดของผู้ใช้ (ในโหมดตัวต่อตัว เป้าหมายจะได้รับผลจาก Moonlight Wave ได้ไม่เกิน 2 ครั้งต่อรอบใหญ่)',
		simDesc = 'Lunala โจมตีเป้าหมายเดี่ยว',
		zawakeEffect = __data_t__zawakeEffect[40272],
		-- {79002}
		zawakeEffectDesc = 'Lunala โจมตีเป้าหมายเดี่ยวฝั่งศัตรู สร้างความเสียหาย#C0xF13B54#พิเศษ#C0x5B545B#เท่ากับ #C0x3D8A99#180% Sp. Atk#C0x5B545B#+$(skillLevel*4*36)$\nตนเองและเพื่อนร่วมทีมประเภท Ghost ที่มี Atk สูงสุด 1 ตัวเข้าสู่สถานะ【Stealth】เป็นเวลา 1 เทิร์น เมื่อสถานะนี้สิ้นสุด จะปล่อย【Moonlight】ใส่ศัตรูแบบสุ่ม 1 ครั้งทันที\n#C0xF13B54#【Stealth】#C0x5B545B#\nไม่ถูกล็อกเป้าหมายด้วยสกิลเชิงรุก แต่ยังได้รับผลกระทบจากการโจมตีแบบหมู่\n#C0xF13B54#【Moonlight】#C0x5B545B#\nสร้างความเสียหายแบบเจาะทะลุพลังป้องกันตาม 6% ของ Max HP ของผู้ใช้ (ในโหมดตัวต่อตัว แต่ละหน่วยจะได้รับความเสียหายจาก Moonlight สูงสุด 2 ครั้งต่อ 1 เทิร์นใหญ่)',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '#C0x5c9970#เพิ่มค่าสัมประสิทธิ์ความเสียหายพื้นฐาน 20% ฟื้นฟู HP 15% ของ HP สูงสุด และทำให้เพื่อนธาตุ Ghost 1 ตัวเข้าสู่【Stealth】นาน 1 เทิร์น',
		upLvDesc = 'เพิ่มความเสียหายคงที่+144',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		changeUnitTrigger = true,
		isCombat = true,
		skillType2 = 1,
