	[40273] = {
		id = 40273,
		skillName = 'ท่าไม้ตาย',
		skillTypeShow = 'ทักษะสังหาร',
		describe = 'Lunala โจมตีศัตรูแบบสุ่ม 2 ตัว สร้างความเสียหายพิเศษ #C0x3D8A99#300% พลังโจมตีพิเศษ#C0x5B545B#+$(skillLevel*4*60)$ ของ#C0xF13B54#ความเสียหายพิเศษ#C0x5B545B#\nมอบสถานะ Lone Moon ให้เป้าหมายเป็นเวลา 1 เทิร์น\nตนเองเข้าสู่สถานะ Full Moon Form 1 เทิร์น ระหว่างนั้นได้รับการลดดาเมจเพิ่ม 20%\n#C0xF13B54#Lone Moon#C0x5B545B#\nดีบัฟระดับ 2 เป็นสถานะแยกเป้าหมาย ไม่สามารถทำ Co-Op หรือ Follow-Up และไม่ได้รับผลจากเพื่อนร่วมทีม (รวมถึงเอฟเฟกต์ประเภทลิงก์)\n#C0xF13B54#Full Moon Form#C0x5B545B#\nร่างแปลงประเภท Psychic เมื่อเข้าสู่ฟอร์มนี้ จะปล่อย Moonlight Wave ทันที 1 ครั้ง เล็งเป้าหมายที่มี Lone Moon ก่อน และทุกครั้งที่ใช้สกิลเชิงรุก จะปล่อย Moonlight Wave เพิ่มอีก 1 ครั้ง\n#C0xF13B54#Moonlight Wave#C0x5B545B#\nสร้างความเสียหายทะลุป้องกันพิเศษ เท่ากับ 6% ของ HP สูงสุดของผู้ใช้ (ในโหมดตัวต่อตัว เป้าหมายจะได้รับผลจาก Moonlight Wave ได้ไม่เกิน 2 ครั้งต่อรอบใหญ่)',
		starEffect = __data_t__starEffect[40273],
		-- {11}
		starEffectDesc = '\n【Crescent Moon】เพิ่มระยะเวลาขึ้น 1 เทิร์น  Pokémon ธาตุ Ghost ฝ่ายเรา จะสร้างความเสียหายเพิ่มขึ้น 10% ต่อเป้าหมายที่ติด【Crescent Moon】',
		zawakeEffect = __data_t__zawakeEffect[40273],
		-- {79003}
		zawakeEffectDesc = 'Lunala โจมตีศัตรูแบบสุ่ม 2 ตัว สร้างความเสียหาย#C0xF13B54#พิเศษ#C0x5B545B#เท่ากับ #C0x3D8A99#300% Sp. Atk#C0x5B545B#+$(skillLevel*4*60)$\nใส่สถานะ【Lone Moon】กับเป้าหมาย 1 เทิร์น\nตนเองเข้าสู่【Full Moon Form】เป็นเวลา 1 เทิร์น ขณะอยู่ในสถานะนี้ ได้รับ Damage Reduction เพิ่มขึ้น 20%\n#C0xF13B54#【Lone Moon】#C0x5B545B#\nดีบัฟระดับ 2 ส่งผลให้เป้าหมายโดดเดี่ยว ไม่สามารถทำ Co-op หรือ Link ได้ และไม่ได้รับผลจากเพื่อนร่วมทีมใด ๆ\n#C0xF13B54#【Full Moon Form】#C0x5B545B#\nแปลงร่างเป็นแบบ Psychic ทันทีที่เข้าสู่สถานะ จะเปิดใช้งานผลของ Moon Phase【Full Moon】โดยอัตโนมัติ จะเน้นโจมตีเป้าหมายที่มีสถานะ【Lone Moon】 และทุกครั้งที่โจมตีจะปล่อย【Moonlight】 1 ครั้ง\n#C0xF13B54#【Moonlight】#C0x5B545B#\nสร้างความเสียหายแบบเจาะทะลุพลังป้องกันตาม 6% ของ Max HP ของผู้ใช้ (ในโหมดตัวต่อตัว แต่ละหน่วยจะได้รับความเสียหายจาก Moonlight สูงสุด 2 ครั้งต่อ 1 เทิร์นใหญ่)',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '#C0x5c9970#เพิ่มค่าสัมประสิทธิ์ความเสียหายพื้นฐาน 20% ท่าไม้ตายโจมตีเป้าหมาย +1；หลังจบแต่ละรอบของ【Full Moon Mode】จะเพิ่มความเสียหายของ【Moonlight Glow】ถาวร 20% (สูงสุด 60%)；ครั้งแรกที่จบ【Full Moon Mode】เพื่อนธาตุ Ghost ทั้งหมดจะได้รับ【Stealth】1 เทิร์น',
		upLvDesc = 'เพิ่มความเสียหายคงที่+240',
