	[40276] = {
		id = 40276,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = 'Lunar Phase Cycle:\nในช่วงเริ่มรอบใหญ่ แต่ละรอบจะเปลี่ยนเฟสของดวงจันทร์ตามลำดับ New Moon > First Quarter > Full Moon > Last Quarter\nPhantom Defense:\nหาก HP ของ Lunala มากกว่า 70% จะได้รับการลดดาเมจ 30% เพื่อนร่วมทีมที่อยู่ในสถานะ Invisibility จะไม่สามารถถูกลิงก์ได้ และเพื่อนร่วมทีมสาย Ghost/Psychic ที่อยู่ในสถานะ Invisibility จะได้รับการลดดาเมจเพิ่ม 10%\n#C0xF13B54#New Moon#C0x5B545B#\nสุ่มเพิ่มขีดจำกัดโกรธของศัตรู 3 ตัวเป็น 150 แต้ม จนกว่าจะใช้ท่าไม้ตาย และสุ่มใส่ Lone Moon ให้ศัตรู 1 ตัว 1 เทิร์น\n#C0xF13B54#First Quarter#C0x5B545B#\nมอบ Invisibility ให้ตนเองและเพื่อนร่วมทีมสาย Ghost ที่มีพลังโจมตีสูงสุด 2 ตัว เป็นเวลา 2 เทิร์น\n#C0xF13B54#Full Moon#C0x5B545B#\nปล่อย Moonlight Wave 3 ครั้งทันทีเมื่อเข้าสู่เฟสนี้\n#C0xF13B54#Last Quarter#C0x5B545B#\nฟื้น HP ให้เพื่อนร่วมทีมสาย Ghost/Psychic 20% ของ HP สูงสุด และเพิ่มความเร็ว 9% ระหว่างเฟสนี้\n#C0xF13B54#Lunar Crest#C0x5B545B#\nบัฟระดับ 3 ไม่สามารถซ้อนทับได้ เมื่อได้รับความเสียหายถึงตาย จะใช้ Lunar Crest เพื่อคืนชีพด้วย HP เต็มก่อนถึงการกระทำถัดไป',
		starEffect = __data_t__starEffect[40276],
		-- {8}
		starEffectDesc = '\nCycle of Rebirth: #L0# เมื่อเข้าสู่【Waning Moon】เป็นครั้งแรก ฟื้น HP 20% ของ HP สูงสุดของตนเอง  \nPokémon ธาตุ Ghost ทั้งทีมจะได้รับ【Moon Cycle Mark】  \nMoonlit Reunion: #L0# ทุกครั้งที่เกิด Cycle of Rebirth จะฟื้น HP 20% ของ HP สูงสุดให้ Pokémon ธาตุ Ghost ที่อยู่ในสนาม',
		zawakeEffect = __data_t__zawakeEffect[40276],
		-- {79004}
		zawakeEffectDesc = 'Moon Phase Cycle：#L0#เมื่อเริ่มเทิร์นใหญ่แต่ละรอบ จะสลับสถานะตามลำดับ【New Moon】→【First Quarter】→【Full Moon】→【Last Quarter】\nPhantom Guard：#L0#เมื่อ HP สูงกว่า 70% จะได้รับ Damage Reduction 30% โปเกมอนฝ่ายเราที่อยู่ในสถานะ Stealth จะไม่ถูกเชื่อมโยง และ Ghost/Psychic type ใน Stealth จะได้รับ Damage Reduction เพิ่มขึ้น 10%\n#C0xF13B54#【New Moon】#C0x5B545B#\nเมื่อเริ่มสถานะนี้ ทำให้ศัตรูแบบสุ่ม 3 ตัวมี Max Rage เพิ่มขึ้น 150 จนกว่าจะใช้ Ultimate ครั้งถัดไป และสุ่มใส่【Lone Moon】กับศัตรู 1 ตัว 1 เทิร์น\n#C0xF13B54#【First Quarter】#C0x5B545B#\nเมื่อเริ่มสถานะนี้ ตนเองและเพื่อน Ghost type ที่มี Atk สูงสุด 2 ตัว ได้รับ【Stealth】เป็นเวลา 2 เทิร์น\n#C0xF13B54#【Full Moon】#C0x5B545B#\nเมื่อเริ่มสถานะนี้ จะปล่อย【Moonlight】จำนวน 3 ครั้ง\n#C0xF13B54#【Last Quarter】#C0x5B545B#\nเมื่อเริ่มสถานะนี้ จะฟื้นฟู HP ให้ Ghost/Psychic type ฝ่ายเรา 20% ของ Max HP และเพิ่ม Speed 9% ระหว่างสถานะนี้\n#C0xF13B54#【Moon Seal】#C0x5B545B#\nบัฟระดับ 3 ไม่สามารถซ้อนกันได้ เมื่อได้รับความเสียหายที่อาจตาย จะใช้ Seal นี้แทน และฟื้นคืนชีพด้วย HP เต็มก่อนเทิร์นถัดไป',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '#C0x5c9970#เมื่อเข้าสู่【New Moon】ครั้งแรก ศัตรูทั้งหมดเพิ่มเพดานเกจโกรธ 150 หน่วย และสุ่มใส่สถานะ【Lone Moon】ให้ศัตรู 3 ตัว 1 เทิร์น; ทุกครั้งที่ตนฟื้นคืนชีพจะเข้าสู่【Full Moon Mode】 1 เทิร์น และเมื่อเพื่อนธาตุ Ghost ฟื้นคืนชีพจะมี HP ฟื้นกลับมา 40%',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		changeUnitTrigger = true,
		isCombat = true,
		passivePriority = 95,
