	[40726] = {
		id = 40726,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = 'Jet Boost：เมื่ออยู่ในสถานะ【พุ่งออกจากสนาม】 ทุกครั้งที่โปเกมอนฝ่ายเราทำการ จะเพิ่มแต้ม【พลังงาน】ให้ตัวเอง 1 แต้ม เมื่อพลังงานเต็มหรือถึงรอบการกระทำถัดไป จะกลับเข้าสนามและโจมตีศัตรูที่มี HP ต่ำที่สุดด้วยความเสียหายพิเศษเท่ากับ (50%*จำนวนแต้มพลังงาน) หากพลังงานเต็ม ดาเมจจะเป็นความเสียหายจริง；หากโจมตีแล้วสามารถสังหารเป้าหมายได้ ดาเมจที่เกินจะถ่ายโอนไปยังศัตรูที่มี HP ต่ำที่สุดถัดไปต่อเนื่องจนกว่าจะไม่สามารถฆ่าได้อีก; หลังจากนั้นจะเปลี่ยนแต้ม【พลังงาน】แต่ละแต้มเป็นอัตราการป้องกันและความแข็งแกร่งในการป้องกัน 10% นาน 2 เทิร์น\nพลังอัลตร้าบีสต์：เมื่อ Celesteela อยู่ในสนาม เพื่อนร่วมทีมที่เป็น Ultra Beast ทั้งหมดจะได้รับอัตราการป้องกันเพิ่มขึ้น 10%\n【พลังงาน】：เอฟเฟกต์พิเศษ มีค่าสูงสุด 10 แต้ม',
		starEffect = __data_t__starEffect[40726],
		-- {8}
		starEffectDesc = 'เอฟเฟกต์พิเศษ: เมื่อเริ่มการต่อสู้จะออกจากสนามทันที; เพิ่ม Energy สูงสุดเป็น 15 และเมื่อพันธมิตรใช้การกระทำเพิ่มเติม จะเพิ่ม Energy ให้ Celesteela อีก 1 แต้ม',
		zawakeEffect = __data_t__zawakeEffect[40726],
		-- {79004}
		zawakeEffectDesc = 'Jet Mode：เมื่ออยู่ใน【Jet Retreat】ทุกครั้งที่โปเกมอนฝ่ายเรากระทำการ Celesteela จะได้รับ 1 แต้ม【Energy】 เมื่อสะสมเต็มหรือถึงรอบเทิร์นถัดไปจะกลับเข้าสนาม และโจมตีศัตรูที่ HP น้อยที่สุดด้วยความเสียหายพิเศษตาม (50%*จำนวนแต้ม Energy) ของ Sp. Atk (หากแต้มเต็ม ความเสียหายจะเป็น True Damage) หากโจมตีสังหารเป้าหมาย ความเสียหายส่วนเกินจะกระจายใส่ศัตรู HP น้อยที่สุดถัดไปต่อเนื่องจนกว่าจะไม่สามารถสังหารได้อีก จากนั้นจะแปลงแต้ม【Energy】แต่ละแต้มเป็น 10% Block Rate และ 10% Block Power ให้ตนเองเป็นเวลา 2 เทิร์น\nUltra Beast Boost：เมื่อ Celesteela อยู่ในสนาม Ultra Beast ฝ่ายเราทุกตัวได้รับ Block Rate เพิ่ม 10%\n【Energy】：เอฟเฟกต์พิเศษ สูงสุด 10 แต้ม',
		zawakeSimpleDesc = 'Jet: เมื่ออยู่ในสถานะ 【Jet Escape】 จะได้รับ 1 แต้ม【Energy】ทุกครั้งที่เพื่อนร่วมทีมเคลื่อนไหว เมื่อ Energy เต็ม หรือหลังจากเทิร์นถัดไปของตนเอง จะกลับเข้าสู่สนามและโจมตีศัตรูที่มี HP ต่ำที่สุด 1 ครั้ง โดยสร้างความเสียหายพิเศษตาม Sp.Atk (50%*จำนวนแต้ม Energy) หาก Energy เต็ม ความเสียหายจะเป็นความเสียหายจริง หากโจมตีจนเป้าหมายตาย ความเสียหายส่วนเกินจะถ่ายไปยังศัตรูที่มี HP ต่ำที่สุดอีกตัว และทำเช่นนี้ต่อไปจนไม่มีเป้าหมายตายได้อีก; หลังจากนั้นจะแปลงแต่ละแต้ม Energy เป็น 10% Resistance Rate และ 10% Resistance Strength เป็นเวลา 2 เทิร์น\nBeast Boost: ขณะ Celesteela อยู่ในสนาม Ultimate Beast ฝ่ายเราทุกตัวได้รับการเพิ่ม 10% Resistance Rate\n【Energy】: เอฟเฟกต์พิเศษ มีค่าสูงสุด 10 แต้ม',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
