	[41113] = {
		id = 41113,
		skillName = 'ท่าไม้ตาย',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#นี่ไง~ ดอกไม้ให้เธอ!#C0x5B545B#\nโจมตีศัตรู 2 แถวติดกัน สร้างความเสียหายพิเศษ #C0x3D8A99#220% พลังโจมตีพิเศษ#C0x5B545B#+$(skillLevel*4*60)$ ของ#C0xF13B54#ความเสียหายพิเศษ#C0x5B545B#\nวาง【กับดักแรงโน้มถ่วง】ไว้ตรงกลางสนาม กับดักจะทำงานเมื่อศัตรูเริ่มเทิร์น สร้างความเสียหายกับดัก #C0xF13B54#150%#C0x5B545B# ของพลังโจมตีพิเศษแก่ศัตรูทุกตัว ถ้าศัตรูที่กระตุ้นกับดักอยู่แถวหลัง และไม่มีใครยืนแถวหน้า จะถูกดึงมาแถวหน้าแทน\n#C0xF13B54#【กับดักแรงโน้มถ่วง】#C0x5B545B#\nกับดักพิเศษ ยกเลิกการกระทำของศัตรูเมื่อทำงาน ใช้งานได้ 1 ครั้ง\n#C0xF13B54#【กับดักหนามแหลม】#C0x5B545B#\nกับดักพิเศษ เมื่อเป้าหมายในแถวนี้เคลื่อนที่หรือเริ่มเทิร์น จะสร้างความเสียหายเท่ากับ 60% ของพลังโจมตีพิเศษของผู้วาง ใช้งานได้ 2 ครั้ง\n#C0xF13B54#【ออร่าลดพลังโจมตี II】#C0x5B545B#\nออร่าพิเศษ ลดพลังโจมตีทั้งสองด้านของศัตรูทั้งหมด 10%',
		simDesc = '#C0xC0C0C0#นี่ไง ดอกไม้สำหรับเธอ!#C0x5B545B#\n\nMagearna ขับเคลื่อนด้วยเกียร์เทคโนโลยี ปลดปล่อยลำแสงปืนใหญ่สุดรุนแรงให้โลกเบ่งบานดั่งดอกไม้ สร้างความเสียหายให้กับศัตรู 2 แถวที่อยู่ติดกัน',
		starEffect = __data_t__starEffect[41113],
