	[41226] = {
		id = 41226,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#ฉันสามารถ...เป็นเงาของคุณได้ไหม?#C0x5B545B#\n#F10#\n#F40##F40##L10#เงาแห่งมายา：#L0#เมื่อลงสนามจะเข้าสู่ร่างวิญญาณกึ่งหลอมรวม (ลดพลังโจมตีทั้งสองประเภทและความเสียหายที่ได้รับ 20%, ความเร็วเพิ่มขึ้น 20%, อัตราต้านสถานะเพิ่มขึ้น 40%) เมื่อใช้ท่าไม้ตายจะกลับสู่ร่างปกติ หลังใช้ท่าไม้ตาย 2 ครั้งจะสามารถเข้าสู่เงาแห่งมายาอีกครั้ง (จำกัดสูงสุด 2 ครั้ง)\n#F10#\n#F40##L10#โหมดสถิตเงา：#L0#เมื่อได้รับความเสียหายที่รุนแรงถึงตายครั้งแรก จะใช้【เจ็ดดวงดาว夺魂】โต้กลับใส่ผู้โจมตี หากสามารถฆ่าเป้าหมายได้ จะฟื้นคืนชีพในร่างเงาแห่งมายาพร้อม HP 50% หากไม่สามารถฆ่าเป้าหมายได้ จะเข้าสู่【สถิตเงา】กับเป้าหมายนาน 3 เทิร์น และเพิ่มดาเมจการลอบโจมตี 15% ต่อจำนวนศัตรูแต่ละตัว ระหว่างนั้นจะลดค่าสถานะทั้งหกของเป้าหมายลง #C0x5c9970#$(15+skillLevel*0.15-0.15)$%#C0x5B545B# หากเป้าหมายตายระหว่างนั้น จะคืนชีพในร่างเงาแห่งมายาพร้อม HP 50%\n#F10#\n#F40##L10#ผู้เชี่ยวชาญเทคนิค：#L0#สกิลออร่าพิเศษ เมื่อศัตรูถูกโจมตีโดยโปเกมอนธาตุผีด้วยสกิลเชิงรุก การฟื้นโกรธจะลดลง 50% และหากยังไม่เต็มโกรธ จะได้รับความเสียหายจากธาตุผีเพิ่มขึ้น 20% Marshadow จะไม่สนใจการลดความเสียหายของศัตรูอีก 20% และไม่สนค่าป้องกันกายภาพ 40%；\nโปเกมอนธาตุต่อสู้และ Meltan แถวหน้าจะเพิ่มอัตราการป้องกัน 35% และเมื่อป้องกันจะลดดาเมจครั้งนั้นลงอีก 20%；\nโปเกมอนธาตุต่อสู้แถวหลังจะเพิ่มอัตราทะลุป้องกัน 35% และเมื่อโจมตีเป้าหมายที่ไม่ได้ป้องกัน จะมีโอกาส 40% (ตัวเอง 100%) ในการโจมตีธรรมดาซ้ำอีก 1 ครั้ง；\n#F10#\n#F40##L10#จู่โจมแม่นยำ：#L0#ในรอบใหญ่เดียวกัน แต่ละชุดการโจมตีจะมีโอกาสโจมตีสำเร็จเพิ่มขึ้น 25% และแต่ละชุดที่โจมตีเป้าหมายเดิมจะเพิ่มความเสียหายและการไม่สนการลดดาเมจ 5%；ทุกครั้งที่โจมตีครบ 5 ชุด จะได้รับโกรธ 100 หน่วย',
		starEffect = __data_t__starEffect[41226],
		-- {8}
		starEffectDesc = '#F40##L10#True Shadow: #L0# โจมตีไม่สนแบ่งความเสียหายหรือโล่, เพิ่ม Ignore Resilience Rate 50%, หากไม่ถูก Resilience แต่ละฮิตมีโอกาส 60% สร้าง True Damage 80% Atk เพิ่มเติม  ',
		zawakeEffect = __data_t__zawakeEffect[41226],
		-- {79004}
		zawakeEffectDesc = '#C0xC0C0C0#ฉัน...สามารถเป็นเงาของเธอได้ไหม?#C0x5B545B#\n#F10#\n#F40##F40##L10#Phantom Shadow:#L0# เข้าสนามในสภาพกึ่งวิญญาณ (ลด Atk และ Sp. Atk พื้นฐานลง 20%, รับความเสียหายลดลง 20%, ความเร็วเพิ่มขึ้น 20%, อัตราต้านคอนโทรลเพิ่มขึ้น 40%) หลังใช้ Ultimate จะคืนร่างจริง หลังใช้ Ultimate 2 ครั้งจะกลับสู่สภาพ Phantom Shadow อีกครั้ง (สูงสุด 2 ครั้ง); เมื่อเข้าสนาม เพื่อนร่วมทีมประเภท Ghost ทั้งหมดจะได้รับ【Phantom Shadow】\n#F10#\n#F40##L10#Shadow Dwell Mode:#L0# เมื่อได้รับดาเมจร้ายแรงครั้งแรก จะสวนกลับผู้ที่ทำดาเมจด้วย【Seven Star Soul Steal】 หากสังหารเป้าหมายได้ จะอยู่รอดในร่าง Phantom Shadow โดยมี HP 50%; หากไม่สามารถสังหารได้ จะทำการ【ติดตามเงา】เป้าหมายนั้นเป็นเวลา 3 เทิร์น และทุกครั้งที่มีศัตรูในสนาม 1 ตัว จะเพิ่ม Sneak Damage 15% ระหว่างนี้ลด Stats ทั้ง 6 ของเป้าหมายลง#C0x5c9970#$(15+skillLevel*0.15-0.15)$%#C0x5B545B# หากเป้าหมายตายระหว่างนั้น จะอยู่รอดในร่าง Phantom Shadow โดยมี HP 50%\n#F10#\n#F40##L10#เทคนิคชั้นยอด:#L0# สกิลออร่า เมื่อศัตรูถูกโจมตีโดยสกิลของ Pokémon ประเภท Ghost การฟื้น Rage จะลดลง 50% หากยังไม่เต็ม Rage จะได้รับความเสียหายจาก Ghost เพิ่มขึ้น 20% Marshadow จะเมิน Damage Reduction 20% และ Physical Def 40% ของเป้าหมายเพิ่มเติม; Pokémon สาย Fighting แถวหน้า และ Meltan เพิ่ม Block Rate ขึ้น 35% ขณะป้องกันจะลดดาเมจครั้งนี้ลง 20%; Pokémon สาย Fighting แถวหลังเพิ่ม Penetration Rate 35% เมื่อการโจมตีไม่ถูก Block จะมีโอกาส 40% (100% สำหรับตัวเอง) โจมตีธรรมดาเพิ่มอีก 1 ครั้ง\n#F10#\n#F40##L10#Precision Strike:#L0# ภายในรอบใหญ่เดียวกัน Hit Rate ของแต่ละฮิตจะเพิ่มขึ้น 25% ต่อฮิต ดาเมจต่อเป้าหมายเดียวจะเพิ่มขึ้น 5% ต่อฮิต และเมิน Damage Reduction เพิ่มขึ้น 5% ต่อฮิต; ทุก 5 ฮิตที่ทำได้ จะฟื้น Rage 150 หน่วย; เมื่อโจมตีไม่ถูก Block จะทำให้เป้าหมายติดสถานะ Vulnerable เท่ากับ 30% ของ Penetration Rate ที่เกินมา มีผล 1 เทิร์น',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = 'ทุกครั้งที่สร้างความเสียหายครบ 5 Hit จะได้รับโกรธจาก 100 เป็น 150; เมื่อเข้าสู่สนาม เพื่อนร่วมทีมสาย Ghost ทั้งหมดได้รับ【Shadow of Delusion】; เมื่อโจมตีโดยไม่ถูกป้องกัน จะทำให้เป้าหมายติดสถานะ【Vulnerable】เท่ากับ 30% ของอัตรา Break Resistance ส่วนเกิน เป็นเวลา 1 เทิร์น',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		changeUnitTrigger = true,
		isCombat = true,
		skillType = 3,
		skillType2 = 3,
		skillNatureType = 1,
		passiveTriggerType = 7,
