	[41613] = {
		id = 41613,
		skillName = 'ท่าไม้ตาย',
		skillTypeShow = 'ทักษะสังหาร',
		describe = 'Zeraora รวบรวมพลังไฟฟ้าแรงสูงไว้ในมือทั้งสอง และโจมตีด้วยหมัดความเร็วสายฟ้า 6 ครั้งใส่เป้าหมายแบบสุ่ม แต่ละหมัดสร้างความเสียหายทางกายภาพ #C0xE69900#220% พลังโจมตีกายภาพ#C0x5B545B#+$(skillLevel*4*60)$ ของ#C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# หากโจมตีโดนโปเกมอนศัตรู 3 ตัวที่แตกต่างกัน จะกระตุ้น【สนามไฟฟ้าสถิต】ส่งผลต่อศัตรูทั้งสนาม เป็นเวลา 1~2 รอบใหญ่\n#F10# \n#F40##L10#สนามไฟฟ้าสถิต：#L0#ในช่วงนี้ ศัตรูที่ติด【ช็อต】จะมีโอกาส 50% ไม่สามารถรับบัฟได้ และเมื่อโจมตีจะมีโอกาส 80% ถูก【ชา】เป็นเวลา 1 เทิร์น โปเกมอนไฟฟ้าฝ่ายเราที่โจมตีเป้าหมายในสนามไฟฟ้าสถิต จะส่งผ่าน 25% ของดาเมจจากสกิลไปยังเป้าหมาย【ถูกทำให้เป็นแม่เหล็ก】ได้สูงสุด 2 ตัว',
		simDesc = 'Zeraora รวมกระแสไฟฟ้าแรงสูงไว้ที่มือทั้งสอง แล้วปล่อยหมัดด้วยความเร็วสายฟ้าฟาดถึง 5 ครั้ง โจมตีเป้าหมายแบบสุ่ม หากโจมตีเป้าหมายต่างกันหลายคนจะกระตุ้นเอฟเฟกต์ Static Field',
		starEffect = __data_t__starEffect[41613],
		-- {11}
		starEffectDesc = 'เมื่อใช้งานหากมี【Thunder Phantom】อยู่ จะรวมร่างกับ Thunder Phantom กลายเป็น【Thunder Avatar】เป็นเวลา 2 เทิร์น\nThunder Avatar: ได้รับค่าพลัง 80% ของ Thunder Phantom, เพิ่ม Evasion 50%, ทุกการโจมตีแบบ Active จะกลายเป็น Plasma Thunder Punch (ไม่ใช้พลัง, ฟื้น Rage แต่ฟื้นช้าลง 50%), เพิ่มจำนวนหมัด +1 และการันตีโดน  ',
		zawakeEffect = __data_t__zawakeEffect[41613],
		-- {79003}
		zawakeEffectDesc = 'Zeraora รวบรวมกระแสไฟฟ้าแรงสูงไว้ในฝ่ามือ ปล่อยหมัดด้วยความเร็วเหนือสายลม 6 ครั้งใส่เป้าหมายแบบสุ่ม แต่ละครั้งสร้างความเสียหาย#C0xE69900#220%Atk#C0x5B545B#+$(skillLevel*4*60)$เป็น#C0xF13B54#Physical Damage#C0x5B545B# หากโจมตีโดน Pokémon ที่ต่างกันครบ 3 ตัว จะกระตุ้น【Static Field】ใส่ศัตรูทั้งสนาม เป็นเวลา 1~2 เทิร์น\n#F10# \n#F40##L10#Static Field：#L0#ในช่วงนี้เป้าหมายที่มี【Electrify】มีโอกาส 50% ที่จะไม่สามารถรับบัฟได้ และหลังการโจมตีจะมีโอกาส 80% ที่จะติด【Paralyze】1 เทิร์น ถ้า Pokémon ธาตุไฟฟ้าฝ่ายเราโจมตีเป้าหมายใน Static Field ความเสียหาย 25% ของสกิลจะส่งผ่านไปยังเป้าหมายที่มีสถานะ【Magnetized】สูงสุด 2 ตัว',
		zawakeSimpleType = 2,
