	[41753] = {
		id = 41753,
		skillName = 'ท่าไม้ตาย',
		skillTypeShow = 'ทักษะสังหาร',
		describe = 'Meltan ยิงคลื่นกระแทก ใส่ศัตรูแถวหน้าและแถวหลังอย่างละ 1 ตัวแบบสุ่ม สร้างความเสียหายทางกายภาพ #C0xE69900#320% พลังโจมตีกายภาพ#C0x5B545B#+$(skillLevel*4*48)$ของ#C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# เป้าหมายแถวหน้าจะติด【เกราะแตกร้าว】 เป้าหมายแถวหลังจะติด【อาวุธพังทลาย】 หากมีเป้าหมายเพียงตัวเดียวจะติดทั้งสองเอฟเฟกต์ พร้อมกับใน 1 เทิร์นถัดไป HP ที่แปลงจากโลหะเหลวจะเพิ่มเป็น 40% และทุกครั้งที่ถูกโจมตีจะกระตุ้นเอฟเฟกต์โต้กลับแข็งแกร่ง\n#F10# \n#F40##L10#【เกราะแตกร้าว】#L0#ดีบัฟพิเศษ ไม่สามารถล้างได้ เพิ่มความเสียหายที่ได้รับ 20% และลดอัตราการป้องกันลง 30% นาน 2 เทิร์น\n#F10# \n#F40##L10#【อาวุธพังทลาย】#L0#ดีบัฟพิเศษ ไม่สามารถล้างได้ ลดโบนัสความเสียหายลง 30% และลดอัตราคริติคอลลง 30% นาน 2 เทิร์น',
		starEffect = __data_t__starEffect[41753],
		-- {11}
		starEffectDesc = 'เอฟเฟกต์พิเศษ: เอฟเฟกต์【Armor Break】และ【Weapon Collapse】จะถูกใส่ให้กับศัตรูแนวหน้าและแนวหลังอย่างละ 2 ตัว',
		zawakeEffect = __data_t__zawakeEffect[41753],
		-- {79003}
		zawakeEffectDesc = 'Meltan ใช้หมัดเหล็กกระแทกพื้นอย่างแรง โจมตีศัตรูแบบสุ่มในแถวหน้าและแถวหลังอย่างละเป้าหมาย สร้างความเสียหายทางกายภาพ #C0xE69900#320% Physical Attack#C0x5B545B#+$(skillLevel*4*48)$ เป็น#C0xF13B54#Physical Damage#C0x5B545B# เป้าหมายแถวหน้าจะติดสถานะ【Armor Break】 เป้าหมายแถวหลังจะติดสถานะ【Weapon Collapse】 หากมีเป้าหมายเพียงตัวเดียว จะได้รับทั้งสองสถานะ พร้อมเพิ่มอัตราดูดเลือดจาก Liquid Metal เป็น 40% ใน 1 เทิร์นถัดไป และจะเปิดใช้ Hardened Counter ทุกครั้งที่ถูกโจมตี\n#F10#\n#F40##L10#【Armor Break】#L0#ดีบัฟพิเศษ ไม่สามารถลบได้ เพิ่ม Damage Taken 20% และลด Resistance Rate 30% เป็นเวลา 2 เทิร์น\n#F10#\n#F40##L10#【Weapon Collapse】#L0#ดีบัฟพิเศษ ไม่สามารถลบได้ ลด Damage Bonus และ Critical Rate 30% เป็นเวลา 2 เทิร์น',
		zawakeSimpleType = 2,
