	[41756] = {
		id = 41756,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#L10#โลหะเหลว：#L0#ทุกครั้งที่ได้รับความเสียหาย จะดูดซับ 20% ของความเสียหายและแปลงเป็น HP ในปริมาณเท่ากัน พร้อมเพิ่มอัตราการป้องกันและความแข็งแกร่งในการป้องกันของตัวเอง 20% เป็นเวลา 1 เทิร์น ทุกครั้งที่ป้องกันสำเร็จจะกระตุ้นเอฟเฟกต์【โต้กลับแข็งแกร่ง】 (เพิ่มพลังป้องกันกายภาพพื้นฐานของตัวเองถาวร 10% สะสมได้สูงสุด 10 ครั้ง และโต้กลับใส่ผู้โจมตีด้วยความเสียหายจริง 300% ของค่าป้องกันกายภาพ)\n#F10# \n#F40##L10#ไม่หวั่นแม้ชีวิต：#L0#เมื่อโปเกมอนฝ่ายเราถูกโจมตีด้วยสกิลที่สร้างความเสียหายเกิน 80% ของ HP ปัจจุบัน Melmetal จะรับความเสียหายนั้นแทน และหาก Melmetal ถูกโจมตีด้วยการโจมตีที่รุนแรงถึงตาย จะป้องกันความเสียหายนั้นได้ การทำงานของเอฟเฟกต์ใด ๆ จะทำให้ไม่หวั่นแม้ชีวิตเข้าสู่คูลดาวน์ 2 เทิร์น\n#F10# \n#F40##L10#ขึ้นสนิม：#L0#เมื่อ Melmetal ตาย จะกลายสภาพเป็นสนิมและแยกร่างเป็น Meltan โดย Meltan จะสืบทอดค่าสถานะพื้นฐานทั้งหมดของ Melmetal #C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B# (รีเฟรชพาสซีฟและรีเซ็ตคูลดาวน์ของสกิลย่อย)',
		starEffect = __data_t__starEffect[41756],
		-- {8}
		starEffectDesc = 'เอฟเฟกต์เสริม: เพิ่มความเสียหายของสกิล Assist และ Counter ของ Pokémon ธาตุ Steel ฝ่ายเรา 30%; เมื่อเข้าสู่สนามหรือรับความเสียหายแทนเพื่อน จะให้【Steel Shield】แก่ Pokémon ธาตุ Steel (ปริมาณเท่ากับ 500% Def ของ Melmetal), หากมี Pokémon ธาตุ Steel 3 ตัวขึ้นไป จะให้【Steel Shield】กับทีมทั้งหมด  ',
		zawakeEffect = __data_t__zawakeEffect[41756],
		-- {79004}
		zawakeEffectDesc = '#L10#Liquid Metal：#L0#เมื่อได้รับความเสียหาย จะดูดซับ 20% ของความเสียหายที่ได้รับและแปลงเป็นพลังชีวิตในปริมาณเท่ากัน พร้อมเพิ่ม Resistance Rate และ Resistance Strength ของตัวเอง 20% เป็นเวลา 1 เทิร์น เมื่อสามารถต้านทานความเสียหายได้สำเร็จ จะกระตุ้นผลของ【Hardened Counter】(เพิ่ม Physical Defense พื้นฐานของตัวเองถาวร 10% สามารถสะสมได้สูงสุด 10 ครั้ง และโต้กลับศัตรูด้วย True Damage เท่ากับ 300% ของ Physical Defense ของตน)\n#F10#\n#F40##L10#Reckless Devotion：#L0#เมื่อเพื่อนร่วมทีมได้รับความเสียหายจากการโจมตีเชิงรุกที่มากกว่า 80% ของพลังชีวิตปัจจุบัน Melmetal จะรับความเสียหายนั้นแทน หาก Melmetal ถูกโจมตีจนจะตาย จะต้านทานความเสียหายจากการโจมตีนั้นได้ หลังจากเปิดใช้งานผลใดผลหนึ่งจะเข้าสู่คูลดาวน์ 2 เทิร์น\n#F10#\n#F40##L10#Rust：#L0#เมื่อ Melmetal ตาย จะเกิดสนิมและสลายเป็น Meltan โดย Meltan จะสืบทอด#C0x5c9970#$(30+skillLevel*0.3-0.3)$%#C0x5B545B#ของค่าพลังเริ่มต้นทั้งหมดของ Melmetal (รีเฟรชพาสซีฟและรีเซ็ตคูลดาวน์สกิลย่อยทั้งหมด)',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = 'เพิ่มอัตราสร้างความเสียหายพื้นฐาน (รายละเอียดเอฟเฟกต์จะมีการอัปเดตและปรับปรุงในภายหลัง)',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
