	[41763] = {
		id = 41763,
		skillName = 'ท่าไม้ตาย',
		skillTypeShow = 'ทักษะสังหาร',
		describe = 'Meltan ใช้หมัดเหล็กทุบพื้นอย่างรุนแรง โจมตีศัตรูแบบสุ่ม 1 ตัวจากแถวหน้าและ 1 ตัวจากแถวหลัง โดยแต่ละเป้าหมายจะได้รับความเสียหายทางกายภาพ #C0xE69900#320% พลังโจมตีกายภาพ#C0x5B545B#+$(skillLevel*4*48)$ของ#C0xF13B54#ความเสียหายทางกายภาพ#C0x5B545B# เป้าหมายแถวหน้าจะได้รับ【เกราะแตกร้าว】 เป้าหมายแถวหลังจะได้รับ【อาวุธพังทลาย】 หากมีเพียงเป้าหมายเดียวจะได้รับทั้งสองสถานะพร้อมกัน และในเทิร์นถัดไป HP ที่แปลงจากโลหะเหลวจะเพิ่มขึ้นเป็น 40% และทุกครั้งที่ถูกโจมตีจะกระตุ้นเอฟเฟกต์โต้กลับแข็งแกร่ง\n#F10# \n#F40##L10#【เกราะแตกร้าว】#L0#ดีบัฟพิเศษ ไม่สามารถล้างได้ เพิ่มความเสียหายที่ได้รับ 20% และลดอัตราการป้องกันลง 30% นาน 2 เทิร์น\n#F10# \n#F40##L10#【อาวุธพังทลาย】#L0#ดีบัฟพิเศษ ไม่สามารถล้างได้ ลดโบนัสความเสียหายลง 30% และลดอัตราคริติคอลลง 30% นาน 2 เทิร์น',
		simDesc = 'Meltan ใช้หมัดเหล็กทุบพื้นอย่างแรง โจมตีเป้าหมายศัตรูแบบสุ่ม 1 ตัวจากแถวหน้าและแถวหลัง',
		starEffect = __data_t__starEffect[41763],
