	[41816] = {
		id = 41816,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = 'เมื่อโจมตีแบบแอคทีฟ จะใส่ 1 ชั้นของ【Frost Mark】ให้กับศัตรูในพื้นที่ แต่ละชั้นที่ศัตรูมีจะทำให้ความเสียหาย Sp. Atk ของ Ninetales (Alolan Form) ลดลงเพิ่มอีก 5%\n【ปลดล็อก 6 ดาว】: Blizzard\'s Blessing\nความเร็วของตัวเองเมื่อเพิ่มจากตอนเริ่มเข้าสนามทุก 1% จะเพิ่มอัตราหลบหลีก 2% (สูงสุด 50%)\nใน【Hail】จะเพิ่มความเร็วตัวเอง 9% และลดความเสียหายแบบพาสซีฟที่ได้รับลง 10%',
		starEffect = __data_t__starEffect[41816],
		-- {8}
		starEffectDesc = '\nทุกการใช้【Ice Particle】ครบ 6 ครั้ง จะได้รับโล่เท่ากับ 260% Sp. Def และเมื่อโล่แตกจะยิง Ice Ball ไปยังแหล่งที่มาของความเสียหาย สร้างความเสียหายธาตุน้ำแข็งเท่ากัน',
		zawakeEffect = __data_t__zawakeEffect[41816],
		-- {79004}
		zawakeEffectDesc = 'เมื่อโจมตีเชิงรุก จะมอบ 1 ชั้นของ【Frost Shard】แก่เป้าหมายในระยะ ศัตรูแต่ละคนที่มี【Frost Shard】จะลดความเสียหาย Sp.ATK ของ Alolan Ninetales ลง 5%\n【ปลดล็อก 6★】: Blizzard Blessing\nความเร็วของตนเพิ่มขึ้นจากตอนเริ่มต้นทุก 1% จะเพิ่มอัตราหลบหลีก 2% (สูงสุด 50%)\nใน【Hail】 ความเร็วของตนเพิ่มขึ้น 9% และลดความเสียหายแบบ Passive ลง 10%',
		zawakeSimpleType = 2,
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		changeUnitTrigger = true,
		isCombat = true,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5
	},
