	[42216] = {
		id = 42216,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = 'เมื่อเริ่มการต่อสู้ จะมอบสถานะ【Emotion】ให้ทุกตัวในสนาม และ Mesprit จะไม่ติดผลเปลี่ยนแปลงจาก Emotion  \n 【Emotion】: เอฟเฟกต์พิเศษ ไม่สามารถซ้อนทับหรือลบได้ เริ่มต้นเป็นสถานะ【Calm】  \n 【Calm】: สถานะกลาง หากโจมตีเพื่อนร่วมทีม มีโอกาส 20% เปลี่ยนเป็น【Guilt】; หากโจมตีศัตรู มีโอกาส 20% เปลี่ยนเป็น【Joy】; หากโดนเพื่อนโจมตี มีโอกาส 20% เปลี่ยนเป็น【Sadness】; หากโดนศัตรูโจมตี มีโอกาส 20% เปลี่ยนเป็น【Anger】  \n 【Guilt】: สถานะลบ ทุกครั้งที่เพื่อนร่วมทีมจะออกเทิร์น Mesprit จะได้รับความเสียหายเท่ากับ 70% ATK ของผู้ที่ออกเทิร์นนั้น จะกลับเป็น Calm ก่อนเริ่มเทิร์นถัดไป  \n 【Joy】: สถานะบวก เมื่อเปลี่ยนเข้าสู่ Joy จะได้รับเกจโกรธ 100 หน่วย ระหว่างสถานะนี้จะเพิ่มความเร็วฟื้นฟูเกจโกรธ 50% และจะกลับเป็น Calm หลังจบเทิร์น  \n 【Sadness】: สถานะลบ เมื่อเปลี่ยนเข้าสู่ Sadness จะเสียเกจโกรธ 200 หน่วย ระหว่างสถานะนี้จะลดความเร็วฟื้นฟูเกจโกรธ 50% และจะกลับเป็น Calm ก่อนเริ่มเทิร์น  \n 【Anger】: สถานะบวก ระหว่างสถานะนี้จะเพิ่ม Damage Bonus 45% และลด Damage Reduction 15% จะกลับเป็น Calm หลังจบเทิร์น',
		starEffect = __data_t__starEffect[42216],
		-- {8}
		starEffectDesc = 'ศัตรูที่ไม่อยู่ในอารมณ์ Calm จะสร้างความเสียหายต่อ Mesprit ลดลง 70%',
		zawakeEffect = __data_t__zawakeEffect[42216],
		-- {79004}
		zawakeEffectDesc = 'เมื่อเริ่มการต่อสู้ มอบสถานะอารมณ์ให้กับยูนิตทุกตัวในสนาม Uxie จะได้รับผลภูมิคุ้มกันจากการเปลี่ยนแปลงของอารมณ์\nอารมณ์: เอฟเฟกต์พิเศษ ไม่สามารถซ้อนทับหรือถูกลบได้ เริ่มต้นด้วยสถานะ “Calm”\nCalm: อารมณ์เป็นกลาง มีโอกาส 20% ที่จะเปลี่ยนเป็น “Guilt” เมื่อโจมตีเพื่อนร่วมทีม, เปลี่ยนเป็น “Joy” เมื่อโจมตีศัตรู, เปลี่ยนเป็น “Sadness” เมื่อถูกเพื่อนโจมตี, และเปลี่ยนเป็น “Rage” เมื่อถูกศัตรูโจมตี\nGuilt: อารมณ์ด้านลบ ก่อนที่เพื่อนร่วมทีมจะเริ่มเทิร์น ตัวเองจะได้รับความเสียหายเท่ากับ 70% Atk ของผู้ที่กำลังจะเริ่มเทิร์นนั้น และจะเปลี่ยนกลับเป็น “Calm” ก่อนเทิร์นถัดไป\nJoy: อารมณ์ด้านบวก เมื่อเปลี่ยนเป็น Joy จะได้รับ 100 Fury ทันที และในช่วงที่มีผลจะฟื้น Fury เร็วขึ้น 50% จะเปลี่ยนกลับเป็น “Calm” หลังจากจบเทิร์นถัดไป\nSadness: อารมณ์ด้านลบ เมื่อเปลี่ยนเป็น Sadness จะเสีย 200 Fury และในช่วงที่มีผลจะฟื้น Fury ช้าลง 50% จะเปลี่ยนกลับเป็น “Calm” ก่อนเทิร์นถัดไป\nRage: อารมณ์ด้านบวก ในช่วงที่มีผลจะเพิ่มพลังโจมตี 45% แต่ลดการต้านทานความเสียหายลง 15% จะเปลี่ยนกลับเป็น “Calm” หลังจากจบเทิร์นถัดไป',
