	[52107] = {
		id = 52107,
		skillName = 'Held Item - Fusion Turbo',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#F40##L10#【เทอร์โบเพลิง】:#L0#ผู้ถือคือ Kyurem ขาวเพลิง: \nเมื่อเข้าสู่สนาม จะเพิ่มพลัง HP สูงสุดของฝ่ายเราทั้งหมด $(20+(skillLevel-1)*2)$% และมอบบัฟลดความเสียหายที่ได้รับและอัตราสะท้อนความเสียหายให้ตนเอง $(20+(skillLevel-1)*2)$% (คงอยู่ 5 เทิร์น) \n#F40##L10#【เทอร์โบสายฟ้าม่วง】:#L0#ผู้ถือคือ Kyurem มืด: \nเมื่อเข้าสู่สนาม จะเพิ่มโบนัสความเสียหายของท่าไม้ตายให้ฝ่ายเราทั้งหมด $(20+(skillLevel-1)*2)$% และเพิ่มพลังโจมตีกายภาพและโบนัสความเสียหายของตนเอง $(20+(skillLevel-1)*2)$% (คงอยู่ 5 เทิร์น) \n#F40##L10#【เทอร์โบเยือกแข็ง】:#L0#ผู้ถือคือ Kyurem ขาวเพลิง: \nKyurem ขาวเพลิงปลดปล่อยเทอร์โบเยือกแข็ง มอบโล่เท่ากับ $(80+(skillLevel-1)*5)$% ของ HP สูงสุดของผู้ถือให้กับฝ่ายเราทั้งหมด ขณะโล่ยังคงอยู่จะเพิ่มอัตราต้านควบคุม $(20+(skillLevel-1)*2)$% \n#F40##L10#【เทอร์โบเยือกฟ้า】:#L0#ผู้ถือคือ Kyurem มืด: \nKyurem มืดปลดปล่อยเทอร์โบเยือกฟ้า มอบสถานะ【ซ่อนตัวในสายฟ้า】ให้โปเกมอนไฟฟ้าฝ่ายเรา (คงอยู่ 1 เทิร์น) ขณะอยู่ในสถานะ【โอเวอร์โหลดแห่งความมืด】จะเสริมความเสียหายธาตุไฟฟ้าเพิ่มอีก $(100+(skillLevel-1)*10)$% ตามพลังโจมตีคู่ \n#F40##L10#【รัตติกาลอันเป็นนิรันดร์】:#L0#ผู้ถือคือ Kyurem ขาวเพลิง: \n【กำแพงน้ำแข็งเพลิง】สามารถอัปเกรดเป็น【เปลวไฟแห่งการจบสิ้น】 สร้างความเสียหายธาตุน้ำแข็ง/ไฟให้ศัตรู $(100+(skillLevel-1)*10)$% ตามพลังโจมตีคู่ \n#F40##L10#【โวลต์เยือกแข็ง】:#L0#ผู้ถือคือ Kyurem มืด: \nเริ่มการต่อสู้มีโอกาส 50% ที่จะเปิดใช้งานสภาพอากาศ【พายุฟ้าคะนอง】 เพิ่มโบนัสความเสียหายให้โปเกมอนไฟฟ้าทั้งสนาม 20% เพิ่มความเสียหายคริติคอลของสายฟ้าอีก 20% และความเร็วในการฟื้นโทสะ 20% (คงอยู่ 3 เทิร์น ไม่สามารถถูกแทนที่ด้วยสภาพอากาศอื่น) และสร้าง【เมฆสายฟ้าเยือกแข็ง】ให้ฝ่ายศัตรู',
		alwaysEffective = true,
		passivePriority = 3,
		skillType = 3,
