	[70212] = {
		id = 70212,
		skillName = 'สกิลพิเศษ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#ข้าไม่ได้พาความกลัวมา ข้าคือความกลัวเอง#C0x5B545B#\n#F10#\n#F40#Mega Gengar ส่องแสงพ่นลูกบอลเงาใส่ศัตรูในแถว สร้างความเสียหายพิเศษ#C0x3D8A99#180%พลังพิเศษ#C0x5B545B#+$(skillLevel*4*48)$ของ#C0xF13B54#ความเสียหายพิเศษ#C0x5B545B# วางตุ๊กตา Clefable จนกว่า Gengar จะทำการกระทำครั้งถัดไป หรือเมื่อตุ๊กตาถูกโจมตี 2 ครั้งจะหายไป\n#F10#\n#F40##L10#ตุ๊กตา Clefable:#L0# ยูนิตอัญเชิญ ขณะอยู่ในสนาม Gengar จะ【หลบซ่อน】ในเงาของตุ๊กตา และไม่รับความเสียหายจากแหล่งพาสซีฟ ตุ๊กตามี【ร่างคำสาป】 เมื่อถูกโจมตี ศัตรูจะได้รับ【คำสาปรัตติกาล】\n#F10#\n#F40##L10#คำสาปรัตติกาล:#L0# ดีบัฟ ต้องล้าง 2 ครั้ง โทสะที่จะได้รับครั้งถัดไปจะกลายเป็นค่าลบ และความเสียหายที่จะโจมตีใส่ Mega Gengar หรือเพื่อนร่วมทีมสายผี 50% จะกลายเป็นการฟื้นฟู HP แทน',
		zawakeEffect = __data_t__zawakeEffect[70212],
		-- {79002}
		zawakeEffectDesc = '#C0xC0C0C0#เราไม่ได้พาความกลัวมา... เราคือความกลัวเอง#C0x5B545B#\n#F10#\n#F40#Shiny Mega Gengar ยิงลูกบอลเงาใส่เป้าหมายแถวแนวนอนฝ่ายศัตรู สร้างความเสียหาย#C0xF13B54#พิเศษ#C0x5B545B#เท่ากับ #C0x3D8A99#180% พลังโจมตีพิเศษ#C0x5B545B#+$(skillLevel*4*48)$ จากนั้นวางตุ๊กตา Clefable ซึ่งคงอยู่จนกว่า Gengar จะถึงรอบการกระทำถัดไป หรือเมื่อตุ๊กตาถูกโจมตี 2 ครั้ง\n#F10#\n#F40##L10#ตุ๊กตา Clefable：#L0#สิ่งอัญเชิญ Gengar จะ【Shadow Merge】เข้ากับเงาของตุ๊กตานี้ในระหว่างที่มันอยู่ และจะไม่รับผลจากความเสียหายแบบพาสซีฟ ตุ๊กตา Clefable มีสถานะ【Cursed Body】เมื่อถูกโจมตีจะทำให้ศัตรูติดสถานะ【Curse of Eternal Night】\n#F10#\n#F40##L10#Curse of Eternal Night：#L0#ดีบัฟพิเศษ ต้องการการล้างสถานะ 2 ครั้ง ครั้งถัดไปที่ได้รับเกจโกรธจะกลายเป็นค่าลบ และความเสียหายที่โจมตีใส่ Shiny Mega Gengar หรือเพื่อนร่วมทีมสาย Ghost 50% จะกลายเป็นการฟื้นฟู',
		zawakeSimpleType = 1,
