	[70216] = {
		id = 70216,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#จะยอมรับเงา...หรือจะตายในความมืด#C0x5B545B#\n#F10#\n#F40##L10#ดูดพลังงาน:#L0# ทุกครั้งที่โจมตีจะดูด 20% ของโทสะเป้าหมาย หากดูดได้ไม่ถึง 100 แต้ม จะใส่【คำสาปอาฆาต】เพิ่ม 1 ชั้น; ทุกครั้งที่ศัตรูเสียโทสะรวมกันครบ 150 แต้ม Mega Gengar จะฟื้น HP ตามพลังพิเศษ 120% และทำให้ศัตรูติด【คำสาปอาฆาต】 1 ชั้น\n#F10#\n#F40##L10#ร่างคำสาป:#L0# ต้านทานความเร็วแปรปรวน เมื่อมีใครโจมตี Mega Gengar จะติด【คำสาปอาฆาต】 2 เทิร์น (หากโดนโจมตีจากสายผี/พิษ จะขยายอีก 1 เทิร์น) แต่ละชั้นของคำสาปจะลดความเสียหายที่สายพิษได้รับลง 18%\n#F10#\n#F40##L10#หลบซ่อนในเงาผี:#L0# หากมีเพื่อนอยู่แถวหน้า เงาของเพื่อนจะให้การคุ้มครองแก่ Mega Gengar: หากศัตรูมีโทสะน้อยกว่า 50% Mega Gengar จะอยู่ใน【หลบซ่อน】 และสร้างความเสียหายเพิ่มขึ้น #C0x5c9970#$(20+skillLevel*0.15-0.15)$%#C0x5B545B#\n#F20#\n#F40#【คำสาปอาฆาต】: ดีบัฟ ล้างได้เท่านั้น ศัตรูจะได้รับความเสียหายธาตุพิษจริง เท่ากับ 50% พลังพิเศษของ Gengar ก่อนเริ่มเทิร์น สะสมได้สูงสุด 5 ชั้น หากถูกล้างจะระเบิดเป็นความเสียหายธาตุพิษ 1.5 เท่า หากสะสมครบ 3 ชั้น จะเสียโทสะ 100 และติด【พิษหลอนภาพ】 1 เทิร์น\n#F10#\n#F40#【พิษหลอนภาพ】: เอฟเฟกต์ควบคุม ไม่สามารถล้างได้ ก่อนเริ่มเทิร์น มีโอกาส 80% ที่จะเห็นเพื่อนร่วมทีมแบบสุ่มเป็น Mega Gengar และโจมตีด้วยการโจมตีปกติ\n#F10#\n#F40#【หลบซ่อน】: สถานะสายผีแบบล่องหน หายไปจากวิสัยทัศน์ของศัตรู ไม่สามารถถูกเลือกเป้าหมายหรือใส่เอฟเฟกต์ได้',
		starEffect = __data_t__starEffect[70216],
		-- {8}
		starEffectDesc = '#L10#Ghost Backstab：#L0#หลังจากใช้ Endless Night ภายใน 2 เทิร์น การใช้สกิลโจมตีปกติจะเปลี่ยนเป็น Ghost Backstab โจมตีเป้าหมายเพิ่มเติม 1 ตัว สร้างความเสียหายพิเศษ 400% และติด【Nightmare】 3 เทิร์น หากเป้าหมายติด Poison จะกลายเป็นความเสียหายจริง และดูด Rage ปัจจุบันของเป้าหมาย 50%',
		zawakeEffect = __data_t__zawakeEffect[70216],
		-- {79004, 1}
		zawakeEffectDesc = '#L10#Ghostly Ambush：#L0#เมื่อศัตรูตาย Gengar จะขโมยเงาของพวกมันและแปลงร่างเป็นยูนิตศัตรูที่ตายไปแทนที่ตำแหน่งเดิม รอจนถึงเทิร์นถัดไปของตัวเอง จากนั้นจะโจมตีแทงด้านหลังใส่ศัตรูแบบสุ่ม 1 ตัว สร้างความเสียหายพิเศษ 500% พร้อมใส่สถานะ【Nightmare】3 เทิร์น หากเป้าหมายนั้นติดพิษ ความเสียหายจะกลายเป็น True Damage และดูดเกจโกรธของเป้าหมาย 50% (สามารถเกิดได้ 2 ครั้งต่อการต่อสู้);\nGhost Stealth Boost：เมื่อมีเพื่อนร่วมทีมสาย Ghost อยู่ในสนาม จะสามารถให้การปกป้องได้ด้วย; การโจมตีจะไม่สนผลของภูมิประเทศ',
		zawakeSimpleType = 1,
