	[70223] = {
		id = 70223,
		skillName = 'ท่าไม้ตาย',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#ความมืดกลืนกินข้าไม่ได้...แต่เจ้าจะถูกมันกลืน!#C0x5B545B#\n#F10#\n#F40#Mega Gengar ส่องแสงเปิดหนังสือผีเรียกศัตรู 2 ตัวลำดับถัดไปเข้าเมืองผี สร้างความเสียหายพิเศษ#C0x3D8A99#320%พลังพิเศษ#C0x5B545B#+$(skillLevel*4*60)$ของ#C0xF13B54#ความเสียหายพิเศษ#C0x5B545B# และใส่【ฝันร้าย】เป็นเวลา 1 เทิร์น\n#F10#\n#F40##L10#ฝันร้าย:#L0# ดีบัฟพิเศษ ต้องล้าง 3 ครั้ง กลางคืนมืดบังการมองเห็น ทำให้ขอบเขตเป้าหมายของสกิลลดลงแบบสุ่ม 1 ช่อง (อย่างน้อยคงเหลือ 1 ช่อง) และเอฟเฟกต์จะไม่ส่งผลต่อเป้าหมายที่อยู่นอกขอบเขตนั้น ขณะมี【ฝันร้าย】 เพื่อนสายผีทั้งหมดจะอยู่ใน【หลบซ่อน】 และทุกครั้งที่ Gengar โจมตีจะดูดโทสะของเป้าหมาย 50 แต้ม',
		simDesc = 'Shiny Mega Gengar เปิดหนังสือปีศาจ นำศัตรู 2 ตัวถัดจากลำดับการเคลื่อนไหวของตนเข้าสู่เมืองผีเงาเพื่อสัมผัสความเจ็บปวดจากนรก และทำให้ติดสถานะ Night Terror',
		starEffect = __data_t__starEffect[70223],
		-- {11}
		starEffectDesc = 'ยินดีต้อนรับสู่บ้านของ Gengar！\n#F10#\n#F40##L10#บ้านผีสิงคำสาป：#L0#หากมีเพื่อนร่วมทีมที่ไม่สามารถ【Stealth】ได้ จะสุ่มแปลงหนึ่งในนั้นเป็น【บ้านผีสิงคำสาป】; หากไม่มีเป้าหมายที่ไม่สามารถ【Stealth】ได้และมีตำแหน่งว่างในทีม (เลือกแถวหน้าก่อน) จะสร้างบ้านผีสิงคำสาปขึ้นในตำแหน่งว่างนั้น เป้าหมายแรกที่โจมตีบ้านผีสิงจะถูกดึงเข้าไปก่อนโจมตีและติดสถานะ【Madness】 หลังจากนั้นบ้านผีสิงจะหายไป (Madness: ดีบัฟพิเศษ ไม่สามารถลบได้ ไม่สามารถโจมตี Gengar ได้ ระหว่างเทิร์นของตนเองหรือ Gengar จะทำร้ายตัวเอง โดยสร้างความเสียหายจริง 150% ATK ของตนเอง, Gengar จะได้รับภูมิคุ้มกันจาก Madness)  ',
		zawakeEffect = __data_t__zawakeEffect[70223],
		-- {79003}
		zawakeEffectDesc = '#C0xC0C0C0#ความมืดกลืนกินเราไม่ได้ แต่เราจะ... กลืนกินเธอ!#C0x5B545B#\n#F10#\n#F40#Shiny Mega Gengar พลิกหนังสือวิญญาณ ลากศัตรู 2 ตัวสุดท้ายในลำดับเทิร์นเข้าสู่เมืองผีเพื่อสัมผัสกับความทรมานในนรก สร้างความเสียหาย#C0xF13B54#พิเศษ#C0x5B545B#เท่ากับ #C0x3D8A99#280% พลังโจมตีพิเศษ#C0x5B545B#+$(skillLevel*4*48)$ และใส่สถานะ【Nightmare】เป็นเวลา 1 เทิร์น\n#F10#\n#F40##L10#Nightmare：#L0#ดีบัฟพิเศษ ต้องล้าง 3 ครั้ง ความมืดปกคลุมสายตาทำให้ช่วงเลือกเป้าหมายโจมตีลดลงแบบสุ่ม (อย่างน้อย 1) เอฟเฟกต์และความเสียหายจะไม่ส่งผลต่อเป้าหมายที่อยู่นอกขอบเขต; ขณะเป้าหมายอยู่ในสถานะ【Nightmare】เพื่อนร่วมทีมสาย Ghost ทั้งหมดจะถือว่าอยู่ในสถานะ【Shadow Merge】กับเป้าหมายนั้น และ Gengar จะดูดเกจโกรธของเป้าหมายที่โจมตี 50 แต้มทุกครั้ง',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '#C0x5c9970#เอฟเฟกต์ Nightmare เสริมความแรง: เพิ่มระยะเวลาอีก 1 เทิร์น และจำกัดวิสัยทัศน์เหลือเพียง 1 เป้าหมาย; ภายใน 1 เทิร์นหลังใช้ท่าไม้ตาย Shiny Mega Gengar จะเข้าสู่สถานะ【Shadow Cloak】หากเป้าหมายมีสถานะ Grudge',
