	[70226] = {
		id = 70226,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#เลือกซะ...กอดเงาไว้ หรือจะตายท่ามกลางความมืด#C0x5B545B#\n#F10#\n#F40##L10#การดูดพลังงาน:#L0# ทุกครั้งที่โจมตีจะดูด 20% โทสะของเป้าหมาย หากดูดได้ไม่ถึง 100 แต้ม จะใส่【คำสาปอาฆาต】 1 ชั้นเพิ่มเติม; ทุก ๆ 150 โทสะที่ศัตรูเสียไป Gengar จะฟื้น HP เท่ากับ 120% พลังพิเศษ และทำให้ศัตรูติด【คำสาปอาฆาต】 1 ชั้น\n#F10#\n#F40##L10#ร่างคำสาป:#L0# ต้านทานความเร็วแปรปรวน เมื่อมีใครโจมตี Gengar จะติด【คำสาปอาฆาต】 2 เทิร์น (หากถูกโจมตีโดยสายผี/พิษ จะขยายเพิ่ม 1 เทิร์น) ทุกชั้นของคำสาปนี้จะลดความเสียหายที่สายพิษได้รับลง 18%\n#F10#\n#F40##L10#เงาผีซ่อนตัว:#L0# หากมีเพื่อนอยู่แถวหน้า เงาของเพื่อนจะให้การคุ้มครองแก่ Gengar: หากศัตรูมีโทสะน้อยกว่า 50% Gengar จะอยู่ใน【หลบซ่อน】 และสร้างความเสียหายเพิ่มขึ้น #C0x5c9970#$(20+skillLevel*0.15-0.15)$%#C0x5B545B#\n#F20#\n#F40#【คำสาปอาฆาต】: ดีบัฟ ล้างได้เท่านั้น เป้าหมายจะได้รับความเสียหายธาตุพิษจริงเท่ากับ 50% พลังพิเศษของ Gengar ก่อนเริ่มเทิร์น สะสมได้สูงสุด 5 ชั้น หากถูกล้างจะระเบิดสร้างความเสียหายธาตุพิษ 1.5 เท่า หากถึง 3 ชั้น จะสูญเสียโทสะ 100 และติด【พิษภาพหลอน】 1 เทิร์น\n#F10#\n#F40#【พิษภาพหลอน】: เอฟเฟกต์ควบคุม ไม่สามารถล้างได้ ก่อนเทิร์นมีโอกาส 80% ที่จะมองเห็นเพื่อนร่วมทีมแบบสุ่มเป็น Gengar และใช้การโจมตีปกติกับเป้าหมายนั้น\n#F10#\n#F40#【หลบซ่อน】: สถานะพิเศษสายผี หายไปจากระยะเป้าหมายของศัตรู ไม่สามารถถูกเลือกหรือรับเอฟเฟกต์ใด ๆ ได้',
		starEffect = __data_t__starEffect[70226],
		-- {8}
		starEffectDesc = '#L10#Ghost Backstab：#L0#หลังจากใช้ Endless Night ภายใน 2 เทิร์น การใช้สกิลโจมตีปกติจะเปลี่ยนเป็น Ghost Backstab โจมตีเป้าหมายเพิ่มเติม 1 ตัว สร้างความเสียหายพิเศษ 400% และติด【Nightmare】 3 เทิร์น หากเป้าหมายติด Poison จะกลายเป็นความเสียหายจริง และดูด Rage ปัจจุบันของเป้าหมาย 50%',
		zawakeEffect = __data_t__zawakeEffect[70226],
		-- {79004, 1}
		zawakeEffectDesc = '#L10#Ghostly Ambush：#L0#เมื่อศัตรูตาย Gengar จะขโมยเงาของพวกมันและแปลงร่างเป็นยูนิตศัตรูที่ตายไปแทนที่ตำแหน่งเดิม รอจนถึงเทิร์นถัดไปของตัวเอง จากนั้นจะโจมตีแทงด้านหลังใส่ศัตรูแบบสุ่ม 1 ตัว สร้างความเสียหายพิเศษ 500% พร้อมใส่สถานะ【Nightmare】3 เทิร์น หากเป้าหมายนั้นติดพิษ ความเสียหายจะกลายเป็น True Damage และดูดเกจโกรธของเป้าหมาย 50% (สามารถเกิดได้ 2 ครั้งต่อการต่อสู้);\nGhost Stealth Boost：เมื่อมีเพื่อนร่วมทีมสาย Ghost อยู่ในสนาม จะสามารถให้การปกป้องได้ด้วย; การโจมตีจะไม่สนผลของภูมิประเทศ',
