	[70816] = {
		id = 70816,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#ต้นไม้โลก หล่อเลี้ยงเทพทั้งมวล#C0x5B545B#\n\n#F40##L10#การสร้างพันธุกรรมใหม่:#L0# หลังจบการกระทำแต่ละครั้ง ตนเองจะเข้าสู่สถานะ【การสร้างพันธุกรรมใหม่】 (แต่ละร่างแปลงใช้ได้ครั้งเดียว) เมื่อผ่านไป 1 เทิร์น หรือเมื่อ HP ของร่างแปลงหมด จะจบสถานะนี้ และฟื้นฟู HP 30% ของ HP สูงสุด\n#F40##L10#ฟองพลังจิต:#L0# ตนเองจะได้รับ【ฟองพลังจิต】ถาวร ป้องกันการแปลงร่างและแปลงพันธุกรรม เพิ่มอัตราต้านดีบัฟ 10% ทุกครั้งที่ถูกโจมตีจะลดโบนัสความเสียหายของผู้โจมตี 10% และลดคริติคอลดาเมจ 20% เมื่อ HP ต่ำกว่า 30% เป็นครั้งแรก จะเข้าสู่สภาวะฟื้นคืนจากความฝัน หลับ 1 เทิร์น และความเสียหายที่ได้รับจะกลายเป็นการฟื้นฟู HP \n #C0xF13B54#【การสร้างพันธุกรรมใหม่】#C0x5B545B#\nแปลงร่างสายพลังจิตแบบสุ่มเป็นหนึ่งใน Mega Alakazam, Mewtwo หรือ Cresselia โดยรับ HP เท่ากับช่วงเปลี่ยนร่าง และได้รับรอบการกระทำใหม่ทั้งขณะร่างแปลงและก่อนร่างเดิมจะถึงรอบถัดไป ใช้ร่างแปลงโจมตีในช่วงนี้ \n #C0xF13B54#【การสร้างพันธุกรรมใหม่ - Mega Alakazam】#C0x5B545B#\nแปลงร่างเป็น Mega Alakazam รับ HP ตามช่วงเปลี่ยนร่าง\nพาสซีฟ: เพิ่มความเร็ว 10% โจมตีมีโอกาส 50% ทำให้ศัตรู 1 ตัวกลายเป็นหิน\nสกิลหลัก: สร้างความเสียหายพิเศษ#C0x3D8A99#180%พลังพิเศษ#C0x5B545B#ของ#C0xF13B54#ความเสียหายพิเศษ#C0x5B545B# พร้อมมีโอกาส 100% ทำให้เป้าหมายติด【เงียบ】 1 เทิร์น \n #C0xF13B54#【การสร้างพันธุกรรมใหม่ - Mewtwo】#C0x5B545B#\nแปลงร่างเป็น Mewtwo รับ HP ตามช่วงเปลี่ยนร่าง\nพาสซีฟ: เพิ่ม HP สูงสุด 200% และมีอัตราสะท้อนความเสียหาย 15%\nสกิลหลัก: สร้างความเสียหายพิเศษ#C0x3D8A99#100%พลังพิเศษ#C0x5B545B#ของ#C0xF13B54#ความเสียหายพิเศษ#C0x5B545B# เชื่อมโยงกับเพื่อนร่วมทีมสายพลังจิตแบบสุ่ม 1 ตัว เพิ่มอัตราลดความเสียหาย 10% และแบ่งเบาความเสียหาย 50% \n #C0xF13B54#【การสร้างพันธุกรรมใหม่ - Cresselia】#C0x5B545B#\nแปลงร่างเป็น Cresselia รับ HP ตามช่วงเปลี่ยนร่าง\nพาสซีฟ: เพิ่มอัตราต้านควบคุม 50% และอัตราฟื้นฟู HP 20%\nสกิลหลัก: สร้างความเสียหายพิเศษ#C0x3D8A99#120%พลังพิเศษ#C0x5B545B#ของ#C0xF13B54#ความเสียหายพิเศษ#C0x5B545B#',
		starEffect = __data_t__starEffect[70816],
		-- {6}
		starEffectDesc = '\n#F40##L10#Psychic Field:#L0#\nเริ่มแต่ละเทิร์น จะสุ่มลดค่าพลังโจมตีหนึ่งประเภทของศัตรูทุกตัว (ATK, Sp.Atk, Damage Bonus) และฝั่งเราจะสุ่มเพิ่มค่าป้องกันหนึ่งประเภท (DEF, Sp.Def, Damage Reduction) ผลกระทบมีผล 10%; ทุก 5 เทิร์นจะเกิด【Gene Burst】ทำให้ศัตรูถอยกลับสู่ร่างเริ่มต้น และลบเอฟเฟกต์ Mega Evolution ทั้งหมด นาน 1 เทิร์น  ',
		zawakeEffect = __data_t__zawakeEffect[70816],
		-- {79004}
		zawakeEffectDesc = '#C0xC0C0C0#ต้นไม้แห่งโลก เลี้ยงดูเหล่าทวยเทพ#C0x5B545B#\n\n#F40##L10#Gene Reshape:#L0#หลังจบเทิร์นตนเองทุกครั้ง จะทำการ【Gene Reshape】 (แต่ละรูปร่างสามารถทำได้ 1 ครั้ง) หลังผ่าน 1 เทิร์นหรือเมื่อ HP ของรูปร่างใหม่หมด การ Reshape จะสิ้นสุด และฟื้นฟู HP 30% ของ HP สูงสุด\n#F40##L10#Psychic Bubble:#L0#ได้รับสถานะ【Psychic Bubble】แบบถาวร ต้านทานการแปลงร่างและการเลียนแบบ เพิ่มโอกาสต้านดีบัฟ 10%; ทุกครั้งที่โดนโจมตีจะลดความเสียหายที่ผู้โจมตีทำได้ 10% และลดคริติคอลดาเมจ 20%; เมื่อ HP ต่ำกว่า 30% ครั้งแรกจะเข้าสู่【Dream Rebirth】 หลับ 1 เทิร์น และฟื้นฟู HP ตามความเสียหายที่ได้รับระหว่างนั้น\n#C0xF13B54#【Gene Reshape】#C0x5B545B#\nแปลงร่างพิเศษสาย Psychic เป็น 1 ใน 3 แบบสุ่ม: Mega Alakazam, Mewtwo, หรือ Cresselia พร้อม HP เท่ากับตอนแปลง และจะได้รับเทิร์นทันทีโดยใช้ร่างใหม่นั้นในการโจมตี\n#C0xF13B54#【Gene Reshape - Mega Alakazam】#C0x5B545B#\nแปลงร่างเป็น Mega Alakazam พร้อม HP ขณะแปลง\n- พาสซีฟ: เพิ่มความเร็ว 10%, เมื่อโจมตีมีโอกาส 50% ทำให้เป้าหมายติด【Petrify】\n- แอคทีฟ: สร้างความเสียหายพิเศษ#C0x3D8A99#180%#C0x5B545B# และมีโอกาส 100% ทำให้เป้าหมายติด【Silence】 1 เทิร์น\n#C0xF13B54#【Gene Reshape - Mewtwo】#C0x5B545B#\nแปลงร่างเป็น Mewtwo พร้อม HP ขณะแปลง\n- พาสซีฟ: เพิ่ม HP สูงสุด 200% และมีอัตราสะท้อนความเสียหาย 15%\n- แอคทีฟ: สร้างความเสียหายพิเศษ#C0x3D8A99#100%#C0x5B545B# และเชื่อมโยงกับเพื่อนร่วมทีมสาย Psychic แบบสุ่ม 1 ตัว เพิ่ม Damage Reduction 10% และแบ่งรับความเสียหาย 50%\n#C0xF13B54#【Gene Reshape - Cresselia】#C0x5B545B#\nแปลงร่างเป็น Cresselia พร้อม HP ขณะแปลง\n- พาสซีฟ: เพิ่มอัตราต้านสถานะ 50% และอัตราฟื้นฟู 20%\n- แอคทีฟ: สร้างความเสียหายพิเศษ#C0x3D8A99#120%#C0x5B545B#',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '#C0x5c9970#เมื่อการแปลงร่าง【Genetic Reshape】สิ้นสุด ตัวหลักจะคงพาสซีฟของร่างนั้นไว้ 1 เทิร์น (สามารถสะสมได้จากทั้ง 3 รูปแบบ); จำนวนครั้งของ【Genetic Reshape】เพิ่มขึ้น 1',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
