	[70821] = {
		id = 70821,
		skillName = 'สกิลทั่วไป',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#จุดเริ่มต้นของความฝัน ดั่งจิตใจแรกเริ่มไม่เปลี่ยนแปลง#C0x5B545B#\nOrigin Mew โจมตีเป้าหมายศัตรูเดี่ยว สร้างความเสียหายพิเศษ#C0x3D8A99#100%พลังพิเศษ#C0x5B545B#+$(skillLevel*4*24)$ของ#C0xF13B54#ความเสียหายพิเศษ#C0x5B545B# พร้อมเพิ่มความเร็วและลดความเสียหายที่ได้รับของตนเอง 25%\n#F40##L10#ผู้นำสายพลังจิต:#L0# เมื่อเพื่อนร่วมทีมสายพลังจิตทำการกระทำ Origin Mew จะร่วมโจมตีด้วยทุกครั้ง และทุกครั้งที่ร่วมโจมตีจะเพิ่มความเร็วและลดความเสียหายที่ได้รับของเพื่อนร่วมทีมสายพลังจิต 5% สะสมได้สูงสุด 10 ชั้น',
		zawakeEffect = __data_t__zawakeEffect[70821],
		-- {79001}
		zawakeEffectDesc = '#C0xC0C0C0#กำเนิดจากฝัน ไม่ลืมจุดเริ่มต้น#C0x5B545B#\nOrigin Mew โจมตีเป้าหมายเดี่ยวฝ่ายศัตรู สร้างความเสียหาย#C0xF13B54#พิเศษ#C0x5B545B#เท่ากับ #C0x3D8A99#100% พลังโจมตีพิเศษ#C0x5B545B#+$(skillLevel*4*24)$ เพิ่มความเร็วและการลดความเสียหายของตนเอง 25%\n#F40##L10#Psychic Commander：#L0#เมื่อเพื่อนร่วมทีมสาย Psychic ออกเทิร์น Origin Mew จะโจมตีร่วมด้วย และเพิ่มความเร็วกับการลดความเสียหายของเพื่อนสาย Psychic ทีละ 5% (สะสมได้สูงสุด 10 ชั้น)',
