	[70822] = {
		id = 70822,
		skillName = 'สกิลพิเศษ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#หมื่นแปรเปลี่ยน แต่ไม่ลืมต้นกำเนิด#C0x5B545B#\nOrigin Mew โจมตีเป้าหมายศัตรูใดก็ได้ 1 ตัว สร้างความเสียหายพิเศษ#C0x3D8A99#180%พลังพิเศษ#C0x5B545B#+$(skillLevel*4*36)$ของ#C0xF13B54#ความเสียหายพิเศษ#C0x5B545B# และ【แปลงร่างพันธุกรรม】เลียนแบบเพื่อนร่วมทีมสายพลังจิตที่มีพลังโจมตีสูงสุด 1 เทิร์น ได้รับ HP เท่ากับ 20% ของ HP ปัจจุบันของเป้าหมาย (ไม่เกิน 35% ของ HP สูงสุดของตนเอง) พร้อมรับความเสียหายแทนเป้าหมาย 30%\n#C0xF13B54#【แปลงร่างพันธุกรรม】#C0x5B545B#\nแปลงร่างเป็นภาพลักษณ์ของเป้าหมาย (ไม่รวมความสามารถของเป้าหมาย) เมื่อ HP ของร่างแปลงหมด เอฟเฟกต์จะสิ้นสุดก่อนเวลา หากไม่มีเป้าหมายให้แปลงร่าง จะฟื้นฟู HP ของตนเอง 15% ของ HP สูงสุด',
		zawakeEffect = __data_t__zawakeEffect[70822],
		-- {79002}
		zawakeEffectDesc = '#C0xC0C0C0#รูปแบบเปลี่ยนไป แต่แก่นแท้ยังคงเดิม#C0x5B545B#\nOrigin Mew โจมตีเป้าหมายเดี่ยวฝ่ายศัตรูแบบสุ่ม สร้างความเสียหาย#C0xF13B54#พิเศษ#C0x5B545B#เท่ากับ #C0x3D8A99#180% พลังโจมตีพิเศษ#C0x5B545B#+$(skillLevel*4*36)$ และ【Gene Mimicry】เลียนแบบรูปลักษณ์ของเพื่อนร่วมทีมสาย Psychic ที่มีพลังโจมตีสูงสุด 1 เทิร์น พร้อมรับ HP ปัจจุบันของเป้าหมาย 20% (ไม่เกิน 35% HP สูงสุดของ Origin Mew); แบกรับความเสียหายแทนเป้าหมาย 30%\n#C0xF13B54#【Gene Mimicry】#C0x5B545B#\nแปลงร่างเป็นยูนิตสาย Psychic เป้าหมาย (ไม่รับสกิลของเป้าหมาย), หาก HP ของร่างเลียนแบบหมดก่อน จะยุติการแปลง หากไม่มีเป้าหมายให้แปลง จะฟื้นฟู HP ตนเอง 15% ของ HP สูงสุด',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '#C0x5c9970#เพิ่มอัตราสร้างความเสียหายพื้นฐานเป็น 200%; มอบสถานะ【Stealth】ให้เพื่อนร่วมทีม 1 เทิร์น',
		upLvDesc = 'เพิ่มความเสียหายคงที่+144',
