	[70823] = {
		id = 70823,
		skillName = 'ท่าไม้ตาย',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#—ไม้หนึ่งต้น สะท้อนจิตวิญญาณแห่งทุกสรรพสิ่ง#C0x5B545B#\n\nOrigin Mew โจมตีศัตรูทั้งสนาม สร้างความเสียหายพิเศษ#C0x3D8A99#180%พลังพิเศษ#C0x5B545B#+$(skillLevel*4*48)$ของ#C0xF13B54#ความเสียหายพิเศษ#C0x5B545B# และใส่【ปั่นป่วนพันธุกรรม】 1 เทิร์น\n#C0xF13B54#【ปั่นป่วนพันธุกรรม】#C0x5B545B#\nแปลงร่างสายพลังจิต ทำให้เป้าหมายหลักกลายเป็นเซลล์ไข่เดี่ยว 2 เทิร์น เป้าหมายอื่นมีโอกาส 50% ที่จะกลายร่างเป็นโปเกมอนเริ่มต้นแบบสุ่มหลังทำการกระทำ\n#C0xF13B54#【เซลล์ไข่เดี่ยว】#C0x5B545B#\nแปลงร่างสายพลังจิต เป้าหมายยังสามารถกระทำได้ตามปกติ แต่จะถูกบังคับใช้สกิลเฉพาะ เมื่อเสีย HP สะสม 30% จะยกเลิกสถานะนี้\nสกิลเฉพาะของเซลล์ไข่เดี่ยว:\nการโจมตีปกติ: สร้างความเสียหาย 100% พลังพิเศษ\nสกิลรอง: สร้างความเสียหาย 150% พลังพิเศษ\nท่าไม้ตาย: สร้างความเสียหาย 300% พลังพิเศษ และฟื้นฟู 10% HP สูงสุดของตนเอง',
		starEffect = __data_t__starEffect[70823],
		-- {11}
		starEffectDesc = '\nเปลี่ยนศัตรู 1 ตัวให้กลายเป็น【Single-cell Orb】',
		zawakeEffect = __data_t__zawakeEffect[70823],
		-- {79003}
		zawakeEffectDesc = '#C0xC0C0C0#—ไม้ดอกหนึ่งกิ่ง ทุกสิ่งมีวิญญาณ#C0x5B545B#\n\nOrigin Mew โจมตีศัตรูทั้งหมด สร้างความเสียหาย#C0xF13B54#พิเศษ#C0x5B545B#เท่ากับ #C0x3D8A99#180% พลังโจมตีพิเศษ#C0x5B545B#+$(skillLevel*4*48)$ และใส่สถานะ【Gene Chaos】1 เทิร์น\n#C0xF13B54#【Gene Chaos】#C0x5B545B#\nแปลงร่างเป้าหมายหลักเป็น【Zygote】เป็นเวลา 2 เทิร์น เป้าหมายอื่นหลังจบเทิร์นมีโอกาส 50% ที่จะกลายร่างเป็นร่างแรกของโปเกมอนแบบสุ่ม\n#C0xF13B54#【Zygote】#C0x5B545B#\nแปลงร่างพิเศษแบบ Psychic เป้าหมายยังเคลื่อนไหวได้ แต่จะถูกบังคับใช้สกิลเฉพาะเท่านั้น ยกเลิกการแปลงเมื่อเสีย HP สะสมครบ 30% จาก HP สูงสุด\n- โจมตีธรรมดา: สร้างความเสียหาย 100% พลังพิเศษ\n- สกิลเล็ก: สร้างความเสียหาย 150% พลังพิเศษ\n- สกิลไม้ตาย: สร้างความเสียหาย 300% พลังพิเศษ และฟื้นฟู 10% HP สูงสุด',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '#C0x5c9970#เพิ่มอัตราสร้างความเสียหายพื้นฐานเป็น 200%: เมื่อใช้ท่าไม้ตายครั้งแรก หากยังไม่เปิดใช้งานเอฟเฟกต์【Endless Vitality】จะทำการ Resonance เพิ่มเติมกับเพื่อน Psychic 1 ตัวร่วมใช้สกิล; ครั้งนี้ท่าไม้ตายจะมีโอกาส 100% แปลงศัตรู 1 ตัวเป็น【Single-cell Sphere】',
		upLvDesc = 'เพิ่มความเสียหายคงที่+192',
