	[70912] = {
		id = 70912,
		skillName = 'สกิลพิเศษ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#เจ้าจะติดตามข้าตลอดไปไหม?#C0x5B545B#\n\nโจมตีศัตรูเดี่ยว สร้างความเสียหายพิเศษ#C0x3D8A99#160%พลังพิเศษ#C0x5B545B#+$(skillLevel*4*36)$ของ#C0xF13B54#ความเสียหายพิเศษ#C0x5B545B# ทำให้เป้าหมายติด【เสน่ห์】 1 เทิร์น\nเรียกอัศวินเข้าสู่สนาม 1 เทิร์น (ครั้งแรกอยู่ 2 เทิร์น รับพลังโจมตีกายภาพ 200%) เพื่อรับความเสียหาย, ดีบัฟ และควบคุมแทน พร้อมได้รับบัฟของสายต่อสู้ หากเรียกซ้ำ อัศวินจะฟื้น HP ตามพลังพิเศษ 300%\n\nอัศวินจะโจมตีร่วมกับผู้ใช้ สร้างความเสียหายกายภาพ#C0xE69900#160%พลังโจมตีกายภาพ#C0x5B545B#+$(skillLevel*4*24)$ของ#C0xF13B54#ความเสียหายกายภาพ#C0x5B545B# มอบ【เลือดไหล】 2 เทิร์น หากเป้าหมายมีสถานะ【เลือดไหล】 จะเปลี่ยนเป็น【ฉีกขาด】',
		zawakeEffect = __data_t__zawakeEffect[70912],
		-- {79002}
		zawakeEffectDesc = '#C0xC0C0C0#เธอจะติดตามฉันไปตลอดหรือเปล่านะ?#C0x5B545B#\n\nโจมตีเป้าหมายเดี่ยวฝ่ายศัตรู สร้างความเสียหาย#C0xF13B54#พิเศษ#C0x5B545B#เท่ากับ #C0x3D8A99#160% พลังโจมตีพิเศษ#C0x5B545B#+$(skillLevel*4*36)$ ใส่สถานะ【Charm】ให้เป้าหมาย 1 เทิร์น\nอัญเชิญ Knight ลงสนาม 1 เทิร์น (ครั้งแรกอยู่ 2 เทิร์น, รับพลังโจมตีกายภาพ 200%) แบกรับความเสียหาย ดีบัฟ และเอฟเฟกต์ควบคุมแทนตนเอง พร้อมรับบัฟสาย Fighting; เมื่ออัญเชิญซ้ำ Knight จะฟื้นฟู HP เท่ากับ 300% พลังพิเศษของผู้ใช้\n\nKnight จะโจมตีร่วมกับผู้ใช้ สร้างความเสียหาย#C0xF13B54#กายภาพ#C0x5B545B#เท่ากับ #C0xE69900#160% พลังกายภาพ#C0x5B545B#+$(skillLevel*4*24)$ ใส่สถานะ【Bleed】2 เทิร์น หากเป้าหมายติด【Bleed】อยู่แล้ว จะเปลี่ยนเป็น【Tear】',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '#C0x5c9970#เพิ่มอัตราสร้างความเสียหายพื้นฐานเป็น 200%, Knight จะสืบทอดค่าพลังจากผู้เรียก 150%; หากเรียกซ้ำจะฟื้นฟู HP เต็มและรีเซ็ตระยะเวลา',
