	[70916] = {
		id = 70916,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#ตอนนี้ พวกเขาทั้งหมดเป็นของข้าแล้ว~#C0x5B545B#\n\n#F20# \n#F40#【#L10#หมอกแห่งแฟรี่#L0#】เมื่อ Super Gardevoir (แบบส่องแสง) เข้าสู่สนาม ทีมจะได้รับสภาพอากาศ【หมอกแห่งแฟรี่】ในช่วงจัดทีม ทำให้โปเกมอนสายแฟรี่ทั้งฝ่ายเราและฝ่ายศัตรูไม่ติดสถานะควบคุมและฟื้นฟู HP 10% ทุกเทิร์น โปเกมอนสายมังกรทั้งสองฝ่ายสร้างความเสียหายลดลง 20% (สุ่มเปิดใช้งานแต่ละครั้งคงอยู่ 3 เทิร์น)\n\n#F40##L10#ราชินีแห่งหนาม#L0#: ศัตรูที่ไม่ใช่สายความงาม จะรับความเสียหายแทนผู้ใช้ 25% (ไม่สามารถกระจายต่อ) ลดความเสียหายจากศัตรูสายความงามลง 20% (ศัตรูอื่นลดเพิ่มอีก 10%)\nก่อนรอบใหญ่จะสุ่มวาง【กับดักหนาม】ใส่ศัตรู 1 ตัว และมีโอกาส 20% ทำให้ศัตรูติด【เสน่ห์】\n\n#F40##L10#สง่างามเย้ายวน#L0#: ขณะอยู่ในสนาม ตนเองและเพื่อนสายแฟรี่แต่ละคนจะเพิ่มโบนัสความเสียหายและลดความเสียหายที่ได้รับ 20% (เพิ่มสูงสุด 100%)\nเมื่อโปเกมอนสายความงามของเราถูกศัตรูสายอื่นโจมตี จะลดความเสียหายลง 30% และมีโอกาส 30% ทำให้ผู้โจมตีติด【เสน่ห์】 1 เทิร์น; เมื่อโจมตีศัตรูที่ติด【เสน่ห์】 จะทะลุป้องกันครึ่งหนึ่ง\nตนเองต้านทานผลของแรงโน้มถ่วง\n\n#F40##L10#เสน่ห์สะกดใจ#L0#: ขณะอยู่ในสนาม เอฟเฟกต์ควบคุมประเภท【เสน่ห์】ต้องล้าง 2 ครั้งถึงจะหาย หากใส่เสน่ห์ไม่สำเร็จ จะสร้างความเสียหายพิเศษเท่ากับ 300% พลังพิเศษของผู้ใช้ให้เป้าหมาย\nทุก ๆ 3 เทิร์น จะแชร์【เสน่ห์】ให้เพื่อนร่วมทีมสายพลังจิต/แฟรี่ 1 ตัว เป็นเวลา 1 เทิร์น เมื่อโจมตีเป้าหมายหลักจะมีโอกาสทำให้ติด【เสน่ห์】 1 เทิร์น\nตนเองและ Super Gallade (แบบส่องแสง) ต้านทาน【เสน่ห์】 และเพื่อนร่วมทีมสายความงามจะมีต้านทานเสน่ห์เพิ่มขึ้น 60%',
		starEffect = __data_t__starEffect[70916],
		-- {8}
		starEffectDesc = '\nทุกๆ 1 เทิร์น จะมี 1 เทิร์นที่การโจมตีของเป้าหมายมีโอกาส 65% ทำให้เป้าหมายหลักติด【Charm】 (ถ้าติดอยู่แล้วจะต่อเวลาขึ้นอีก 1 เทิร์น)\nเมื่อ HP ของตัวเองต่ำกว่า 45% ครั้งแรก จะอัญเชิญ【Knight】เข้าสนามเป็นเวลา 2 เทิร์น',
		zawakeEffect = __data_t__zawakeEffect[70916],
		-- {79004}
		zawakeEffectDesc = '#C0xC0C0C0#ตอนนี้พวกเขาเป็นของฉันแล้ว~#C0x5B545B#\n\n#F20# \n#F40#【#L10#Fairy Mist#L0#】เมื่อ Shiny Mega Gardevoir เข้าสนาม ทีมจะได้รับสภาพอากาศ【Fairy Mist】ในช่วงจัดทีม ทำให้ Pokémon สาย Fairy ของทั้งสองฝ่ายต้านทานการควบคุมทั้งหมดและฟื้นฟู HP 10% ทุกเทิร์น; Pokémon สาย Dragon ทั้งสองฝ่ายจะสร้างความเสียหายลดลง 20% (แต่ละรอบจะสุ่มเปิดใช้ 1 ครั้ง และคงอยู่ 3 เทิร์น)\n#F40##L10#Queen of Thorns#L0#: ศัตรูที่ไม่ใช่สาย Beautiful จะรับความเสียหายแทนตนเอง 25% (ไม่สามารถแบ่งต่อ) และลดความเสียหายที่ได้รับจากสาย Beautiful ลง 20% (สายอื่นลดเพิ่มอีก 10%)\nก่อนเริ่มรอบใหญ่ จะวาง【Thorn Trap】ใส่ศัตรูแบบสุ่ม 1 ตัว และมีโอกาส 20% ใส่สถานะ【Charm】ศัตรูแบบสุ่ม 1 ตัว\n#F40##L10#Elegant Aura#L0#: ขณะอยู่ในสนาม ตนเองและเพื่อนร่วมทีมสาย Fairy จะได้รับ Damage Bonus +20% และ Damage Reduction +20% (เพิ่มได้อีก +20% ต่อจำนวนเพื่อนสาย Fairy สูงสุด 100%)\nเมื่อเพื่อนสาย Beautiful ถูกศัตรูต่างสายโจมตีแบบแอคทีฟ จะลดความเสียหายที่ได้รับ 30% และมีโอกาส 30% ใส่สถานะ【Charm】ให้ผู้โจมตี 1 เทิร์น; เมื่อตนเองโจมตีเป้าหมายที่ติด【Charm】 จะไม่สนค่าป้องกันครึ่งหนึ่ง\nตนเองต้านทานผลของสกิลประเภท Gravity\n#F40##L10#Alluring Grace#L0#: ขณะอยู่ในสนาม สถานะควบคุมประเภท【Charm】ต้องล้าง 2 ครั้งจึงจะหาย; หากใส่【Charm】ไม่สำเร็จ จะสร้างความเสียหายพิเศษเท่ากับ 300% พลังพิเศษของผู้ใช้ให้เป้าหมาย\nทุก 3 เทิร์น จะมอบความสามารถ【Charm】ให้เพื่อนร่วมทีมสาย Psychic/Fairy 1 ตัว เป็นเวลา 1 เทิร์น; การโจมตีจะสามารถใส่สถานะ【Charm】ให้เป้าหมายหลัก 1 เทิร์น\nตนเองและ Shiny Mega Gallade ต้านทานสถานะ【Charm】; เพื่อนร่วมทีมสาย Beautiful เพิ่มโอกาสต้าน Charm 60%',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '#C0x5c9970#เมื่อฝ่ายเราสะสมการทำให้ศัตรูติด【Charm】ครบ 6 ครั้ง จะใช้ท่าไม้ตายทันที 1 ครั้ง (จำกัด 1 ครั้งต่อเกม); เมื่ออยู่ร่วมสนามกับ Shiny Mega Gallade จะได้รับ【First Strike I】 1 ครั้งทุกเทิร์น และ Knight ที่เรียกออกมาจะเพิ่มค่าสถานะอีก 50%',
