	[71012] = {
		id = 71012,
		skillName = 'สกิลพิเศษ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#ไม่มีอะไรทะลวงการป้องกันของข้าได้#C0x5B545B#\nZamazenta ใช้ร่างกายดั่งโล่พุ่งชนศัตรูเดี่ยว สร้างความเสียหายกายภาพ#C0xE69900#180%พลังโจมตีกายภาพ#C0x5B545B#+$(skillLevel*4*48)$ของ#C0xF13B54#ความเสียหายกายภาพ#C0x5B545B#\nเสีย HP ปัจจุบันของตนเอง 6% แนวเดียวกันจะได้รับ【โล่พลังภายใน】เท่ากับ 20% ของ (HP สูงสุด + HP ที่เสียไป) ของ Zamazenta ภายใน 5 เทิร์นถัดไป เพื่อนร่วมทีมที่อยู่ด้านหลังจะได้รับความเสียหายทางตรงและทะลุเกราะลดลง 40% และเมื่อตนเองกระตุ้นการป้องกัน จะต้านทานเอฟเฟกต์ควบคุมของสกิลได้',
		simDesc = 'Zamazenta พุ่งทะยานขึ้นฟ้า ปลดปล่อยแสงเจิดจ้าโจมตีศัตรูเดี่ยว และลด Special Defense ของแนวหน้าศัตรู',
		zawakeEffect = __data_t__zawakeEffect[71012],
		-- {79002}
		zawakeEffectDesc = '#C0xC0C0C0#ไม่มีอะไรทะลวงการป้องกันของข้าได้#C0x5B545B#\nZamazenta พุ่งชนศัตรูเป้าหมายเดี่ยวด้วยร่างอันแข็งแกร่งประดุจโล่ สร้างความเสียหาย#C0xE69900#180% Physical Attack#C0x5B545B#+$(skillLevel*4*48)$ เป็น#C0xF13B54#Physical Damage#C0x5B545B#\nสูญเสีย HP ปัจจุบัน 6% ให้แนวหน้ารับ【Qi Shield】จาก Zamazenta เท่ากับ 20% (Max HP + HP ที่เสียไป) เป็นเวลา 5 เทิร์น ในช่วงนี้ เพื่อนร่วมทีมแนวหลังได้รับความเสียหายตรงและทะลุเกราะลดลง 40% และเมื่อตัวเอง Trigger การต้านทาน จะป้องกันเอฟเฟกต์ควบคุมจากสกิลได้',
		zawakeSimpleType = 2,
