	[71013] = {
		id = 71013,
		skillName = 'ท่าไม้ตาย',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#ข้าจะรับการโจมตีทั้งหมดของเจ้าเอง#C0x5B545B#\nZamazenta พุ่งเข้าใส่เป้าหมายศัตรูเดี่ยวด้วยพลังดั่งภูเขาถล่ม สร้างความเสียหายกายภาพ#C0xE69900#400%พลังโจมตีกายภาพ#C0x5B545B#+$(skillLevel*4*48)$ของ#C0xF13B54#ความเสียหายกายภาพ#C0x5B545B#\nใส่สถานะ【จ้องตาข่มขวัญ】ให้เป้าหมาย 2 เทิร์น\nให้เพื่อนร่วมทีมทั้งหมดได้รับ【โล่พลังภายใน】เท่ากับ 30% ของ (HP สูงสุด + HP ที่เสียไป) ของ Zamazenta (สายต่อสู้ได้คูณ 2) เชิญเพื่อนร่วมทีมที่มีพลังโจมตีสูงสุด 2 คน (เลือกสายต่อสู้ก่อน) ให้โจมตีปกติ และสร้างโล่จาก HP ที่เสียไปให้ตนเอง พร้อมแน่นอนว่าจะต้านการโจมตีครั้งถัดไป\n【จ้องตาข่มขวัญ】: เอฟเฟกต์ควบคุม ไม่สามารถล้างได้ เป้าหมายสามารถเลือกโจมตีได้แค่ Zamazenta และผลของการโจมตีจะไม่ส่งผลกับเพื่อนร่วมทีมอื่น\n【โทสะแห่งนักสู้】: ก่อนเริ่มเทิร์น หากโทสะมากกว่า 500 แต่ยังไม่เต็ม จะเสีย HP ปัจจุบัน 10% เพื่อเติมโทสะให้เต็ม',
		simDesc = 'Zamazenta โจมตีเป้าหมายศัตรูเดี่ยวอย่างรุนแรง มอบสถานะ【Fierce Gaze】แก่ศัตรู และให้ตนเอง【Chi Barrier】พร้อมชวนเพื่อนร่วมทีมเข้าร่วมโจมตีปกติ',
		starEffect = __data_t__starEffect[71013],
		-- {11}
		starEffectDesc = 'ขยายระยะการโจมตีไปยังแถวหน้าของศัตรู และสร้างความเสียหายจริงตาม HP ที่สูญเสียของตนเอง  \nเมื่อ HP ลดลงต่ำกว่า 50% ครั้งแรก จะทำให้ Shield ที่ได้จากท่าไม้ตายของตนเองและเพื่อนร่วมทีมเพิ่มขึ้น 100%',
		zawakeEffect = __data_t__zawakeEffect[71013],
		-- {79003}
		zawakeEffectDesc = '#C0xC0C0C0#ข้าจะรับการโจมตีทั้งหมดของเจ้าเอง#C0x5B545B#\nZamazenta พุ่งใส่ศัตรูเป้าหมายเดี่ยวราวกับภูเขาทลาย สร้างความเสียหาย#C0xE69900#400% Physical Attack#C0x5B545B#+$(skillLevel*4*48)$ เป็น#C0xF13B54#Physical Damage#C0x5B545B#\nทำให้เป้าหมายติด【Fierce Gaze】เป็นเวลา 2 เทิร์น\nให้เพื่อนร่วมทีมทั้งหมดได้รับ【Qi Shield】จาก Zamazenta เท่ากับ 30% (Max HP + HP ที่เสียไป) (เพิ่มเป็น 2 เท่าสำหรับเพื่อนร่วมทีมสาย Fighting) เชิญชวนเพื่อนร่วมทีมที่มี ATK สูงสุด 2 คน (ให้ความสำคัญกับสาย Fighting) โจมตีปกติพร้อมเสริม【Qi Shield】เท่ากับ HP ที่เสียไปให้ตนเอง การโจมตีครั้งต่อไปของตนจะต้านทานได้แน่นอน\n【Fierce Gaze】: เอฟเฟกต์ควบคุม ไม่สามารถลบได้ เป้าหมายที่ติดจะสามารถเลือกโจมตีได้เพียง Zamazenta เท่านั้น และดาเมจรวมถึงเอฟเฟกต์เสริมจะไม่ส่งผลกับเพื่อนร่วมทีมคนอื่น\nBattle Fury: ก่อนเริ่มเทิร์น หากพลังโกรธมากกว่า 500 แต่ไม่เต็ม จะเสีย HP ปัจจุบัน 10% เพื่อทำให้พลังโกรธเต็มทันที',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '#C0x5c9970#เพิ่มอัตราสร้างความเสียหายพื้นฐานเป็น 450%: เมื่อ HP ต่ำกว่า 50% การใช้ท่าไม้ตายจะได้รับปริมาณโล่เพิ่มอีก 25%; ได้รับ【Shield Counter】2 ครั้ง',
		upLvDesc = 'เพิ่มความเสียหายคงที่+192',
