	[71033] = {
		id = 71033,
		skillName = 'ท่าไม้ตาย',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#ข้าจะรับการโจมตีทั้งหมดของเจ้าเอง#C0x5B545B#\nZamazenta พุ่งเข้าใส่เป้าหมายศัตรูเดี่ยวด้วยพลังดั่งภูเขาถล่ม สร้างความเสียหายกายภาพ#C0xE69900#400%พลังโจมตีกายภาพ#C0x5B545B#+$(skillLevel*4*48)$ของ#C0xF13B54#ความเสียหายกายภาพ#C0x5B545B#\nมอบสถานะ【จ้องตาข่มขวัญ】ให้เป้าหมาย 2 เทิร์น\nให้เพื่อนร่วมทีมทุกคนได้รับ【โล่พลังภายใน】เท่ากับ 30% ของ (HP สูงสุด + HP ที่สูญเสียไป) ของ Zamazenta (สายต่อสู้ได้รับคูณ 2) เชิญเพื่อนร่วมทีมที่มีพลังโจมตีสูงสุด 2 คน (เน้นเลือกสายต่อสู้ก่อน) ใช้การโจมตีปกติ พร้อมกับให้ตนเองได้รับโล่ตาม HP ที่เสียไป และได้รับ【โล่พลังภายใน】 1 ชั้น การโจมตีถัดไปจะต้านทานได้แน่นอน\n【จ้องตาข่มขวัญ】: เอฟเฟกต์ควบคุม ไม่สามารถล้าง เป้าหมายสามารถโจมตีได้แค่ Zamazenta เท่านั้น และสกิลหรือเอฟเฟกต์อื่นจะไม่ส่งผลต่อเพื่อนร่วมทีมของ Zamazenta\n【โทสะแห่งนักสู้】: ก่อนเริ่มเทิร์น หากโทสะมากกว่า 500 แต่ยังไม่เต็ม จะเสีย HP ปัจจุบัน 10% เพื่อเติมโทสะให้เต็ม',
		simDesc = 'Zamazenta โจมตีเป้าหมายศัตรูเดี่ยวอย่างรุนแรง มอบสถานะ【Fierce Gaze】แก่ศัตรู และให้ตนเอง【Chi Barrier】พร้อมชวนเพื่อนร่วมทีมเข้าร่วมโจมตีปกติ',
		starEffect = __data_t__starEffect[71033],
