	[71126] = {
		id = 71126,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#ดอกไม้จะเบ่งบาน ณ ที่ที่เลือดไหลริน#C0x5B545B#\n#F20#\n#F40##L10#อัศวินโลหิต#L0#: เมื่อผู้ใช้โจมตี จะทำให้เป้าหมายติด【เลือดไหล】 1 ชั้น หากมีพลังต่อสู้มากกว่า 500 จะมอบ【ฉีกขาด】เพิ่มเติมอีก 1 ชั้น\nขณะมีพลังต่อสู้ จะเพิ่มความเสียหายและลดความเสียหายที่ได้รับขึ้น 15%\nผู้ใช้และ Super Gardevoir (ส่องแสง) จะต้านทาน【เลือดไหล】และ【ฉีกขาด】\n#F40##L10#พลังต่อสู้ล้นเหลือ#L0#: โทสะที่ได้รับทั้งหมดจะถูกแปลงเป็นพลังต่อสู้ 1.2 เท่า\nขณะมีพลังต่อสู้ จะเพิ่มอัตราป้องกัน 30% และความแข็งแกร่งของการป้องกัน 20% (หากพลังต่อสู้มากกว่า 500 เอฟเฟกต์จะเพิ่มเป็น 2 เท่า)\n#C0xF13B54#【เลือดไหล】#C0x5B545B#\nดีบัฟระดับ 1 เมื่อเป้าหมายเคลื่อนที่หรือกระทำ จะได้รับความเสียหายจริงจากผู้ใช้ 40% ของพลังพิเศษ/กายภาพ สะสมได้สูงสุด 3 ชั้น\n#C0xF13B54#【ฉีกขาด】#C0x5B545B#\nดีบัฟระดับ 1 เป้าหมายไม่สามารถฟื้น HP ก่อนโจมตีจะได้รับความเสียหายจริงจากผู้ใช้ 50% ของพลังโจมตีกายภาพ สะสมได้สูงสุด 3 ชั้น\n#C0xF13B54#【โจมตีก่อน I】#C0x5B545B#\nบัฟระดับ 1 ก่อนถูกโจมตี จะโจมตีฝ่ายตรงข้ามด้วยการโจมตีปกติ 1 ครั้ง\n#C0xF13B54#【โจมตีก่อน II】#C0x5B545B#\nบัฟระดับ 2 ก่อนถูกโจมตี จะโจมตีฝ่ายตรงข้ามด้วยการโจมตีปกติ 2 ครั้ง ลำดับก่อนกว่าโจมตีก่อน I\n#C0xF13B54#【เดิมพันชีวิต】#C0x5B545B#\nร่างเฉพาะ ระหว่างสถานะนี้จะเพิ่มพลังโจมตีกายภาพและความเสียหายจากการโจมตีปกติ 30% HP จะไม่ต่ำกว่า 1 เมื่อสถานะสิ้นสุด หาก HP ของตนเองยังเหลือเกิน 35% จะเสีย HP สูงสุดครึ่งหนึ่ง แล้วฟื้น HP เต็ม',
		starEffect = __data_t__starEffect[71126],
		-- {8}
		starEffectDesc = '\n#F40##L10#Seize the Initiative#L0#:\nก่อนจะโดนโจมตี จะใช้【First Strike I】ก่อน 1 ครั้ง (สูงสุด 2 ครั้งต่อรอบใหญ่)\nเมื่อ Qi สูงกว่า 500 จะได้รับ【First Strike I】เพิ่มอีก 1 ครั้ง\n#F40##L10#Desperate Struggle#L0#:\nเมื่อได้รับความเสียหายถึงตายครั้งแรก จะเหลือ 1 HP และได้ Qi เต็ม จากนั้นเข้าสู่สถานะ【Struggle】เป็นเวลา 2 เทิร์น',
		zawakeEffect = __data_t__zawakeEffect[71126],
		-- {79004, 1}
		zawakeEffectDesc = '\n#F40##L10#Strike First#L0#:\nก่อนจะถูกโจมตี จะทำการโจมตีด้วย【First Strike I】1 ครั้ง (จำกัดสูงสุด 2 ครั้งต่อเทิร์นใหญ่)\nเมื่อ Qi มากกว่า 500 จะได้รับ【First Strike I】เพิ่มอีก 1 ครั้ง\n#F40##L10#Desperate Fight#L0#:\nเมื่อได้รับความเสียหายถึงตายเป็นครั้งแรก จะเหลือ 1 HP ได้รับ Qi เต็ม และเข้าสู่สถานะ【Desperation】เป็นเวลา 2 เทิร์น',
		zawakeSimpleType = 2,
