	[71212] = {
		id = 71212,
		skillName = 'สกิลพิเศษ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#เธอจะติดตามฉันตลอดไปไหม?#C0x5B545B#\n\nโจมตีเป้าหมายศัตรูเดี่ยว สร้างความเสียหายพิเศษ#C0x3D8A99#160%พลังพิเศษ#C0x5B545B#+$(skillLevel*4*36)$ของ#C0xF13B54#ความเสียหายพิเศษ#C0x5B545B# ทำให้เป้าหมายติด【เสน่ห์】 1 เทิร์น\nเรียกอัศวินเข้าสู่สนาม 1 เทิร์น (ครั้งแรกอยู่ 2 เทิร์น, สืบทอดพลังโจมตีกายภาพ 200%) อัศวินจะรับความเสียหาย ผลลบ และสถานะควบคุมแทน พร้อมได้รับบัฟของสายต่อสู้ หากเรียกซ้ำ อัศวินจะฟื้นฟู HP เท่ากับ 300% ของพลังพิเศษของผู้ใช้\n\nอัศวินโจมตีร่วมกับผู้ใช้ สร้างความเสียหายกายภาพ#C0xE69900#160%พลังโจมตีกายภาพ#C0x5B545B#+$(skillLevel*4*24)$ของ#C0xF13B54#ความเสียหายกายภาพ#C0x5B545B# มอบ【เลือดไหล】 2 เทิร์น หากเป้าหมายมีสถานะ【เลือดไหล】จะเปลี่ยนเป็น【ฉีกขาด】',
		zawakeEffect = __data_t__zawakeEffect[71212],
		-- {79002}
		zawakeEffectDesc = '#C0xC0C0C0#เจ้าจะติดตามข้าไปตลอดหรือไม่?#C0x5B545B#\n\nโจมตีเป้าหมายเดี่ยวของศัตรู สร้างความเสียหาย#C0x3D8A99#160% Sp.Atk#C0x5B545B#+$(skillLevel*4*36)$ เป็น#C0xF13B54#Special Damage#C0x5B545B# ทำให้เป้าหมายติด【Charm】1 เทิร์น\nอัญเชิญ Knight เข้าสนาม 1 เทิร์น (ครั้งแรก 2 เทิร์น, รับสืบทอด 200% ATK) เพื่อแบกรับความเสียหาย, ดีบัฟ และคอนโทรลแทน และได้รับโบนัสสาย Fighting การอัญเชิญซ้ำ Knight จะฟื้น HP ตาม 300% Sp.Atk ของผู้ร่าย\n\nKnight ร่วมโจมตีกับตนเอง สร้างความเสียหาย#C0xE69900#160% ATK#C0x5B545B#+$(skillLevel*4*24)$ เป็น#C0xF13B54#Physical Damage#C0x5B545B# ติด【Bleed】2 เทิร์น หากเป้าหมายมี【Bleed】อยู่แล้วจะเปลี่ยนเป็น【Rend】',
