	[71213] = {
		id = 71213,
		skillName = 'ท่าไม้ตาย',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#ใครกันแน่ที่กล้าหาญที่สุด?#C0x5B545B#\n\nโจมตีศัตรูแบบสุ่ม 2 ตัว (จะเลือกเป้าหมายที่ไม่ใช่ประเภทความงามก่อน) สร้างความเสียหายพิเศษ#C0x3D8A99#300%พลังพิเศษ#C0x5B545B#+$(skillLevel*4*48)$ของ#C0xF13B54#ความเสียหายพิเศษ#C0x5B545B# (หากมีเป้าหมายเดียว ความเสียหายจะเพิ่มเป็น 2 เท่า) ทำให้ทั้งสองติด【แย่งความรัก】 1 รอบ และ【เสน่ห์】 1 เทิร์น (ครั้งแรก 2 เทิร์น)\n\n【แย่งความรัก】: เป้าหมายจะใช้การโจมตีปกติต่อกันเอง ระหว่างนั้นความเสียหายที่สร้างจะเพิ่มขึ้น 300% ผู้ที่เสีย HP มากกว่า (หรือพ่ายแพ้) ถือว่าแพ้ หากรอด จะได้รับดีบัฟลดพลังป้องกัน 30% เป็นเวลา 2 เทิร์น หากอัศวินอยู่ในสนาม จะโจมตีเป้าหมายทันที สร้างความเสียหายกายภาพ#C0xE69900#600%พลังโจมตีกายภาพ#C0x5B545B#+$(skillLevel*4*24)$ของ#C0xF13B54#ความเสียหายกายภาพ#C0x5B545B#',
		simDesc = '#C0xC0C0C0#ใครจะกล้าหาญกว่ากัน?#C0x5B545B#\n\nโจมตีศัตรูแบบสุ่ม 2 ตัว (ให้ความสำคัญกับเป้าหมายที่ไม่ใช่ Pokémon สายสวยงาม) สร้างความเสียหาย',
		starEffect = __data_t__starEffect[71213],
		-- {11}
		starEffectDesc = '\nก่อนใช้ท่าไม้ตายจะได้รับ【Anti-Control Weakening Aura II】เป็นเวลา 2 เทิร์น\nและติดตั้ง【Thorn Trap】ไว้ที่เป้าหมาย',
		zawakeEffect = __data_t__zawakeEffect[71213],
		-- {79003}
		zawakeEffectDesc = '#C0xC0C0C0#ใครกันแน่ที่กล้าหาญกว่ากัน?#C0x5B545B#\n\nสุ่มโจมตีเป้าหมายศัตรู 2 ตัว (เลือกที่ไม่ใช่สาย Beauty ก่อน) สร้างความเสียหาย#C0x3D8A99#300% Sp.Atk#C0x5B545B#+$(skillLevel*4*48)$ เป็น#C0xF13B54#Special Damage#C0x5B545B# (หากโจมตีได้แค่ 1 เป้าหมาย ความเสียหายจะเพิ่มเป็น 2 เท่า) ทำให้ทั้งคู่ติด【Compete for Favor】1 เทิร์น และ【Charm】 1 เทิร์น (ครั้งแรก 2 เทิร์น)\n\n【Compete for Favor】: เป้าหมายจะโจมตีใส่กันด้วยการโจมตีปกติ ขณะนั้นความเสียหายเพิ่มขึ้น 300% ใครเสีย HP มาก (หรือแพ้) จะถือว่าเป็นฝ่ายพ่าย หากรอดชีวิต จะโดนลดพลังป้องกัน 30% นาน 2 เทิร์น หาก Knight อยู่ในสนาม จะโจมตีเป้าหมายทันที สร้างความเสียหาย#C0xE69900#600% ATK#C0x5B545B#+$(skillLevel*4*24)$ เป็น#C0xF13B54#Physical Damage#C0x5B545B#',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '#C0x5c9970#เพิ่มอัตราสร้างความเสียหายพื้นฐานเป็น 330% หากฝ่ายแพ้ในการ【Compete for Favor】ยังไม่ตาย Knight และ Shiny Gallade จะโจมตีเพิ่มเติมเป้าหมายด้วย 300% Atk และการโจมตีปกติอย่างละ 1 ครั้ง (จำกัดเพียง 2 ครั้งแรก); ฝ่ายชนะจะถูกควบคุม 1 เทิร์นโดย Shiny Mega Gardevoir',
		upLvDesc = 'เพิ่มความเสียหายคงที่+192',
