	[71216] = {
		id = 71216,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#ตอนนี้พวกเขาเป็นของฉันแล้ว~#C0x5B545B#\n\n#F20# \n#F40#【#L10#หมอกแห่งแฟรี่#L0#】เมื่อ Super Gardevoir (รูปแบบส่องแสง) เข้าสู่สนาม ทีมจะได้รับสภาพอากาศ【หมอกแห่งแฟรี่】ในช่วงจัดตำแหน่ง ทำให้โปเกมอนสายแฟรี่ทั้งฝ่ายเราและศัตรูต้านสถานะควบคุมทั้งหมด และฟื้นฟู HP 10% ทุกเทิร์น ส่วนโปเกมอนสายมังกรทั้งสองฝ่ายจะสร้างความเสียหายลดลง 20% (สุ่มเปิดในแต่ละเทิร์น และคงอยู่ 3 เทิร์น)\n\n#F40##L10#ราชินีแห่งหนาม#L0#: ศัตรูที่ไม่ใช่ประเภทความงามจะรับความเสียหายแทนผู้ใช้ 25% (ไม่สามารถส่งต่อได้) ลดความเสียหายจากศัตรูประเภทความงามลง 20% (ศัตรูประเภทอื่นลดเพิ่มอีก 10%)\nก่อนเริ่มรอบใหญ่ สุ่มวาง【กับดักหนาม】ใส่ศัตรู 1 ตัว และมีโอกาส 20% ทำให้ศัตรู 1 ตัวติด【เสน่ห์】\n\n#F40##L10#สง่างามเย้ายวน#L0#: ขณะอยู่ในสนาม ตนเองและเพื่อนร่วมทีมสายแฟรี่แต่ละตัวจะได้รับโบนัสความเสียหายเพิ่ม 20% และลดความเสียหายที่ได้รับ 20% (สูงสุด 100% ตามจำนวนสายแฟรี่)\nเมื่อโปเกมอนความงามฝ่ายเราถูกโจมตีโดยศัตรูต่างประเภท จะลดความเสียหายลง 30% และมีโอกาส 30% ทำให้ผู้โจมตีติด【เสน่ห์】 1 เทิร์น; โจมตีเป้าหมายที่ติด【เสน่ห์】จะทะลุป้องกันครึ่งหนึ่ง\nตนเองต้านทานผลจากแรงโน้มถ่วง\n\n#F40##L10#เสน่ห์สะกดใจ#L0#: ขณะอยู่ในสนาม เอฟเฟกต์ควบคุมประเภท【เสน่ห์】ต้องล้าง 2 ครั้งจึงจะหาย หากล้มเหลวจะสร้างความเสียหายพิเศษ 300% พลังพิเศษแก่เป้าหมาย\nทุก 3 เทิร์น จะแชร์ความสามารถ【เสน่ห์】ให้เพื่อนร่วมทีมสายจิต/แฟรี่ 1 ตัว เป็นเวลา 1 เทิร์น เมื่อโจมตีจะมีโอกาสทำให้เป้าหมายหลักติด【เสน่ห์】 1 เทิร์น\nตนเองและ Super Gallade (รูปแบบส่องแสง) ต้านทานเสน่ห์ และเพื่อนร่วมทีมความงามได้รับต้านทานเสน่ห์เพิ่ม 60%',
		starEffect = __data_t__starEffect[71216],
		-- {8}
		starEffectDesc = '\nทุกๆ 1 เทิร์น จะมี 1 เทิร์นที่การโจมตีของเป้าหมายมีโอกาส 65% ทำให้เป้าหมายหลักติด【Charm】 (ถ้าติดอยู่แล้วจะต่อเวลาขึ้นอีก 1 เทิร์น)\nเมื่อ HP ของตัวเองต่ำกว่า 45% ครั้งแรก จะอัญเชิญ【Knight】เข้าสนามเป็นเวลา 2 เทิร์น',
		zawakeEffect = __data_t__zawakeEffect[71216],
		-- {79004}
		zawakeEffectDesc = '#C0xC0C0C0#ตอนนี้พวกเขาเป็นของข้าแล้ว~#C0x5B545B#\n\n#F20# \n#F40#【#L10#Fairy Mist#L0#】เมื่อ Shiny Mega Gardevoir เข้าสนาม ทีมจะได้รับสภาพอากาศ【Fairy Mist】ในช่วงจัดตำแหน่ง ทำให้ Pokémon สาย Fairy ทั้งสองฝ่ายไม่ติดสถานะควบคุม และฟื้น HP 10% ทุกเทิร์น ในขณะเดียวกัน Pokémon สาย Dragon ทั้งสองฝ่ายจะได้รับความเสียหายลดลง 20% (สุ่มเปิดทุกเทิร์น มีผลต่อเนื่อง 3 เทิร์นต่อครั้ง)\n\n#F40##L10#Queen of Thorns#L0#: ศัตรูที่ไม่ใช่สาย Beauty จะช่วยรับ 25% ความเสียหายแทนตนเอง (แต่ไม่สามารถกระจายความเสียหายนี้ต่อได้) ลดความเสียหายจากศัตรูสาย Beauty 20% (ศัตรูสายอื่นลดเพิ่มอีก 10%)\nก่อนเทิร์นใหญ่จะวาง【Thorn Trap】บนศัตรูแบบสุ่ม 1 ตัว และมีโอกาส 20% ที่จะ【Charm】ศัตรู 1 ตัว\n\n#F40##L10#Elegant Grace#L0#: ขณะอยู่ในสนาม ตนเองและ Pokémon สาย Fairy ทุกตัวจะได้รับโบนัสเพิ่มความเสียหาย 20% และลดความเสียหาย 20% (เพิ่มอีก 20% ต่อ Pokémon Fairy ที่เพิ่มขึ้น สูงสุด 100%)\nPokémon สาย Beauty ฝ่ายเราจะได้รับความเสียหายลดลง 30% จากการโจมตีแบบ Active ของศัตรูสายอื่น และมีโอกาส 30% ที่จะ【Charm】ผู้โจมตี 1 เทิร์น; เมื่อโจมตีเป้าหมายที่ติด【Charm】จะไม่สนใจครึ่งหนึ่งของพลังป้องกัน\nตนเองไม่ติดผลจากแรงโน้มถ่วง\n\n#F40##L10#Charm Allure#L0#: ขณะอยู่ในสนาม เอฟเฟกต์ควบคุมแบบ【Charm】ต้องใช้ 2 ครั้งในการลบออก หากการเพิ่มสถานะ【Charm】ล้มเหลว จะสร้างความเสียหายพิเศษเท่ากับ 300% Sp.Atk ของผู้ร่ายให้กับเป้าหมาย\nทุก 3 เทิร์น จะส่งต่อความสามารถ【Charm】ให้กับเพื่อนร่วมทีมสาย Psychic/Fairy 1 ตัว เป็นเวลา 1 เทิร์น การโจมตีจะทำให้เป้าหมายหลักติด【Charm】1 เทิร์น\nตนเองและ Shiny Mega Gallade จะไม่ติด【Charm】เพื่อนร่วมทีมสาย Beauty จะเพิ่มค่าต้านทาน【Charm】ขึ้น 60%',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '#C0x5c9970#เมื่อฝ่ายเราสะสมการทำให้ศัตรูติด【Charm】ครบ 6 ครั้ง จะใช้ท่าไม้ตายทันที 1 ครั้ง (จำกัดทั้งสนามได้เพียง 1 ครั้ง); เมื่ออยู่ร่วมสนามกับ Shiny Mega Gallade จะได้รับ【First Strike I】 1 ครั้งในทุกเทิร์น และ Knight ที่เรียกออกมาจะเพิ่มค่าสถานะ 50%',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		changeUnitTrigger = true,
