	[71311] = {
		id = 71311,
		skillName = 'สกิลทั่วไป',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#มาเถอะ~ เข้ามาใกล้อีกนิด ฉันรู้ว่าเธอคิดอะไรอยู่#C0x5B545B#\n\nโจมตีเป้าหมายศัตรูเดี่ยว สร้างความเสียหายพิเศษ#C0x3D8A99#100%พลังพิเศษ#C0x5B545B#+$(skillLevel*4*24)$ของ#C0xF13B54#ความเสียหายพิเศษ#C0x5B545B# วาง【กับดักหนาม】ใส่เป้าหมาย และเพิ่มพลังพิเศษของตนเอง 20% เป็นเวลา 2 เทิร์น\n【กับดักหนาม】: สะสมได้ 2 ครั้ง จะถูกกระตุ้นก่อนการกระทำของเป้าหมาย สร้างความเสียหายจากกับดักตามพลังพิเศษของผู้ใช้ 150% หลังจากถูกกระตุ้นจะมอบ 1 ชั้นของ【เลือดไหล】ให้เป้าหมาย เป็นเวลา 2 เทิร์น',
		zawakeEffect = __data_t__zawakeEffect[71311],
		-- {79001}
		zawakeEffectDesc = '#C0xC0C0C0#มาสิ~เข้ามาใกล้อีกนิด ข้ารู้ว่าเจ้าคิดอะไรอยู่#C0x5B545B#\n\nโจมตีเป้าหมายเดี่ยวของศัตรู สร้างความเสียหาย#C0x3D8A99#100% Sp.Atk#C0x5B545B#+$(skillLevel*4*24)$ เป็น#C0xF13B54#Special Damage#C0x5B545B# วาง【Thorn Trap】บนเป้าหมาย และเพิ่ม Sp.Atk ตนเอง 20% นาน 2 เทิร์น\n【Thorn Trap】: ซ้อนทับ 2 ครั้ง จะทำงานก่อนเป้าหมายเคลื่อนไหว สร้างความเสียหายกับเป้าหมาย 150% Sp.Atk ของผู้วาง และติด【Bleed】1 ชั้น นาน 2 เทิร์น',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '#C0x5c9970#เพิ่มอัตราสร้างความเสียหายพื้นฐานเป็น 120% และใส่【Thorn Trap】ให้เป้าหมาย 1 ชิ้น',
		upLvDesc = 'เพิ่มความเสียหายคงที่+96',
