	[90413] = {
		id = 90413,
		skillName = 'ท่าไม้ตาย',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#ไม่เป็นไร...แค่ลูกปลอดภัยพ่อก็พอใจแล้ว#C0x5B545B#\n①โจมตีศัตรูเดี่ยว สร้างความเสียหาย#C0xE69900#380%พลังโจมตีกายภาพ#C0x5B545B#+$(skillLevel*4*48)$ของ#C0xF13B54#ความเสียหายกายภาพ#C0x5B545B# พร้อมใช้【เถาวัลย์แห่งชีวิต】เชื่อมโยงเพื่อนร่วมทีม 1 เทิร์น\n②ตนเองฟื้น HP 5% ของ HP สูงสุด\n③และใช้【เถาวัลย์แส้】กระตุ้นเพื่อนร่วมทีมสายพืช/มืด 1 เทิร์น\n#C0xF13B54#【เถาวัลย์แห่งชีวิต】#C0x5B545B#\nบัฟระดับ 3 เมื่อผู้ใช้ฟื้นฟู HP จะกระจายไปยังเพื่อนร่วมทีมที่เชื่อมด้วยเถาวัลย์; หากเป็นสายพืชจะได้รับเพิ่ม 15% หากเป็นสายมืด เมื่อโจมตีจะดูดเลือดเป้าหมายหลัก 5% มาฟื้นตัวเอง\n#C0xF13B54#【เถาวัลย์แส้】#C0x5B545B#\nบัฟระดับ 3 กระตุ้นเพื่อนร่วมทีม โดยแลกกับการเสีย HP 5% ของเป้าหมาย แต่สามารถกระตุ้น【ล้างดีบัฟ I】 และทำให้การโจมตีเชิงรุกครั้งถัดไปเพิ่มพลังโจมตีคู่ 15% และเจาะการลดความเสียหาย 10%\n#C0xF13B54#【พ่อห่วงใย】#C0x5B545B#\nเอฟเฟกต์พิเศษ ผู้ใช้จะสลับ HP กับเพื่อนร่วมทีมที่มี HP น้อยที่สุด จากนั้นฟื้น HP ของตนเอง 15% ของ HP สูงสุด',
		simDesc = '#C0xC0C0C0#ไม่เป็นไร…ขอแค่เธอปลอดภัยก็พอ#C0x5B545B#\n① โจมตีศัตรูเดี่ยว สร้างความเสียหาย พร้อมใช้【Vine of Vitality】เชื่อมโยงกับเพื่อนร่วมทีม 1 เทิร์น',
		starEffect = __data_t__starEffect[90413],
		-- {11}
		starEffectDesc = '\nเมื่อเพื่อนร่วมทีมที่เชื่อมด้วย 【Immortal Vine】 มีเพื่อนธาตุ Grass/Dark ที่มี HP ต่ำกว่าตนเอง จะกระตุ้น 【Caretaker Protection】 (ทั้งสนามสามารถกระตุ้นได้ 3 ครั้ง)\n⑤เมื่อกระตุ้น 【Caretaker Protection】 ตนเองจะไม่โดนดาเมจเกิน 30% ของ Max HP, นาน 1 เทิร์น',
		zawakeEffect = __data_t__zawakeEffect[90413],
		-- {79003}
		zawakeEffectDesc = '#C0xC0C0C0#ไม่เป็นไร...ตราบใดที่เจ้ายังปลอดภัย#C0x5B545B#\n① โจมตีเป้าหมายเดี่ยว สร้างความเสียหาย#C0xE69900#ATK 380%#C0x5B545B#+$(skillLevel*4*48)$ เป็น#C0xF13B54#กายภาพ#C0x5B545B# ใช้【Immortal Vine】เชื่อมโยงกับเพื่อนร่วมทีม 1 เทิร์น\n② ฟื้นฟู HP ของตนเอง 5% จาก HP สูงสุด\n③ ใช้【Whip Vine】กระตุ้นเพื่อนร่วมทีมธาตุ Grass/Dark 1 เทิร์น\n#C0xF13B54#【Immortal Vine】#C0x5B545B#\nบัฟเลเวล 3 เมื่อผู้ใช้ฟื้นฟู HP จะกระจาย HP ไปยังพันธมิตรที่เชื่อมโยงด้วย Grass-type ได้รับการฟื้นฟูมากขึ้น 15% ส่วน Dark-type เมื่อโจมตี จะดูด HP เป้าหมายหลัก 5% ให้กับตัวเอง\n#C0xF13B54#【Whip Vine】#C0x5B545B#\nบัฟเลเวล 3 ใช้แส้ปลุกเร้าเพื่อนร่วมทีม ดูด HP ปัจจุบันของเป้าหมาย 5% แต่สามารถกระตุ้น【Dispel I】 และเพิ่ม ATK/Sp.ATK 15% กับ Ignore DMG Reduction 10% ให้กับการโจมตีถัดไปของเพื่อนร่วมทีม\n#C0xF13B54#【Dad\'s Care】#C0x5B545B#\nเอฟเฟกต์พิเศษ สลับ HP ระหว่างผู้ใช้กับพันธมิตรที่มี HP ต่ำสุด จากนั้นฟื้น HP ของผู้ใช้ 15% จาก HP สูงสุด',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '#C0x5c9970#เพิ่มอัตราสร้างความเสียหายพื้นฐานเป็น 420%, หลังเปิดใช้งาน【Healer’s Protection】ทั้งสองฝ่ายที่สลับเลือดจะไม่โดนความเสียหายเกิน 25% Max HP เป็นเวลา 1 เทิร์น',
		upLvDesc = 'เพิ่มความเสียหายคงที่+192',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		changeUnitTrigger = true,
		isCombat = true,
		skillType2 = 2,
		skillNatureType = 4,
		targetTypeDesc = 'ศัตรูเดี่ยว',
