	[90422] = {
		id = 90422,
		skillName = 'สกิลพิเศษ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#ลูกคือสิ่งที่ดีที่สุดของพ่อ#C0x5B545B#\n①โจมตีเป้าหมายศัตรูเดี่ยว สร้าง#C0xE69900#180%พลังโจมตีกายภาพ#C0x5B545B#+$(skillLevel*4*48)$ของ#C0xF13B54#ความเสียหายกายภาพ#C0x5B545B#\n②จากนั้นทำให้ตนเองเข้าสู่สถานะ【พรางตัวด้วยเถาวัลย์】เป็นเวลา 1 เทิร์น เมื่อพรางตัวสิ้นสุด จะมอบ【พันธนาการ】ให้ศัตรู 1 คนเป็นเวลา 1 เทิร์น\n#C0xF13B54#【พรางตัวด้วยเถาวัลย์】#C0x5B545B#\nสถานะพรางตัว มีค่าเท่ากับ 30% ของ HP สูงสุดของผู้ใช้ (ถูกโจมตีจนหมดจะสิ้นสุดสถานะ) ระหว่างถูกโจมตีจะดูดเลือดจากศัตรู 3% ของ HP สูงสุดเก็บไว้ และเมื่อสิ้นสุดจะฟื้นฟู HP ตามที่เก็บได้\n#C0xF13B54#【พันธนาการ】#C0x5B545B#\nดีบัฟควบคุมระดับ 1 ทำให้ศัตรูไม่สามารถกระทำใด ๆ ได้ ไม่สามารถล้างด้วยสายธาตุน้ำ แต่สามารถถูกทำลายโดยสถานะเผาไหม้',
		zawakeEffect = __data_t__zawakeEffect[90422],
		-- {79002}
		zawakeEffectDesc = '#C0xC0C0C0#เจ้าคือลูกชายที่ยอดเยี่ยมที่สุดของข้า#C0x5B545B#\n① โจมตีเป้าหมายเดี่ยว สร้างความเสียหาย#C0xE69900#ATK 180%#C0x5B545B#+$(skillLevel*4*48)$ เป็น#C0xF13B54#กายภาพ#C0x5B545B#\n② เข้าสู่สถานะ【Vine Camouflage】1 เทิร์น หลังจบสถานะจะทำให้ศัตรู 1 ตัวติด【Entangle】1 เทิร์น\n#C0xF13B54#【Vine Camouflage】#C0x5B545B#\nสถานะพรางตัว มี HP เท่ากับ 30% ของ HP สูงสุดของผู้ใช้ (หมดแล้วสถานะจะหายไป) เมื่อโดนโจมตีจะดูดเลือด 3% ของ HP สูงสุดศัตรู และคืนกลับให้ผู้ใช้เมื่อสถานะจบลง\n#C0xF13B54#【Entangle】#C0x5B545B#\nคอนโทรลเลเวล 1 ทำให้เป้าหมายไม่สามารถเคลื่อนไหวได้ ไม่สามารถล้างด้วยธาตุน้ำ แต่จะถูกทำลายโดยสกิลเผาไหม้',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '#C0x5c9970#เพิ่มอัตราสร้างความเสียหายพื้นฐานเป็น 200%, เพื่อนร่วมทีมประเภท Grass/Dark ที่เคลื่อนไหวก่อนหน้าจะได้รับสถานะ【Vine Camouflage】เป็นเวลา 1 เทิร์น',
