	[90426] = {
		id = 90426,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#ถ้ามีใครที่สู้ไม่ไหว...ไม่ว่าจะวิธีไหนพ่อจะปกป้องลูกให้ได้#C0x5B545B#\n①【เถาวัลย์ดูดเลือด】:\nเมื่อผู้ใช้โจมตีเชิงรุก / หรือศัตรูติด【พันธนาการ】 จะสร้าง【เถาวัลย์ดูดเลือด】เพื่อโจมตีศัตรูแบบสุ่ม 1 ตัว (สูงสุด 3 ครั้งต่อรอบใหญ่); เมื่อกระตุ้นครบ 6 ครั้ง จะติดตั้งกับดัก【เถาวัลย์ยักษ์】ซึ่งเมื่อถูกกระตุ้นจะสร้างความเสียหายกับดัก 80% พลังโจมตีกายภาพของ Zarude แก่ศัตรูทั้งหมด\n②【พรแห่งต้นไม้เทพ】:\nทุกครั้งที่ HP ของตนลดลง 3% อัตราการฟื้นฟูจะเพิ่มขึ้น 1%; เมื่อได้รับความเสียหายจากศัตรู จะฟื้นคืน 20% ของความเสียหายที่ได้รับทันที\n③เมื่อ【เถาวัลย์ยักษ์】ถูกกระตุ้น ตนเองจะได้รับ【เถาวัลย์ป้องกัน】เป็นเวลา 2 เทิร์น\n#C0xF13B54#【เถาวัลย์ดูดเลือด】#C0x5B545B#\nกับดัก สร้างความเสียหายจากกับดักตามพลังโจมตีกายภาพ 40% ของผู้ใช้ และดูด 3% การลดความเสียหาย และ HP สูงสุดของศัตรู มาให้กับโปเกมอนสายพืช/มืดแบบสุ่ม 1 ตัว ฝ่ายเรา เป็นเวลา 2 เทิร์น\n#C0xF13B54#【เถาวัลย์ยักษ์】#C0x5B545B#\nกับดัก เมื่อโปเกมอนสายพืช/มืดฝ่ายเราโดนโจมตีเชิงรุก จะกระตุ้น สร้างความเสียหายจากกับดัก พร้อมสุ่มพัดศัตรู 1 ตัวออกไป จากนั้นคูลดาวน์ 2 เทิร์น\n#C0xF13B54#【เถาวัลย์ป้องกัน】#C0x5B545B#\nร่างเฉพาะ เมื่อถูกกระตุ้นจะล้างและกันสถานะห้ามฟื้นฟู ระหว่างนี้ดูดเลือด, ลดความเสียหาย, และพลังป้องกันคู่ของผู้ใช้เพิ่มขึ้น 10% หากใช้พันธนาการใส่ศัตรูสายพลังจิตในระดับเดียวกันหรือต่ำกว่า จะไม่สามารถเข้าสู่ ร่างพลังจิต ได้\n#C0xF13B54#【คำสั่งแห่งผู้ชั่วร้าย】#C0x5B545B#\nเอฟเฟกต์พิเศษ หาก HP ของเป้าหมายมากกว่าผู้ใช้ จะสลับ HP กัน และผู้ใช้จะฟื้น HP เพิ่ม 20% ของ HP สูงสุด; หาก HP ของเป้าหมายน้อยกว่าผู้ใช้ จะไม่สลับ และผู้ใช้จะฟื้น 30% HP สูงสุด ส่วนเป้าหมายจะเสีย 20% HP สูงสุด\n#C0xF13B54#【พันธนาการ】#C0x5B545B#\nดีบัฟควบคุมระดับ 1 ทำให้ศัตรูไม่สามารถกระทำการใด ๆ ได้ ไม่สามารถถูกล้างด้วยธาตุน้ำ แต่สามารถถูกทำลายด้วยสถานะเผาไหม้',
		starEffect = __data_t__starEffect[90426],
		-- {8}
		starEffectDesc = '\nเมื่อ 【Giant Vine】 ถูกกระตุ้น จะได้รับ 【Shield Vine】 2 เทิร์น\nเมื่อได้รับดาเมจร้ายแรง จะรอดชีวิตด้วย HP 20% ของ Max HP หาก HP น้อยกว่าศัตรูที่มี HP มากที่สุดจะกระตุ้น 【Villain\'s Verdict】 (ไม่เลือก Boss เป็นเป้าหมาย, คูลดาวน์ 5 เทิร์น, ทั้งสนามกระตุ้นได้ 2 ครั้ง)',
		zawakeEffect = __data_t__zawakeEffect[90426],
		-- {79004}
		zawakeEffectDesc = '#C0xC0C0C0#หากเจอศัตรูที่เราไม่อาจเอาชนะได้...ไม่ว่าจะอย่างไรก็จะปกป้องเจ้าให้ได้#C0x5B545B#\n①【Bloodsucking Vine】:\nเมื่อผู้ใช้โจมตี หรือเมื่อศัตรูติด【Entangle】 จะสร้าง【Bloodsucking Vine】โจมตีศัตรูแบบสุ่ม 1 ตัว (สูงสุด 3 ครั้งต่อเทิร์นใหญ่); เมื่อสะสมครบ 6 ครั้ง จะติดตั้งกับดัก【Giant Vine】 ที่จะสร้างดาเมจกับศัตรูทั้งหมดตาม 80% ATK ของ Zarude\n②【Divine Tree’s Blessing】:\nทุกครั้งที่ HP ลดลง 3% จะเพิ่ม Healing Rate 1%; เมื่อถูกศัตรูโจมตี จะฟื้น HP ทันที 20% จากความเสียหายที่ได้รับ\n③ เมื่อ【Giant Vine】ทำงาน ผู้ใช้จะได้รับ【Protective Vine】นาน 2 เทิร์น\n#C0xF13B54#【Bloodsucking Vine】#C0x5B545B#\nกับดัก สร้างความเสียหายเท่ากับ 40% ATK ของผู้ใช้ และดูด DMG Reduction กับ HP สูงสุดเริ่มต้น 3% ของเป้าหมาย โอนไปยังพันธมิตรแบบสุ่มที่เป็น Grass/Dark นาน 2 เทิร์น\n#C0xF13B54#【Giant Vine】#C0x5B545B#\nกับดัก เมื่อพันธมิตร Grass/Dark โดน Active Skill จากศัตรู กับดักจะทำงาน สร้างดาเมจและจับเป้าหมายศัตรูแบบสุ่ม 1 ตัวออกจากสนาม หลังจากทำงานแล้วจะคูลดาวน์ 2 เทิร์น\n#C0xF13B54#【Protective Vine】#C0x5B545B#\nรูปแบบเฉพาะตัว เมื่อทำงานจะล้างและกันเอฟเฟกต์ Anti-Heal เพิ่ม HP Steal, DMG Reduction และ DEF (ทั้งสองประเภท) 10% ขณะมีผล หากใช้สกิลที่มี【Entangle】จะยับยั้งการแปลงร่างของ Psychic-type ที่ระดับเดียวกันหรือต่ำกว่า\n#C0xF13B54#【Villain\'s Decree】#C0x5B545B#\nเอฟเฟกต์พิเศษ หาก HP ของเป้าหมายมากกว่าผู้ใช้ จะสลับ HP กัน และผู้ใช้จะฟื้นอีก 20% จาก HP สูงสุด; หาก HP ของเป้าหมายต่ำกว่า จะไม่สลับ HP แต่ผู้ใช้จะฟื้น 30% HP และเป้าหมายเสีย 20% HP สูงสุด\n#C0xF13B54#【Entangle】#C0x5B545B#\nคอนโทรลเลเวล 1 ทำให้เป้าหมายไม่สามารถเคลื่อนไหว ไม่สามารถล้างด้วยธาตุน้ำ แต่จะถูกทำลายด้วยสกิลประเภทเผาไหม้',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '#C0x5c9970#เมื่อเปิดใช้งาน【Wicked Rescue】จะเข้าสู่สถานะ【Vine Camouflage】เป็นเวลา 1 เทิร์น; ขณะอยู่ใน【Vine Shield Mimic】การโจมตีจะสุ่มลบน้ำซัมมอนของศัตรู 1 ตัว หรือทำให้สิ่งกีดขวางธาตุ Rock 1 ตัว HP เหลือครึ่ง',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
