	[90512] = {
		id = 90512,
		skillName = 'สกิลพิเศษ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#มั่นคงดังหินผา หนักแน่นดั่งหมี!#C0x5B545B#\n\n①โจมตีเป้าหมายศัตรูเดี่ยว สร้าง#C0xE69900#180%พลังโจมตีกายภาพ#C0x5B545B#+$(skillLevel*4*48)$ของ#C0xF13B54#ความเสียหายกายภาพ#C0x5B545B#\n②จากนั้นสร้าง【เกราะแรงโน้มถ่วง】ตามผลรวมของพลังป้องกันคู่ 120%\n③ในเทิร์นถัดไป หากมี【เกราะแรงโน้มถ่วง】จะลดความเสียหายที่ได้รับลง 30%\n#C0xF13B54#【เกราะแรงโน้มถ่วง】#C0x5B545B#\nโล่พิเศษ ไม่ลดลงเมื่อเวลาผ่านไป จะดูดซับความเสียหายจากการโจมตีเชิงรุกที่เพื่อนร่วมทีมสายเหล็ก/พลังจิตที่อยู่แถวหลังช่องติดกันได้รับ 25% โดยผู้ใช้จะเป็นผู้รับแทน (ความเสียหายที่รับแทนจะไม่เกิน 15% ของ HP สูงสุดของผู้ใช้)',
		simDesc = 'Metagross รวมแสงไว้ที่กากบาทโลหะบนใบหน้าแล้วปล่อยเป็นปืนใหญ่โจมตีศัตรูเดี่ยว',
		zawakeEffect = __data_t__zawakeEffect[90512],
		-- {79002}
		zawakeEffectDesc = '#C0xC0C0C0#มั่นคงดั่งหินผา หนักแน่นดั่งหมี!#C0x5B545B#\n\n①โจมตีเป้าหมายเดี่ยวฝ่ายศัตรู สร้าง#C0xE69900#180% Physical ATK#C0x5B545B#+$(skillLevel*4*24)$ ของ#C0xF13B54#Physical Damage#C0x5B545B#\n②สร้าง【Gravity Barrier】ด้วยค่าเท่ากับ 120% ของ DEF+SPDEF\n③ใน 1 เทิร์นถัดไป หากมี【Gravity Barrier】จะลดความเสียหายที่ได้รับลง 30%',
