	[90523] = {
		id = 90523,
		skillName = 'ท่าไม้ตาย',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#แรงโน้มถ่วงทำให้ทุกสิ่งดึงดูดกัน และจึงทำให้ฉันพบเธอ#C0x5B545B#\n\n①เมื่อ【ค่าพลังโน้มถ่วง】เต็ม สามารถปล่อยให้เป้าหมายหลักติด【ไร้น้ำหนัก】เป็นเวลา 1 เทิร์น\n②ควบคุมให้มันพุ่งชนเป้าหมายแบบสุ่มที่อยู่แถวหลัง 1 ตัว สร้างความเสียหาย#C0xE69900#300%พลังโจมตีกายภาพ#C0x5B545B#/#C0xE69900#150%พลังโจมตีกายภาพ#C0x5B545B#+$(skillLevel*4*42)$ของ#C0xF13B54#ความเสียหายกายภาพ#C0x5B545B#ตามลำดับ\n③และมอบดีบัฟ【น้ำหนักเกิน】ให้เป้าหมายที่ถูกชน เป็นเวลา 1 เทิร์น\n#C0xF13B54#【ค่าพลังโน้มถ่วง】#C0x5B545B#\nทุก 1 แต้มจะเพิ่มพลังป้องกันคู่ 5% เมื่อค่าพลังโน้มถ่วงเต็มสามารถปลดปล่อยท่าไม้ตายได้\n#C0xF13B54#【ไร้น้ำหนัก】#C0x5B545B#\nดีบัฟระดับ 3 ทำให้ทักษะผลักหรือโยกย้ายเป้าหมายหมดผล เพิ่มความอ่อนแอต่อสายเหล็ก/พลังจิต 10% ระหว่างสถานะนี้ HP และพลังป้องกันคู่จะไม่เพิ่มขึ้นตามสถานะไร้น้ำหนัก\n#C0xF13B54#【น้ำหนักเกิน】#C0x5B545B#\nดีบัฟระดับ 3 ลดความเร็วเป้าหมายลง 9% และลดความเร็วในการฟื้นโทสะ 20% ระหว่างสถานะนี้ พลังโจมตีคู่และความเร็วจะไม่เพิ่มขึ้นตามสถานะน้ำหนักเกิน',
		simDesc = '#C0xC0C0C0#แรงโน้มถ่วงมีอยู่ในทุกสรรพสิ่ง และทำให้ข้าได้พบเจ้า#C0x5B545B#\n\n① เมื่อค่ากลับสู่เต็ม【Gravity】สามารถทำให้เป้าหมายหลักติดสถานะ【Weightless】ได้ 1 เทิร์น',
