	[90616] = {
		id = 90616,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#F40##L10#คลื่นพลังปั่นป่วน#L0#:\n①หลังจากตนเองทำการกระทำในเทิร์นนี้ จะมอบ【โจมตีซ้ำ I】ให้กับเพื่อนร่วมทีมประเภทเหล็ก/ต่อสู้แบบสุ่ม 1 ถึง 3 คน (เอฟเฟกต์คงอยู่จนจบเทิร์นนี้)\n②ความเสียหายจากการโจมตีทั้งหมดของตนเองต่อศัตรูที่ยังไม่ได้ใช้【การกระทำเพิ่มเติม】ในเทิร์นนี้ จะเพิ่มขึ้น 10%\n#F40##L10#สัมผัสคลื่นพลัง#L0#:\n③เมื่อเพื่อนร่วมทีมประเภทเหล็ก/ต่อสู้ใช้【การกระทำเพิ่มเติม】จะทำให้ตนเองสะสมพลังคลื่นพลัง เมื่อสะสมครบ 3/6/9 ครั้ง ตนเองจะสามารถฉีด【พลังคลื่นพลัง】ตามพลังพิเศษ 60%/80%/100% ในการโจมตี 2 ครั้งแรกของแต่ละเทิร์น\n\n#C0xF13B54#【ปลดล็อกระดับ 6 ดาว】:รอยประทับคลื่นพลัง#C0x5B545B#\n④หลังจากตนเองใช้【การกระทำเพิ่มเติม】แต่ละครั้ง จะเพิ่มความเสียหายจากการโจมตีต่อเนื่อง 5% และอัตราทะลุป้องกัน 1 เทิร์น (สะสมได้สูงสุด 30%)\n⑤หลังจากตนเองใช้【การกระทำเพิ่มเติม】ครบทุก 3 ครั้ง จะได้รับ【คลื่นพลัง共鸣】 1 ครั้ง\n#C0xF13B54#【โจมตีซ้ำ I】#C0x5B545B#\nบัฟระดับ 1, เป็นเอฟเฟกต์ประเภทการโจมตีต่อเนื่อง เมื่อตัวละครในทีมโจมตี ตนเองจะใช้การโจมตีปกติเพื่อไล่โจมตีเป้าหมายเดียวกันเพิ่มเติม\n#C0xF13B54#【การกระทำเพิ่มเติม】#C0x5B545B#\nเป็นคำรวมเรียกของ การช่วยโจมตี, โจมตีต่อเนื่อง, โต้กลับ, เชิญร่วมสู้, โจมตีก่อน\n#C0xF13B54#【พลังคลื่นพลัง】#C0x5B545B#\nพลังคลื่นพลัง (เมื่อฉีดโดยสายต่อสู้จะสามารถละเลยโล่และสิ่งกีดขวางของหิน), คงอยู่จนจบเทิร์นถัดไป; หากเป้าหมายถูกโจมตีโดยการโจมตีเชิงรุกของผู้ใช้หรือโดยการโจมตีใด ๆ จากสายต่อสู้ในเทิร์นถัดไป พลังคลื่นพลังจะถูกกระตุ้นและสลาย พร้อมสร้างความเสียหาย 1 เท่าของพลังคลื่นพลัง (สายต่อสู้สร้าง 2 เท่า)\n#C0xF13B54#【คลื่นพลัง共鸣】#C0x5B545B#\nบัฟระดับ 2, ผู้ใช้จะสามารถลอกแบบหนึ่งใน【การกระทำเพิ่มเติม】ที่เพื่อนร่วมทีมประเภทต่อสู้/เหล็กเคยใช้ แล้วใช้ในรูปแบบการโจมตีปกติ; และเพื่อนร่วมทีมนั้นในครั้งต่อไปที่ใช้【การกระทำเพิ่มเติม】จะสามารถฉีดพลังคลื่นพลังตามพลังพิเศษ 100% ของผู้ใช้ได้\n#C0xF13B54#【คลื่นพลังย้อนกลับ】#C0x5B545B#\nบัฟระดับ 3, ความเสียหายจากการโจมตีเชิงรุกที่ผู้ใช้ได้รับในครั้งถัดไปจะถูกแปลงเป็นโล่ในปริมาณ 50% ของค่าความเสียหายนั้น (แต่ไม่ต่ำกว่าผลรวมของพลังโจมตีกายภาพและพลังพิเศษของตนเอง 100%) และระหว่างการทำงานนี้ เอฟเฟกต์ดีบัฟระดับ 1/2 ที่ได้รับจะถูกแปลงเป็น【連打I】และมีระยะเวลา 2 เทิร์น',
		starEffect = __data_t__starEffect[90616],
		-- {8}
		starEffectDesc = '\n⑥การโจมตีทั้งหมดของตนจะถือว่าเป็นการโจมตีแบบ Combo (จะได้รับบัฟความเสียหายจาก Combo); เมื่อเรียนรู้ 【Aura Resonance】 แล้วจะได้รับ 【Aura Inversion】 1 ครั้ง',
		zawakeEffect = __data_t__zawakeEffect[90616],
		-- {79004}
		zawakeEffectDesc = '#F40##L10#Aura Distortion#L0#:\n①หลังตนเองทำการโจมตีในเทิร์นนี้ จะสุ่มมอบ【Pursuit I】ให้เพื่อนร่วมทีมสาย Steel/Fighting 1 ถึง 3 ตัว (มีผลจนจบเทิร์น)\n②การโจมตีของตนเองในเทิร์นนี้ต่อศัตรูที่ยังไม่ได้ใช้ Extra Action จะเพิ่มความเสียหายขึ้น 10%\n#F40##L10#Aura Sense#L0#:\n③เมื่อเพื่อนร่วมทีมสาย Steel/Fighting ใช้ Extra Action จะสะสมพลังงาน Aura ให้กับตนเอง สะสมครบ 3/6/9 ครั้ง ตนเองจะสามารถฉีด【Aura Energy】ตาม 60%/80%/100% Sp. ATK ใส่เป้าหมายจากการโจมตี 2 ครั้งแรกในแต่ละเทิร์น\n\n#C0xF13B54#【ปลดล็อก 6★】: Aura Inscription#C0x5B545B#\n④ทุกครั้งที่ตนเองใช้ Extra Action จะเพิ่ม 5% ความเสียหายจากการโจมตีต่อเนื่อง และอัตราทะลุบล็อก 1 เทิร์น (สูงสุด 30%)\n⑤ทุกครั้งที่ใช้ Extra Action ครบ 3 ครั้ง จะได้รับ 1 ครั้งของ【Aura Resonance】\n#C0xF13B54#【Pursuit I】#C0x5B545B#\nบัฟระดับ 1 ประเภทโจมตีต่อเนื่อง เมื่อเพื่อนร่วมทีมโจมตี จะใช้ Normal Attack ไล่ตามเป้าหมายเดียวกัน\n#C0xF13B54#【Extra Action】#C0x5B545B#\nชื่อรวมของ Co-op, Combo, Counter, Duel, และ Priority Action\n#C0xF13B54#【Aura Energy】#C0x5B545B#\nพลังงาน Aura (หากฉีดโดยโปเกมอนสาย Fighting จะทะลุผ่านโล่และสิ่งกีดขวาง Rock) คงอยู่จนจบเทิร์นถัดไป; ในเทิร์นถัดไปหากถูกโจมตีโดยผู้ปล่อยหรือโปเกมอนสาย Fighting จะระเบิดสร้างความเสียหาย Aura เท่ากับ 1 เท่า (หรือ 2 เท่า ถ้าเป็นสาย Fighting) จากนั้นจะสลายไป\n#C0xF13B54#【Aura Resonance】#C0x5B545B#\nบัฟระดับ 2 ผู้ปล่อยจะได้รับความสามารถของ Extra Action หนึ่งอย่างที่เพื่อนร่วมทีมสาย Fighting/Steel เคยใช้มาก่อน แล้วใช้ผ่านรูปแบบ Normal Attack; เพื่อนคนนั้นจะสามารถฉีด【Aura Energy】เท่ากับ 100% Sp. ATK ของผู้ปล่อยใน Extra Action ถัดไป\n#C0xF13B54#【Aura Reversal】#C0x5B545B#\nบัฟระดับ 3 ความเสียหายจากการโจมตีแบบ Active ครั้งถัดไปที่ผู้ปล่อยได้รับ จะถูกเปลี่ยนเป็นโล่เท่ากับ 50% ของค่าความเสียหาย (ไม่น้อยกว่า 100% ของ ATK+Sp. ATK ของตนเอง) และระหว่างการป้องกันนี้ ผลดีบัฟระดับ 1/2 ที่ได้รับจะถูกแปลงเป็น【Combo I】และมีผลนาน 2 เทิร์น',
