	[90716] = {
		id = 90716,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#เจ้าก็แค่เม็ดทราย และข้า—แม้แต่เม็ดทรายก็ไม่อาจทนอยู่ในสายตา#C0x5B545B#\n①สกิลออร่าพิเศษ, เพิ่มความเสียหายจากท่าแผ่นดินไหวฝ่ายเรา 10% (มีโอกาส 20% ที่จะเพิ่มเป็น 2 เท่า) ทุกครั้งที่มีเพื่อนร่วมทีมธาตุมังกร/ดิน 1 ตัว จะเพิ่มคริติคอลแดเมจของตนเอง 5%\n②ดมกลิ่นเลือดเพื่อออกล่า, สามารถโจมตีเป้าหมายที่มีพลังชีวิตต่ำกว่า 75% ได้โดยไม่สนตำแหน่งหน้า/หลังหรือสภาพล่องหน เพิ่มอัตราคริติคอลและความเสียหายขึ้นอีก 10% และสร้างความเสียหายธาตุดิน 150% พร้อมดูดเลือดเท่ากับความเสียหาย \n#C0xF13B54#【ปลดล็อค 6 ดาว】: ความเดือดดาลแห่งทะเลทราย#C0x5B545B#\n③ทุก 10% ของค่าความโกรธปัจจุบัน จะเพิ่มคริติคอล 2%, ลดความเสียหาย 2% และเพิ่มพลังโจมตีกายภาพ 2%\n④เมื่อความโกรธเต็ม จะปลดปล่อย【แผ่นดินไหวทะเลทราย】และเพิ่มคริติคอลถาวร 5% (สูงสุด 20%)\n⑤เมื่ออยู่ในสภาพอากาศพายุทราย จะเพิ่มอัตราหลบหลีกธาตุดิน 20% เพิ่มเติม  ',
		starEffect = __data_t__starEffect[90716],
		-- {8}
		starEffectDesc = '\n⑥เมื่อ HP สัดส่วนต่ำกว่า 50% ครั้งแรก จะเข้าสู่สถานะ 【Desert Rampage】 4 เทิร์น, เพิ่ม Lifesteal 100%, เพิ่ม Crit Damage 60%',
		zawakeEffect = __data_t__zawakeEffect[90716],
		-- {79004}
		zawakeEffectDesc = '#C0xC0C0C0#เจ้าก็แค่เม็ดทราย และข้า—ไม่ยอมให้แม้แต่เม็ดทรายอยู่ในสายตา!#C0x5B545B#\n①ออร่าทักษะ เพิ่มความเสียหายจากท่าประเภท Earthquake ของฝ่ายเรา 10% (มีโอกาส 20% ทำดาเมจสองเท่า) ทุกครั้งที่มีเพื่อนร่วมทีมประเภท Dragon/Ground จะเพิ่ม Crit DMG ของตนเอง 5%\n②ตามล่ากลิ่นเลือด สามารถโจมตีเป้าหมายฝ่ายศัตรูที่มี HP น้อยกว่า 75% โดยไม่สนแถวหน้า/หลังและสถานะล่องหน เพิ่มโอกาสคริติคอลและความเสียหายอีก 10% และสร้างความเสียหายประเภท Ground 150% พร้อมดูดเลือดตามจำนวนความเสียหาย\n#C0xF13B54#【ปลดล็อก 6★】: ความพิโรธแห่งทะเลทราย#C0x5B545B#\n③ค่าความโกรธปัจจุบันทุก 10% จะเพิ่ม 2% Crit, Damage Reduction และ Physical ATK\n④เมื่อค่าโกรธเต็ม จะปลดปล่อย【Desert Quake】และเพิ่ม Crit ถาวร 5% (สูงสุด 20%)\n⑤ขณะอยู่ในสภาพอากาศ Sandstorm จะเพิ่มโอกาสหลบการโจมตีจากท่า Ground-type อีก 20%',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '#C0x5c9970#【Desert Quake】เพิ่มค่าสร้างความเสียหายเป็น 110%; ขณะอยู่ในสถานะ【Desert Rampage】จะติดเอฟเฟกต์ Desert Quake ทุกครั้งที่ลงมือ; ขณะอยู่ใน【Quicksand Abyss】การโจมตีแรกที่ได้รับจะไร้ผล (ไม่มีผลกับ Flying)',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		changeUnitTrigger = true,
		isCombat = true,
		skillType = 3,
		skillType2 = 3,
		passiveTriggerType = 7,
		posChoose = 5,
		skillProcess = {907161, 907162, 907163, 999990},
