	[90813] = {
		id = 90813,
		skillName = 'ท่าไม้ตาย',
		skillTypeShow = 'ทักษะสังหาร',
		describe = 'โจมตีเป้าหมายศัตรูในแนวแถว, สร้าง#C0xE69900#320% พลังโจมตีกายภาพ#C0x5B545B#+$(skillLevel*4*48)$ ของ#C0xF13B54#ความเสียหายกายภาพ#C0x5B545B#\nการโจมตีครั้งนี้มีโอกาสคริติคอลเพิ่มขึ้น 15%\nมีผล【ลมหายใจเพลิงคราม】\nเป้าหมายได้รับสถานะ【เถ้าถ่าน】เป็นเวลา 2 เทิร์น\nทำให้เพื่อนร่วมทีมที่ใช้【การโจมตีลมหายใจมังกร】3 ครั้งถัดไป สร้างสถานะ【เพลิงคราม】 1 ชั้นให้กับเป้าหมายแบบสุ่ม\n#C0xF13B54#【ลมหายใจเพลิงคราม】#C0x5B545B#\nการโจมตีลมหายใจมังกร สร้าง【เพลิงคราม】ให้เป้าหมาย 1~3 ชั้น, หากเกินขีดจำกัด, เพลิงครามส่วนเกินจะถูกถ่ายโอนไปยังศัตรูแบบสุ่ม และทำให้เกิดความเสียหายของเพลิงคราม 1 ชั้น\n#C0xF13B54#【เถ้าถ่าน】#C0x5B545B#\nดีบัฟระดับ 3, เมื่อเอฟเฟกต์เผาไหม้สิ้นสุดลง (รวมถึงถูกลบล้าง/ชำระล้าง), มีโอกาส 50% ที่จะติดไฟอีกครั้ง 1 ชั้นและได้รับระยะเวลาต่อเนื่องเท่าเดิม\n#C0xF13B54#【การโจมตีลมหายใจมังกร】#C0x5B545B#\nชื่อรวมของการโจมตีพิเศษประเภทมังกร: รวมถึง【ลมหายใจมังกร I】【ลมหายใจมังกร II】, 【ท่าเต้นมังกรสุดยอด】, 【ลมหายใจมังกรกำมะถัน】, 【ลมหายใจเพลิงคราม】 เป็นต้น  ',
		simDesc = 'Mega Charizard X ตื่นจากรัตติกาล ดึงปีกขึ้นบินสูงและพ่นเปลวไฟสีน้ำเงินใส่ศัตรูเดี่ยว มีโอกาสทำให้ติดสถานะ Burn',
		starEffect = __data_t__starEffect[90813],
		-- {11}
		starEffectDesc = '\nสร้าง【Scorched Earth】เป็นเวลา 2 เทิร์นบนแนวรุก และเปิดใช้งาน【Dragon Feast】ของตนเอง 1 เทิร์น',
		zawakeEffect = __data_t__zawakeEffect[90813],
		-- {79003}
		zawakeEffectDesc = 'โจมตีเป้าหมายทั้งแถวของฝ่ายศัตรู สร้างความเสียหาย#C0xE69900#320% Physical ATK#C0x5B545B#+$(skillLevel*4*48)$ ของ#C0xF13B54#Physical Damage#C0x5B545B#\nมีโอกาสคริติคอลเพิ่ม 15% ในการโจมตีนี้\nแนบผล【Blueflame Breath】\nใส่สถานะ【Ember】นาน 2 เทิร์นให้เป้าหมาย\nการโจมตีประเภท Dragon Breath จากเพื่อนร่วมทีม 3 ครั้งถัดไป จะใส่【Blueflame】1 ชั้นแก่เป้าหมายแบบสุ่ม\n#C0xF13B54#【Blueflame Breath】#C0x5B545B#\nการโจมตีประเภท Dragon Breath จะใส่【Blueflame】1~3 ชั้นแก่เป้าหมาย; หากเกินขีดจำกัด จะส่งผลให้ชั้นเกินถูกย้ายไปยังศัตรูอื่นแบบสุ่มและสร้างความเสียหายจาก Blueflame 1 ชั้น\n#C0xF13B54#【Ember】#C0x5B545B#\nดีบัฟระดับ 3 เมื่อเอฟเฟกต์เผาไหม้สิ้นสุด (รวมถึงการลบ/ชำระล้าง) มีโอกาส 50% ที่จะจุดติดไฟใหม่อีก 1 ชั้น โดยมีระยะเวลาเท่ากับของเดิม\n#C0xF13B54#【Dragon Breath Attack】#C0x5B545B#\nชื่อรวมของท่าพิเศษสาย Dragon เช่น【Dragon Breath I】,【Dragon Breath II】,【Ultimate Dragon Dance】,【Sulfurous Dragon Breath】,【Blueflame Breath】 ฯลฯ\n#C0xF13B54#【Dragon Breath Attack】#C0x5B545B#\n#C0xF13B54#【Blueflame】#C0x5B545B#\nดีบัฟระดับ 3 แต่ละชั้นสร้างความเสียหายธาตุไฟเท่ากับ 60%~90% Physical ATK ของผู้ใช้ สูงสุด 3 ชั้น; ศัตรูมีดีบัฟเผาไหม้เพิ่มเติมแต่ละชั้นจะเพิ่มเพดานดาเมจอีก 10% (สูงสุดรวม +50%)\n#C0xF13B54#【Scorched Earth】#C0x5B545B#\nเมื่อศัตรูเคลื่อนไหวบนพื้นดินที่แผดเผา จะได้รับความเสียหายจากสถานะเผาไหม้ 1~2 ชั้นเพิ่มเติม; หากไม่มีสถานะเผาไหม้ จะถูกใส่【Blueflame】1 ชั้นแทน\n#C0xF13B54#【Dragon Feast】#C0x5B545B#\n【Dragon Devour】ของตนเองเพิ่มเป็น 2 เท่า; และสามารถกลืนกินดีบัฟระดับ 1/2 ของตนเอง 1~2 ชนิด',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '#C0x5c9970#เพิ่มอัตราสร้างความเสียหายพื้นฐานเป็น 340%: ตัวเองและเพื่อนร่วมทีมประเภท Fire/Dragon ที่มี Critical สูงสุด จะได้รับ【Azure Flame Blast】2 เทิร์น; 2 ครั้งแรกของ【Scorched Earth】จะครอบคลุมพื้นที่สนามฝ่ายศัตรูทั้งหมด\n【Azure Flame Blast】: บัฟระดับ 2 เมื่อโจมตีคริติคอลจะจุดชนวน 1 ชั้นของ【Azure Flame】แล้วใส่เพิ่มให้เป้าหมายอีก 1~2 ชั้น',
