	[90912] = {
		id = 90912,
		skillName = 'สกิลพิเศษ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = 'โจมตีเป้าหมายเดี่ยว สร้างความเสียหาย #C0xE69900#80% โจมตีกายภาพ#C0x5B545B# + #C0x3D8A99#80% โจมตีพิเศษ#C0x5B545B# + $(skillLevel*4*30)$ เป็น #C0xF13B54#ความเสียหายพิเศษ#C0x5B545B# และเข้าสู่【Snowman Camouflage】เป็นเวลา 1 เทิร์น เมื่อหมดผลมีโอกาส 50% ทำให้ศัตรูแบบสุ่มติด【Frozen I】เป็นเวลา 1 เทิร์น (เลือกเป้าหมายที่มี【Frostbite】ก่อน) และฟื้นฟูพลังชีวิต 35% ของค่าพลังโจมตีรวมของตนเอง\n#C0xF13B54#【Snowman Camouflage】#C0x5B545B#\nเอฟเฟกต์พรางตัว มีค่าพลังชีวิตเท่ากับ 50% ของพลังโจมตีรวมของผู้ใช้ (เมื่อค่าพลังชีวิตหมด เอฟเฟกต์จะหายไป) และเพิ่มค่าการสะท้อนความเสียหาย 10% คงอยู่จนกว่าตัวเองจะกระทำการในครั้งถัดไป\n#C0xF13B54#【Frozen I】#C0x5B545B#\nดีบัฟควบคุมระดับ 1 เป้าหมายไม่สามารถกระทำการได้ จะถูกลบล้างเมื่อเสียพลังชีวิตรวม 35% ของพลังชีวิตสูงสุด\n#C0xF13B54#【Frostbite】#C0x5B545B#\nดีบัฟระดับ 2 ไม่สามารถซ้อนทับได้ เป้าหมายได้รับความเสียหายจากธาตุน้ำแข็งเพิ่มขึ้น 12% และเมื่อถูกแช่แข็งจะเสียพลังชีวิตทันที 10% ของพลังชีวิตสูงสุด (ไม่นับเป็นความเสียหายจากการละลายน้ำแข็ง) และเมื่อผู้ใช้กระทำการ จะสร้างความเสียหายธาตุน้ำแข็ง 45% ของพลังโจมตีรวมแก่เป้าหมายที่มี【Frostbite】',
		zawakeEffect = __data_t__zawakeEffect[90912],
		-- {79002}
		zawakeEffectDesc = 'ลมหมุนหิมะเต้น พรางกายในพายุ\nโจมตีเป้าหมายเดี่ยว สร้างความเสียหาย#C0xE69900#80% Physical ATK#C0x5B545B#+#C0x3D8A99#80% Sp. ATK#C0x5B545B#+$(skillLevel*4*30)$ ของ#C0xF13B54#Special Damage#C0x5B545B# เข้าสู่【Yeti Disguise】1 เทิร์น เมื่อจบการพรางตัว มีโอกาส 50% ที่จะ【Freeze I】ศัตรูแบบสุ่ม 1 ตัว (เลือกเป้าหมายที่มี【Frostbite】ก่อน) และฟื้น HP เท่ากับ 35% ของค่า ATK+Sp.ATK รวม\n#C0xF13B54#【Yeti Disguise】#C0x5B545B#\nเอฟเฟกต์พรางตัว มี HP เท่ากับ 50% ของ ATK+Sp.ATK รวมของผู้ใช้ (หมดแล้วจะหลุดพรางตัว) ระหว่างนี้ Reflect Damage +10% จนถึงเทิร์นถัดไป\n#C0xF13B54#【Freeze I】#C0x5B545B#\nดีบัฟควบคุมระดับ 1 เป้าหมายไม่สามารถเคลื่อนไหวได้ เมื่อเสีย HP สะสมถึง 35% ของ Max HP จะหลุดแช่แข็งทันที\n#C0xF13B54#【Frostbite】#C0x5B545B#\nดีบัฟระดับ 2 ไม่สามารถซ้อนทับได้ เพิ่มความอ่อนแอต่อ Ice-type 12% เมื่อถูกแช่แข็งจะเสีย HP เท่ากับ 10% Max HP ทันที (ไม่นับเป็นดาเมจจากการหลุด Freeze) และเมื่อผู้ใช้โจมตี จะสร้างความเสียหายธาตุน้ำแข็งเท่ากับ 45% ของ ATK+Sp.ATK รวม',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '#C0x5c9970#เพิ่มอัตราสร้างความเสียหายพื้นฐานเป็น 90%, เมื่อสิ้นสุดการปลอมตัว จะสร้างความเสียหายธาตุน้ำแข็งใส่ศัตรูแบบสุ่ม 1 ตัวเท่ากับจำนวนการฟื้นฟูที่ได้รับ; ในสภาพอากาศหิมะ โอกาสแช่แข็งจากการปลอมตัวจะเป็น 100%',
