	[90916] = {
		id = 90916,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = 'พายุหิมะปะทุ สรรพสิ่งเข้าสู่ความเงียบงัน\nสภาพอากาศ【Blizzard】: เมื่อเข้ามาในสนาม ทีมจะได้รับสภาพอากาศ【Blizzard】ในช่วงจัดตำแหน่งทีม\nหากมีโปเกมอนน้ำแข็งระดับตำนานอยู่ในทีม จะสามารถอัปเกรดเป็น【Ice Snowstorm】\nในสภาพอากาศหิมะ ตัวเองได้รับพลังโจมตีพิเศษและกายภาพเพิ่มขึ้น 5%\n#C0xF13B54#【Frostbite】#C0x5B545B#\nดีบัฟระดับ 2 ไม่สามารถซ้อนทับได้ เป้าหมายได้รับความเสียหายจากธาตุน้ำแข็งเพิ่มขึ้น 12% และเมื่อถูกแช่แข็งจะเสียพลังชีวิตทันที 10% ของพลังชีวิตสูงสุด (ไม่นับเป็นความเสียหายจากการละลายน้ำแข็ง) และเมื่อผู้ใช้กระทำการ จะสร้างความเสียหายธาตุน้ำแข็ง 45% ของพลังโจมตีรวมแก่เป้าหมายที่มี【Frostbite】',
		starEffect = __data_t__starEffect[90916],
		-- {6}
		starEffectDesc = '\nSnow Accumulation:\nในหนึ่งรอบใหญ่ ทุกครั้งที่เพื่อนร่วมทีมธาตุ Grass/Ice เคลื่อนไหว จะทำให้ Shiny Mega Abomasnow สะสมโบนัสความเสียหายและลดความเสียหาย 5% ต่อครั้ง (สูงสุด 5 ครั้งต่อเทิร์น)\nเมื่อ Pokémon ธาตุ Ice ออกเทิร์นแรกในรอบใหญ่ จะสร้าง【Frostbite】ให้ศัตรูแบบสุ่ม 2 เทิร์น\nFrost Blossom:\nสะสมอัตราสะท้อนความเสียหายของเพื่อนร่วมทีมธาตุ Grass/Ice เป็นผลึก เมื่อสะสมถึง 75% ของค่ารวม ATK และ Sp.Atk ของตนเอง จะสร้าง【Frost Blossom】ที่แขนทั้งสอง\nเมื่อได้รับ Healing Rate จะเพิ่ม Reflect Rate ไปพร้อมกัน (สูงสุดไม่เกิน 20%)【Frostbite】',
		zawakeEffect = __data_t__zawakeEffect[90916],
		-- {79004}
		zawakeEffectDesc = 'พายุหิมะพัด ทุกสรรพสิ่งสงบนิ่ง\nเมื่ออยู่ภายใต้สภาพอากาศ Blizzard:\nเมื่อลงสนาม ทีมจะได้รับสภาพอากาศ【Blizzard】ตั้งแต่เริ่มจัดทีม\nหากร่วมทีมกับ Ice-type คุณภาพ Mythical จะอัปเกรดเป็น【Snowstorm】\nตนเองในสภาพอากาศ Snow ได้รับ ATK+Sp.ATK เพิ่มอีก 5%\nปรมาจารย์แห่งการพรางตัว:\nขณะพรางตัว เพื่อนร่วมทีมจะมี HP พรางตัวเพิ่ม 20% และ Reflect Damage เพิ่มขึ้น 10%\nประเภทความเสียหายจากการโจมตีของตนจะยึดค่าที่สูงกว่าระหว่าง ATK หรือ Sp. ATK\n#C0xF13B54#【Frostbite】#C0x5B545B#\nดีบัฟระดับ 2 ไม่สามารถซ้อนทับได้ เพิ่มความอ่อนแอต่อ Ice-type 12% เมื่อถูกแช่แข็งจะเสีย HP เท่ากับ 10% Max HP ทันที (ไม่นับเป็นดาเมจจากการหลุด Freeze) และเมื่อผู้ใช้โจมตี จะสร้างความเสียหายธาตุน้ำแข็งเท่ากับ 45% ของ ATK+Sp.ATK รวม\n#C0xF13B54#【Blizzard】#C0x5B545B#\nสภาพอากาศทั่วไป เพิ่ม Reflect, Ice Damage และลด Passive Damage ของ Ice-type ฝ่ายเรา 10%; เพิ่มโอกาสแช่แข็งอีก 10%\n#C0xF13B54#【Frost Aura】#C0x5B545B#\nบัฟระดับ 2 ไม่สามารถซ้อนทับได้ ล้างและกันดีบัฟแบบติดตัวและสถานะแช่แข็ง หากเป้าหมายได้รับดาเมจเกิน 75% ของ ATK+Sp.ATK รวมในการกระทำครั้งเดียว จะใช้ 1 ชาร์จ【Frost Aura】จำกัดความเสียหายไว้ที่ 75% และสะท้อนความเสียหายจำนวนเท่ากันกลับ พร้อมมีโอกาส 35% ใส่【Freeze I】1 เทิร์นแก่ผู้โจมตี',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '#C0x5c9970#เมื่อเริ่มการต่อสู้ จะเข้าสู่รูปแบบ【Yukionna Disguise】เป็นเวลา 1 เทิร์น; เมื่อเข้าสนามจะมีบัฟ【Frost Bloom】: ในสภาพอากาศหิมะ เมื่อ HP ต่ำกว่า 40% ครั้งแรก จะเข้าสู่สถานะ【Snow Concealment】เป็นเวลา 2 เทิร์น',
