	[91213] = {
		id = 91213,
		skillName = 'ท่าไม้ตาย',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#จงเป็นพยานต่อเปลวเพลิงอันยิ่งใหญ่#C0x5B545B#\n① โจมตีเป้าหมายเดี่ยวของศัตรู (จะโจมตี【Nemesis】เป็นลำดับแรก) สร้างความเสียหาย #C0xE69900#400% โจมตีกายภาพ#C0x5B545B# +$(skillLevel*4*36)$ เป็น #C0xF13B54#ความเสียหายกายภาพ#C0x5B545B# และเพิ่มอัตราคริติคอลของท่าไม้ตายนี้ขึ้น 15%\n② ก่อนโจมตี ทำให้เป้าหมายหลักติด【Gathering Flames】และทำให้เป้าหมายอื่นติด【Fear】เป็นเวลา 2 เทิร์น (ไม่มีผลต่อโปเกมอนธาตุน้ำ)\n③ จุดประกาย【Blazing Battle Spirit】เป็นเวลา 2 เทิร์น',
		simDesc = '#C0xC0C0C0#จงเป็นพยานแห่งเปลวเพลิงสูงสุดนี้เถิด#C0x5B545B# โจมตีศัตรูเดี่ยว (เน้นเป้าหมายที่มีสถานะ【Nemesis】) สร้างความเสียหายกายภาพ การโจมตีนี้เพิ่มโอกาสคริติคอลของท่าไม้ตายอีก 15%',
		starEffect = __data_t__starEffect[91213],
		-- {11}
		starEffectDesc = '\n④หลังใช้ท่าไม้ตาย จะเข้าสู่【Heroic Form】2 เทิร์น และเสริมคอมโบอีก 1 ครั้ง (30% พลังโจมตี); ครั้งแรกของ【Heroic Form】จะไม่ตายจากการโจมตี (HP อย่างน้อยคงที่ 30%)',
		zawakeEffect = __data_t__zawakeEffect[91213],
		-- {79003}
		zawakeEffectDesc = '#C0xC0C0C0#จงเป็นสักขีพยานต่อเปลวเพลิงสูงสุดเถอะ#C0x5B545B#\n①โจมตีเป้าหมายเดี่ยวฝ่ายศัตรู (เลือกเป้าหมาย【Nemesis】ก่อน) สร้างความเสียหาย#C0xE69900#400% Physical ATK#C0x5B545B#+$(skillLevel*4*36)$ ของ#C0xF13B54#Physical Damage#C0x5B545B# การโจมตีนี้มีอัตราคริติคอลเพิ่ม 15%\n②ก่อนโจมตี ใส่【Flame Focus】ให้เป้าหมายหลัก และใส่【Intimidate】นาน 2 เทิร์นให้เป้าหมายอื่น 1 ตัว (ไม่ทำงานกับ Pokémon ธาตุน้ำ)\n③จุดประกาย【Blazing Will】นาน 2 เทิร์น',
