	[91216] = {
		id = 91216,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#C0xC0C0C0#ภายใต้หน้ากาก ฉันเป็นใครไม่สำคัญ สิ่งที่สำคัญคือสิ่งที่ฉันทำ#C0x5B545B#\n① ต้านทานผลลัพธ์จากการขโมยค่าพลังธาตุ\n② ขณะที่อยู่ในสนาม การโจมตีปกติของโปเกมอนธาตุไฟ/ต่อสู้ฝ่ายเดียวกันสร้างความเสียหายเพิ่มขึ้น 10%; ทักษะทั้งหมดของตัวเองได้รับโบนัสจากการโจมตีปกติ\n③ การโจมตีในแต่ละรอบใหญ่เพิ่มความเสียหาย 5% และเพิ่มอัตราต้านทานความเสียหาย 10% (สูงสุด 6 ครั้ง) ของ【Blaze Kick】\n④ เป้าหมายที่มีเอฟเฟกต์เผาไหม้แต่ละชั้น จะเพิ่มอัตราคริติคอลที่ตัวเองทำได้กับเป้าหมายขึ้น 7% และเพิ่มความเสียหายคริติคอล 3% (สูงสุด 5 ชั้น) และหากมี 5 ชั้น จะทำให้โจมตีคริติคอลแน่นอน (ไม่มีผลกับโปเกมอนธาตุน้ำ)',
		starEffect = __data_t__starEffect[91216],
		-- {8}
		starEffectDesc = '\n⑤เมื่อเข้าสนาม จะมองศัตรูที่มี ATK/Sp.Atk สูงสุดเป็น【Rival】 (ใช้ได้ 1 ครั้งต่อแมตช์); เมื่อ【Rival】โดนเพื่อนร่วมทีมธาตุ Fire/Fighting โจมตี จะเสริมการโจมตี【Flame Kick Combo】เพิ่ม 1 ครั้ง (สูงสุด 3 ครั้งต่อเทิร์น)',
		zawakeEffect = __data_t__zawakeEffect[91216],
		-- {79004}
		zawakeEffectDesc = '#C0xC0C0C0#ฉันเป็นใครภายใต้หน้ากากนั้นไม่สำคัญ สิ่งสำคัญคือสิ่งที่ฉันกระทำ#C0x5B545B#\n①ภูมิคุ้มกันต่อเอฟเฟกต์ขโมยธาตุ\n②ขณะอยู่ในสนาม Pokémon ธาตุ Fire/Fighting ฝ่ายเราจะเพิ่มความเสียหายจากการโจมตีปกติ 10%; ทักษะทั้งหมดของตนเองจะได้รับโบนัสความเสียหายแบบเดียวกับการโจมตีปกติ\n③ในแต่ละเทิร์นใหญ่ เมื่อโจมตีจะเพิ่มความเสียหาย 5% และการต้านทานความเสียหาย 10% (สะสมได้สูงสุด 6 ครั้ง)\n④ทุก 1 ชั้นของสถานะเผาไหม้บนเป้าหมาย จะเพิ่มอัตราคริติคอลของตนต่อเป้าหมายนั้น 7% และคริติคอลดาเมจ 3% (สูงสุด 5 ชั้น); หากครบ 5 ชั้น จะคริติคอลแน่นอน (ไม่ทำงานกับ Pokémon ธาตุน้ำ)\n\n#C0xF13B54#【ปลดล็อก 6★】: Flame Kick Combo#C0x5B545B#\n④เมื่อคริติคอลจะไม่สนการต้านทานความเสียหาย และเมื่อการโจมตีแบบ Active คริติคอล จะโจมตีเพิ่มอีก 1 ครั้งด้วย【Flame Kick Combo】 (หากยังเป็นคริติคอล มีโอกาส 50% ที่จะโจมตีเพิ่มอีกครั้ง)',
