	[91312] = {
		id = 91312,
		skillName = 'สกิลพิเศษ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = 'โจมตีเป้าหมายเดี่ยวของศัตรู สร้างความเสียหาย #C0x3D8A99#180% โจมตีพิเศษ#C0x5B545B# +$(skillLevel*4*36)$ เป็น #C0xF13B54#ความเสียหายพิเศษ#C0x5B545B#\nทำให้เป้าหมายติด【Toxic Decay】เป็นเวลา 2 เทิร์น\nให้ตัวเองและเพื่อนร่วมทีมธาตุพิษ/มังกรที่มีพลังโจมตีสูงสุดได้รับ【Serum Hormone】เป็นเวลา 2 เทิร์น,#C0xF13B54#【Serum Hormone】#C0x5B545B#\nสามารถลบล้างดีบัฟระดับ 1 หรือ 2 ได้ 1 ครั้ง ลดความเสียหายที่ได้รับ 15% ลดความเสียหายธาตุพิษที่ได้รับ 20% และทำให้ท่า Dragon Breath และ G-Max Cannon สร้างความเสียหายเต็มพิกัด,#C0xF13B54#【Infinity Venom】#C0x5B545B#\nดีบัฟพิษ สามารถแพร่กระจายได้ต่อเนื่อง 6 เทิร์น ก่อนเริ่มเทิร์นทำให้เป้าหมายได้รับความเสียหายธาตุพิษ 70% ของพลังโจมตีพิเศษของผู้ใช้ สามารถซ้อนทับได้สูงสุด 10 ชั้น,#C0xF13B54#【Toxic Decay】#C0x5B545B#\nเมื่อเป้าหมายได้รับการรักษา 50% ของค่าฟื้นฟูจะถูกเปลี่ยนเป็นความเสียหายธาตุพิษ และทำให้ติด【Infinity Venom】เพิ่ม 1 ชั้น หลังจากถูกกระตุ้นโดยการรักษา 3 ครั้ง เอฟเฟกต์นี้จะหายไป',
		zawakeEffect = __data_t__zawakeEffect[91312],
		-- {79002}
		zawakeEffectDesc = 'โจมตีเป้าหมายเดี่ยวฝ่ายศัตรู สร้าง#C0x3D8A99#180% Sp. Atk#C0x5B545B#+$(skillLevel*4*36)$เป็น#C0xF13B54#Special Damage#C0x5B545B#\nมอบสถานะ#C0xF13B54#【Toxic Decay】#C0x5B545B#เป็นเวลา 2 เทิร์น\nมอบสถานะ#C0x5C9971#【Serum Hormone】#C0x5B545B#ให้ตัวเองและเพื่อนร่วมทีมประเภท Poison/Dragon ที่มี Atk สูงสุดเป็นเวลา 2 เทิร์น\n#C0xF13B54#【Serum Hormone】#C0x5B545B#\nลบ 1 ครั้งของดีบัฟระดับ 1/2 ลดดาเมจที่ได้รับ 15% ลดดาเมจธาตุ Poison ที่ได้รับ 20% ท่า Dragon Breath และ Max Cannon จะสร้างดาเมจสูงสุดแน่นอน\n#C0xF13B54#【Infinity Venom】#C0x5B545B#\nเอฟเฟกต์พิษ แพร่กระจายได้ ต่อเนื่อง 6 เทิร์น ก่อนเริ่มเทิร์นสร้างดาเมจธาตุ Poison เท่ากับ 70% Sp. Atk ของผู้ใช้ สามารถซ้อนทับได้สูงสุด 10 ชั้น\n#C0xF13B54#【Toxic Decay】#C0x5B545B#\nเมื่อเป้าหมายได้รับการฟื้นฟู จะเปลี่ยน 50% ของค่าฟื้นฟูเป็นดาเมจธาตุ Poison และเพิ่ม 1 ชั้นของ【Infinity Venom】 หลังจากฟื้นฟูครบ 3 ครั้ง เอฟเฟกต์จะหายไป',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '#C0x5c9970#เพิ่มอัตราสร้างความเสียหายพื้นฐานเป็น 200%, ได้รับ【Infinity Poison】 2 ชั้น; เมื่อสิ้นสุด【Poison Decay】จะเพิ่มอีก 3 ชั้นของ【Infinity Poison】',
		upLvDesc = 'เพิ่มความเสียหายคงที่+144',
