	[91313] = {
		id = 91313,
		skillName = 'ท่าไม้ตาย',
		skillTypeShow = 'ทักษะสังหาร',
		describe = 'โจมตีศัตรูแบบสุ่ม 3 ตัว สร้างความเสียหาย #C0x3D8A99#220% โจมตีพิเศษ#C0x5B545B# +$(skillLevel*4*90)$ เป็น #C0xF13B54#ความเสียหายพิเศษ#C0x5B545B#\nทำให้เป้าหมายติด【Venomous Dragon Breath】\nจากนั้นเข้าสู่【Dynamax】เป็นเวลา 1 เทิร์น,#C0xF13B54#【Dynamax】#C0x5B545B#\nสถานะพิเศษ เพิ่มพลังชีวิตสูงสุด 100% และพลังป้องกันทั้งสองประเภท ท่าแอคทีฟจะเปลี่ยนเป็นโจมตีศัตรูแบบสุ่ม 3 ตัว สร้างความเสียหาย 200% ของพลังโจมตีพิเศษ; ทุกๆ ชั้นของ【Infinity Venom】ที่ปล่อยโดยท่าไม้ตาย จะเพิ่มความเสียหายธาตุพิษและอัตราลดความเสียหายของตัวเอง 3%,#C0xF13B54#【Venomous Dragon Breath】#C0x5B545B#\nลมหายใจมังกร สร้างความเสียหายธาตุพิษ 40%~100% ของพลังโจมตีพิเศษแก่เป้าหมาย (หากเป็นโปเกมอนธาตุแฟรี่จะใช้เพียงอัตราต่ำสุด) และทำให้เป้าหมายทั้งหมดในบริเวณใกล้เคียงติด【Infinity Venom】ที่ตัวเองมีทั้งหมด,#C0xF13B54#【G-Max Cannon】#C0x5B545B#\nท่าไม้ตายเสริมพลัง ไม่ต้องใช้พลังโกรธ โจมตีศัตรูทั้งหมด สร้างความเสียหายเพิ่มขึ้น 3~5 เท่า และทำให้จำนวนชั้นของ【Infinity Venom】บนศัตรูแบบสุ่ม 2 ตัวเพิ่มขึ้นเป็น 2 เท่า',
		simDesc = 'โจมตีศัตรูแบบสุ่ม 3 เป้าหมาย สร้างความเสียหายพิเศษ มอบสถานะ【Toxic Dragon Breath】จากนั้นเข้าสู่ร่าง【Dynamax】เป็นเวลา 1 เทิร์น',
		starEffect = __data_t__starEffect[91313],
		-- {11}
		starEffectDesc = '\nหลัง Gigantamax จะต้านทาน 1 ครั้งจากสถานะควบคุมระดับ 3 หรือต่ำกว่า และการโจมตีจะกลายเป็น【Max Cannon】',
		zawakeEffect = __data_t__zawakeEffect[91313],
		-- {79003}
		zawakeEffectDesc = 'โจมตีศัตรูแบบสุ่ม 3 ตัว สร้าง#C0x3D8A99#220% Sp. Atk#C0x5B545B#+$(skillLevel*4*90)$เป็น#C0xF13B54#Special Damage#C0x5B545B#\nใส่สถานะ【Toxic Dragon Breath】ให้เป้าหมาย\nจากนั้นเข้าสู่สถานะ【Gigantamax】เป็นเวลา 1 เทิร์น\n#C0xF13B54#【Gigantamax】#C0x5B545B#\nสถานะพิเศษ เพิ่ม HP Max 100% และเพิ่ม Def/Sp. Def ทักษะจะเปลี่ยนเป็นการโจมตีศัตรูแบบสุ่ม 3 ตัว สร้าง 200% Sp. Atk; เมื่อ【Infinity Venom】ที่ปล่อยจากท่า Ultimate มีจำนวนมากขึ้น แต่ละชั้นจะเพิ่มดาเมจธาตุ Poison และลดดาเมจที่ได้รับ 3%\n#C0xF13B54#【Toxic Dragon Breath】#C0x5B545B#\nท่าโจมตีด้วย Dragon Breath สร้างดาเมจธาตุ Poison 40%~100% Sp. Atk (ต่อ Fairy Pokémon จะใช้ค่าสัมประสิทธิ์ต่ำสุด) และปล่อย【Infinity Venom】ทั้งหมดของตนใส่ศัตรูในพื้นที่\n#C0xF13B54#【Max Cannon】#C0x5B545B#\nUltimate Skill เสริม ไม่ใช้พลังงาน โจมตีศัตรูทุกตัว ดาเมจเพิ่ม 3~5 เท่า และสุ่มเลือกศัตรู 2 ตัว ทำให้จำนวนชั้นของ【Infinity Venom】บนตัวพวกเขาเพิ่มเป็นสองเท่า',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '#C0x5c9970#เพิ่มอัตราสร้างความเสียหายพื้นฐานเป็น 240%, หลังใช้ท่าไม้ตายจะกระตุ้นพิษในร่างของศัตรูแบบสุ่ม 1 ตัว ทำให้กลายเป็น【Plague Source】เป็นเวลา 2 เทิร์น; ระหว่าง Dynamax เพื่อนร่วมทีมธาตุ Poison/Dragon ที่ถูกโจมตี จะสามารถลดความเสียหายได้ 100% ของรวม Def/Sp.Def ของ Eternatus',
		upLvDesc = 'เพิ่มความเสียหายคงที่+360',
