	[91436] = {
		id = 91436,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#L10#Hyper Regeneration:#L0# เมื่อเข้ามาในสนาม อัตราการฟื้นฟูของตัวเองเพิ่มขึ้น 1% จะเพิ่มอัตราคริติคอลขึ้น 1% (สูงสุด 50%); ปริมาณการรักษาจะได้รับโบนัสตามอัตราคริติคอล และในแต่ละเทิร์นหากการรักษาคริติคอล 2 ครั้งแรกสำเร็จ จะกระตุ้น【Dispel II】\n#L10#Life Storage:#L0# เมื่อได้รับการรักษาคริติคอล จะสะสม 15% ของค่าฟื้นฟูไว้ใน【Wood Leaf Missile】ที่หาง (สูงสุด 500% ของพลังโจมตีพิเศษ),#C0xF13B54#【Dispel II】#C0x5B545B#\nลบล้างเอฟเฟกต์ผิดปกติระดับ 1 หรือ 2 จำนวน 2 ชั้นของฝ่ายเดียวกัน หรือลบล้างบัฟของศัตรู 2 ชั้น,#C0xF13B54#【Wood Leaf Missile】#C0x5B545B#\nเมื่อยิงออกไป 1 เทิร์นหลังจากนั้นจะตกลงใส่เป้าหมายที่มีพลังชีวิตน้อยที่สุดของศัตรู สร้างความเสียหายธาตุพืช 1.5 เท่าของพลังชีวิตที่สะสมไว้; หากโจมตีศัตรูที่ธาตุแพ้ทาง จะสามารถคริติคอลและทำให้ติด【Bind】เป็นเวลา 1 เทิร์น,#C0xF13B54#【Forest Fruits】#C0x5B545B#\nเอฟเฟกต์พิเศษ สูงสุด 3 ลูก: เมื่อพลังชีวิตของผู้ใช้ต่ำกว่า 75%/50%/25% จะใช้ผลไม้ 1 ลูกเพื่อฟื้นฟูพลังชีวิต 75% ของพลังโจมตีพิเศษ เมื่อมีผลไม้อยู่ จะเพิ่มความเสียหายของธาตุพืชขึ้น 15%,#C0xF13B54#【Rock Cutter】#C0x5B545B#\nก่อนโจมตีแอคทีฟ ผู้ใช้จะทำลายสิ่งกีดขวางธาตุหิน 1 ชิ้น (ยกเว้น Super Diamond Wall) และทำให้การโจมตีทั้งหมดสามารถทะลุผ่านสิ่งกีดขวางธาตุหินได้ และสร้างความเสียหายเพิ่มขึ้น 2 เท่าแก่เป้าหมายที่เป็นธาตุหิน/ดิน,#C0xF13B54#【Water Breaker】#C0x5B545B#\nสร้างความเสียหายแก่สิ่งที่ถูกเรียกจากธาตุน้ำเพิ่มขึ้น 3 เท่า เมื่อทำลายสิ่งที่ถูกเรียก จะสร้างความเสียหาย 150% ของพลังโจมตีพิเศษของธาตุพืชแก่ผู้เรียก,#C0xF13B54#【Lightning Avoidance】#C0x5B545B#\nต้านทานความเสียหายจากธาตุไฟฟ้า และลดความเสียหายจากท่าโจมตีธาตุไฟฟ้าอื่นลงครึ่งหนึ่ง',
		starEffect = __data_t__starEffect[91436],
		-- {6}
		starEffectDesc = '\n#L10#Deep Forest Fruit:#L0# เมื่อสะสม Critical Heal ได้ครบ 3 ครั้ง จะมี【Deep Forest Fruit】เติบโตที่หลัง\n#L10#Sangwood Power:#L0# หากอยู่อันดับ 2 แรกในความเร็วทีม จะได้รับ【Rock Cutter】/【Water Breaker】/【Lightning Avoider】: เมื่อทำลายสิ่งกีดขวาง Rock หรือเรียก Water จะเพิ่ม Speed ถาวร 3% (สูงสุด 5 ครั้ง)',
		zawakeEffect = __data_t__zawakeEffect[91436],
		-- {79004}
		zawakeEffectDesc = '#L10#Ultra Healing：#L0#เมื่อเข้าสนาม ทุก 1% อัตราฟื้นฟูของตน จะเพิ่มอัตราคริติคอล 1% (สูงสุด 50%) และการฟื้นฟูจะได้รับผลจากคริติคอล การฟื้นฟูติดคริติคอล 2 ครั้งแรกในแต่ละเทิร์นจะกระตุ้น【Dispel II】\n#L10#HP Storage：#L0#เมื่อฟื้นฟูติดคริติคอล จะเก็บ 15% ของค่าฟื้นฟูไว้ใน【Leaf Missile】ที่หาง (สูงสุด 500% Sp. Atk)\n#C0xF13B54#【Dispel II】#C0x5B545B#\nลบสถานะผิดปกติระดับ 1/2 ของฝ่ายเรา 2 ชั้น หรือบัฟระดับ 1/2 ของฝ่ายศัตรู 2 ชั้น\n#C0xF13B54#【Leaf Missile】#C0x5B545B#\nหลังยิง 1 เทิร์นจะตกใส่ศัตรูที่มี HP น้อยที่สุด สร้างดาเมจ Grass-Type Sp. Atk เท่ากับ 1.5 เท่าของพลังที่เก็บสะสมไว้ หากเป็นธาตุแพ้จะคริติคอลได้ และ【Bind】เป้าหมาย 1 เทิร์น\n#C0xF13B54#【Jungle Fruit】#C0x5B545B#\nเอฟเฟกต์พิเศษ สูงสุด 3 ผล: เมื่อ HP ผู้ใช้ต่ำกว่า 75%/50%/25% จะกินผลไม้ 1 ผล ฟื้นฟู HP 75% ของ Sp. Atk เมื่อมีผลไม้จะเพิ่มดาเมจ Grass-Type 15%\n#C0xF13B54#【Rock Break】#C0x5B545B#\nก่อนโจมตีแบบ Active จะทำลายสิ่งกีดขวางประเภท Rock 1 ชิ้น (ยกเว้น Super Diamond Wall) และสามารถทะลุผ่านสิ่งกีดขวาง Rock ได้ทั้งหมด ดาเมจต่อ Rock/Ground-Type จะเพิ่มเป็น 2 เท่า\n#C0xF13B54#【Water Break】#C0x5B545B#\nดาเมจต่อ Summon ประเภท Water เพิ่มเป็น 3 เท่า เมื่อกำจัดได้ จะส่งต่อดาเมจ 150% Grass-Type Sp. Atk ไปยังผู้เรียก Summon\n#C0xF13B54#【Lightning Avoid】#C0x5B545B#\nกันดาเมจธาตุ Electric ได้ทั้งหมด ดาเมจจากท่า Electric อื่นๆ จะลดลงครึ่งหนึ่ง',
		zawakeSimpleType = 2,
