	[91513] = {
		id = 91513,
		skillName = 'ท่าไม้ตาย',
		skillTypeShow = 'ทักษะสังหาร',
		describe = 'โจมตีเป้าหมายในแถวหน้าของศัตรู สร้างความเสียหาย #C0x3D8A99#220% โจมตีพิเศษ#C0x5B545B# +$(skillLevel*4*60)$ เป็น #C0xF13B54#ความเสียหายพิเศษ#C0x5B545B#\nทำให้เป้าหมายหลักติด【กลืนกินตะกละ】เป็นเวลา 1 เทิร์น และเปิดใช้งาน【ดอกไม้ฟื้นฟู】เป็นเวลา 2 เทิร์น,#C0xF13B54#【กลืนกินตะกละ】#C0x5B545B#\nเอฟเฟกต์ควบคุมระดับ 3 สร้างความเสียหายธาตุพืช 300% และกลืนกินศัตรูเข้าไปในกระเพาะ (ไม่สามารถกลืนกินศัตรูธาตุไฟหรือศัตรูที่มีสกิลกลืนกิน) ตัวเองเพิ่ม【ไขมัน】50KG และเมื่อสิ้นสุดการกลืนกิน จะทำให้ศัตรูติด【รัดพัน】เป็นเวลา 1 เทิร์น,#C0xF13B54#【ดอกไม้ฟื้นฟู】#C0x5B545B#\nเอฟเฟกต์ออร่า เพิ่มอัตราการรักษาของโปเกมอนธาตุพืชฝ่ายเดียวกัน 15% และเมื่อโปเกมอนธาตุพืชฝ่ายเดียวกันจบเทิร์น จะฟื้นฟูพลังชีวิตเท่ากับ 80% ของพลังป้องกันคู่ของผู้ใช้,#C0xF13B54#【กรดในกระเพาะ】#C0x5B545B#\nเมื่อผู้ใช้ได้รับการรักษาจากธาตุพืช/พิษ ศัตรูที่ถูกกลืนกินจะได้รับและถูกกระตุ้น【พิษหนาม】 1 ชั้น (เป้าหมายที่ถูกกลืนกินจะเหลือพลังชีวิตขั้นต่ำ 1 แต้ม); เมื่อคายศัตรูออกมา การกัดกร่อนจะลดอัตราลดความเสียหายของศัตรูและลดความต้านทานความเสียหายธาตุพืชลง 30% เป็นเวลา 2 เทิร์น',
		simDesc = 'โจมตีเป้าหมายแนวหน้า สร้างความเสียหายพิเศษ มอบสถานะ【Greedy Devour】ให้เป้าหมายหลัก 1 เทิร์น และเปิดใช้งาน【Healing Bloom】เป็นเวลา 2 เทิร์น',
		starEffect = __data_t__starEffect[91513],
		-- {11}
		starEffectDesc = '\nกลืนกินสถานะลบระดับ 1/2 ของ Pokémon ธาตุ Grass ฝ่ายเรา 1 ชั้น (เน้นดูดซับพิษก่อน)\nเพิ่ม【Fat】ให้ตัวเอง 30KG\nหากเป้าหมายมี【Glutton Devour】จะได้รับ【Stomach Acid Corrosion】',
		zawakeEffect = __data_t__zawakeEffect[91513],
		-- {79003}
		zawakeEffectDesc = 'โจมตีเป้าหมายแถวหน้า สร้าง#C0x3D8A99#220% Sp. Atk#C0x5B545B#+$(skillLevel*4*60)$เป็น#C0xF13B54#Special Damage#C0x5B545B#\nใส่สถานะ【Greedy Devour】กับเป้าหมายหลัก 1 เทิร์น และเปิดใช้งาน【Healing Flower】 2 เทิร์น\n#C0xF13B54#【Greedy Devour】#C0x5B545B#\nดีบัฟระดับ 3 ควบคุม สร้างดาเมจ Grass 300% ใส่ศัตรูและกลืนกินเข้าสู่กระเพาะ (ไม่สามารถกลืน Pokémon ธาตุไฟหรือผู้มีทักษะกลืนกินได้) ผู้ใช้เพิ่ม Fat 50KG หลังกลืนกิน เมื่อจบการกลืนจะ【Bind】ศัตรู 1 เทิร์น\n#C0xF13B54#【Healing Flower】#C0x5B545B#\nเอฟเฟกต์ออร่า เพิ่มอัตราฟื้นฟูของฝ่ายเรา (Grass-Type) 15% หลัง Grass-Type ฝ่ายเราดำเนินการ จะฟื้น HP เท่ากับ 80% ของค่ารวม Def และ Sp. Def ของผู้ใช้\n#C0xF13B54#【Fat】#C0x5B545B#\nเอฟเฟกต์พิเศษ ทุก 10KG Fat สามารถสะสมความเสียหายที่ได้รับได้ 40% ของค่ารวม Def และ Sp. Def\n#C0xF13B54#【Gastric Acid Corrosion】#C0x5B545B#\nเมื่อผู้ใช้ได้รับการฟื้นฟูจากธาตุ Grass/Poison เป้าหมายที่ถูกกลืนจะได้รับและกระตุ้น 1 ชั้นของ【Thorn Toxin】 (ผู้ถูกกลืนจะเหลือ HP อย่างน้อย 1) เมื่อถูกคายออก จะลดดาเมจลดและดาเมจ Grass ที่ได้รับของศัตรู 30% นาน 2 เทิร์น\n#C0xF13B54#【Thorn Toxin】#C0x5B545B#\nดีบัฟระดับ 2 เอฟเฟกต์พิษ แพร่กระจายได้ ต่อเนื่อง 3 เทิร์น: แต่ละชั้นลดอัตราลดดาเมจของเป้าหมายลง 5% ก่อนเริ่มเทิร์นสร้างดาเมจธาตุ Poison เท่ากับ 30% Sp. Atk ของผู้ใช้ ซ้อนสูงสุด 8 ชั้น: สิ้นสุดแต่ละชั้นจะแพร่ 1 ชั้นไปยังศัตรูแบบสุ่ม',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '#C0x5c9970#เพิ่มอัตราสร้างความเสียหายพื้นฐานเป็น 240%, เมื่อคายเป้าหมายที่กลืนไว้ จะเข้าสู่【Giant Flower】รูปแบบปลอมตัว 1 เทิร์น\n【Giant Flower】: รูปแบบปลอมตัว ลำตัวซ่อนใต้ดิน มีดอกไม้ขนาดยักษ์โผล่จากด้านหลัง\nมี HP เท่ากับ 200% ของรวม Def+Sp.Def ของผู้ใช้ (แตกเมื่อ HP หมด)\nศัตรูที่โจมตีจะได้รับ【Thorn Toxin】1 ชั้น',
		upLvDesc = 'เพิ่มความเสียหายคงที่+240',
