	[91613] = {
		id = 91613,
		skillName = 'ท่าไม้ตาย',
		skillTypeShow = 'ทักษะสังหาร',
		describe = 'โจมตีเป้าหมายในแถวของศัตรู สร้างความเสียหาย #C0x3D8A99#320% โจมตีพิเศษ#C0x5B545B# +$(skillLevel*4*48)$ เป็น #C0xF13B54#ความเสียหายพิเศษ#C0x5B545B#\nปล่อย【Ion Dragon Breath】ใส่เป้าหมาย และสร้าง【Cation Field】เป็นเวลา 1 เทิร์น; เมื่อ【Cation Field】สิ้นสุด ตัวเองจะเข้าสู่【Low Power Mode】เป็นเวลา 1 เทิร์น,#C0xF13B54#【Ion Dragon Breath】#C0x5B545B#\nการโจมตีด้วยลมหายใจมังกร มีเอฟเฟกต์ดูดสายฟ้า สร้างความเสียหายธาตุไฟฟ้า 60%~100% ของพลังโจมตีพิเศษ และทำให้เป้าหมายติด【Electrification II】เป็นเวลา 2 เทิร์น,#C0xF13B54#【Cation Field】#C0x5B545B#\nเอฟเฟกต์สนามพิเศษของโปเกมอนไฟฟ้า เพิ่มความเสียหายธาตุไฟฟ้าของโปเกมอนไฟฟ้าฝ่ายเดียวกัน 20% เพิ่มอัตราหลบหลีกธาตุไฟฟ้า และเพิ่มความเร็วในการฟื้นฟูพลังโกรธ พร้อมทั้งลบล้างและป้องกันเอฟเฟกต์ นอนหลับ/สับสน/อัมพาต,#C0xF13B54#【Preview Future】#C0x5B545B#\nเอฟเฟกต์พิเศษ จำลองภาพอนาคต เป้าหมายที่ถูกทำเครื่องหมายจะได้รับ【Ion Dragon Breath】ตามจำนวนเทิร์นที่กำหนด (N = จำนวนโปเกมอนไฟฟ้าฝ่ายเดียวกัน, 1≤N≤3); เมื่อเพื่อนร่วมทีมโปเกมอนไฟฟ้าใช้ท่าไม้ตาย จะเร่งนับเวลาของศัตรูแบบสุ่ม 1 ตัว 1 หน่วย; หากถูกใช้ซ้ำ จะระเบิดเอฟเฟกต์เดิมก่อน,#C0xF13B54#【Low Power Mode】#C0x5B545B#\nรูปแบบเฉพาะ ลดพลังโจมตีทั้งสองประเภทและความเร็วลง 20% แต่ลดอัตราการสูญเสียพลังชีวิตลง 20% และเพิ่มอัตราฟื้นฟูพลังโกรธขึ้น 50%',
		simDesc = 'โจมตีเป้าหมายในแถว สร้างความเสียหายพิเศษ ปล่อย【Ion Dragon Breath】ใส่เป้าหมาย และวาง【Cation Field】เป็นเวลา 1 เทิร์น; เมื่อ【Cation Field】สิ้นสุด ตนเองจะเข้าสู่【Low Power Mode】เป็นเวลา 1 เทิร์น',
		starEffect = __data_t__starEffect[91613],
		-- {11}
		starEffectDesc = '\nในการใช้ไม้ตาย 3 ครั้งแรก จะดึงพลังโจมตีไม้ตาย 50%/40%/30% มาจากอนาคต (จะถูกหักคืน 30%/40%/50% ในครั้งที่ 4/5/6)\nเมื่อเปิด【Positive Ion Field】จะใส่【Future Rehearsal】ให้ศัตรูแบบสุ่ม 3 ตัว (เน้นเป้าหมายที่ Shock อยู่)',
