	[91616] = {
		id = 91616,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#L10#Quantum Engine:#L0# เมื่อเข้าสู่สนาม จะสร้างสนามไฟฟ้า และเพิ่มพลังโจมตีพิเศษของตัวเอง 5% พร้อมเพิ่ม【การหลบหลีกไฟฟ้า】ขึ้น 20%\n#L10#Preemptive Lightning Strike:#L0# ในสนามไฟฟ้าของฝ่ายเดียวกัน **Miraidon** สามารถมองเห็นอนาคต และทำการโจมตี【Preemptive Lightning Strike】ต่อศัตรูที่กำลังจะโจมตีเป้าหมายหลักของทีมโปเกมอนไฟฟ้า/มังกร (สามารถเกิดขึ้นได้ N ครั้งต่อรอบใหญ่, N = จำนวนโปเกมอนไฟฟ้า/มังกรในสนาม),#C0xF13B54#【Cation Field】#C0x5B545B#\nเอฟเฟกต์สนามพิเศษของโปเกมอนไฟฟ้า เพิ่มความเสียหายธาตุไฟฟ้าของโปเกมอนไฟฟ้าฝ่ายเดียวกัน 20% เพิ่มอัตราหลบหลีกธาตุไฟฟ้า และเพิ่มความเร็วในการฟื้นฟูพลังโกรธ พร้อมทั้งลบล้างและป้องกันเอฟเฟกต์ นอนหลับ/สับสน/อัมพาต,#C0xF13B54#【การหลบหลีกไฟฟ้า】#C0x5B545B#\nอัตราหลบหลีกพิเศษ ลดความเสียหายจากท่าธาตุบินเป็น 2 เท่า แต่ไม่มีผลกับท่าธาตุดิน; สามารถซ้อนกับอัตราหลบหลีกปกติได้,#C0xF13B54#【Ion Dragon Breath】#C0x5B545B#\nการโจมตีด้วยลมหายใจมังกร มีเอฟเฟกต์ดูดสายฟ้า สร้างความเสียหายธาตุไฟฟ้า 60%~100% ของพลังโจมตีพิเศษ และทำให้เป้าหมายติด【Electrification II】เป็นเวลา 2 เทิร์น,#C0xF13B54#【Preemptive Lightning Strike】#C0x5B545B#\nเอฟเฟกต์ดูดสายฟ้า ก่อนที่เป้าหมายจะทำการโจมตี จะสร้างความเสียหายธาตุไฟฟ้า 120% ของพลังโจมตีพิเศษ และทำให้เป้าหมายเสียบัฟระดับ 1 หรือ 2 หนึ่งรายการ,#C0xF13B54#【Paradox Engine】#C0x5B545B#\nเอฟเฟกต์พิเศษ ใช้พลังจากอนาคต (ฟื้นฟูพลังชีวิตเต็มและสืบทอดค่าสถานะทั้งหมดที่มีอยู่ ในช่วงเวลาดังกล่าวการหลบหลีกจะกลายเป็นหลบหลีกสมบูรณ์ และสามารถหลบหลีกความเสียหายจากท่าโจมตีแบบพาสซีฟได้); เมื่อ【Cation Field】สิ้นสุดหรือพลังชีวิตจากร่างอนาคตหมดลง ตัวเองจะกลับสู่【Low Power Mode】โดยร่างปัจจุบันจะรับความเสียหาย 25% ของที่ร่างอนาคตได้รับ',
		starEffect = __data_t__starEffect[91616],
		-- {6}
		starEffectDesc = '\n#L10#Power of Future:#L0# ในการเคลื่อนไหวก่อนเต็มเกจ 3 ครั้งแรก จะดูด 400/300/200 Rage จากอนาคต (จะถูกหักคืน 100/200/300 Rage ในครั้งที่ 4/5/6)\nเมื่อหลบหลีกสำเร็จ จะปล่อย【Ionic Dragon Breath】ใส่แหล่งที่มาของความเสียหาย (สูงสุด 3 ครั้งต่อรอบใหญ่)\n#L10#Paradox Engine:#L0# เมื่อเปิด【Positive Ion Field】จะเปิดใช้งาน【Paradox Engine】',
		zawakeEffect = __data_t__zawakeEffect[91616],
		-- {79004}
		zawakeEffectDesc = '#L10#Quantum Engine：#L0#เมื่อเข้าสู่สนาม หากมีการวางสนาม Electric จะเพิ่ม Sp. Atk ของตัวเอง 5% และ【Electric Evasion】อีก 20%\n#L10#Preset Thunderstrike：#L0#ขณะอยู่ในสนาม Electric ของฝ่ายเรา Miraidon สามารถมองเห็นอนาคต หากเป้าหมายต่อไปเป็นศัตรูที่เตรียมโจมตีใส่ Pokémon ธาตุ Electric/Dragon ฝ่ายเรา จะโจมตีด้วย【Preset Thunderstrike】1 ครั้ง (สูงสุด N ครั้งต่อเทิร์นใหญ่ โดย N คือจำนวน Pokémon ธาตุ Electric/Dragon ตอนเข้ารบ)\n#C0xF13B54#【Cation Field】#C0x5B545B#\nสนามฝ่ายเราแบบ Electric ระดับสูง เพิ่มดาเมจธาตุ Electric, อัตราหลบแบบ Electric และความเร็วฟื้นฟูพลังโกรธของ Pokémon ธาตุ Electric 20% ทำให้จิตใจฮึกเหิม ลบและป้องกันสถานะหลับ/สับสน/อัมพาต\n#C0xF13B54#【Electric Evasion】#C0x5B545B#\nอัตราหลบพิเศษ ได้ผลเป็นสองเท่าเมื่อรับดาเมจจาก Flying-Type ท่าโจมตี แต่จะไร้ผลหากถูกโจมตีด้วย Ground-Type; สามารถซ้อนกับอัตราหลบทั่วไปได้\n#C0xF13B54#【Ionic Dragon Breath】#C0x5B545B#\nท่าโจมตีด้วย Dragon Breath มีเอฟเฟกต์ชักนำสายฟ้า สร้างดาเมจธาตุ Electric 60%~100% Sp. Atk และติดสถานะ【Electrified II】กับเป้าหมายเป็นเวลา 2 เทิร์น\n#C0xF13B54#【Preset Thunderstrike】#C0x5B545B#\nเอฟเฟกต์ชักนำสายฟ้า โจมตีก่อนที่เป้าหมายจะเริ่มเทิร์น สร้างดาเมจธาตุ Electric 120% Sp. Atk ทำให้เป้าหมายไม่สามารถได้รับบัฟระดับ 1/2 ที่กำลังจะได้รับในอนาคต 1 ครั้ง\n#C0xF13B54#【Paradox Engine】#C0x5B545B#\nเอฟเฟกต์พิเศษ ยืมร่างในอนาคต (HP เต็ม และสืบทอดสเตตัสทั้งหมด ขณะนี้มีอัตราหลบสมบูรณ์ หลบหลีกดาเมจประเภท Passive ได้ด้วย); เมื่อ Cation Field จบ หรือร่างอนาคตหมด HP จะกลับสู่ร่างปัจจุบันใน【Low Power Mode】และรับความเสียหาย 25% จากที่ร่างอนาคตรับไว้',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '#C0x5c9970#ยืมพลังแห่งร่างในอนาคต (เพิ่มทุกค่าสถานะ 25%, หลังโจมตีด้วยสกิลที่ไม่ใช่ท่าไม้ตาย 1 ครั้ง จะกลับสู่ร่างพลังต่ำในปัจจุบัน); ร่างปัจจุบันจะรับความเสียหาย 15% แทนร่างอนาคต',
