	[91713] = {
		id = 91713,
		skillName = 'ท่าไม้ตาย',
		skillTypeShow = 'ทักษะสังหาร',
		describe = 'โจมตีเป้าหมายเดี่ยวของศัตรู สร้างความเสียหาย #C0xE69900#400% โจมตีกายภาพ#C0x5B545B# +$(skillLevel*4*48)$ เป็น #C0xF13B54#ความเสียหายกายภาพ#C0x5B545B#\nความเสียหายของการโจมตีนี้จะเพิ่มขึ้น 50% หากเป้าหมายมีน้ำหนักน้อยกว่าตัวเอง\nก่อนใช้ท่าโจมตีจะกระตุ้น #C0xF13B54#【กวาดกับดัก】#C0x5B545B# 2 ครั้ง เพื่อลบล้างกับดักของศัตรู 1 รายการ\nเพิ่มพลังป้องกันกายภาพของตัวเอง 80% เป็นเวลา 2 เทิร์น\nได้รับ #C0xF13B54#【โครงกระดูกเหล็กกล้า】#C0x5B545B# บัฟระดับ 3 ความเสียหายที่ได้รับทั้งหมดจะถูกคำนวณเป็นพลังโจมตีกายภาพแทน เป็นเวลา 2 เทิร์น\nขุดสร้าง #C0xF13B54#【อุโมงค์ลับโจมตี】#C0x5B545B# ซึ่งเป็นเอฟเฟกต์พื้นที่พิเศษของธาตุดินใน 2 ตำแหน่งแบบสุ่ม\nโปเกมอนธาตุดินฝ่ายเดียวกันสามารถใช้ทางอุโมงค์นี้เพื่อโจมตีเป้าหมายที่เชื่อมต่อกันได้\nเป้าหมายที่อยู่เหนืออุโมงค์จะมีความเร็วลดลง 9% และได้รับ #C0xF13B54#【ฝุ่นทรายบดบัง III】#C0x5B545B# ดีบัฟระดับ 1 ทำให้มีโอกาส 30% ที่จะพลาดการโจมตีโปเกมอนธาตุดิน เป็นเวลา 2 เทิร์น',
		starEffect = __data_t__starEffect[91713],
		-- {11}
		starEffectDesc = '\nหลังใช้ท่าไม้ตาย จะสร้าง#C0xF13B54#【Strangle Asphyxiation】#C0x5B545B#ระดับ 3 เป็นการควบคุมเป้าหมายหลัก ลากศัตรูเข้าหาตนเองและพันร่างเพื่อบีบรัด ระหว่างนั้นทั้งสองฝ่ายไม่สามารถกระทำการใดๆ ทุกครั้งที่ตนเองถูกโจมตีหรือฝั่งเรากระตุ้น Earthquake จะสร้างความเสียหาย【Shockback】แก่เป้าหมาย 1 ครั้ง (Flying-type สามารถหลบหนีด้วยเอฟเฟกต์ออกจากสนาม) นาน 1 เทิร์น\nทำให้เพื่อนร่วมทีมประเภท Ground ลำดับแรกก่อนหน้า ใช้พฤติกรรมพิเศษ#C0xF13B54#【Sand Buried】#C0x5B545B#ไม่สามารถถูกเลือกเป็นเป้าหมาย และจะได้รับผลเฉพาะจาก Earthquake เท่านั้น หากตำแหน่งที่เริ่มต้นของการขุดทรายถูกครอบครอง หน่วยจะถูกกักตัวใต้ดิน 1 เทิร์น และโผล่กลับมาจากตำแหน่งว่างแบบสุ่มของฝ่ายเรานาน 1 เทิร์น (เลือกโจมตีเป้าหมายที่โจมตีสูงสุดก่อน)',
		zawakeEffect = __data_t__zawakeEffect[91713],
		-- {79003}
		zawakeEffectDesc = 'โจมตีเป้าหมายเดี่ยวฝ่ายศัตรู สร้าง#C0xE69900#400% Atk#C0x5B545B#+$(skillLevel*4*48)$เป็น#C0xF13B54#Physical Damage#C0x5B545B# ดาเมจจะเพิ่มขึ้น 50% หากเป้าหมายมีน้ำหนักน้อยกว่าตัวผู้ใช้\nก่อนปล่อยสกิลจะกระตุ้น【Trap Sweep】 2 ครั้ง ทำลายกับดักศัตรู 1 อันต่อครั้ง\nเพิ่ม Def ของตนเอง 80% เป็นเวลา 2 เทิร์น\nได้รับสถานะ【Alloy Iron Body】บัฟระดับ 3 ดาเมจที่ได้รับจะถูกคำนวณจาก Atk แทน เป็นเวลา 2 เทิร์น\nขุด【Ambush Tunnel】แบบสุ่มใน 2 ตำแหน่ง สนามระดับสูงธาตุ Ground ที่ทำให้ Pokémon ธาตุ Ground ของฝ่ายเราสามารถโจมตีเป้าหมายที่เชื่อมต่อผ่านอุโมงค์ได้\nเป้าหมายที่อยู่บนอุโมงค์จะมี Speed ลดลง 9% และได้รับสถานะ【Sand Blind III】ดีบัฟระดับ 1 ที่ทำให้การโจมตี Pokémon ธาตุ Ground มีโอกาสพลาด 30% เป็นเวลา 2 เทิร์น',
		zawakeSimpleType = 2,
