	[252016] = {
		id = 252016,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '【Psychic Invisibility】：Ancient Alakazam อยู่ในสถานะล่องหนถาวร (ไม่สามารถถูกเลือกเป็นเป้าหมายได้ แต่ยังได้รับผลกระทบจากความเสียหายแบบ AOE)\n【Shadow Clone】：Ancient Alakazam จะเรียกเงาแยกตัวเอง 3-5 ตัวทุก ๆ 3 เทิร์น เงาแยกจะรับความเสียหายแทน Alakazam 40% เงาแยกสามารถมีอยู่บนสนามได้สูงสุด 5 ตัว หากเงาแยกทั้งหมดถูกกำจัด Ancient Alakazam จะยกเลิกสถานะล่องหนและเข้าสู่【Weakened】เป็นเวลา 2 เทิร์น (Weakened: ไม่สามารถกระทำการใด ๆ ได้ และได้รับความเสียหายเพิ่ม 100%) พร้อมกันนั้นโปเกมอนฝ่ายผู้เล่นทั้งหมดจะเข้าสู่สถานะ【Victory Rush】เป็นเวลา 2 รอบใหญ่ (Victory Rush: ล้างสถานะดีบัฟและควบคุมทั้งหมด และฟื้นฟูเกจความโกรธเต็มก่อนเริ่มแต่ละเทิร์น)\n【Petrify Bind】：เมื่อเงาแยกตัวใดถูกกำจัด หากยังมีเงาแยกตัวอื่นอยู่บนสนาม ผู้ที่สังหารจะถูก Ancient Alakazam ทำให้【Petrify】เป็นเวลา 3 เทิร์น (Petrify: ไม่สามารถกระทำการใด ๆ และได้รับการลดความเสียหาย 100%)\n【Stat Boost】：Ancient Alakazam จะเพิ่มค่าสถานะและประสิทธิภาพการโจมตีของตนเองตามปริมาณความเสียหายที่ได้รับสะสม',
		zawakeEffect = __data_t__zawakeEffect[252016],
		-- {79004}
		zawakeEffectDesc = '【Psychic Invisibility】：Ancient Alakazam อยู่ในสถานะล่องหนตลอดเวลา (ไม่สามารถถูกเลือกเป้าหมายได้ แต่ยังคงได้รับผลจากการโจมตีแบบพื้นที่)\n【Shadow Clone】：Ancient Alakazam จะอัญเชิญร่างแยก 3-5 ตัวทุก ๆ 3 เทิร์น ร่างแยกจะถ่ายโอนความเสียหาย 40% ให้ Ancient Alakazam และสามารถมีร่างแยกบนสนามได้สูงสุด 5 ตัว หากร่างแยกทั้งหมดถูกกำจัด Ancient Alakazam จะยกเลิกสถานะล่องหนและเข้าสู่สถานะ【Weak】เป็นเวลา 2 เทิร์น (Weak: ไม่สามารถกระทำการได้ และได้รับผลเพิ่มความเสียหาย 100%) ในขณะเดียวกัน Pokémon ฝ่ายผู้เล่นทั้งหมดจะเข้าสู่สถานะ【Victory】เป็นเวลา 2 รอบใหญ่ (Victory: ล้างผลลบและควบคุมทั้งหมดของตนเอง ฟื้นฟูพลังโกรธทั้งหมดก่อนเริ่มแต่ละเทิร์น)\n【Petrification Imprisonment】：เมื่อร่างแยกใด ๆ ถูกกำจัด หากยังมีร่างแยกเหลืออยู่บนสนาม ผู้ที่กำจัดจะถูก Ancient Alakazam ทำให้【Petrified】เป็นเวลา 3 เทิร์น (Petrified: ไม่สามารถกระทำการได้ และได้รับการลดความเสียหายเพิ่มขึ้น 100%)\n【Stat Boost】：Ancient Alakazam จะค่อย ๆ เพิ่มค่าสถานะและเอฟเฟกต์การโจมตีตามปริมาณความเสียหายที่ได้รับ',
		zawakeSimpleType = 1,
		zawakeSimpleDesc = '【Psychic Invisibility】: Ancient Alakazam อยู่ในสถานะล่องหนถาวร (ไม่สามารถถูกเลือกเป้าหมาย แต่ยังโดน AoE ได้)\n【Shadow Clone】: Ancient Alakazam จะเรียกร่างแยก 3-5 ตัวทุก 3 เทิร์น ร่างแยกรับดาเมจแทน 40% สูงสุดมีได้ 5 ตัว หากร่างแยกทั้งหมดถูกทำลาย Alakazam จะสูญเสียล่องหนและเข้าสู่【Weakened】2 เทิร์น (Weakened: ไม่สามารถกระทำการได้ รับความเสียหายเพิ่ม 100%) พร้อมทั้งทำให้ Pokémon ฝ่ายเราเข้าสู่【Victory State】2 เทิร์น (Victory: ลบสถานะลบและควบคุมทั้งหมด ฟื้น Rage เต็มเมื่อเริ่มเทิร์น)\n【Petrify Lock】: เมื่อร่างแยกถูกฆ่า หากยังมีร่างแยกหลงเหลืออยู่ ผู้ฆ่าจะถูก【Petrify】3 เทิร์น (Petrify: ไม่สามารถกระทำการได้ และลดความเสียหายที่ได้รับลง 100%)\n【Stat Boost】: Ancient Alakazam จะค่อยๆ เพิ่มพลังโจมตีและสเตตัสตามความเสียหายที่ได้รับ',
