	[810226] = {
		id = 810226,
		skillName = 'พาสชีพ',
		skillTypeShow = 'ทักษะสังหาร',
		describe = '#F40##L10#Mewtwo:#L0#\nเมื่อ Mega Mewtwo Y เข้าสนามจะสุ่มเปลี่ยนร่างในแต่ละเทิร์น (Mega Mewtwo Y, Mega Mewtwo X, ร่างต้นแบบ) และจะใช้สกิลและพาสซีฟของร่างนั้นได้ทั้งหมด\n#F40##L10#Will of Mewtwo:#L0#\nหากจัดทีมร่วมกับ Mewtwo, Mewtwo X, Mewtwo Y จะได้รับ【Mewtwo Legacy】\n#F40##L10#Mental Force:#L0#\nหากมีโปเกมอนสายพลังจิตในทีมอย่างน้อย 1 ตัว จะทำให้ Mega Mewtwo Y ได้รับโบนัส ATK และ Sp. ATK เพิ่ม 10% (ซ้อนทับได้สูงสุด 50%) ต่อเนื่อง 5 เทิร์น\n#C0xF13B54#【Mewtwo Legacy】#C0x5B545B#\nMega Mewtwo Y จะได้รับเอฟเฟกต์เจาะทะลุป้องกันคู่ต่อสู้ 20% ต่อเนื่อง 3 เทิร์น (เอฟเฟกต์นี้ทำงานเพียงครั้งเดียว)',
		starEffect = {18},
		starEffectDesc = '\n#F40##L10#Recover:#L0#\nเมื่อ Divine Mewtwo ล้มลง จะใช้ Recover ทันที หลังจากใช้งาน Divine Mewtwo จะกลับสู่สนามด้วย HP และ Rage เต็ม พร้อมเพิ่มค่าสถานะทั้ง 6 แบบ 50% และเพิ่มโบนัสความเสียหายสุดท้าย 100% และลดความเสียหายสุดท้าย 100% นาน 5 เทิร์น (เอฟเฟกต์นี้เกิดได้เพียงครั้งเดียวต่อแมตช์)',
		zawakeEffect = __data_t__zawakeEffect[810226],
		-- {79004}
		zawakeEffectDesc = '#F40##L10#Mewtwo:#L0# \nเมื่อ Divine Mewtwo เข้าสนาม ทุกเทิร์นจะสุ่มเปลี่ยนร่าง (Divine Mewtwo, Mega Mewtwo X, Mega Mewtwo Y) เมื่อเปลี่ยนร่างจะได้รับทุกสกิลและพาสซีฟของร่างนั้น\n#F40##L10#Mewtwo Will:#L0#\nหากลงสนามพร้อมกันกับ Mewtwo, Mewtwo X และ Mewtwo Y จะได้รับสถานะพิเศษ 【Mewtwo Legacy】\n#F40##L10#Inner Focus:#L0#\nหากในทีมของเรามี Pokémon ประเภท Psychic ลงสนามพร้อมกัน จะทำให้ Divine Mewtwo ได้รับโบนัสพลังโจมตีกายภาพ 10% และพลังโจมตีพิเศษ 10% (สามารถสะสมได้สูงสุด 50%) เป็นเวลา 5 เทิร์น\n#C0xF13B54#【Mewtwo Legacy】#C0x5B545B#\nDivine Mewtwo จะได้รับเอฟเฟกต์ ทะลวงการป้องกันกายภาพและพิเศษของศัตรู 20% เป็นเวลา 3 เทิร์น (เอฟเฟกต์นี้จะทำงานเพียงครั้งเดียวเท่านั้น)',
		zawakeSimpleType = 2,
		zawakeSimpleDesc = '#C0x5c9970#【Mewtwo Legacy】\n#F20# \n#F40##C0x5c9970#【Divine Mewtwo Legacy】Divine Mewtwo จะได้รับเอฟเฟกต์ไม่สน DEF และ Sp.DEF ของศัตรู 30% นาน 3 เทิร์น (พาสซีฟนี้จะทำงานเพียงครั้งเดียว)',
		iconRes = 'ICON/skill/skill/001gqs_skill2.png',
		changeUnitTrigger = true,
		isCombat = true,
		skillType = 3,
		skillType2 = 3,
