	[810323] = {
		id = 810323,
		skillName = 'ท่าไม้ตาย',
		skillTypeShow = 'ทักษะสังหาร',
		describe = 'Ho-Oh โบยบินบนฟ้า พ่นลำแสงร้อนแรงดั่งแสงอาทิตย์จากปากใส่ศัตรูทั้งหมด สร้างความเสียหายกายภาพ #C0xE69900#180% Atk#C0x5B545B#+$(skillLevel*4*60)$#C0xF13B54# ใส่ศัตรูทั้งหมดด้วย【Sacred Fire Burn】1 ชั้น 2 เทิร์น；มอบ【Blessing of the Sacred Bird】ให้เพื่อนร่วมทีม 1 ตัว (ยกเว้นตัวเอง โดยเลือกแนวหน้าก่อน)（Blessing of the Sacred Bird：เอฟเฟกต์พิเศษ หลังถูกน็อกเอาต์จะกลายเป็นไข่นกฟีนิกซ์ ไข่จะสลายหากโดนโจมตีครบ 6 ครั้ง หากไม่ถูกทำลายจะฟื้นคืนชีพเมื่อจบเทิร์นถัดไป ด้วย HP 50% และเกจโกรธ 30%，ทั้งแมตช์สามารถเกิดได้เพียง 1 ครั้ง）',
		simDesc = 'Ho-Oh โบยบินบนท้องฟ้า พ่นลำแสงร้อนแรงจากปากใส่ศัตรูทั้งทีม มอบสถานะ Sacred Burn 1 ชั้น และมอบบัฟ Blessing of the Sacred Bird ให้เพื่อนร่วมทีม 1 คนแบบสุ่ม (ไม่รวมตัวเอง)',
		starEffect = __data_t__starEffect[810323],
		-- {11}
		starEffectDesc = 'เอฟเฟกต์เสริม: เป้าหมายที่ฟื้นจาก【Divine Bird Blessing】จะคง HP และ Rage เต็ม',
		zawakeEffect = __data_t__zawakeEffect[810323],
		-- {79003}
		zawakeEffectDesc = 'Ho-Oh โบยบินเหนือท้องฟ้า ปล่อยลำแสงร้อนแรงราวแสงอาทิตย์ออกจากปาก โจมตีเป้าหมายทุกตัวของศัตรู สร้างความเสียหาย#C0xE69900#180%物攻#C0x5B545B#+$(skillLevel*4*60)$เป็น#C0xF13B54#Physical Damage#C0x5B545B# ใส่สถานะ【Sacred Fire Burn】1 ชั้นให้ศัตรูทุกตัว 2 เทิร์น มอบ【Divine Bird’s Blessing】ให้เพื่อนร่วมทีม 1 ตัว (ยกเว้นตัวเอง โดยเลือกแนวหน้าเป็นลำดับแรก) (Divine Bird’s Blessing: เอฟเฟกต์พิเศษ เมื่อตายจะกลายเป็นไข่ฟีนิกซ์ ไข่จะถูกโจมตีได้ 6 ครั้ง ถ้าถูกโจมตีครบจะถูกทำลาย หากไม่ถูกทำลาย จะฟื้นคืนชีพเมื่อจบเทิร์นถัดไป โดยฟื้นกลับมาพร้อม 50% HP และ 30% Rage) เมื่อ Ho-Oh ฟื้นคืนชีพ จะสุ่มมอบ【Divine Bird’s Blessing】ให้เพื่อนร่วมทีม 2 ตัว และในสนามสามารถฟื้นคืนชีพได้สูงสุด 2 ตัว มอบ【Sacred Fire Barrier】ให้โปเกมอนไฟฝ่ายเดียวกันทุกตัว 2 เทิร์น',
